using Amiga;
using Copper68k;
using CopperMod.Amiga;
using CopperMod.Amiga.CopperStart.Graphics.Portable;
using PortableLayers = CopperStart.Layers;

namespace CopperMod.Amiga.Tests;

public sealed partial class CopperStartLayersBootTests
{
    private const int ExecLibraryListOffset = 0x17A;
    private const int LibraryNameOffset = 0x0A;
    private const int LibraryVersionOffset = 0x14;
    private const int LibraryOpenCountOffset = 0x20;

    [Fact]
    public void CopperStartBootPublishesCompleteMorphOsLayersLibrary()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);

        boot.StartBootFromDisk(CreateBootableDisk());

        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        Assert.True(boot.HasCopperStartLayers);
        Assert.NotEqual(0u, libraryBase);
        Assert.NotEqual(0u, boot.CopperStartLayersRootAddress);
        Assert.Equal(47, boot.CopperStartLayersGatewayCount);
        Assert.Equal(libraryBase, bus.ReadLong(
            AmigaKickstartHost.ExecLibraryBase + ExecLibraryListOffset));
        Assert.Equal(
            "layers.library",
            ReadCString(bus, bus.ReadLong(libraryBase + LibraryNameOffset), 32));
        Assert.Equal((ushort)52, bus.ReadWord(libraryBase + LibraryVersionOffset));
        AssertInstalledProfileGateways(
            bus,
            libraryBase,
            PortableLayers.LayersAbiProfile.Unified);

        Assert.True(bus.HasHostGateway(Lvo(libraryBase, -6)));
        Assert.True(bus.HasHostGateway(Lvo(libraryBase, LayersLvo.InitLayers)));
        Assert.True(bus.HasHostGateway(Lvo(libraryBase, LayersLvo.DoHookClipRects)));
        Assert.True(bus.HasHostGateway(Lvo(
            libraryBase,
            LayersLvo.CreateUpfrontLayerTagList)));

        const uint nameAddress = 0x1800;
        WriteCString(bus, nameAddress, "layers.library");
        var open = new M68kCpuState();
        open.A[1] = nameAddress;
        open.A[7] = 0x3000;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(AmigaKickstartHost.ExecLibraryBase, -408),
            open));
        Assert.Equal(libraryBase, open.D[0]);
        Assert.Equal((ushort)1, bus.ReadWord(libraryBase + LibraryOpenCountOffset));

        var close = new M68kCpuState();
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, -12),
            close));
        Assert.Equal((ushort)0, bus.ReadWord(libraryBase + LibraryOpenCountOffset));
    }

    [Fact]
    public void UnifiedProfilePublishesExtensionsAndReportsMissingRenderProvider()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;

        Assert.Equal(
            PortableLayers.LayersAbiProfile.Unified,
            boot.CopperStartLayersProfile);
        boot.ResetCopperStartLayersForTest();
        Assert.True(boot.ReinstallCopperStartLayersForTest(
            PortableLayers.LayersAbiProfile.Unified));
        Assert.Equal(
            PortableLayers.LayersAbiProfile.Unified,
            boot.CopperStartLayersProfile);
        Assert.Equal(47, boot.CopperStartLayersGatewayCount);
        var libraryBase = boot.CopperStartLayersLibraryBase;
        Assert.Equal(
            LayersAbiConstants.MorphOsV52,
            bus.ReadWord(libraryBase + LibraryVersionOffset));
        AssertInstalledProfileGateways(
            bus,
            libraryBase,
            PortableLayers.LayersAbiProfile.Unified);

        short[] enhanced =
        [
            LayersLvo.CreateUpfrontLayerTagList,
            LayersLvo.CreateBehindLayerTagList,
            LayersLvo.WhichLayerBehindLayer,
            LayersLvo.IsLayerVisible,
            LayersLvo.RenderLayerInfoTagList,
            LayersLvo.LockLayerUpdates,
            LayersLvo.UnlockLayerUpdates,
            LayersLvo.IsVisibleInLayer,
            LayersLvo.IsLayerHitable
        ];
        foreach (var lvo in enhanced)
            Assert.True(bus.HasHostGateway(Lvo(libraryBase, lvo)));

        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var tags = AllocateGuestMemory(bus, 16);
        bus.WriteLong(tags, (uint)LayerRenderTag.DestinationBitMap);
        bus.WriteLong(tags + 4, surface.BitMap);
        bus.WriteLong(tags + 8, 0);
        bus.WriteLong(tags + 12, 0);
        var render = new M68kCpuState
        {
            A = { [0] = layerInfo, [1] = tags },
            D = { [0] = 0xFFFF_FFFF }
        };
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.RenderLayerInfoTagList),
            render));
        Assert.Equal(0u, render.D[0]);

        DeleteLayer(bus, libraryBase, surface.Layer);
        DisposeLayerInfo(bus, libraryBase, layerInfo);
        FreeBitMap(bus, surface.BitMap);
        FreeGuestMemory(bus, tags, 16);
        boot.ResetCopperStartLayersForTest();
        // Reinstalling the unified profile is the same complete gateway
        // surface used by CopperStart's current compatibility install.
        Assert.True(boot.ReinstallCopperStartLayersForTest(
            PortableLayers.LayersAbiProfile.Unified));
        // The unified profile publishes the same complete gateway surface as
        // the default install.  Keep this expectation tied to the installed
        // profile rather than the historical pre-extension count.
        Assert.Equal(47, boot.CopperStartLayersGatewayCount);
        Assert.Equal(
            PortableLayers.LayersAbiProfile.Unified,
            boot.CopperStartLayersProfile);
        Assert.True(bus.HasHostGateway(Lvo(
            boot.CopperStartLayersLibraryBase,
            LayersLvo.RenderLayerInfoTagList)));
    }

    [Fact]
    public void GraphicsLayerRomLocksUseA5AndShareTheLayersOwner()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;

        var allocateBitMap = new M68kCpuState();
        allocateBitMap.D[0] = 16;
        allocateBitMap.D[1] = 16;
        allocateBitMap.D[2] = 1;
        allocateBitMap.D[3] = (uint)BitMapFlags.Clear;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(AmigaKickstartHost.GraphicsLibraryBase, -918),
            allocateBitMap));
        var bitMap = allocateBitMap.D[0];
        Assert.NotEqual(0u, bitMap);

        var newLayerInfo = new M68kCpuState();
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.NewLayerInfo),
            newLayerInfo));
        var layerInfo = newLayerInfo.D[0];
        Assert.NotEqual(0u, layerInfo);

        var create = new M68kCpuState();
        create.A[0] = layerInfo;
        create.A[1] = bitMap;
        create.D[0] = 0;
        create.D[1] = 0;
        create.D[2] = 15;
        create.D[3] = 15;
        create.D[4] = (uint)LayerCreationFlags.Simple;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.CreateUpfrontLayer),
            create));
        var layer = create.D[0];
        Assert.NotEqual(0u, layer);

        var wrongRegister = new M68kCpuState();
        wrongRegister.A[0] = layer;
        wrongRegister.A[5] = 0;
        wrongRegister.D[0] = uint.MaxValue;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(
                AmigaKickstartHost.GraphicsLibraryBase,
                GraphicsLayersLvo.AttemptLockLayerRom),
            wrongRegister));
        Assert.Equal(0u, wrongRegister.D[0]);

        var attempt = new M68kCpuState();
        attempt.A[0] = 0xDEAD_BEEFu;
        attempt.A[5] = layer;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(
                AmigaKickstartHost.GraphicsLibraryBase,
                GraphicsLayersLvo.AttemptLockLayerRom),
            attempt));
        Assert.Equal(1u, attempt.D[0]);

        var nestedAttempt = new M68kCpuState();
        nestedAttempt.A[0] = 0xDEAD_BEEFu;
        nestedAttempt.A[5] = layer;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(
                AmigaKickstartHost.GraphicsLibraryBase,
                GraphicsLayersLvo.AttemptLockLayerRom),
            nestedAttempt));
        Assert.Equal(1u, nestedAttempt.D[0]);

        for (var index = 0; index < 2; index++)
        {
            var unlock = new M68kCpuState();
            unlock.A[0] = 0xDEAD_BEEFu;
            unlock.A[5] = layer;
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(
                    AmigaKickstartHost.GraphicsLibraryBase,
                    GraphicsLayersLvo.UnlockLayerRom),
                unlock));
        }

        var delete = new M68kCpuState();
        delete.A[0] = 0xDEAD_BEEFu;
        delete.A[1] = layer;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.DeleteLayer),
            delete));
        Assert.NotEqual(0u, delete.D[0]);

        var dispose = new M68kCpuState();
        dispose.A[0] = layerInfo;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.DisposeLayerInfo),
            dispose));

        var freeBitMap = new M68kCpuState();
        freeBitMap.A[0] = bitMap;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(AmigaKickstartHost.GraphicsLibraryBase, -924),
            freeBitMap));
    }

    [Fact]
    public void LayerLockContentionBlocksAndResumesThroughOuterTaskScheduler()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var execBase = AmigaKickstartHost.ExecLibraryBase;
        var ownerTask = ReadCurrentTask(bus, execBase);
        Assert.NotEqual(0u, ownerTask);
        Assert.Equal(
            (byte)TaskState.Running,
            ReadTaskState(bus, ownerTask));

        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);

        // Task A owns the lock before Task B becomes runnable.
        var ownerLock = new M68kCpuState();
        ownerLock.A[1] = surface.Layer;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.LockLayer),
            ownerLock));

        var task = AllocateGuestMemory(bus, 0x80);
        var taskStack = AllocateGuestMemory(bus, 0x1000);
        var ownerStack = AllocateGuestMemory(bus, 0x1000);
        var ownerCode = AllocateGuestMemory(bus, 0x40);
        var waiterCode = AllocateGuestMemory(bus, 0x60);
        bus.ClearMemory(task, 0x80);
        var taskStackTop = taskStack + 0x1000;
        var ownerStackTop = ownerStack + 0x1000;
        InitializeTaskPublicFields(bus, task, taskStackTop, 10);

        // A runs only after B has parked. Unlock publishes B as ready; the
        // actual exchange still occurs at the following instruction boundary.
        var ownerWriter = new InstructionWriter(bus, ownerCode);
        ownerWriter.MoveAddressImmediate(0, surface.Layer);
        ownerWriter.JumpSubroutine(Lvo(libraryBase, LayersLvo.UnlockLayer));
        ownerWriter.MoveDataImmediate(5, 0xA5A5_0001u);
        ownerWriter.BranchToSelf();

        // Values written before the contended call must survive B's complete
        // parked frame. The post-call marker proves the continuation performed
        // the delayed RTS instead of polling or recursively running the CPU.
        var waiterWriter = new InstructionWriter(bus, waiterCode);
        waiterWriter.MoveDataImmediate(7, 0xB7B7_0002u);
        waiterWriter.MoveAddressImmediate(2, 0x0001_2340u);
        waiterWriter.MoveAddressImmediate(5, 0x0001_5670u);
        waiterWriter.MoveAddressImmediate(1, surface.Layer);
        waiterWriter.OrImmediateConditionCodes(M68kCpuState.Extend);
        waiterWriter.JumpSubroutine(Lvo(libraryBase, LayersLvo.LockLayer));
        waiterWriter.MoveDataImmediate(6, 0xB6B6_0003u);
        waiterWriter.BranchToSelf();

        machine.Cpu.Reset(ownerCode, ownerStackTop);
        machine.Cpu.State.D[4] = 0xA4A4_0004u;
        var addTask = new M68kCpuState();
        addTask.A[1] = task;
        addTask.A[2] = waiterCode;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(execBase, (int)ExecLvo.AddTask),
            addTask));
        Assert.Equal(task, addTask.D[0]);
        Assert.True(boot.CopperStartTaskDispatchPending);

        var startCycle = machine.Cpu.State.Cycles;
        _ = boot.ContinueCopperStartRuntimeUntilCycle(
            startCycle + 2_000,
            maxInstructions: 100);

        var selectedTask = ReadCurrentTask(bus, execBase);
        Assert.True(
            selectedTask == task,
            $"selected=0x{selectedTask:X8}, waiter=0x{task:X8}, " +
            $"pc=0x{machine.Cpu.State.ProgramCounter:X8}, " +
            $"D6=0x{machine.Cpu.State.D[6]:X8}, D7=0x{machine.Cpu.State.D[7]:X8}, " +
            $"ownerState={ReadTaskState(bus, ownerTask)}, " +
            $"waiterState={ReadTaskState(bus, task)}, " +
            $"ownerPri={ReadTaskPriority(bus, ownerTask)}, " +
            $"waiterPri={ReadTaskPriority(bus, task)}, " +
            $"ready=0x{ReadReadyTaskHead(bus, execBase):X8}, " +
            $"pending={boot.CopperStartTaskDispatchPending}, " +
            $"takeover={boot.KickstartRomExecTakeoverState}, " +
            $"cycles={machine.Cpu.State.Cycles}, halted={machine.Cpu.State.Halted}.");
        Assert.Equal((byte)TaskState.Running, ReadTaskState(bus, task));
        Assert.Equal((byte)TaskState.Ready, ReadTaskState(bus, ownerTask));
        Assert.Equal(0xB7B7_0002u, machine.Cpu.State.D[7]);
        Assert.Equal(0xB6B6_0003u, machine.Cpu.State.D[6]);
        Assert.Equal(0x0001_2340u, machine.Cpu.State.A[2]);
        Assert.Equal(0x0001_5670u, machine.Cpu.State.A[5]);
        // AddTask materializes the canonical startup frame with the final-PC
        // return word at the top of the caller-provided stack.  The resumed
        // task therefore enters with A7 four bytes below the reserved top;
        // the CPU's normal RTS consumes that link exactly once.
        Assert.Equal(taskStackTop - 4u, machine.Cpu.State.A[7]);
        Assert.True(machine.Cpu.State.GetFlag(M68kCpuState.Extend));
        Assert.True(machine.Cpu.State.Cycles >= startCycle);

        var waiterUnlock = new M68kCpuState();
        waiterUnlock.A[0] = surface.Layer;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.UnlockLayer),
            waiterUnlock));
        DeleteLayer(bus, libraryBase, surface.Layer);
        DisposeLayerInfo(bus, libraryBase, layerInfo);
        FreeBitMap(bus, surface.BitMap);
    }

    [Fact]
    public void LayeredGraphicsContentionParksAndResumesTheExactCpuFrame()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var execBase = AmigaKickstartHost.ExecLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(bus, libraryBase, layerInfo, 0, 0, 15, 15);

        var ownerLock = new M68kCpuState();
        ownerLock.A[1] = surface.Layer;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.LockLayer),
            ownerLock));

        var task = AllocateGuestMemory(bus, 0x80);
        var taskStack = AllocateGuestMemory(bus, 0x1000);
        var ownerStack = AllocateGuestMemory(bus, 0x1000);
        var ownerCode = AllocateGuestMemory(bus, 0x40);
        var waiterCode = AllocateGuestMemory(bus, 0xA0);
        bus.ClearMemory(task, 0x80);
        var taskStackTop = taskStack + 0x1000;
        var ownerStackTop = ownerStack + 0x1000;
        InitializeTaskPublicFields(bus, task, taskStackTop, 10);

        var ownerWriter = new InstructionWriter(bus, ownerCode);
        ownerWriter.MoveAddressImmediate(0, surface.Layer);
        ownerWriter.JumpSubroutine(Lvo(libraryBase, LayersLvo.UnlockLayer));
        ownerWriter.MoveDataImmediate(5, 0xA5A5_1001u);
        ownerWriter.BranchToSelf();

        var waiterWriter = new InstructionWriter(bus, waiterCode);
        waiterWriter.MoveDataImmediate(0, 7);
        waiterWriter.MoveDataImmediate(1, 6);
        waiterWriter.MoveDataImmediate(2, 0xD2D2_1002u);
        waiterWriter.MoveDataImmediate(3, 0xD3D3_1003u);
        waiterWriter.MoveDataImmediate(4, 0xD4D4_1004u);
        waiterWriter.MoveDataImmediate(5, 0xD5D5_1005u);
        waiterWriter.MoveDataImmediate(7, 0xD7D7_1007u);
        waiterWriter.MoveAddressImmediate(0, 0x0001_1100u);
        waiterWriter.MoveAddressImmediate(1, surface.RastPort);
        waiterWriter.MoveAddressImmediate(2, 0x0001_2200u);
        waiterWriter.MoveAddressImmediate(3, 0x0001_3300u);
        waiterWriter.MoveAddressImmediate(4, 0x0001_4400u);
        waiterWriter.MoveAddressImmediate(5, 0x0001_5500u);
        waiterWriter.MoveAddressImmediate(6, 0x0001_6600u);
        waiterWriter.OrImmediateConditionCodes(M68kCpuState.Extend);
        waiterWriter.JumpSubroutine(Lvo(
            AmigaKickstartHost.GraphicsLibraryBase,
            (int)GraphicsLvo.Draw));
        waiterWriter.MoveDataImmediate(6, 0xD6D6_1006u);
        var waiterLoop = waiterWriter.Address;
        waiterWriter.BranchToSelf();

        boot.EnableCopperStartLayersProviderOperationTraceForTest();
        var traceStart = boot.CaptureCopperStartLayersProviderOperationTraceForTest();
        machine.Cpu.Reset(ownerCode, ownerStackTop);
        var addTask = new M68kCpuState();
        addTask.A[1] = task;
        addTask.A[2] = waiterCode;
        Assert.True(InvokeHostTrap(bus, Lvo(execBase, (int)ExecLvo.AddTask), addTask));

        var startCycle = machine.Cpu.State.Cycles;
        _ = boot.ContinueCopperStartRuntimeUntilCycle(
            startCycle + 3_000,
            maxInstructions: 180);

        Assert.Equal(task, ReadCurrentTask(bus, execBase));
        Assert.Equal(waiterLoop, machine.Cpu.State.ProgramCounter);
        Assert.Equal(0u, machine.Cpu.State.D[0]);
        Assert.Equal(6u, machine.Cpu.State.D[1]);
        Assert.Equal(0xD2D2_1002u, machine.Cpu.State.D[2]);
        Assert.Equal(0xD3D3_1003u, machine.Cpu.State.D[3]);
        Assert.Equal(0xD4D4_1004u, machine.Cpu.State.D[4]);
        Assert.Equal(0xD5D5_1005u, machine.Cpu.State.D[5]);
        Assert.Equal(0xD6D6_1006u, machine.Cpu.State.D[6]);
        Assert.Equal(0xD7D7_1007u, machine.Cpu.State.D[7]);
        Assert.Equal(0x0001_1100u, machine.Cpu.State.A[0]);
        Assert.Equal(surface.RastPort, machine.Cpu.State.A[1]);
        Assert.Equal(0x0001_2200u, machine.Cpu.State.A[2]);
        Assert.Equal(0x0001_3300u, machine.Cpu.State.A[3]);
        Assert.Equal(0x0001_4400u, machine.Cpu.State.A[4]);
        Assert.Equal(0x0001_5500u, machine.Cpu.State.A[5]);
        Assert.Equal(0x0001_6600u, machine.Cpu.State.A[6]);
        Assert.Equal(taskStackTop - 4u, machine.Cpu.State.A[7]);
        Assert.True(machine.Cpu.State.GetFlag(M68kCpuState.Extend));
        Assert.Equal(
            $"LayeredRaster({(short)GraphicsLvo.Draw})",
            boot.DescribeCopperStartLayersProviderOperationOrderForTest(traceStart));
        Assert.Equal(1, boot.CopperStartLayersLastRasterProviderGuardCountForTest);
        Assert.Equal(
            (ushort)1,
            boot.CopperStartLayersLastRasterProviderPrimaryGuardDepthForTest);
        Assert.Equal(
            (ushort)0,
            boot.CopperStartLayersLastRasterProviderSecondaryGuardDepthForTest);
        Assert.Equal(
            0,
            boot.CopperStartLayersCompatibilityRasterDispatchCountForTest);
        Assert.Equal(
            0u,
            ReadLayerLockOwner(bus, surface.Layer));
        Assert.Equal(
            (ushort)6,
            bus.ReadWord(
                surface.RastPort +
                (uint)GraphicsLayouts.RastPortCurrentY));

        DeleteLayer(bus, libraryBase, surface.Layer);
        DisposeLayerInfo(bus, libraryBase, layerInfo);
        FreeBitMap(bus, surface.BitMap);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void DualLayerClipBlitParksOnceAndResumesWithBothGuards(bool poisonUnusedRegisterBits)
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var execBase = AmigaKickstartHost.ExecLibraryBase;
        var sourceInfo = NewLayerInfo(bus, libraryBase);
        var destinationInfo = NewLayerInfo(bus, libraryBase);
        var source = CreateLayer(bus, libraryBase, sourceInfo, 0, 0, 15, 15);
        var destination = CreateLayer(
            bus,
            libraryBase,
            destinationInfo,
            0,
            0,
            15,
            15);

        var writeSource = new M68kCpuState();
        writeSource.A[1] = source.RastPort;
        writeSource.D[0] = 2;
        writeSource.D[1] = 3;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.WritePixel),
            writeSource));
        Assert.Equal(0u, writeSource.D[0]);
        Assert.True(ReadPlanarBitMapPixel(bus, source.BitMap, 2, 3));

        var ownerLock = new M68kCpuState();
        ownerLock.A[1] = source.Layer;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.LockLayer),
            ownerLock));

        var task = AllocateGuestMemory(bus, 0x80);
        var taskStack = AllocateGuestMemory(bus, 0x1000);
        var ownerStack = AllocateGuestMemory(bus, 0x1000);
        var ownerCode = AllocateGuestMemory(bus, 0x40);
        var waiterCode = AllocateGuestMemory(bus, 0xB0);
        bus.ClearMemory(task, 0x80);
        var taskStackTop = taskStack + 0x1000;
        InitializeTaskPublicFields(bus, task, taskStackTop, 10);

        var ownerWriter = new InstructionWriter(bus, ownerCode);
        ownerWriter.MoveAddressImmediate(0, source.Layer);
        ownerWriter.JumpSubroutine(Lvo(libraryBase, LayersLvo.UnlockLayer));
        ownerWriter.MoveDataImmediate(5, 0xA5A5_2001u);
        ownerWriter.BranchToSelf();

        var unusedHighWord = poisonUnusedRegisterBits ? 0xFFFF_0000u : 0u;
        var blitInputs = new uint[]
        {
            unusedHighWord | 2u,
            unusedHighWord | 3u,
            unusedHighWord | 7u,
            unusedHighWord | 8u,
            unusedHighWord | 1u,
            unusedHighWord | 1u,
            poisonUnusedRegisterBits ? 0xA5FF_12C0u : 0xC0u,
        };
        var waiterWriter = new InstructionWriter(bus, waiterCode);
        waiterWriter.MoveDataImmediate(0, blitInputs[0]);
        waiterWriter.MoveDataImmediate(1, blitInputs[1]);
        waiterWriter.MoveDataImmediate(2, blitInputs[2]);
        waiterWriter.MoveDataImmediate(3, blitInputs[3]);
        waiterWriter.MoveDataImmediate(4, blitInputs[4]);
        waiterWriter.MoveDataImmediate(5, blitInputs[5]);
        waiterWriter.MoveDataImmediate(6, blitInputs[6]);
        waiterWriter.MoveDataImmediate(7, 0xD7D7_2007u);
        waiterWriter.MoveAddressImmediate(0, source.RastPort);
        waiterWriter.MoveAddressImmediate(1, destination.RastPort);
        waiterWriter.MoveAddressImmediate(2, 0x0002_2200u);
        waiterWriter.MoveAddressImmediate(3, 0x0002_3300u);
        waiterWriter.MoveAddressImmediate(4, 0x0002_4400u);
        waiterWriter.MoveAddressImmediate(5, 0x0002_5500u);
        waiterWriter.MoveAddressImmediate(6, 0x0002_6600u);
        waiterWriter.OrImmediateConditionCodes(M68kCpuState.Extend);
        waiterWriter.JumpSubroutine(Lvo(
            AmigaKickstartHost.GraphicsLibraryBase,
            (int)GraphicsLvo.ClipBlit));
        waiterWriter.MoveDataImmediate(7, 0xD7D7_20FFu);
        var waiterLoop = waiterWriter.Address;
        waiterWriter.BranchToSelf();

        boot.EnableCopperStartLayersProviderOperationTraceForTest();
        var traceStart = boot.CaptureCopperStartLayersProviderOperationTraceForTest();
        machine.Cpu.Reset(ownerCode, ownerStack + 0x1000);
        var addTask = new M68kCpuState();
        addTask.A[1] = task;
        addTask.A[2] = waiterCode;
        Assert.True(InvokeHostTrap(bus, Lvo(execBase, (int)ExecLvo.AddTask), addTask));

        var startCycle = machine.Cpu.State.Cycles;
        _ = boot.ContinueCopperStartRuntimeUntilCycle(
            startCycle + 4_000,
            maxInstructions: 220);

        Assert.Equal(task, ReadCurrentTask(bus, execBase));
        Assert.Equal(waiterLoop, machine.Cpu.State.ProgramCounter);
        Assert.Equal(0u, machine.Cpu.State.D[0]);
        Assert.Equal(blitInputs[1], machine.Cpu.State.D[1]);
        Assert.Equal(blitInputs[2], machine.Cpu.State.D[2]);
        Assert.Equal(blitInputs[3], machine.Cpu.State.D[3]);
        Assert.Equal(blitInputs[4], machine.Cpu.State.D[4]);
        Assert.Equal(blitInputs[5], machine.Cpu.State.D[5]);
        Assert.Equal(blitInputs[6], machine.Cpu.State.D[6]);
        Assert.Equal(0xD7D7_20FFu, machine.Cpu.State.D[7]);
        Assert.Equal(source.RastPort, machine.Cpu.State.A[0]);
        Assert.Equal(destination.RastPort, machine.Cpu.State.A[1]);
        Assert.Equal(0x0002_2200u, machine.Cpu.State.A[2]);
        Assert.Equal(0x0002_3300u, machine.Cpu.State.A[3]);
        Assert.Equal(0x0002_4400u, machine.Cpu.State.A[4]);
        Assert.Equal(0x0002_5500u, machine.Cpu.State.A[5]);
        Assert.Equal(0x0002_6600u, machine.Cpu.State.A[6]);
        Assert.Equal(taskStackTop - 4u, machine.Cpu.State.A[7]);
        Assert.True(machine.Cpu.State.GetFlag(M68kCpuState.Extend));
        Assert.True(ReadPlanarBitMapPixel(bus, destination.BitMap, 7, 8));
        Assert.Equal(
            $"LayeredRaster({(short)GraphicsLvo.ClipBlit})",
            boot.DescribeCopperStartLayersProviderOperationOrderForTest(traceStart));
        Assert.Equal(2, boot.CopperStartLayersLastRasterProviderGuardCountForTest);
        Assert.Equal(
            (ushort)1,
            boot.CopperStartLayersLastRasterProviderPrimaryGuardDepthForTest);
        Assert.Equal(
            (ushort)1,
            boot.CopperStartLayersLastRasterProviderSecondaryGuardDepthForTest);
        Assert.Equal(
            0,
            boot.CopperStartLayersCompatibilityRasterDispatchCountForTest);
        Assert.Equal(
            0u,
            ReadLayerLockOwner(bus, source.Layer));
        Assert.Equal(
            0u,
            ReadLayerLockOwner(bus, destination.Layer));

        DeleteLayer(bus, libraryBase, source.Layer);
        DeleteLayer(bus, libraryBase, destination.Layer);
        DisposeLayerInfo(bus, libraryBase, sourceInfo);
        DisposeLayerInfo(bus, libraryBase, destinationInfo);
        FreeBitMap(bus, source.BitMap);
        FreeBitMap(bus, destination.BitMap);
    }

    [Fact]
    public void RemovingBlockedRasterTaskCancelsWaitOperationAndHeldTopologyGuard()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var execBase = AmigaKickstartHost.ExecLibraryBase;
        var ownerTask = ReadCurrentTask(bus, execBase);
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(bus, libraryBase, layerInfo, 0, 0, 15, 15);

        var ownerLock = new M68kCpuState();
        ownerLock.A[1] = surface.Layer;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.LockLayer),
            ownerLock));

        var task = AllocateGuestMemory(bus, 0x80);
        var taskStack = AllocateGuestMemory(bus, 0x1000);
        var ownerStack = AllocateGuestMemory(bus, 0x1000);
        var ownerCode = AllocateGuestMemory(bus, 0x20);
        var waiterCode = AllocateGuestMemory(bus, 0x60);
        bus.ClearMemory(task, 0x80);
        InitializeTaskPublicFields(bus, task, taskStack + 0x1000, 10);

        var ownerWriter = new InstructionWriter(bus, ownerCode);
        ownerWriter.BranchToSelf();
        var waiterWriter = new InstructionWriter(bus, waiterCode);
        waiterWriter.MoveDataImmediate(0, 3);
        waiterWriter.MoveDataImmediate(1, 4);
        waiterWriter.MoveAddressImmediate(1, surface.RastPort);
        waiterWriter.JumpSubroutine(Lvo(
            AmigaKickstartHost.GraphicsLibraryBase,
            (int)GraphicsLvo.Draw));
        waiterWriter.MoveDataImmediate(7, 0xDEAD_7007u);
        waiterWriter.BranchToSelf();

        var beforeWait = boot.CopperStartAvailablePublicMemory;
        machine.Cpu.Reset(ownerCode, ownerStack + 0x1000);
        var addTask = new M68kCpuState();
        addTask.A[1] = task;
        addTask.A[2] = waiterCode;
        Assert.True(InvokeHostTrap(bus, Lvo(execBase, (int)ExecLvo.AddTask), addTask));
        var startCycle = machine.Cpu.State.Cycles;
        _ = boot.ContinueCopperStartRuntimeUntilCycle(
            startCycle + 1_500,
            maxInstructions: 100);

        Assert.Equal(ownerTask, ReadCurrentTask(bus, execBase));
        Assert.Equal(1, boot.CopperStartLayersPendingWaitCountForTest);
        Assert.Equal((byte)TaskState.Waiting, ReadTaskState(bus, task));
        Assert.True(boot.CopperStartAvailablePublicMemory < beforeWait);
        Assert.Equal(
            task,
            ReadLayerInfoLockOwner(bus, layerInfo));

        var remove = new M68kCpuState();
        remove.A[1] = task;
        Assert.True(InvokeHostTrap(bus, Lvo(execBase, ExecLvo.RemTask), remove));

        Assert.Equal(0, boot.CopperStartLayersPendingWaitCountForTest);
        Assert.Equal(beforeWait, boot.CopperStartAvailablePublicMemory);
        Assert.Equal(
            0u,
            ReadLayerInfoLockOwner(bus, layerInfo));
        Assert.Equal(
            ownerTask,
            ReadLayerLockOwner(bus, surface.Layer));
        Assert.Equal(
            ushort.MaxValue,
            ReadLayerLockQueueCount(bus, surface.Layer));

        var ownerUnlock = new M68kCpuState();
        ownerUnlock.A[0] = surface.Layer;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.UnlockLayer),
            ownerUnlock));
        DeleteLayer(bus, libraryBase, surface.Layer);
        DisposeLayerInfo(bus, libraryBase, layerInfo);
        FreeBitMap(bus, surface.BitMap);
    }

    [Fact]
    public void ResetCancelsBlockedRasterAndReinstallReturnsToMemoryBaseline()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var execBase = AmigaKickstartHost.ExecLibraryBase;
        var baseline = boot.CopperStartAvailablePublicMemory;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(bus, libraryBase, layerInfo, 0, 0, 15, 15);

        var ownerLock = new M68kCpuState();
        ownerLock.A[1] = surface.Layer;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.LockLayer),
            ownerLock));

        var task = AllocateGuestMemory(bus, 0x80);
        var taskStack = AllocateGuestMemory(bus, 0x1000);
        var ownerStack = AllocateGuestMemory(bus, 0x1000);
        var ownerCode = AllocateGuestMemory(bus, 0x20);
        var waiterCode = AllocateGuestMemory(bus, 0x60);
        bus.ClearMemory(task, 0x80);
        InitializeTaskPublicFields(bus, task, taskStack + 0x1000, 10);
        var ownerWriter = new InstructionWriter(bus, ownerCode);
        ownerWriter.BranchToSelf();
        var waiterWriter = new InstructionWriter(bus, waiterCode);
        waiterWriter.MoveDataImmediate(0, 5);
        waiterWriter.MoveDataImmediate(1, 5);
        waiterWriter.MoveAddressImmediate(1, surface.RastPort);
        waiterWriter.JumpSubroutine(Lvo(
            AmigaKickstartHost.GraphicsLibraryBase,
            (int)GraphicsLvo.Draw));
        waiterWriter.BranchToSelf();

        machine.Cpu.Reset(ownerCode, ownerStack + 0x1000);
        var addTask = new M68kCpuState();
        addTask.A[1] = task;
        addTask.A[2] = waiterCode;
        Assert.True(InvokeHostTrap(bus, Lvo(execBase, (int)ExecLvo.AddTask), addTask));
        var startCycle = machine.Cpu.State.Cycles;
        _ = boot.ContinueCopperStartRuntimeUntilCycle(
            startCycle + 1_500,
            maxInstructions: 100);
        Assert.Equal(1, boot.CopperStartLayersPendingWaitCountForTest);

        boot.ResetCopperStartLayersForTest();
        Assert.False(boot.HasCopperStartLayers);
        Assert.Equal(0, boot.CopperStartLayersGatewayCount);
        Assert.Equal(0, boot.CopperStartLayersPendingWaitCountForTest);
        Assert.Equal(0, boot.CopperStartLayersOpaqueAllocationCountForTest);
        Assert.Equal(0, boot.CopperStartLayersPixelTransactionCountForTest);

        var remove = new M68kCpuState();
        remove.A[1] = task;
        Assert.True(InvokeHostTrap(bus, Lvo(execBase, ExecLvo.RemTask), remove));
        FreeBitMap(bus, surface.BitMap);
        FreeGuestMemory(bus, waiterCode, 0x60);
        FreeGuestMemory(bus, ownerCode, 0x20);
        FreeGuestMemory(bus, ownerStack, 0x1000);
        FreeGuestMemory(bus, taskStack, 0x1000);
        FreeGuestMemory(bus, task, 0x80);
        Assert.True(boot.ReinstallCopperStartLayersForTest());
        Assert.Equal(baseline, boot.CopperStartAvailablePublicMemory);
        Assert.Equal(0, boot.CopperStartLayersPendingWaitCountForTest);
    }

    [Fact]
    public void RasterCleanupLinkRetryResumesWithoutRepeatingProviderExecution()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(bus, libraryBase, layerInfo, 0, 0, 15, 15);
        var code = AllocateGuestMemory(bus, 0x80);
        var stack = AllocateGuestMemory(bus, 0x1000);
        var writer = new InstructionWriter(bus, code);
        writer.MoveDataImmediate(0, 9);
        writer.MoveDataImmediate(1, 10);
        writer.MoveDataImmediate(2, 0xD2D2_3002u);
        writer.MoveDataImmediate(7, 0xD7D7_3007u);
        writer.MoveAddressImmediate(0, 0x0003_1100u);
        writer.MoveAddressImmediate(1, surface.RastPort);
        writer.MoveAddressImmediate(5, 0x0003_5500u);
        writer.OrImmediateConditionCodes(M68kCpuState.Extend);
        writer.JumpSubroutine(Lvo(
            AmigaKickstartHost.GraphicsLibraryBase,
            (int)GraphicsLvo.Draw));
        writer.MoveDataImmediate(6, 0xD6D6_3006u);
        var loop = writer.Address;
        writer.BranchToSelf();

        boot.EnableCopperStartLayersProviderOperationTraceForTest();
        var traceStart = boot.CaptureCopperStartLayersProviderOperationTraceForTest();
        var opaqueBefore = boot.CopperStartLayersOpaqueAllocationCountForTest;
        var memoryBefore = boot.CopperStartAvailablePublicMemory;
        boot.FailNextCopperStartLayersRasterRetireLinkReadForTest(layerInfo);
        machine.Cpu.Reset(code, stack + 0x1000);
        var startCycle = machine.Cpu.State.Cycles;
        _ = boot.ContinueCopperStartRuntimeUntilCycle(
            startCycle + 2_000,
            maxInstructions: 140);

        Assert.Equal(loop, machine.Cpu.State.ProgramCounter);
        Assert.Equal(0u, machine.Cpu.State.D[0]);
        Assert.Equal(10u, machine.Cpu.State.D[1]);
        Assert.Equal(0xD2D2_3002u, machine.Cpu.State.D[2]);
        Assert.Equal(0xD6D6_3006u, machine.Cpu.State.D[6]);
        Assert.Equal(0xD7D7_3007u, machine.Cpu.State.D[7]);
        Assert.Equal(0x0003_1100u, machine.Cpu.State.A[0]);
        Assert.Equal(surface.RastPort, machine.Cpu.State.A[1]);
        Assert.Equal(0x0003_5500u, machine.Cpu.State.A[5]);
        Assert.True(machine.Cpu.State.GetFlag(M68kCpuState.Extend));
        Assert.Equal(0, boot.CopperStartLayersPendingWaitCountForTest);
        Assert.Equal(opaqueBefore, boot.CopperStartLayersOpaqueAllocationCountForTest);
        Assert.Equal(memoryBefore, boot.CopperStartAvailablePublicMemory);
        Assert.Equal(
            $"LayeredRaster({(short)GraphicsLvo.Draw})",
            boot.DescribeCopperStartLayersProviderOperationOrderForTest(traceStart));
        Assert.Equal(
            0u,
            ReadLayerLockOwner(bus, surface.Layer));

        DeleteLayer(bus, libraryBase, surface.Layer);
        DisposeLayerInfo(bus, libraryBase, layerInfo);
        FreeBitMap(bus, surface.BitMap);
    }

