    [Fact]
    public void SwitchingToKickstartRomWithdrawsEveryCopperStartLayersVector()
    {
        var machine = new Machine(MachineOptions
            .ForProfile(MachineProfile.A500Pal512KBoot)
            .WithKickstart(KickstartConfiguration.FromRomImage(
                KickstartVersion.Kickstart20,
                CreateMinimalKickstartRom()))
            .WithLiveAgnusDma(false));
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        Assert.NotEqual(0u, libraryBase);

        uint[] installedAddresses =
        [
            Lvo(libraryBase, -6),
            Lvo(libraryBase, LayersLvo.InitLayers),
            Lvo(libraryBase, LayersLvo.CreateUpfrontLayer),
            Lvo(libraryBase, LayersLvo.ScrollLayer),
            Lvo(libraryBase, LayersLvo.SwapBitsRastPortClipRect),
            Lvo(libraryBase, LayersLvo.DoHookClipRects),
            0x00F0_8C00,
            0x00F0_8C10
        ];
        foreach (var address in installedAddresses)
            Assert.True(bus.HasHostGateway(address));

        boot.StartKickstartRomBoot(CreateBootableDisk());

        Assert.False(boot.HasCopperStartLayers);
        Assert.Equal(0u, boot.CopperStartLayersLibraryBase);
        Assert.Equal(0u, boot.CopperStartLayersRootAddress);
        Assert.Equal(0, boot.CopperStartLayersGatewayCount);
        foreach (var address in installedAddresses)
            Assert.False(bus.HasHostGateway(address));
    }

    [Fact]
    public void ValidatedRasterExecutorConsumesSuppliedHeadInsteadOfStaleLayerHead()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;

        var layerInfo = NewLayerInfo(bus, boot.CopperStartLayersLibraryBase);
        var surface = CreateLayer(
            bus,
            boot.CopperStartLayersLibraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);
        Assert.NotEqual(0u, plane);
        Assert.Equal((byte)0, bus.ReadByte(plane));

        // LayersRasterCore supplied this exact head before the provider call.
        // Changing the public field now simulates a stale/hard-coded
        // rediscovery path: the provider must still traverse the supplied
        // endpoint, not Layer.ClipRect.
        WriteLayerClipRect(bus, surface.Layer, 0);
        var frame = new PortableLayers.LayersRegisterFrame
        {
            A1 = surface.RastPort,
            D0 = 0,
            D1 = 0,
            D2 = 0,
            D3 = 0
        };
        var executor = (IGraphicsValidatedLayerRasterBackend)boot;
        Assert.True(executor.TryExecuteLayeredRaster(
            GraphicsLayersLvo.RectFill,
            ref frame,
            new GraphicsValidatedLayerEndpoint(
                surface.RastPort,
                surface.Layer,
                surface.FirstClipRect),
            default));
        Assert.Equal((byte)0x80, bus.ReadByte(plane));

        WriteLayerClipRect(bus, surface.Layer, surface.FirstClipRect);
        DeleteLayer(bus, boot.CopperStartLayersLibraryBase, surface.Layer);
        DisposeLayerInfo(bus, boot.CopperStartLayersLibraryBase, layerInfo);
        FreeBitMap(bus, surface.BitMap);
    }

    [Fact]
    public void ValidatedPixelArraysReturnRequestedCountAcrossSuppliedClip()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var array = AllocateGuestMemory(bus, 16); // one RASSIZE row for five pixels
        var layerMemory = new LayersTestGuestMemory(bus);
        var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
        var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
            ref layerMemory,
            APTR.FromPointer(surface.Layer)).Raw;
        var clipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(clipBounds + (uint)(index * 2));

        try
        {
            // The endpoint admits three of five requested samples. Poison the
            // public head so every read/write must use the supplied topology.
            WriteRectangleBounds(bus, clipBounds, 0, 0, 2, 0);
            WriteLayerClipRect(bus, surface.Layer, 0);
            var endpoint = new GraphicsValidatedLayerEndpoint(
                surface.RastPort,
                surface.Layer,
                surface.FirstClipRect);
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;

            for (uint index = 0; index < 5; index++)
                bus.WriteByte(array + index, 1, 0);
            var writeLine = new PortableLayers.LayersRegisterFrame
            {
                A0 = surface.RastPort,
                A2 = array,
                D0 = 0,
                D1 = 0,
                D2 = 5
            };
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.WritePixelLine8,
                ref writeLine,
                endpoint,
                default));
            Assert.Equal(5u, writeLine.D0);
            Assert.Equal((byte)0xE0, bus.ReadByte(plane));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);

            for (uint index = 0; index < 5; index++)
                bus.WriteByte(array + index, 0xCC, 0);
            var readArray = new PortableLayers.LayersRegisterFrame
            {
                A0 = surface.RastPort,
                A2 = array,
                D0 = 0,
                D1 = 0,
                D2 = 4,
                D3 = 0
            };
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.ReadPixelArray8,
                ref readArray,
                endpoint,
                default));
            Assert.Equal(5u, readArray.D0);
            Assert.Equal((byte)1, bus.ReadByte(array));
            Assert.Equal((byte)1, bus.ReadByte(array + 1u));
            Assert.Equal((byte)1, bus.ReadByte(array + 2u));
            Assert.Equal((byte)0, bus.ReadByte(array + 3u));
            Assert.Equal((byte)0, bus.ReadByte(array + 4u));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(clipBounds + (uint)(index * 2), savedBounds[index]);
            WriteLayerClipRect(bus, surface.Layer, surface.FirstClipRect);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
            FreeGuestMemory(bus, array, 16);
        }
    }

    [Fact]
    public void ValidatedPixelArrayRejectsMissingSelectedPlaneWithoutPartialWrite()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var originalDepth = ReadBitMapDepth(bus, surface.BitMap);
        var array = AllocateGuestMemory(bus, 16); // one RASSIZE row

        try
        {
            // Plane zero is writable but plane one is declared and absent.
            // The layered provider must reject this as one malformed planar
            // endpoint before publishing a partial colour value.
            WriteBitMapDepth(bus, surface.BitMap, 2);
            WriteRastPortMask(bus, surface.RastPort, 0x03);
            bus.WriteByte(plane, 0x55, 0);
            bus.WriteByte(array, 3, 0);
            var frame = new PortableLayers.LayersRegisterFrame
            {
                A0 = surface.RastPort,
                A2 = array,
                D0 = 0xA55A_0000,
                D1 = 0,
                D2 = 1
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.False(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.WritePixelLine8,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    surface.RastPort,
                    surface.Layer,
                    surface.FirstClipRect),
                default));
            Assert.Equal(0xA55A_0000u, frame.D0);
            Assert.Equal((byte)0x55, bus.ReadByte(plane));
        }
        finally
        {
            WriteBitMapDepth(bus, surface.BitMap, originalDepth);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
            FreeGuestMemory(bus, array, 16);
        }
    }

    [Fact]
    public void ValidatedChunkyPixelsStageAnAliasedSourceBeforeLayerWrites()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var bytesPerRow = ReadBitMapBytesPerRow(bus, surface.BitMap);

        try
        {
            // The caller's eleven one-byte rows alias plane bytes 0..10.
            // The first destination pixel is byte 10 (x=7, y=5), which is
            // not consumed from the source until its final row.  A streaming
            // implementation turns that final original zero into one.  The
            // V40 vector must instead snapshot all source samples first.
            for (var offset = 0; offset <= 10; offset++)
                bus.WriteByte(plane + (uint)offset, offset == 0 ? (byte)1 : (byte)0, 0);
            bus.WriteByte(plane + (uint)(15 * bytesPerRow), 0, 0);

            var frame = new PortableLayers.LayersRegisterFrame
            {
                A0 = surface.RastPort,
                A2 = plane,
                D0 = 7,
                D1 = 5,
                D2 = 7,
                D3 = 15,
                D4 = 1
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.True(executor.TryExecuteLayeredRaster(
                (short)GraphicsLvo.WriteChunkyPixels,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    surface.RastPort,
                    surface.Layer,
                    surface.FirstClipRect),
                default));

            Assert.Equal(0u, frame.D0);
            Assert.Equal(
                (byte)0,
                bus.ReadByte(plane + (uint)(15 * bytesPerRow)));
        }
        finally
        {
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

    [Fact]
    public void ValidatedChunkyPixelsTreatsZeroMaskAsASourceFreeNoOp()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var maskAddress = surface.RastPort + (uint)GraphicsLayouts.RastPortMask;
        var savedMask = bus.ReadByte(maskAddress);

        try
        {
            bus.WriteByte(maskAddress, 0, 0);
            bus.WriteByte(plane, 0x5A, 0);
            var frame = new PortableLayers.LayersRegisterFrame
            {
                A0 = surface.RastPort,
                A2 = 0,
                D0 = 0,
                D1 = 0,
                D2 = 0,
                D3 = 0,
                D4 = 1
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.True(executor.TryExecuteLayeredRaster(
                (short)GraphicsLvo.WriteChunkyPixels,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    surface.RastPort,
                    surface.Layer,
                    surface.FirstClipRect),
                default));

            Assert.Equal(0u, frame.D0);
            Assert.Equal((byte)0x5A, bus.ReadByte(plane));
        }
        finally
        {
            bus.WriteByte(maskAddress, savedMask, 0);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

    [Fact]
    public void ValidatedChunkyPixelsPreflightTheWholeLayeredDestination()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var source = AllocateGuestMemory(bus, 9);
        var originalPlane = ReadBitMapPlane(bus, surface.BitMap, 0);
        const uint oneBytePlane = 0xE100_0000;
        bus.MapWritableMemory(oneBytePlane, new byte[1]);

        try
        {
            // The first byte covers x=0..7, but x=8 needs an unmapped
            // second byte. The V40 vector must decline before plotting the
            // first byte rather than expose a visible prefix.
            WriteBitMapPlane(bus, surface.BitMap, 0, oneBytePlane);
            for (uint index = 0; index < 9; index++)
                bus.WriteByte(source + index, 1, 0);

            var frame = new PortableLayers.LayersRegisterFrame
            {
                A0 = surface.RastPort,
                A2 = source,
                D0 = 0,
                D1 = 0,
                D2 = 8,
                D3 = 0,
                D4 = 9
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.False(executor.TryExecuteLayeredRaster(
                (short)GraphicsLvo.WriteChunkyPixels,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    surface.RastPort,
                    surface.Layer,
                    surface.FirstClipRect),
                default));

            Assert.Equal((byte)0, bus.ReadByte(oneBytePlane));
        }
        finally
        {
            WriteBitMapPlane(bus, surface.BitMap, 0, originalPlane);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
            FreeGuestMemory(bus, source, 9);
        }
    }

    [Fact]
    public void ValidatedPixelLineStagesAnAliasedSourceBeforeLayerWrites()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var bytesPerRow = ReadBitMapBytesPerRow(bus, surface.BitMap);

        try
        {
            // Source byte 7 plots x=7, which sets bit zero of destination
            // byte 10. That byte is not consumed until source column 10.
            // A V36 writer must retain the original zero sample at column 10.
            for (var offset = 0; offset < 16; offset++)
                bus.WriteByte(plane + (uint)offset, offset == 7 ? (byte)1 : (byte)0, 0);
            bus.WriteByte(plane + (uint)(5 * bytesPerRow + 1), 0, 0);

            var frame = new PortableLayers.LayersRegisterFrame
            {
                A0 = surface.RastPort,
                A2 = plane,
                D0 = 0,
                D1 = 5,
                D2 = 11
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.True(executor.TryExecuteLayeredRaster(
                (short)GraphicsLvo.WritePixelLine8,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    surface.RastPort,
                    surface.Layer,
                    surface.FirstClipRect),
                default));

            Assert.Equal(11u, frame.D0);
            Assert.Equal(
                (byte)0,
                (byte)(bus.ReadByte(plane + (uint)(5 * bytesPerRow + 1)) & 0x20));
        }
        finally
        {
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

