    [Fact]
    public void InstallClipRegionRebuildsRasterProjectionWithoutGraphicsDamageMutation()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(bus, libraryBase, layerInfo, 0, 0, 15, 15);
        var rectangle = AllocateGuestMemory(bus, (uint)GraphicsLayouts.RectangleSize);
        uint region = 0;
        uint malformedRegion = 0;
        var installed = false;

        try
        {
            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.NewRegion),
                newRegion));
            region = newRegion.D[0];
            Assert.NotEqual(0u, region);

            // A caller-owned Region remains graphics-owned; layers consumes
            // its public geometry only to rebuild the Layer ClipRect topology.
            WriteRectangleBounds(bus, rectangle, 2, 3, 5, 6);
            var include = new M68kCpuState
            {
                A = { [0] = region, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.OrRectRegion),
                include));
            Assert.Equal(1u, include.D[0]);

            // A separate island forces graphics.library to publish a second
            // RegionRectangle node, including its successor/predecessor
            // links, before layers.library consumes the chain.
            WriteRectangleBounds(bus, rectangle, 10, 9, 12, 11);
            include = new M68kCpuState
            {
                A = { [0] = region, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.OrRectRegion),
                include));
            Assert.Equal(1u, include.D[0]);

            var regionMemory = new LayersTestGuestMemory(bus);
            var regionAddress = APTR.FromPointer(region);
            var regionHead = LayersRegionCodec.ReadFirst(ref regionMemory, regionAddress);
            var regionSecond = LayersRegionRectangleCodec.ReadNext(
                ref regionMemory,
                regionHead);
            Assert.True(regionHead.IsNotNull);
            Assert.True(regionSecond.IsNotNull);
            Assert.True(LayersRegionRectangleCodec.ReadNext(
                ref regionMemory,
                regionSecond).IsNull);
            Assert.Equal(
                LayersRegionCodec.HeadAnchor(regionAddress).Raw,
                LayersRegionRectangleCodec.ReadPrevious(ref regionMemory, regionHead).Raw);
            Assert.Equal(
                regionHead.Raw,
                LayersRegionRectangleCodec.ReadPrevious(
                    ref regionMemory,
                    regionSecond).Raw);
            Assert.Equal(0u, ReadLayerClipRegion(bus, surface.Layer));

            var install = new M68kCpuState
            {
                A = { [0] = surface.Layer, [1] = region }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                install));
            Assert.Equal(0u, install.D[0]);
            Assert.Equal(region, ReadLayerClipRegion(bus, surface.Layer));
            installed = true;

            var layerMemory = new LayersTestGuestMemory(bus);
            var clipHeadBeforeMalformedInstall = ReadLayerClipRect(bus, surface.Layer);
            var flagsBeforeMalformedInstall = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeMalformedInstall = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            var newMalformedRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.NewRegion),
                newMalformedRegion));
            malformedRegion = newMalformedRegion.D[0];
            Assert.NotEqual(0u, malformedRegion);
            WriteRectangleBounds(bus, rectangle, 0, 0, 1, 1);
            include = new M68kCpuState
            {
                A = { [0] = malformedRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.OrRectRegion),
                include));
            var malformedAddress = APTR.FromPointer(malformedRegion);
            var malformedHead = LayersRegionCodec.ReadFirst(
                ref regionMemory,
                malformedAddress);
            Assert.True(malformedHead.IsNotNull);
            // A valid graphics Region has a Region.RegionRectangle predecessor
            // on its first node. Corrupting just that link must make Layers
            // decline the replacement atomically.
            LayersRegionRectangleCodec.WritePrevious(
                ref regionMemory,
                malformedHead,
                APTR.Null);
            var malformedInstall = new M68kCpuState
            {
                A = { [0] = surface.Layer, [1] = malformedRegion }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                malformedInstall));
            Assert.Equal(malformedRegion, malformedInstall.D[0]);
            Assert.Equal(region, ReadLayerClipRegion(bus, surface.Layer));
            Assert.Equal(clipHeadBeforeMalformedInstall,
                ReadLayerClipRect(bus, surface.Layer));
            Assert.Equal(flagsBeforeMalformedInstall,
                ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(damageBeforeMalformedInstall,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);

            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;
            var damageBytesBeforeRaster = damageBeforeRaster == 0
                ? Array.Empty<byte>()
                : Enumerable.Range(0, checked((int)LayersRegionCodec.Size))
                    .Select(offset => bus.ReadByte(damageBeforeRaster + (uint)offset))
                    .ToArray();

            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            ClearPlanarBitMap(bus, surface.BitMap);
            var setRast = new M68kCpuState
            {
                A = { [1] = surface.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);

            Assert.True(ReadPlanarBitMapPixel(bus, surface.BitMap, 2, 3));
            Assert.True(ReadPlanarBitMapPixel(bus, surface.BitMap, 5, 6));
            Assert.True(ReadPlanarBitMapPixel(bus, surface.BitMap, 10, 9));
            Assert.True(ReadPlanarBitMapPixel(bus, surface.BitMap, 12, 11));
            Assert.False(ReadPlanarBitMapPixel(bus, surface.BitMap, 1, 3));
            Assert.False(ReadPlanarBitMapPixel(bus, surface.BitMap, 6, 6));
            Assert.False(ReadPlanarBitMapPixel(bus, surface.BitMap, 2, 2));
            Assert.False(ReadPlanarBitMapPixel(bus, surface.BitMap, 5, 7));
            Assert.False(ReadPlanarBitMapPixel(bus, surface.BitMap, 9, 9));
            Assert.False(ReadPlanarBitMapPixel(bus, surface.BitMap, 13, 11));

            // Topology created any refresh/damage state during installation.
            // Painting is pure graphics work and must not publish more damage.
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
            Assert.Equal(
                damageBytesBeforeRaster,
                damageBeforeRaster == 0
                    ? Array.Empty<byte>()
                    : Enumerable.Range(0, checked((int)LayersRegionCodec.Size))
                        .Select(offset => bus.ReadByte(
                            damageBeforeRaster + (uint)offset))
                        .ToArray());

            var uninstall = new M68kCpuState { A = { [0] = surface.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                uninstall));
            Assert.Equal(region, uninstall.D[0]);
            Assert.Equal(0u, ReadLayerClipRegion(bus, surface.Layer));
            installed = false;

            ClearPlanarBitMap(bus, surface.BitMap);
            setRast = new M68kCpuState
            {
                A = { [1] = surface.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.SetRast),
                setRast));
            Assert.True(ReadPlanarBitMapPixel(bus, surface.BitMap, 0, 0));
            Assert.True(ReadPlanarBitMapPixel(bus, surface.BitMap, 15, 15));
        }
        finally
        {
            if (installed)
            {
                var uninstall = new M68kCpuState { A = { [0] = surface.Layer } };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.InstallClipRegion), uninstall);
            }
            if (region != 0)
            {
                var dispose = new M68kCpuState { A = { [0] = region } };
                InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose);
            }
            if (malformedRegion != 0)
            {
                var dispose = new M68kCpuState { A = { [0] = malformedRegion } };
                InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose);
            }
            FreeGuestMemory(bus, rectangle, (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

    [Fact]
    public void LayeredGraphicsGatewayProjectsClipRectWithoutPublishingDamage()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(bus, libraryBase, layerInfo, 0, 0, 15, 15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);
        var clipHead = ReadLayerClipRect(bus, surface.Layer);
        var clipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(clipHead)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + checked((uint)(index * 2)));

        try
        {
            // Restrict the published ClipRect to x=0..4 while the requested
            // RectFill spans x=0..7. The call goes through the actual
            // graphics.library gateway, so LayersRasterCore must pass this
            // exact head into the validated provider rather than allowing a
            // direct/full-surface fallback to paint the tail.
            WriteRectangleBounds(bus, clipBounds, 0, 0, 4, 0);
            ClearPlanarBitMap(bus, surface.BitMap);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 0);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);

            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            var fill = new M68kCpuState
            {
                A = { [1] = surface.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 7, [3] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);

            // x=0..4 are visible (bits 7..3); x=5..7 remain untouched.
            Assert.Equal((byte)0xF8, bus.ReadByte(plane));
            Assert.Equal(clipHead, ReadLayerClipRect(bus, surface.Layer));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + checked((uint)(index * 2)),
                    savedBounds[index]);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

    [Fact]
    public void ActiveUpdateCoalescedProjectionRestrictsRectFillToDamageUnion()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(bus, libraryBase, layerInfo, 0, 0, 15, 15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var memory = new LayersTestGuestMemory(bus);
        var resources = new BootLayersResourcePlatform(bus);
        var layer = APTR.FromPointer(surface.Layer);
        var stableHead = APTR.FromPointer(surface.FirstClipRect);
        var originalStableBounds = LayersClipRectCodec.ReadBounds(
            ref memory, stableHead);
        var secondClipRect = APTR.Null;
        var secondClipRectLinked = false;
        uint damageRegion = 0;
        uint rectangle = 0;
        var updateActive = false;

        try
        {
            LayersClipRectCodec.WriteBounds(ref memory, stableHead,
                LayersRectangleCodec.Create(0, 0, 5, 0));
            secondClipRect = PortableLayers.LayersClipRectAllocationCore.AllocateSingle(
                ref resources, layer, APTR.Null, 6, 0, 11, 0);
            Assert.True(secondClipRect.IsNotNull);
            LayersClipRectCodec.WriteNext(ref memory, stableHead, secondClipRect);
            LayersClipRectCodec.WriteReservedLink(ref memory, secondClipRect,
                APTR.Null);
            secondClipRectLinked = true;
            Assert.True(PortableLayers.LayersClipRectAllocationCore.ValidateOwnedList(
                ref resources, stableHead, layer));

            // Complete the initial empty refresh before explicitly retiring
            // its owned Region for the caller-owned fixture below. EndUpdate
            // itself retains that Region, as native V40 does.
            var initialBegin = new M68kCpuState
            {
                A = { [0] = surface.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                initialBegin));
            Assert.Equal(1u, initialBegin.D[0]);
            var initialEnd = new M68kCpuState
            {
                A = { [0] = surface.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                initialEnd));
            Assert.Equal(1u, initialEnd.D[0]);

            var newDamage = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newDamage));
            damageRegion = newDamage.D[0];
            Assert.NotEqual(0u, damageRegion);
            rectangle = AllocateGuestMemory(
                bus,
                (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 0, 0, 11, 0);
            var addDamage = new M68kCpuState
            {
                A = { [0] = damageRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                addDamage));
            Assert.Equal(1u, addDamage.D[0]);
            RetireOwnedDamageForCallerFixture(bus, boot, layer);
            LayersLayerCodec.WriteDamageList(ref memory, layer,
                APTR.FromPointer(damageRegion));
            var flagsBeforeUpdate = LayersLayerCodec.ReadFlags(ref memory, layer);
            LayersLayerCodec.WriteFlags(ref memory, layer,
                flagsBeforeUpdate | LayerFlags.Refresh);
            var damageBytes = SnapshotGraphicsRegion(bus, damageRegion);

            var begin = new M68kCpuState { A = { [0] = surface.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updateActive = true;
            var savedHead = LayersLayerCodec.ReadSaveClipRects(ref memory, layer);
            Assert.Equal(stableHead.Raw, savedHead.Raw);
            var activeHead = LayersLayerCodec.ReadClipRect(ref memory, layer);
            Assert.NotEqual(stableHead.Raw, activeHead.Raw);
            var activeBounds = LayersClipRectCodec.ReadBounds(ref memory,
                activeHead);
            Assert.Equal((short)0, activeBounds.MinX);
            Assert.Equal((short)0, activeBounds.MinY);
            Assert.Equal((short)11, activeBounds.MaxX);
            Assert.Equal((short)0, activeBounds.MaxY);
            Assert.True(LayersClipRectCodec.ReadBitMap(ref memory,
                activeHead).IsNull);
            Assert.True(LayersClipRectCodec.ReadObscuringLayer(ref memory,
                activeHead).IsNull);
            Assert.True(LayersClipRectCodec.ReadNext(ref memory,
                activeHead).IsNull);

            ClearPlanarBitMap(bus, surface.BitMap);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 0);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var fill = new M68kCpuState
            {
                A = { [1] = surface.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 15, [3] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);

            for (var x = 0; x < 16; x++)
                Assert.Equal(x <= 11,
                    ReadPlanarBitMapPixel(bus, surface.BitMap, x, 0));
            for (var y = 1; y < 16; y++)
                for (var x = 0; x < 16; x++)
                    Assert.False(ReadPlanarBitMapPixel(
                        bus, surface.BitMap, x, y));
            Assert.Equal(activeHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, layer).Raw);
            Assert.Equal(flagsBeforeRaster,
                ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var end = new M68kCpuState
            {
                A = { [0] = surface.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                end));
            Assert.Equal(1u, end.D[0]);
            updateActive = false;
            Assert.Equal(stableHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, layer).Raw);
            Assert.True(LayersLayerCodec.ReadSaveClipRects(ref memory,
                layer).IsNull);
            // Kickstart EndUpdate clears Updating, not the caller-managed
            // Refresh flag, even when complete is TRUE.
            Assert.Equal(flagsBeforeUpdate | LayerFlags.Refresh,
                LayersLayerCodec.ReadFlags(ref memory, layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
        }
        finally
        {
            if (updateActive)
            {
                var abort = new M68kCpuState { A = { [0] = surface.Layer } };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.EndUpdate),
                    abort));
            }

            if (secondClipRect.IsNotNull && secondClipRectLinked)
            {
                LayersClipRectCodec.WriteNext(ref memory, stableHead,
                    APTR.Null);
                secondClipRectLinked = false;
            }
            LayersClipRectCodec.WriteBounds(ref memory, stableHead,
                originalStableBounds);
            if (secondClipRect.IsNotNull)
            {
                Assert.True(PortableLayers.LayersClipRectAllocationCore.FreeList(
                    ref resources, secondClipRect));
                secondClipRect = APTR.Null;
            }
            var root = APTR.FromPointer(boot.CopperStartLayersRootAddress);
            Assert.True(PortableLayers.LayersLayerCore.ValidateTopology(
                ref resources, root, APTR.FromPointer(layerInfo), out _),
                "Layer topology must be valid before deletion.");
            Assert.True(PortableLayers.LayersPartitionPixelCore
                .ValidateOwnedDamageState(ref resources, root, layer),
                "DamageList ownership must be valid before deletion.");
            Assert.True(PortableLayers.LayersClipRectAllocationCore
                .ValidateOwnedList(ref resources,
                    LayersLayerCodec.ReadClipRect(ref memory, layer), layer),
                "ClipRect ownership must be valid before deletion.");
            Assert.True(PortableLayers.LayersClipRectAllocationCore
                .ValidateOwnedList(ref resources,
                    LayersLayerCodec.ReadSuperClipRect(ref memory, layer), layer),
                "SuperClipRect ownership must be valid before deletion.");
            LayersLayerCodec.WriteDamageList(ref memory, layer, APTR.Null);
            Assert.True(PortableLayers.LayersPartitionPixelCore
                .ValidateOwnedDamageState(ref resources, root, layer),
                "Clearing caller-owned damage must preserve layer damage ownership.");
            var finalClipHead = LayersLayerCodec.ReadClipRect(ref memory, layer);
            var finalSuperClipHead = LayersLayerCodec.ReadSuperClipRect(
                ref memory, layer);
            Assert.True(finalClipHead.IsNull ||
                finalClipHead.Raw != finalSuperClipHead.Raw,
                "ClipRect and SuperClipRect heads must remain distinct.");
            DeleteLayer(bus, libraryBase, surface.Layer);
            if (damageRegion != 0)
            {
                var dispose = new M68kCpuState { A = { [0] = damageRegion } };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (rectangle != 0)
                FreeGuestMemory(bus, rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

    [Fact]
    public void ActiveUpdateCoalescedDestinationProjectionRestrictsClipBlitToDamageUnion()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var sourceInfo = NewLayerInfo(bus, libraryBase);
        var destinationInfo = NewLayerInfo(bus, libraryBase);
        var source = CreateLayer(bus, libraryBase, sourceInfo, 0, 0, 15, 15);
        var destination = CreateLayer(
            bus, libraryBase, destinationInfo, 0, 0, 15, 15);
        var memory = new LayersTestGuestMemory(bus);
        var resources = new BootLayersResourcePlatform(bus);
        var destinationLayer = APTR.FromPointer(destination.Layer);
        var stableHead = APTR.FromPointer(destination.FirstClipRect);
        var originalStableBounds = LayersClipRectCodec.ReadBounds(
            ref memory, stableHead);
        var secondClipRect = APTR.Null;
        var secondClipRectLinked = false;
        uint damageRegion = 0;
        uint rectangle = 0;
        var updateActive = false;

        try
        {
            LayersClipRectCodec.WriteBounds(ref memory, stableHead,
                LayersRectangleCodec.Create(0, 0, 5, 0));
            secondClipRect = PortableLayers.LayersClipRectAllocationCore
                .AllocateSingle(ref resources, destinationLayer, APTR.Null,
                    6, 0, 11, 0);
            Assert.True(secondClipRect.IsNotNull);
            LayersClipRectCodec.WriteNext(ref memory, stableHead,
                secondClipRect);
            LayersClipRectCodec.WriteReservedLink(ref memory, secondClipRect,
                APTR.Null);
            secondClipRectLinked = true;
            Assert.True(PortableLayers.LayersClipRectAllocationCore
                .ValidateOwnedList(ref resources, stableHead, destinationLayer));

            // Complete the empty Region installed at layer creation before
            // replacing it with a caller-owned Graphics Region.
            var initialBegin = new M68kCpuState
            {
                A = { [0] = destination.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), initialBegin));
            Assert.Equal(1u, initialBegin.D[0]);
            var initialEnd = new M68kCpuState
            {
                A = { [0] = destination.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), initialEnd));
            Assert.Equal(1u, initialEnd.D[0]);

            var newDamage = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newDamage));
            damageRegion = newDamage.D[0];
            Assert.NotEqual(0u, damageRegion);
            rectangle = AllocateGuestMemory(
                bus, (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 0, 0, 11, 0);
            var addDamage = new M68kCpuState
            {
                A = { [0] = damageRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                addDamage));
            Assert.Equal(1u, addDamage.D[0]);
            RetireOwnedDamageForCallerFixture(bus, boot, destinationLayer);
            LayersLayerCodec.WriteDamageList(ref memory, destinationLayer,
                APTR.FromPointer(damageRegion));
            var flagsBeforeUpdate = LayersLayerCodec.ReadFlags(
                ref memory, destinationLayer);
            LayersLayerCodec.WriteFlags(ref memory, destinationLayer,
                flagsBeforeUpdate | LayerFlags.Refresh);
            var damageBytes = SnapshotGraphicsRegion(bus, damageRegion);

            var begin = new M68kCpuState
            {
                A = { [0] = destination.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updateActive = true;
            var activeHead = LayersLayerCodec.ReadClipRect(
                ref memory, destinationLayer);
            Assert.NotEqual(stableHead.Raw, activeHead.Raw);
            var activeBounds = LayersClipRectCodec.ReadBounds(
                ref memory, activeHead);
            Assert.Equal((short)0, activeBounds.MinX);
            Assert.Equal((short)0, activeBounds.MinY);
            Assert.Equal((short)11, activeBounds.MaxX);
            Assert.Equal((short)0, activeBounds.MaxY);
            Assert.True(LayersClipRectCodec.ReadBitMap(ref memory,
                activeHead).IsNull);
            Assert.True(LayersClipRectCodec.ReadObscuringLayer(ref memory,
                activeHead).IsNull);
            Assert.True(LayersClipRectCodec.ReadNext(ref memory,
                activeHead).IsNull);

            ClearPlanarBitMap(bus, source.BitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            var sourcePlane = ReadBitMapPlane(bus, source.BitMap, 0);
            bus.WriteByte(sourcePlane, 0xFF, 0);
            bus.WriteByte(sourcePlane + 1, 0xFF, 0);
            var flagsBeforeRaster = ReadLayerFlags(bus, destination.Layer);
            var sourceFlagsBeforeRaster = ReadLayerFlags(bus, source.Layer);
            var blit = new M68kCpuState
            {
                A =
                {
                    [0] = source.RastPort,
                    [1] = destination.RastPort
                },
                D =
                {
                    [0] = 0,
                    [1] = 0,
                    [2] = 0,
                    [3] = 0,
                    [4] = 16,
                    [5] = 1,
                    [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ClipBlit),
                blit));

            for (var x = 0; x < 16; x++)
                Assert.Equal(x <= 11,
                    ReadPlanarBitMapPixel(bus, destination.BitMap, x, 0));
            for (var y = 1; y < 16; y++)
                for (var x = 0; x < 16; x++)
                    Assert.False(ReadPlanarBitMapPixel(
                        bus, destination.BitMap, x, y));
            Assert.Equal(sourceFlagsBeforeRaster,
                ReadLayerFlags(bus, source.Layer));
            Assert.Equal(flagsBeforeRaster,
                ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(activeHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory,
                    destinationLayer).Raw);
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory,
                    destinationLayer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var end = new M68kCpuState
            {
                A = { [0] = destination.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), end));
            Assert.Equal(1u, end.D[0]);
            updateActive = false;
            Assert.Equal(stableHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory,
                    destinationLayer).Raw);
            Assert.Equal(flagsBeforeUpdate | LayerFlags.Refresh,
                LayersLayerCodec.ReadFlags(ref memory, destinationLayer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory,
                    destinationLayer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
        }
        finally
        {
            if (updateActive)
            {
                var abort = new M68kCpuState
                {
                    A = { [0] = destination.Layer }
                };
                Assert.True(InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.EndUpdate), abort));
            }
            if (secondClipRect.IsNotNull && secondClipRectLinked)
            {
                LayersClipRectCodec.WriteNext(ref memory, stableHead,
                    APTR.Null);
                secondClipRectLinked = false;
            }
            LayersClipRectCodec.WriteBounds(ref memory, stableHead,
                originalStableBounds);
            if (secondClipRect.IsNotNull)
                Assert.True(PortableLayers.LayersClipRectAllocationCore.FreeList(
                    ref resources, secondClipRect));
            LayersLayerCodec.WriteDamageList(ref memory, destinationLayer,
                APTR.Null);
            DeleteLayer(bus, libraryBase, destination.Layer);
            DeleteLayer(bus, libraryBase, source.Layer);
            if (damageRegion != 0)
            {
                var dispose = new M68kCpuState
                {
                    A = { [0] = damageRegion }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (rectangle != 0)
                FreeGuestMemory(bus, rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            DisposeLayerInfo(bus, libraryBase, destinationInfo);
            DisposeLayerInfo(bus, libraryBase, sourceInfo);
            FreeBitMap(bus, destination.BitMap);
            FreeBitMap(bus, source.BitMap);
        }
    }

    [Fact]
    public void ActiveUpdateCoalescedProjectionRestrictsBitMapRastPortBlitToDamageUnion()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var destination = CreateLayer(bus, libraryBase, layerInfo, 0, 0, 15, 15);
        var sourceBitMap = AllocatePlanarBitMap(bus, 16, 16);
        var memory = new LayersTestGuestMemory(bus);
        var resources = new BootLayersResourcePlatform(bus);
        var layer = APTR.FromPointer(destination.Layer);
        var stableHead = APTR.FromPointer(destination.FirstClipRect);
        var originalStableBounds = LayersClipRectCodec.ReadBounds(
            ref memory, stableHead);
        var secondClipRect = APTR.Null;
        var secondClipRectLinked = false;
        uint damageRegion = 0;
        uint rectangle = 0;
        var updateActive = false;

        try
        {
            LayersClipRectCodec.WriteBounds(ref memory, stableHead,
                LayersRectangleCodec.Create(0, 0, 5, 0));
            secondClipRect = PortableLayers.LayersClipRectAllocationCore
                .AllocateSingle(ref resources, layer, APTR.Null, 6, 0, 11, 0);
            Assert.True(secondClipRect.IsNotNull);
            LayersClipRectCodec.WriteNext(ref memory, stableHead, secondClipRect);
            LayersClipRectCodec.WriteReservedLink(ref memory, secondClipRect,
                APTR.Null);
            secondClipRectLinked = true;
            Assert.True(PortableLayers.LayersClipRectAllocationCore
                .ValidateOwnedList(ref resources, stableHead, layer));

            // Finish the layer's private empty refresh before installing the
            // caller-owned damage region used to build the active projection.
            var initialBegin = new M68kCpuState { A = { [0] = destination.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), initialBegin));
            Assert.Equal(1u, initialBegin.D[0]);
            var initialEnd = new M68kCpuState
            {
                A = { [0] = destination.Layer }, D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), initialEnd));
            Assert.Equal(1u, initialEnd.D[0]);

            var newDamage = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newDamage));
            damageRegion = newDamage.D[0];
            Assert.NotEqual(0u, damageRegion);
            rectangle = AllocateGuestMemory(
                bus, (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 0, 0, 11, 0);
            var addDamage = new M68kCpuState
            {
                A = { [0] = damageRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                addDamage));
            Assert.Equal(1u, addDamage.D[0]);
            RetireOwnedDamageForCallerFixture(bus, boot, layer);
            LayersLayerCodec.WriteDamageList(ref memory, layer,
                APTR.FromPointer(damageRegion));
            var flagsBeforeUpdate = LayersLayerCodec.ReadFlags(ref memory, layer);
            LayersLayerCodec.WriteFlags(ref memory, layer,
                flagsBeforeUpdate | LayerFlags.Refresh);
            var damageBytes = SnapshotGraphicsRegion(bus, damageRegion);

            var begin = new M68kCpuState { A = { [0] = destination.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updateActive = true;
            var activeHead = LayersLayerCodec.ReadClipRect(ref memory, layer);
            Assert.NotEqual(stableHead.Raw, activeHead.Raw);
            var activeBounds = LayersClipRectCodec.ReadBounds(ref memory,
                activeHead);
            Assert.Equal((short)0, activeBounds.MinX);
            Assert.Equal((short)0, activeBounds.MinY);
            Assert.Equal((short)11, activeBounds.MaxX);
            Assert.Equal((short)0, activeBounds.MaxY);
            Assert.True(LayersClipRectCodec.ReadBitMap(ref memory,
                activeHead).IsNull);
            Assert.True(LayersClipRectCodec.ReadObscuringLayer(ref memory,
                activeHead).IsNull);
            Assert.True(LayersClipRectCodec.ReadNext(ref memory,
                activeHead).IsNull);

            ClearPlanarBitMap(bus, sourceBitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            var sourcePlane = ReadBitMapPlane(bus, sourceBitMap, 0);
            bus.WriteByte(sourcePlane, 0xFF, 0);
            bus.WriteByte(sourcePlane + 1, 0xFF, 0);
            var flagsBeforeRaster = ReadLayerFlags(bus, destination.Layer);
            var blit = new M68kCpuState
            {
                A = { [0] = sourceBitMap, [1] = destination.RastPort },
                D =
                {
                    [0] = 0, [1] = 0, [2] = 0, [3] = 0,
                    [4] = 16, [5] = 1, [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltBitMapRastPort),
                blit));

            for (var x = 0; x < 16; x++)
                Assert.Equal(x <= 11,
                    ReadPlanarBitMapPixel(bus, destination.BitMap, x, 0));
            for (var y = 1; y < 16; y++)
                for (var x = 0; x < 16; x++)
                    Assert.False(ReadPlanarBitMapPixel(
                        bus, destination.BitMap, x, y));
            Assert.Equal(flagsBeforeRaster,
                ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(activeHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, layer).Raw);
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            // With a one-pixel layer scroll, logical destination (1,1)..(12,1)
            // maps to this same screen-space damage row (0..11,0). The
            // requested logical rectangle still spans the surface, so source
            // selection advances by one in both axes while output remains in
            // the projected screen-space ClipRect.
            WriteLayerScroll(bus, destination.Layer, 1, 1);
            ClearPlanarBitMap(bus, sourceBitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            for (var y = 0; y < 16; y++)
            for (var x = 0; x < 16; x++)
            {
                if (((x + y) & 1) != 0)
                    continue;
                var address = sourcePlane +
                    checked((uint)(y * 2 + (x >> 3)));
                bus.WriteByte(address,
                    (byte)(bus.ReadByte(address) | (0x80 >> (x & 7))), 0);
            }
            var scrolledBlit = new M68kCpuState
            {
                A = { [0] = sourceBitMap, [1] = destination.RastPort },
                D =
                {
                    [0] = 0, [1] = 0, [2] = 0, [3] = 0,
                    [4] = 16, [5] = 16, [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltBitMapRastPort),
                scrolledBlit));
            Assert.Equal(1u, scrolledBlit.D[0]);
            for (var x = 0; x < 16; x++)
                Assert.Equal(x <= 11 && (x & 1) == 0,
                    ReadPlanarBitMapPixel(bus, destination.BitMap, x, 0));
            for (var y = 1; y < 16; y++)
                for (var x = 0; x < 16; x++)
                    Assert.False(ReadPlanarBitMapPixel(
                        bus, destination.BitMap, x, y));
            Assert.Equal(flagsBeforeRaster,
                ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(activeHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, layer).Raw);
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
            WriteLayerScroll(bus, destination.Layer, 0, 0);

            // Nonzero source and destination origins preserve their relative
            // copy delta after clipping the destination request at x=11.
            ClearPlanarBitMap(bus, sourceBitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            for (var x = 0; x < 16; x++)
            {
                if (x % 3 != 2)
                    continue;
                var address = sourcePlane + (uint)(x >> 3);
                bus.WriteByte(address,
                    (byte)(bus.ReadByte(address) | (0x80 >> (x & 7))), 0);
            }
            var offsetBlit = new M68kCpuState
            {
                A = { [0] = sourceBitMap, [1] = destination.RastPort },
                D =
                {
                    [0] = 2, [1] = 0, [2] = 4, [3] = 0,
                    [4] = 16, [5] = 1, [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltBitMapRastPort),
                offsetBlit));
            Assert.Equal(1u, offsetBlit.D[0]);
            for (var x = 0; x < 16; x++)
                Assert.Equal(x is 4 or 7 or 10,
                    ReadPlanarBitMapPixel(bus, destination.BitMap, x, 0));
            for (var y = 1; y < 16; y++)
                for (var x = 0; x < 16; x++)
                    Assert.False(ReadPlanarBitMapPixel(
                        bus, destination.BitMap, x, y));
            Assert.Equal(flagsBeforeRaster,
                ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(activeHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, layer).Raw);
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            // Source clipping removes the two negative source columns and
            // advances destination output by the same amount. Intersecting
            // that shifted request with damage x=0..11 leaves destination
            // x=6..11, sourced from x=0..5.
            ClearPlanarBitMap(bus, sourceBitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            for (var x = 0; x < 16; x++)
            {
                if (x % 3 != 0)
                    continue;
                var address = sourcePlane + (uint)(x >> 3);
                bus.WriteByte(address,
                    (byte)(bus.ReadByte(address) | (0x80 >> (x & 7))), 0);
            }
            var negativeSourceBlit = new M68kCpuState
            {
                A = { [0] = sourceBitMap, [1] = destination.RastPort },
                D =
                {
                    [0] = unchecked((uint)-2), [1] = 0,
                    [2] = 4, [3] = 0, [4] = 16, [5] = 1, [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltBitMapRastPort),
                negativeSourceBlit));
            Assert.Equal(1u, negativeSourceBlit.D[0]);
            for (var x = 0; x < 16; x++)
                Assert.Equal(x is 6 or 9,
                    ReadPlanarBitMapPixel(bus, destination.BitMap, x, 0));
            for (var y = 1; y < 16; y++)
                for (var x = 0; x < 16; x++)
                    Assert.False(ReadPlanarBitMapPixel(
                        bus, destination.BitMap, x, y));
            Assert.Equal(flagsBeforeRaster,
                ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(activeHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, layer).Raw);
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            // A negative destination origin clips the first two destination
            // columns and advances source selection to x=2, again preserving
            // the source-to-destination delta before damage clipping.
            ClearPlanarBitMap(bus, sourceBitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            for (var x = 0; x < 16; x++)
            {
                if (x % 3 != 2)
                    continue;
                var address = sourcePlane + (uint)(x >> 3);
                bus.WriteByte(address,
                    (byte)(bus.ReadByte(address) | (0x80 >> (x & 7))), 0);
            }
            var negativeDestinationBlit = new M68kCpuState
            {
                A = { [0] = sourceBitMap, [1] = destination.RastPort },
                D =
                {
                    [0] = 0, [1] = 0,
                    [2] = unchecked((uint)-2), [3] = 0,
                    [4] = 16, [5] = 1, [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltBitMapRastPort),
                negativeDestinationBlit));
            Assert.Equal(1u, negativeDestinationBlit.D[0]);
            for (var x = 0; x < 16; x++)
                Assert.Equal(x is 0 or 3 or 6 or 9,
                    ReadPlanarBitMapPixel(bus, destination.BitMap, x, 0));
            for (var y = 1; y < 16; y++)
                for (var x = 0; x < 16; x++)
                    Assert.False(ReadPlanarBitMapPixel(
                        bus, destination.BitMap, x, y));
            Assert.Equal(flagsBeforeRaster,
                ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(activeHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, layer).Raw);
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            // Mirror the horizontal origin checks on Y. First, source and
            // destination both begin two rows above the bitmap; source-bound
            // clipping advances both to row zero before damage admits it.
            ClearPlanarBitMap(bus, sourceBitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            for (var x = 0; x < 16; x++)
            {
                if (x % 3 != 1)
                    continue;
                var address = sourcePlane + (uint)(x >> 3);
                bus.WriteByte(address,
                    (byte)(bus.ReadByte(address) | (0x80 >> (x & 7))), 0);
            }
            var negativeSourceYBlit = new M68kCpuState
            {
                A = { [0] = sourceBitMap, [1] = destination.RastPort },
                D =
                {
                    [0] = 0, [1] = unchecked((uint)-2),
                    [2] = 0, [3] = unchecked((uint)-2),
                    [4] = 16, [5] = 16, [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltBitMapRastPort),
                negativeSourceYBlit));
            Assert.Equal(1u, negativeSourceYBlit.D[0]);
            for (var y = 0; y < 16; y++)
            for (var x = 0; x < 16; x++)
                Assert.Equal(y == 0 && x is 1 or 4 or 7 or 10,
                    ReadPlanarBitMapPixel(bus, destination.BitMap, x, y));
            Assert.Equal(flagsBeforeRaster,
                ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(activeHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, layer).Raw);
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            // Now clip only the destination's leading rows. The source start
            // advances from row zero to row two and damage admits output row 0.
            ClearPlanarBitMap(bus, sourceBitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            var sourceBytesPerRow = ReadBitMapBytesPerRow(bus, sourceBitMap);
            var sourceRow = sourcePlane +
                checked((uint)(2 * sourceBytesPerRow));
            for (var x = 0; x < 16; x++)
            {
                if (x % 3 != 2)
                    continue;
                var address = sourceRow + (uint)(x >> 3);
                bus.WriteByte(address,
                    (byte)(bus.ReadByte(address) | (0x80 >> (x & 7))), 0);
            }
            var negativeDestinationYBlit = new M68kCpuState
            {
                A = { [0] = sourceBitMap, [1] = destination.RastPort },
                D =
                {
                    [0] = 0, [1] = 0,
                    [2] = 0, [3] = unchecked((uint)-2),
                    [4] = 16, [5] = 16, [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltBitMapRastPort),
                negativeDestinationYBlit));
            Assert.Equal(1u, negativeDestinationYBlit.D[0]);
            for (var y = 0; y < 16; y++)
            for (var x = 0; x < 16; x++)
                Assert.Equal(y == 0 && x is 2 or 5 or 8 or 11,
                    ReadPlanarBitMapPixel(bus, destination.BitMap, x, y));
            Assert.Equal(flagsBeforeRaster,
                ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(activeHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, layer).Raw);
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            // Source tail clipping leaves source x=14..15, while destination
            // damage clips the corresponding x=11..12 span down to x=11.
            ClearPlanarBitMap(bus, sourceBitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            bus.WriteByte(sourcePlane + 1, 0x02, 0);
            var sourceTailBlit = new M68kCpuState
            {
                A = { [0] = sourceBitMap, [1] = destination.RastPort },
                D =
                {
                    [0] = 14, [1] = 0, [2] = 11, [3] = 0,
                    [4] = 16, [5] = 1, [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltBitMapRastPort),
                sourceTailBlit));
            Assert.Equal(1u, sourceTailBlit.D[0]);
            for (var x = 0; x < 16; x++)
                Assert.Equal(x == 11,
                    ReadPlanarBitMapPixel(bus, destination.BitMap, x, 0));
            for (var y = 1; y < 16; y++)
                for (var x = 0; x < 16; x++)
                    Assert.False(ReadPlanarBitMapPixel(
                        bus, destination.BitMap, x, y));
            Assert.Equal(flagsBeforeRaster,
                ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(activeHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, layer).Raw);
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            // The source tail contains rows 14..15, but the damage projection
            // admits only destination row zero, so only source row 14 can be
            // observed at the destination.
            ClearPlanarBitMap(bus, sourceBitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            var sourceTailBytesPerRow =
                ReadBitMapBytesPerRow(bus, sourceBitMap);
            var sourceTailRow = sourcePlane +
                checked((uint)(14 * sourceTailBytesPerRow));
            for (var x = 0; x < 16; x++)
            {
                if (x % 3 != 1)
                    continue;
                var address = sourceTailRow + (uint)(x >> 3);
                bus.WriteByte(address,
                    (byte)(bus.ReadByte(address) | (0x80 >> (x & 7))), 0);
            }
            var sourceTailYBlit = new M68kCpuState
            {
                A = { [0] = sourceBitMap, [1] = destination.RastPort },
                D =
                {
                    [0] = 0, [1] = 14, [2] = 0, [3] = 0,
                    [4] = 16, [5] = 16, [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltBitMapRastPort),
                sourceTailYBlit));
            Assert.Equal(1u, sourceTailYBlit.D[0]);
            for (var y = 0; y < 16; y++)
            for (var x = 0; x < 16; x++)
                Assert.Equal(y == 0 && x is 1 or 4 or 7 or 10,
                    ReadPlanarBitMapPixel(bus, destination.BitMap, x, y));
            Assert.Equal(flagsBeforeRaster,
                ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(activeHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, layer).Raw);
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var end = new M68kCpuState
            {
                A = { [0] = destination.Layer }, D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), end));
            Assert.Equal(1u, end.D[0]);
            updateActive = false;
            Assert.Equal(stableHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, layer).Raw);
            Assert.True(LayersLayerCodec.ReadSaveClipRects(ref memory,
                layer).IsNull);
            Assert.Equal(flagsBeforeUpdate | LayerFlags.Refresh,
                LayersLayerCodec.ReadFlags(ref memory, layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
        }
        finally
        {
            if (updateActive)
            {
                var abort = new M68kCpuState { A = { [0] = destination.Layer } };
                Assert.True(InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.EndUpdate), abort));
            }
            if (secondClipRect.IsNotNull && secondClipRectLinked)
            {
                LayersClipRectCodec.WriteNext(ref memory, stableHead,
                    APTR.Null);
                secondClipRectLinked = false;
            }
            LayersClipRectCodec.WriteBounds(ref memory, stableHead,
                originalStableBounds);
            if (secondClipRect.IsNotNull)
                Assert.True(PortableLayers.LayersClipRectAllocationCore.FreeList(
                    ref resources, secondClipRect));
            LayersLayerCodec.WriteDamageList(ref memory, layer, APTR.Null);
            DeleteLayer(bus, libraryBase, destination.Layer);
            if (damageRegion != 0)
            {
                var dispose = new M68kCpuState { A = { [0] = damageRegion } };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (rectangle != 0)
                FreeGuestMemory(bus, rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, sourceBitMap);
            FreeBitMap(bus, destination.BitMap);
        }
    }

    [Fact]
    public void ActiveUpdateCoalescedProjectionRestrictsMaskedBitMapRastPortBlitToDamageUnion()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var destination = CreateLayer(bus, libraryBase, layerInfo, 0, 0, 15, 15);
        var sourceBitMap = AllocatePlanarBitMap(bus, 16, 16);
        var maskPlane = AllocateGuestMemory(bus, 32);
        var memory = new LayersTestGuestMemory(bus);
        var resources = new BootLayersResourcePlatform(bus);
        var layer = APTR.FromPointer(destination.Layer);
        var stableHead = APTR.FromPointer(destination.FirstClipRect);
        var originalStableBounds = LayersClipRectCodec.ReadBounds(
            ref memory, stableHead);
        var secondClipRect = APTR.Null;
        var secondClipRectLinked = false;
        uint damageRegion = 0;
        uint rectangle = 0;
        var updateActive = false;

        try
        {
            LayersClipRectCodec.WriteBounds(ref memory, stableHead,
                LayersRectangleCodec.Create(0, 0, 5, 0));
            secondClipRect = PortableLayers.LayersClipRectAllocationCore
                .AllocateSingle(ref resources, layer, APTR.Null, 6, 0, 11, 0);
            Assert.True(secondClipRect.IsNotNull);
            LayersClipRectCodec.WriteNext(ref memory, stableHead, secondClipRect);
            LayersClipRectCodec.WriteReservedLink(ref memory, secondClipRect,
                APTR.Null);
            secondClipRectLinked = true;
            Assert.True(PortableLayers.LayersClipRectAllocationCore
                .ValidateOwnedList(ref resources, stableHead, layer));

            var initialBegin = new M68kCpuState { A = { [0] = destination.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), initialBegin));
            Assert.Equal(1u, initialBegin.D[0]);
            var initialEnd = new M68kCpuState
            {
                A = { [0] = destination.Layer }, D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), initialEnd));
            Assert.Equal(1u, initialEnd.D[0]);

            var newDamage = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newDamage));
            damageRegion = newDamage.D[0];
            Assert.NotEqual(0u, damageRegion);
            rectangle = AllocateGuestMemory(
                bus, (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 0, 0, 11, 0);
            var addDamage = new M68kCpuState
            {
                A = { [0] = damageRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                addDamage));
            Assert.Equal(1u, addDamage.D[0]);
            RetireOwnedDamageForCallerFixture(bus, boot, layer);
            LayersLayerCodec.WriteDamageList(ref memory, layer,
                APTR.FromPointer(damageRegion));
            var flagsBeforeUpdate = LayersLayerCodec.ReadFlags(ref memory, layer);
            LayersLayerCodec.WriteFlags(ref memory, layer,
                flagsBeforeUpdate | LayerFlags.Refresh);
            var damageBytes = SnapshotGraphicsRegion(bus, damageRegion);

            var begin = new M68kCpuState { A = { [0] = destination.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updateActive = true;
            var activeHead = LayersLayerCodec.ReadClipRect(ref memory, layer);
            Assert.NotEqual(stableHead.Raw, activeHead.Raw);
            var activeBounds = LayersClipRectCodec.ReadBounds(ref memory,
                activeHead);
            Assert.Equal((short)0, activeBounds.MinX);
            Assert.Equal((short)0, activeBounds.MinY);
            Assert.Equal((short)11, activeBounds.MaxX);
            Assert.Equal((short)0, activeBounds.MaxY);
            Assert.True(LayersClipRectCodec.ReadBitMap(ref memory,
                activeHead).IsNull);
            Assert.True(LayersClipRectCodec.ReadObscuringLayer(ref memory,
                activeHead).IsNull);
            Assert.True(LayersClipRectCodec.ReadNext(ref memory,
                activeHead).IsNull);

            ClearPlanarBitMap(bus, sourceBitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            var sourcePlane = ReadBitMapPlane(bus, sourceBitMap, 0);
            bus.WriteByte(sourcePlane, 0xFF, 0);
            bus.WriteByte(sourcePlane + 1, 0xFF, 0);
            bus.WriteByte(maskPlane, 0xAA, 0);
            bus.WriteByte(maskPlane + 1, 0xAA, 0);
            var flagsBeforeRaster = ReadLayerFlags(bus, destination.Layer);
            var blit = new M68kCpuState
            {
                A =
                {
                    [0] = sourceBitMap,
                    [1] = destination.RastPort,
                    [2] = maskPlane
                },
                D =
                {
                    [0] = 0, [1] = 0, [2] = 0, [3] = 0,
                    [4] = 16, [5] = 1, [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltMaskBitMapRastPort),
                blit));
            Assert.Equal(0u, blit.D[0]);

            for (var x = 0; x < 16; x++)
                Assert.Equal(x <= 11 && (x & 1) == 0,
                    ReadPlanarBitMapPixel(bus, destination.BitMap, x, 0));
            for (var y = 1; y < 16; y++)
                for (var x = 0; x < 16; x++)
                    Assert.False(ReadPlanarBitMapPixel(
                        bus, destination.BitMap, x, y));
            Assert.Equal((byte)0xAA, bus.ReadByte(maskPlane));
            Assert.Equal((byte)0xAA, bus.ReadByte(maskPlane + 1));

            // Exercise mask and source addressing through the same scroll:
            // screen damage (0..11,0) maps to source/mask (1..12,1). Only
            // mask bit (1,1) is set, so exactly screen pixel (0,0) is copied.
            WriteLayerScroll(bus, destination.Layer, 1, 1);
            ClearPlanarBitMap(bus, sourceBitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            var sourceBytesPerRow = ReadBitMapBytesPerRow(bus, sourceBitMap);
            for (var y = 0; y < 16; y++)
            for (var x = 0; x < 16; x++)
            {
                if (((x + y) & 1) != 0)
                    continue;
                var address = sourcePlane +
                    checked((uint)(y * sourceBytesPerRow + (x >> 3)));
                bus.WriteByte(address,
                    (byte)(bus.ReadByte(address) | (0x80 >> (x & 7))), 0);
            }
            var scrolledMask = new byte[32];
            scrolledMask[2] = 0x40;
            for (var index = 0; index < scrolledMask.Length; index++)
                bus.WriteByte(maskPlane + (uint)index, scrolledMask[index], 0);
            var scrolledBlit = new M68kCpuState
            {
                A =
                {
                    [0] = sourceBitMap,
                    [1] = destination.RastPort,
                    [2] = maskPlane
                },
                D =
                {
                    [0] = 0, [1] = 0, [2] = 0, [3] = 0,
                    [4] = 16, [5] = 16, [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltMaskBitMapRastPort),
                scrolledBlit));
            Assert.Equal(0u, scrolledBlit.D[0]);
            for (var y = 0; y < 16; y++)
            for (var x = 0; x < 16; x++)
                Assert.Equal(x == 0 && y == 0,
                    ReadPlanarBitMapPixel(bus, destination.BitMap, x, y));
            for (var index = 0; index < scrolledMask.Length; index++)
                Assert.Equal(scrolledMask[index],
                    bus.ReadByte(maskPlane + (uint)index));
            Assert.Equal(flagsBeforeRaster,
                ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(activeHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, layer).Raw);
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
            WriteLayerScroll(bus, destination.Layer, 0, 0);

            // Nonzero origins share one clipping delta across source, mask,
            // destination, and the coalesced active damage. Source/mask x=9
            // maps to destination x=11, the damage projection's right edge.
            ClearPlanarBitMap(bus, sourceBitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            bus.WriteByte(sourcePlane + 1, 0x40, 0);
            var offsetMask = new byte[32];
            offsetMask[1] = 0x40;
            for (var index = 0; index < offsetMask.Length; index++)
                bus.WriteByte(maskPlane + (uint)index, offsetMask[index], 0);
            var offsetMaskedBlit = new M68kCpuState
            {
                A =
                {
                    [0] = sourceBitMap,
                    [1] = destination.RastPort,
                    [2] = maskPlane
                },
                D =
                {
                    [0] = 2, [1] = 0, [2] = 4, [3] = 0,
                    [4] = 16, [5] = 1, [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltMaskBitMapRastPort),
                offsetMaskedBlit));
            Assert.Equal(0u, offsetMaskedBlit.D[0]);
            for (var x = 0; x < 16; x++)
                Assert.Equal(x == 11,
                    ReadPlanarBitMapPixel(bus, destination.BitMap, x, 0));
            for (var y = 1; y < 16; y++)
                for (var x = 0; x < 16; x++)
                    Assert.False(ReadPlanarBitMapPixel(
                        bus, destination.BitMap, x, y));
            for (var index = 0; index < offsetMask.Length; index++)
                Assert.Equal(offsetMask[index],
                    bus.ReadByte(maskPlane + (uint)index));
            Assert.Equal(flagsBeforeRaster,
                ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(activeHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, layer).Raw);
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            // A negative source origin is clipped before mask lookup. Source
            // and mask x=3 therefore map together to destination x=9 after
            // the two-column destination advance and damage intersection.
            ClearPlanarBitMap(bus, sourceBitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            bus.WriteByte(sourcePlane, 0x10, 0);
            var negativeSourceMask = new byte[32];
            negativeSourceMask[0] = 0x10;
            for (var index = 0; index < negativeSourceMask.Length; index++)
                bus.WriteByte(
                    maskPlane + (uint)index, negativeSourceMask[index], 0);
            var negativeSourceMaskedBlit = new M68kCpuState
            {
                A =
                {
                    [0] = sourceBitMap,
                    [1] = destination.RastPort,
                    [2] = maskPlane
                },
                D =
                {
                    [0] = unchecked((uint)-2), [1] = 0,
                    [2] = 4, [3] = 0, [4] = 16, [5] = 1, [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltMaskBitMapRastPort),
                negativeSourceMaskedBlit));
            Assert.Equal(0u, negativeSourceMaskedBlit.D[0]);
            for (var x = 0; x < 16; x++)
                Assert.Equal(x == 9,
                    ReadPlanarBitMapPixel(bus, destination.BitMap, x, 0));
            for (var y = 1; y < 16; y++)
                for (var x = 0; x < 16; x++)
                    Assert.False(ReadPlanarBitMapPixel(
                        bus, destination.BitMap, x, y));
            for (var index = 0; index < negativeSourceMask.Length; index++)
                Assert.Equal(negativeSourceMask[index],
                    bus.ReadByte(maskPlane + (uint)index));
            Assert.Equal(flagsBeforeRaster,
                ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(activeHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, layer).Raw);
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            // Clipping the negative destination origin advances source and
            // mask together: source/mask x=5 maps to destination x=3.
            ClearPlanarBitMap(bus, sourceBitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            bus.WriteByte(sourcePlane, 0x04, 0);
            var negativeDestinationMask = new byte[32];
            negativeDestinationMask[0] = 0x04;
            for (var index = 0; index < negativeDestinationMask.Length; index++)
                bus.WriteByte(
                    maskPlane + (uint)index, negativeDestinationMask[index], 0);
            var negativeDestinationMaskedBlit = new M68kCpuState
            {
                A =
                {
                    [0] = sourceBitMap,
                    [1] = destination.RastPort,
                    [2] = maskPlane
                },
                D =
                {
                    [0] = 0, [1] = 0, [2] = unchecked((uint)-2),
                    [3] = 0, [4] = 16, [5] = 1, [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltMaskBitMapRastPort),
                negativeDestinationMaskedBlit));
            Assert.Equal(0u, negativeDestinationMaskedBlit.D[0]);
            for (var y = 0; y < 16; y++)
                for (var x = 0; x < 16; x++)
                    Assert.Equal(x == 3 && y == 0,
                        ReadPlanarBitMapPixel(bus, destination.BitMap, x, y));
            for (var index = 0; index < negativeDestinationMask.Length; index++)
                Assert.Equal(negativeDestinationMask[index],
                    bus.ReadByte(maskPlane + (uint)index));
            Assert.Equal(flagsBeforeRaster,
                ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(activeHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, layer).Raw);
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var end = new M68kCpuState
            {
                A = { [0] = destination.Layer }, D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), end));
            Assert.Equal(1u, end.D[0]);
            updateActive = false;
            Assert.Equal(stableHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, layer).Raw);
            Assert.True(LayersLayerCodec.ReadSaveClipRects(ref memory,
                layer).IsNull);
            Assert.Equal(flagsBeforeUpdate | LayerFlags.Refresh,
                LayersLayerCodec.ReadFlags(ref memory, layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
        }
        finally
        {
            if (updateActive)
            {
                var abort = new M68kCpuState { A = { [0] = destination.Layer } };
                Assert.True(InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.EndUpdate), abort));
            }
            if (secondClipRect.IsNotNull && secondClipRectLinked)
            {
                LayersClipRectCodec.WriteNext(ref memory, stableHead,
                    APTR.Null);
                secondClipRectLinked = false;
            }
            LayersClipRectCodec.WriteBounds(ref memory, stableHead,
                originalStableBounds);
            if (secondClipRect.IsNotNull)
                Assert.True(PortableLayers.LayersClipRectAllocationCore.FreeList(
                    ref resources, secondClipRect));
            LayersLayerCodec.WriteDamageList(ref memory, layer, APTR.Null);
            DeleteLayer(bus, libraryBase, destination.Layer);
            if (damageRegion != 0)
            {
                var dispose = new M68kCpuState { A = { [0] = damageRegion } };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (rectangle != 0)
                FreeGuestMemory(bus, rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, sourceBitMap);
            FreeBitMap(bus, destination.BitMap);
            FreeGuestMemory(bus, maskPlane, 32);
        }
    }

    [Fact]
    public void ActiveUpdateCoalescedClipBlitProjectionsIntersectAtBothEndpointsWithIndependentScroll()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var sourceInfo = NewLayerInfo(bus, libraryBase);
        var destinationInfo = NewLayerInfo(bus, libraryBase);
        var source = CreateLayer(bus, libraryBase, sourceInfo, 0, 0, 15, 15);
        var destination = CreateLayer(
            bus, libraryBase, destinationInfo, 0, 0, 15, 15);
        var memory = new LayersTestGuestMemory(bus);
        var resources = new BootLayersResourcePlatform(bus);
        var sourceLayer = APTR.FromPointer(source.Layer);
        var destinationLayer = APTR.FromPointer(destination.Layer);
        var sourceStableHead = APTR.FromPointer(source.FirstClipRect);
        var destinationStableHead = APTR.FromPointer(
            destination.FirstClipRect);
        var originalSourceBounds = LayersClipRectCodec.ReadBounds(
            ref memory, sourceStableHead);
        var originalDestinationBounds = LayersClipRectCodec.ReadBounds(
            ref memory, destinationStableHead);
        var secondSourceClipRect = APTR.Null;
        var secondDestinationClipRect = APTR.Null;
        var secondSourceClipRectLinked = false;
        var secondDestinationClipRectLinked = false;
        uint sourceDamageRegion = 0;
        uint destinationDamageRegion = 0;
        uint sourceRectangle = 0;
        uint destinationRectangle = 0;
        var sourceUpdateActive = false;
        var destinationUpdateActive = false;
        const short sourceScrollX = 2;
        const short sourceScrollY = 1;
        const short destinationScrollX = -1;
        const short destinationScrollY = 2;

        try
        {
            LayersClipRectCodec.WriteBounds(ref memory, sourceStableHead,
                LayersRectangleCodec.Create(0, 0, 5, 5));
            secondSourceClipRect = PortableLayers.LayersClipRectAllocationCore
                .AllocateSingle(ref resources, sourceLayer, APTR.Null,
                    6, 0, 11, 5);
            Assert.True(secondSourceClipRect.IsNotNull);
            LayersClipRectCodec.WriteNext(ref memory, sourceStableHead,
                secondSourceClipRect);
            LayersClipRectCodec.WriteReservedLink(ref memory,
                secondSourceClipRect, APTR.Null);
            secondSourceClipRectLinked = true;

            LayersClipRectCodec.WriteBounds(ref memory, destinationStableHead,
                LayersRectangleCodec.Create(4, 1, 9, 6));
            secondDestinationClipRect =
                PortableLayers.LayersClipRectAllocationCore.AllocateSingle(
                    ref resources, destinationLayer, APTR.Null,
                    10, 1, 15, 6);
            Assert.True(secondDestinationClipRect.IsNotNull);
            LayersClipRectCodec.WriteNext(ref memory,
                destinationStableHead, secondDestinationClipRect);
            LayersClipRectCodec.WriteReservedLink(ref memory,
                secondDestinationClipRect, APTR.Null);
            secondDestinationClipRectLinked = true;

            CompleteEmptyUpdate(source.Layer);
            CompleteEmptyUpdate(destination.Layer);
            (sourceDamageRegion, sourceRectangle) =
                CreateDamageRegion(0, 11, 0, 5);
            (destinationDamageRegion, destinationRectangle) =
                CreateDamageRegion(4, 15, 1, 6);
            RetireOwnedDamageForCallerFixture(bus, boot, sourceLayer);
            LayersLayerCodec.WriteDamageList(ref memory, sourceLayer,
                APTR.FromPointer(sourceDamageRegion));
            RetireOwnedDamageForCallerFixture(bus, boot, destinationLayer);
            LayersLayerCodec.WriteDamageList(ref memory, destinationLayer,
                APTR.FromPointer(destinationDamageRegion));
            var sourceFlagsBeforeUpdate = LayersLayerCodec.ReadFlags(
                ref memory, sourceLayer);
            var destinationFlagsBeforeUpdate = LayersLayerCodec.ReadFlags(
                ref memory, destinationLayer);
            LayersLayerCodec.WriteFlags(ref memory, sourceLayer,
                sourceFlagsBeforeUpdate | LayerFlags.Refresh);
            LayersLayerCodec.WriteFlags(ref memory, destinationLayer,
                destinationFlagsBeforeUpdate | LayerFlags.Refresh);
            var sourceDamageBytes = SnapshotGraphicsRegion(
                bus, sourceDamageRegion);
            var destinationDamageBytes = SnapshotGraphicsRegion(
                bus, destinationDamageRegion);

            var beginSource = new M68kCpuState
            {
                A = { [0] = source.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), beginSource));
            Assert.Equal(1u, beginSource.D[0]);
            sourceUpdateActive = true;
            var beginDestination = new M68kCpuState
            {
                A = { [0] = destination.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                beginDestination));
            Assert.Equal(1u, beginDestination.D[0]);
            destinationUpdateActive = true;

            var sourceActiveHead = LayersLayerCodec.ReadClipRect(
                ref memory, sourceLayer);
            var destinationActiveHead = LayersLayerCodec.ReadClipRect(
                ref memory, destinationLayer);
            AssertCoalescedHead(sourceActiveHead, 0, 0, 11, 5);
            AssertCoalescedHead(destinationActiveHead, 4, 1, 15, 6);
            var sourceProjection = LayersClipRectCodec.ReadBounds(
                ref memory, sourceActiveHead);
            var destinationProjection = LayersClipRectCodec.ReadBounds(
                ref memory, destinationActiveHead);

            ClearPlanarBitMap(bus, source.BitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            var sourcePlane = ReadBitMapPlane(bus, source.BitMap, 0);
            var sourceBytesPerRow = ReadBitMapBytesPerRow(bus, source.BitMap);
            for (var y = 0; y <= 5; y++)
            {
                var row = sourcePlane + checked((uint)(y * sourceBytesPerRow));
                bus.WriteByte(row, 0xFF, 0);
                bus.WriteByte(row + 1, 0xFF, 0);
            }
            var sourceFlagsBeforeRaster = ReadLayerFlags(bus, source.Layer);
            var destinationFlagsBeforeRaster =
                ReadLayerFlags(bus, destination.Layer);
            var blit = new M68kCpuState
            {
                A =
                {
                    [0] = source.RastPort,
                    [1] = destination.RastPort
                },
                D =
                {
                    [0] = 0,
                    [1] = 0,
                    [2] = 0,
                    [3] = 0,
                    [4] = 16,
                    [5] = 16,
                    [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ClipBlit),
                blit));

            for (var y = 0; y < 16; y++)
            for (var x = 0; x < 16; x++)
                Assert.Equal(x is >= 4 and <= 11 && y is >= 1 and <= 5,
                    ReadPlanarBitMapPixel(bus, destination.BitMap, x, y));

            // Re-run both coalesced projections through different logical
            // X/Y transforms. Public ClipRects stay in screen coordinates;
            // the destination screen cell maps through logical coordinates
            // to the independently scrolled source screen cell.
            WriteLayerScroll(
                bus, source.Layer, sourceScrollX, sourceScrollY);
            WriteLayerScroll(
                bus, destination.Layer, destinationScrollX,
                destinationScrollY);
            ClearPlanarBitMap(bus, source.BitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            var patternedSourcePlane = ReadBitMapPlane(bus, source.BitMap, 0);
            var sourcePattern = new bool[16, 16];
            for (var y = 0; y < 16; y++)
            for (var x = 0; x < 16; x++)
            {
                sourcePattern[y, x] = (x + (2 * y)) % 3 == 0;
                if (!sourcePattern[y, x]) continue;
                var byteAddress = patternedSourcePlane +
                    checked((uint)(y * sourceBytesPerRow + (x >> 3)));
                var value = bus.ReadByte(byteAddress);
                bus.WriteByte(
                    byteAddress,
                    (byte)(value | (0x80 >> (x & 7))),
                    0);
            }
            var scrolledBlit = new M68kCpuState
            {
                A =
                {
                    [0] = source.RastPort,
                    [1] = destination.RastPort
                },
                D =
                {
                    [0] = 0,
                    [1] = 0,
                    [2] = 0,
                    [3] = 0,
                    [4] = 16,
                    [5] = 16,
                    [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ClipBlit),
                scrolledBlit));
            for (var y = 0; y < 16; y++)
            for (var x = 0; x < 16; x++)
            {
                var logicalX = x + destinationScrollX;
                var logicalY = y + destinationScrollY;
                var sourceScreenX = logicalX - sourceScrollX;
                var sourceScreenY = logicalY - sourceScrollY;
                var expected = x >= destinationProjection.MinX &&
                    x <= destinationProjection.MaxX &&
                    y >= destinationProjection.MinY &&
                    y <= destinationProjection.MaxY &&
                    logicalX is >= 0 and < 16 && logicalY is >= 0 and < 16 &&
                    sourceScreenX >= sourceProjection.MinX &&
                    sourceScreenX <= sourceProjection.MaxX &&
                    sourceScreenY >= sourceProjection.MinY &&
                    sourceScreenY <= sourceProjection.MaxY &&
                    sourcePattern[sourceScreenY, sourceScreenX];
                Assert.Equal(expected,
                    ReadPlanarBitMapPixel(bus, destination.BitMap, x, y));
            }
            Assert.Equal(sourceActiveHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, sourceLayer).Raw);
            Assert.Equal(destinationActiveHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory,
                    destinationLayer).Raw);
            Assert.Equal(sourceFlagsBeforeRaster,
                ReadLayerFlags(bus, source.Layer));
            Assert.Equal(destinationFlagsBeforeRaster,
                ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(sourceDamageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, sourceLayer).Raw);
            Assert.Equal(destinationDamageRegion,
                LayersLayerCodec.ReadDamageList(
                    ref memory, destinationLayer).Raw);
            Assert.Equal(sourceDamageBytes,
                SnapshotGraphicsRegion(bus, sourceDamageRegion));
            Assert.Equal(destinationDamageBytes,
                SnapshotGraphicsRegion(bus, destinationDamageRegion));

            var endDestination = new M68kCpuState
            {
                A = { [0] = destination.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                endDestination));
            Assert.Equal(1u, endDestination.D[0]);
            destinationUpdateActive = false;
            var endSource = new M68kCpuState
            {
                A = { [0] = source.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), endSource));
            Assert.Equal(1u, endSource.D[0]);
            sourceUpdateActive = false;

            Assert.Equal(sourceStableHead.Raw,
                LayersLayerCodec.ReadClipRect(ref memory, sourceLayer).Raw);
            Assert.Equal(destinationStableHead.Raw,
                LayersLayerCodec.ReadClipRect(
                    ref memory, destinationLayer).Raw);
            Assert.Equal(sourceFlagsBeforeUpdate | LayerFlags.Refresh,
                LayersLayerCodec.ReadFlags(ref memory, sourceLayer));
            Assert.Equal(
                destinationFlagsBeforeUpdate | LayerFlags.Refresh,
                LayersLayerCodec.ReadFlags(ref memory, destinationLayer));
            Assert.Equal(sourceDamageRegion,
                LayersLayerCodec.ReadDamageList(ref memory, sourceLayer).Raw);
            Assert.Equal(destinationDamageRegion,
                LayersLayerCodec.ReadDamageList(
                    ref memory, destinationLayer).Raw);
            Assert.Equal(sourceDamageBytes,
                SnapshotGraphicsRegion(bus, sourceDamageRegion));
            Assert.Equal(destinationDamageBytes,
                SnapshotGraphicsRegion(bus, destinationDamageRegion));
        }
        finally
        {
            WriteLayerScroll(bus, source.Layer, 0, 0);
            WriteLayerScroll(bus, destination.Layer, 0, 0);
            if (destinationUpdateActive)
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate),
                    new M68kCpuState { A = { [0] = destination.Layer } });
            if (sourceUpdateActive)
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate),
                    new M68kCpuState { A = { [0] = source.Layer } });

            if (secondSourceClipRect.IsNotNull && secondSourceClipRectLinked)
                LayersClipRectCodec.WriteNext(ref memory, sourceStableHead,
                    APTR.Null);
            if (secondDestinationClipRect.IsNotNull &&
                secondDestinationClipRectLinked)
                LayersClipRectCodec.WriteNext(ref memory,
                    destinationStableHead, APTR.Null);
            LayersClipRectCodec.WriteBounds(ref memory, sourceStableHead,
                originalSourceBounds);
            LayersClipRectCodec.WriteBounds(ref memory,
                destinationStableHead, originalDestinationBounds);
            if (secondSourceClipRect.IsNotNull)
                Assert.True(PortableLayers.LayersClipRectAllocationCore.FreeList(
                    ref resources, secondSourceClipRect));
            if (secondDestinationClipRect.IsNotNull)
                Assert.True(PortableLayers.LayersClipRectAllocationCore.FreeList(
                    ref resources, secondDestinationClipRect));
            LayersLayerCodec.WriteDamageList(ref memory, sourceLayer,
                APTR.Null);
            LayersLayerCodec.WriteDamageList(ref memory, destinationLayer,
                APTR.Null);
            DeleteLayer(bus, libraryBase, destination.Layer);
            DeleteLayer(bus, libraryBase, source.Layer);
            DisposeRegion(sourceDamageRegion);
            DisposeRegion(destinationDamageRegion);
            if (sourceRectangle != 0)
                FreeGuestMemory(bus, sourceRectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            if (destinationRectangle != 0)
                FreeGuestMemory(bus, destinationRectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            DisposeLayerInfo(bus, libraryBase, destinationInfo);
            DisposeLayerInfo(bus, libraryBase, sourceInfo);
            FreeBitMap(bus, destination.BitMap);
            FreeBitMap(bus, source.BitMap);
        }

        void CompleteEmptyUpdate(uint layerAddress)
        {
            var begin = new M68kCpuState { A = { [0] = layerAddress } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            var end = new M68kCpuState
            {
                A = { [0] = layerAddress },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), end));
            Assert.Equal(1u, end.D[0]);
        }

        (uint Region, uint Rectangle) CreateDamageRegion(
            short minX, short maxX, short minY, short maxY)
        {
            var created = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                created));
            Assert.NotEqual(0u, created.D[0]);
            var allocatedRectangle = AllocateGuestMemory(
                bus, (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(
                bus, allocatedRectangle, minX, minY, maxX, maxY);
            var added = new M68kCpuState
            {
                A = { [0] = created.D[0], [1] = allocatedRectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                added));
            Assert.Equal(1u, added.D[0]);
            return (created.D[0], allocatedRectangle);
        }

        void AssertCoalescedHead(
            APTR head, short minX, short minY, short maxX, short maxY)
        {
            var bounds = LayersClipRectCodec.ReadBounds(ref memory, head);
            Assert.Equal(minX, bounds.MinX);
            Assert.Equal(minY, bounds.MinY);
            Assert.Equal(maxX, bounds.MaxX);
            Assert.Equal(maxY, bounds.MaxY);
            Assert.True(LayersClipRectCodec.ReadBitMap(ref memory, head).IsNull);
            Assert.True(LayersClipRectCodec.ReadObscuringLayer(
                ref memory, head).IsNull);
            Assert.True(LayersClipRectCodec.ReadNext(ref memory, head).IsNull);
        }

        void DisposeRegion(uint region)
        {
            if (region == 0) return;
            var dispose = new M68kCpuState { A = { [0] = region } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.DisposeRegion),
                dispose));
        }
    }

    [Fact]
    public void LayeredGraphicsGatewayProjectsBothClipBlitPartitionsWithoutPublishingDamage()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var sourceInfo = NewLayerInfo(bus, libraryBase);
        var destinationInfo = NewLayerInfo(bus, libraryBase);
        var source = CreateLayer(bus, libraryBase, sourceInfo, 0, 0, 15, 15);
        var destination = CreateLayer(
            bus,
            libraryBase,
            destinationInfo,
            0,
            0,
            15,
            15);
        var layerMemory = new LayersTestGuestMemory(bus);
        var sourceClipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(source.FirstClipRect)).Raw;
        var destinationClipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(destination.FirstClipRect)).Raw;
        var sourceBounds = new ushort[4];
        var destinationBounds = new ushort[4];
        for (var index = 0; index < sourceBounds.Length; index++)
        {
            var offset = checked((uint)(index * 2));
            sourceBounds[index] = bus.ReadWord(sourceClipBounds + offset);
            destinationBounds[index] = bus.ReadWord(
                destinationClipBounds + offset);
        }

        try
        {
            // The source admits the complete eight-pixel span while the
            // destination admits only x=0..4.  The gateway must pass both
            // exact published heads to the validated provider; a fallback
            // that clips only the destination or ignores the source head
            // would not have the same two-endpoint contract.
            WriteRectangleBounds(bus, sourceClipBounds, 0, 0, 7, 0);
            WriteRectangleBounds(bus, destinationClipBounds, 0, 0, 4, 0);
            ClearPlanarBitMap(bus, source.BitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            var sourcePlane = ReadBitMapPlane(bus, source.BitMap, 0);
            bus.WriteByte(sourcePlane, 0xFF, 0);

            var sourceFlagsBeforeRaster = ReadLayerFlags(bus, source.Layer);
            var destinationFlagsBeforeRaster = ReadLayerFlags(
                bus,
                destination.Layer);
            var sourceDamageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(source.Layer)).Raw;
            var destinationDamageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(destination.Layer)).Raw;

            var blit = new M68kCpuState
            {
                A =
                {
                    [0] = source.RastPort,
                    [1] = destination.RastPort
                },
                D =
                {
                    [0] = 0,
                    [1] = 0,
                    [2] = 0,
                    [3] = 0,
                    [4] = 8,
                    [5] = 1,
                    [6] = 0xC0,
                    [7] = 0xD7D7_7007
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ClipBlit),
                blit));

            // The destination's x=5..7 tail remains clear because its
            // published ClipRect is the authoritative second endpoint.
            Assert.Equal(
                (byte)0xF8,
                bus.ReadByte(ReadBitMapPlane(bus, destination.BitMap, 0)));
            Assert.Equal(
                destination.FirstClipRect,
                ReadLayerClipRect(bus, destination.Layer));
            Assert.Equal(sourceFlagsBeforeRaster, ReadLayerFlags(bus, source.Layer));
            Assert.Equal(
                destinationFlagsBeforeRaster,
                ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(
                sourceDamageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(source.Layer)).Raw);
            Assert.Equal(
                destinationDamageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(destination.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < sourceBounds.Length; index++)
            {
                var offset = checked((uint)(index * 2));
                bus.WriteWord(sourceClipBounds + offset, sourceBounds[index]);
                bus.WriteWord(
                    destinationClipBounds + offset,
                    destinationBounds[index]);
            }
            DeleteLayer(bus, libraryBase, source.Layer);
            DeleteLayer(bus, libraryBase, destination.Layer);
            DisposeLayerInfo(bus, libraryBase, sourceInfo);
            DisposeLayerInfo(bus, libraryBase, destinationInfo);
            FreeBitMap(bus, source.BitMap);
            FreeBitMap(bus, destination.BitMap);
        }
    }

    [Fact]
    public void LayeredGraphicsGatewayClipBlitIntersectsSourceAndActiveDamagePartitions()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var destinationInfo = NewLayerInfo(bus, libraryBase);
        var sourceInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var sourceBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            destinationInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            31,
            19);
        var top = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            destinationInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            15,
            15);
        var source = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            sourceInfo,
            sourceBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            31,
            19);
        var layerMemory = new LayersTestGuestMemory(bus);
        var sourceClipHead = ReadLayerClipRect(bus, source.Layer);
        var sourceClipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(sourceClipHead)).Raw;
        var savedSourceBounds = new ushort[4];
        for (var index = 0; index < savedSourceBounds.Length; index++)
            savedSourceBounds[index] = bus.ReadWord(
                sourceClipBounds + checked((uint)(index * 2)));
        var stableDestinationHead = ReadLayerClipRect(bus, bottom.Layer);
        var updateActive = false;

        try
        {
            var stableDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(LayersRegionCodec.ReadFirst(
                ref layerMemory,
                stableDamage).IsNull);

            var move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveLayer),
                move));
            Assert.Equal(1u, move.D[0]);
            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNotNull);
            var damageBytes = Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray();

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updateActive = true;
            var updateHead = ReadLayerClipRect(bus, bottom.Layer);
            Assert.NotEqual(stableDestinationHead, updateHead);
            var destinationFlagsBeforeRaster = ReadLayerFlags(bus, bottom.Layer);
            var sourceFlagsBeforeRaster = ReadLayerFlags(bus, source.Layer);
            var sourceDamageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(source.Layer)).Raw;
            var admittedBounds = new List<(short MinX, short MinY, short MaxX, short MaxY)>();
            for (var clipRect = updateHead;
                clipRect != 0;
                clipRect = ReadClipRectNext(bus, clipRect))
            {
                var bounds = LayersClipRectCodec.BoundsAddress(
                    APTR.FromPointer(clipRect)).Raw;
                admittedBounds.Add((
                    unchecked((short)bus.ReadWord(bounds)),
                    unchecked((short)bus.ReadWord(bounds + 2)),
                    unchecked((short)bus.ReadWord(bounds + 4)),
                    unchecked((short)bus.ReadWord(bounds + 6))));
            }
            Assert.NotEmpty(admittedBounds);

            ClearPlanarBitMap(bus, displayBitMap);
            ClearPlanarBitMap(bus, sourceBitMap);
            var sourcePlane = ReadBitMapPlane(bus, sourceBitMap, 0);
            for (uint offset = 0; offset < 4u * 20u; offset++)
                bus.WriteByte(sourcePlane + offset, 0xFF, 0);

            // First restrict only the source endpoint. The destination's
            // active damage list is broader, so exactly source x=4..5/y=4
            // should be copied through the intersection.
            WriteRectangleBounds(bus, sourceClipBounds, 4, 4, 5, 4);
            var blit = new M68kCpuState
            {
                A = { [0] = source.RastPort, [1] = bottom.RastPort },
                D =
                {
                    [0] = 0,
                    [1] = 0,
                    [2] = 0,
                    [3] = 0,
                    [4] = 32,
                    [5] = 20,
                    [6] = 0xC0,
                    [7] = 0xD7D7_7007
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ClipBlit),
                blit));
            for (var y = 0; y < 20; y++)
            {
                for (var x = 0; x < 32; x++)
                {
                    Assert.Equal(
                        (x == 4 || x == 5) && y == 4,
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
                }
            }

            // Restore the source's full published partition. Now the active
            // destination damage projection alone must bound a full-area
            // source-to-destination ClipBlit.
            for (var index = 0; index < savedSourceBounds.Length; index++)
                bus.WriteWord(
                    sourceClipBounds + checked((uint)(index * 2)),
                    savedSourceBounds[index]);
            ClearPlanarBitMap(bus, displayBitMap);
            blit = new M68kCpuState
            {
                A = { [0] = source.RastPort, [1] = bottom.RastPort },
                D =
                {
                    [0] = 0,
                    [1] = 0,
                    [2] = 0,
                    [3] = 0,
                    [4] = 32,
                    [5] = 20,
                    [6] = 0xC0,
                    [7] = 0xD7D7_7007
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ClipBlit),
                blit));
            for (var y = 0; y < 20; y++)
            {
                for (var x = 0; x < 32; x++)
                {
                    var admitted = admittedBounds.Any(bounds =>
                        x >= bounds.MinX && x <= bounds.MaxX &&
                        y >= bounds.MinY && y <= bounds.MaxY);
                    Assert.Equal(
                        admitted,
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
                }
            }

            Assert.Equal(updateHead, ReadLayerClipRect(bus, bottom.Layer));
            Assert.Equal(sourceClipHead, ReadLayerClipRect(bus, source.Layer));
            Assert.Equal(destinationFlagsBeforeRaster,
                ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(sourceFlagsBeforeRaster,
                ReadLayerFlags(bus, source.Layer));
            Assert.Equal(
                damage.Raw,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(
                damageBytes,
                Enumerable.Range(0, checked((int)LayersRegionCodec.Size))
                    .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                    .ToArray());
            Assert.Equal(
                sourceDamageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(source.Layer)).Raw);

            var end = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, end);
            updateActive = false;

        }
        finally
        {
            if (updateActive)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.EndUpdate),
                    end);
            }
            for (var index = 0; index < savedSourceBounds.Length; index++)
                bus.WriteWord(
                    sourceClipBounds + checked((uint)(index * 2)),
                    savedSourceBounds[index]);
            DeleteLayer(bus, libraryBase, source.Layer);
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, sourceInfo);
            DisposeLayerInfo(bus, libraryBase, destinationInfo);
            FreeBitMap(bus, sourceBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void LayeredGraphicsGatewayLeavesDeclinedClipBlitStateAndDamageUntouched()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var sourceInfo = NewLayerInfo(bus, libraryBase);
        var destinationInfo = NewLayerInfo(bus, libraryBase);
        var source = CreateLayer(bus, libraryBase, sourceInfo, 0, 0, 15, 15);
        var destination = CreateLayer(
            bus,
            libraryBase,
            destinationInfo,
            0,
            0,
            15,
            15);
        var layerMemory = new LayersTestGuestMemory(bus);

        try
        {
            ClearPlanarBitMap(bus, source.BitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            bus.WriteByte(ReadBitMapPlane(bus, source.BitMap, 0), 0xFF, 0);
            var destinationBefore = SnapshotPlanarBitMap(bus, destination.BitMap);
            var sourceFlagsBefore = ReadLayerFlags(bus, source.Layer);
            var destinationFlagsBefore = ReadLayerFlags(bus, destination.Layer);
            var sourceDamageBefore = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(source.Layer)).Raw;
            var destinationDamageBefore = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(destination.Layer)).Raw;
            var state = new M68kCpuState
            {
                A =
                {
                    [0] = source.RastPort,
                    [1] = destination.RastPort
                },
                D =
                {
                    [0] = 0,
                    [1] = 0,
                    [2] = 0,
                    [3] = 0,
                    [4] = 8,
                    [5] = 1,
                    [6] = 0xC0,
                    [7] = 0xD7D7_7007
                },
                Cycles = 173
            };

            // Force the validated provider to fail after staging all writes.
            // The gateway must roll the blit back and keep the declined call
            // transparent to the native/provider owner and to Layers damage.
            boot.FailNextValidatedRasterAfterAllBlitsForTest();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ClipBlit),
                state));

            Assert.Equal(0u, state.D[0]);
            Assert.Equal(0u, state.D[1]);
            Assert.Equal(0u, state.D[2]);
            Assert.Equal(0u, state.D[3]);
            Assert.Equal(8u, state.D[4]);
            Assert.Equal(1u, state.D[5]);
            Assert.Equal(0xC0u, state.D[6]);
            Assert.Equal(0xD7D7_7007u, state.D[7]);
            Assert.Equal(173, state.Cycles);
            Assert.Equal(destinationBefore, SnapshotPlanarBitMap(bus, destination.BitMap));
            Assert.Equal(sourceFlagsBefore, ReadLayerFlags(bus, source.Layer));
            Assert.Equal(
                destinationFlagsBefore,
                ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(
                sourceDamageBefore,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(source.Layer)).Raw);
            Assert.Equal(
                destinationDamageBefore,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(destination.Layer)).Raw);
        }
        finally
        {
            DeleteLayer(bus, libraryBase, source.Layer);
            DeleteLayer(bus, libraryBase, destination.Layer);
            DisposeLayerInfo(bus, libraryBase, sourceInfo);
            DisposeLayerInfo(bus, libraryBase, destinationInfo);
            FreeBitMap(bus, source.BitMap);
            FreeBitMap(bus, destination.BitMap);
        }
    }

