    [Fact]
    public void LayeredGraphicsGatewayProjectsMaskedBitMapRastPortBlitWithoutPublishingDamage()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var destination = CreateLayer(bus, libraryBase, layerInfo, 0, 0, 15, 15);
        var sourceBitMap = AllocatePlanarBitMap(bus, 16, 16);
        var maskPlane = AllocateGuestMemory(bus, 32);
        var layerMemory = new LayersTestGuestMemory(bus);
        var clipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(destination.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + checked((uint)(index * 2)));

        try
        {
            // The mask selects x=0 and x=1, while the published destination
            // ClipRect admits only x=0..2. The x=3 tail must remain clear,
            // proving that the real graphics.library gateway passes the
            // exact endpoint projection into the validated layer provider.
            WriteRectangleBounds(bus, clipBounds, 0, 0, 2, 0);
            ClearPlanarBitMap(bus, sourceBitMap);
            ClearPlanarBitMap(bus, destination.BitMap);
            bus.WriteByte(ReadBitMapPlane(bus, sourceBitMap, 0), 0xF0, 0);
            bus.WriteByte(ReadBitMapPlane(bus, destination.BitMap, 0), 0x10, 0);
            bus.WriteByte(maskPlane, 0xCC, 0);

            var flagsBeforeRaster = ReadLayerFlags(bus, destination.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(destination.Layer)).Raw;

            var blit = new M68kCpuState
            {
                A =
                {
                    [0] = sourceBitMap,
                    [1] = destination.RastPort,
                    [2] = maskPlane
                },
                D =
                {
                    [0] = 0,
                    [1] = 0,
                    [2] = 0,
                    [3] = 0,
                    [4] = 4,
                    [5] = 1,
                    [6] = 0xC0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltMaskBitMapRastPort),
                blit));

            Assert.Equal(0u, blit.D[0]);
            Assert.Equal(
                (byte)0xD0,
                bus.ReadByte(ReadBitMapPlane(bus, destination.BitMap, 0)));
            Assert.Equal(
                (byte)0xF0,
                bus.ReadByte(ReadBitMapPlane(bus, sourceBitMap, 0)));
            Assert.Equal((byte)0xCC, bus.ReadByte(maskPlane));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(destination.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + checked((uint)(index * 2)),
                    savedBounds[index]);
            DeleteLayer(bus, libraryBase, destination.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, sourceBitMap);
            FreeBitMap(bus, destination.BitMap);
            FreeGuestMemory(bus, maskPlane, 32);
        }
    }

    [Fact]
    public void LayeredGraphicsGatewayProjectsPatternBlitWithoutPublishingDamage()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(bus, libraryBase, layerInfo, 0, 0, 15, 15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);
        var clipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + checked((uint)(index * 2)));

        try
        {
            // Use the classic default area pattern and complement mode. The
            // published ClipRect admits only x=0..2, so the x=3..4 tail
            // remains seeded and Layer-owned damage stays untouched.
            WriteRectangleBounds(bus, clipBounds, 0, 0, 2, 1);
            ClearPlanarBitMap(bus, surface.BitMap);
            for (var row = 0; row < 16; row++)
                bus.WriteByte(plane + (uint)(row * 2), 0xFF, 0);
            bus.WriteLong(
                surface.RastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
                0);
            bus.WriteByte(
                surface.RastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
                0,
                0);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 2);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);

            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            var pattern = new M68kCpuState
            {
                A = { [1] = surface.RastPort },
                D =
                {
                    [0] = 0,
                    [1] = 0,
                    [2] = 4,
                    [3] = 1,
                    [4] = 0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltPattern),
                pattern));

            Assert.Equal(0u, pattern.D[0]);
            var firstRow = bus.ReadByte(plane);
            var secondRow = bus.ReadByte(plane + 2);
            Assert.Equal((byte)0x18, (byte)(firstRow & 0x18));
            Assert.Equal((byte)0x18, (byte)(secondRow & 0x18));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + checked((uint)(index * 2)),
                    savedBounds[index]);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

    [Fact]
    public void LayeredGraphicsGatewayProjectsTemplateBlitWithoutPublishingDamage()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(bus, libraryBase, layerInfo, 0, 0, 15, 15);
        var template = AllocateGuestMemory(bus, 4);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);
        var clipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + checked((uint)(index * 2)));

        try
        {
            // The template covers x=0..3, but the published destination
            // ClipRect admits only x=0..2. The x=3 bit remains clear and no
            // Layer-owned damage is created by the graphics operation.
            bus.WriteWord(template, 0xF000, 0);
            bus.WriteWord(template + 2u, 0xF000, 0);
            WriteRectangleBounds(bus, clipBounds, 0, 0, 2, 1);
            ClearPlanarBitMap(bus, surface.BitMap);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 0);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);

            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            var blit = new M68kCpuState
            {
                A =
                {
                    [0] = template,
                    [1] = surface.RastPort
                },
                D =
                {
                    [0] = 0,
                    [1] = 0,
                    [2] = 0,
                    [3] = 0,
                    [4] = 4,
                    [5] = 2
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltTemplate),
                blit));

            Assert.Equal(0u, blit.D[0]);
            Assert.Equal((byte)0xE0, bus.ReadByte(plane));
            Assert.Equal((byte)0xE0, bus.ReadByte(plane + 2u));
            Assert.Equal((byte)0, (byte)(bus.ReadByte(plane) & 0x10));
            Assert.Equal((byte)0, (byte)(bus.ReadByte(plane + 2u) & 0x10));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + checked((uint)(index * 2)),
                    savedBounds[index]);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
            FreeGuestMemory(bus, template, 4);
        }
    }

    [Fact]
    public void LayeredGraphicsGatewayProjectsAreaEndWithoutPublishingDamage()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(bus, libraryBase, layerInfo, 0, 0, 15, 15);
        var areaInfo = AllocateGuestMemory(bus, AreaInfo.Size);
        var areaStorage = AllocateGuestMemory(bus, 64);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);
        var clipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + checked((uint)(index * 2)));

        try
        {
            var initArea = new M68kCpuState
            {
                A = { [0] = areaInfo, [1] = areaStorage },
                D = { [0] = 8 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.InitArea),
                initArea));
            WriteRastPortAreaInfo(bus, surface.RastPort, areaInfo);
            WriteRectangleBounds(bus, clipBounds, 0, 0, 2, 2);
            ClearPlanarBitMap(bus, surface.BitMap);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 0);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            bus.WriteLong(
                surface.RastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
                0);
            bus.WriteByte(
                surface.RastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
                0,
                0);

            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            ExecuteAreaVector(GraphicsLvo.AreaMove, 0, 0);
            ExecuteAreaVector(GraphicsLvo.AreaDraw, 4, 0);
            ExecuteAreaVector(GraphicsLvo.AreaDraw, 4, 4);
            ExecuteAreaVector(GraphicsLvo.AreaDraw, 0, 4);
            ExecuteAreaVector(GraphicsLvo.AreaDraw, 0, 0);

            var end = new M68kCpuState
            {
                A = { [1] = surface.RastPort },
                D = { [0] = 0xCAFE_BABEu }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.AreaEnd),
                end));

            Assert.Equal(0u, end.D[0]);
            Assert.NotEqual((byte)0, bus.ReadByte(plane + 2u));
            Assert.NotEqual((byte)0, bus.ReadByte(plane + 4u));
            Assert.Equal((byte)0, bus.ReadByte(plane + 6u));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);

            void ExecuteAreaVector(GraphicsLvo lvo, short x, short y)
            {
                var frame = new M68kCpuState
                {
                    A = { [1] = surface.RastPort },
                    D =
                    {
                        [0] = unchecked((ushort)x),
                        [1] = unchecked((ushort)y)
                    }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)lvo),
                    frame));
                Assert.Equal(0u, frame.D[0]);
            }
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + checked((uint)(index * 2)),
                    savedBounds[index]);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
            FreeGuestMemory(bus, areaStorage, 64);
            FreeGuestMemory(bus, areaInfo, AreaInfo.Size);
        }
    }

    [Fact]
    public void LayeredGraphicsGatewayProjectsFloodWithoutPublishingDamage()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(bus, libraryBase, layerInfo, 0, 0, 15, 15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);
        var clipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + checked((uint)(index * 2)));

        try
        {
            // The seed is inside a three-row ClipRect. Flood must stop at
            // that published projection rather than filling the fourth row,
            // and it must not publish layer-owned damage.
            WriteRectangleBounds(bus, clipBounds, 0, 0, 2, 2);
            ClearPlanarBitMap(bus, surface.BitMap);
            bus.WriteLong(
                surface.RastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
                0);
            bus.WriteByte(
                surface.RastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
                0,
                0);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 0);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);

            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            var flood = new M68kCpuState
            {
                A = { [1] = surface.RastPort },
                D =
                {
                    [0] = 0,
                    [1] = 0,
                    [2] = 1
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.Flood),
                flood));

            Assert.Equal(1u, flood.D[0]);
            for (var row = 0; row < 3; row++)
                Assert.NotEqual((byte)0, bus.ReadByte(plane + (uint)(row * 2)));
            Assert.Equal((byte)0, bus.ReadByte(plane + 6u));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + checked((uint)(index * 2)),
                    savedBounds[index]);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

