        var layerMemory = new LayersTestGuestMemory(bus);
        var clipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + checked((uint)(index * 2)));

        try
        {
            WriteRectangleBounds(bus, clipBounds, 0, 0, 2, 4);
            ClearPlanarBitMap(bus, surface.BitMap);
            for (var row = 0; row < 16; row++)
                bus.WriteByte(plane + (uint)(row * 2), 0xFF, 0);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 2);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);

            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            var ellipse = new M68kCpuState
            {
                A = { [1] = surface.RastPort },
                D =
                {
                    [0] = 2,
                    [1] = 2,
                    [2] = 2,
                    [3] = 2
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.DrawEllipse),
                ellipse));

            Assert.Equal(0u, ellipse.D[0]);
            Assert.NotEqual((byte)0xFF, bus.ReadByte(plane));
            Assert.NotEqual((byte)0xFF, bus.ReadByte(plane + 8u));
            // The endpoint clips the middle row to x=0..2, so x=3..4
            // remains unchanged even though the ellipse spans the full width.
            Assert.Equal(
                (byte)0x18,
                (byte)(bus.ReadByte(plane + 4u) & 0x18));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + checked((uint)(index * 2)),
                    savedBounds[index]);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

    [Fact]
    public void LayeredGraphicsGatewayProjectsScrollRasterWithoutPublishingDamage()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);
        var clipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + checked((uint)(index * 2)));

        try
        {
            // Restrict the endpoint to x=0..4 while the requested scroll
            // covers x=0..7.  The actual graphics.library gateway must pass
            // this published head into the layer provider; otherwise the
            // invisible tail would be moved as well.
            WriteRectangleBounds(bus, clipBounds, 0, 0, 4, 0);
            ClearPlanarBitMap(bus, surface.BitMap);
            bus.WriteByte(plane, 0x55, 0);
            WriteRastPortBackgroundPen(bus, surface.RastPort, 0);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 0);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            WriteRastPortLinePatternCount(bus, surface.RastPort, 4);

            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            var scroll = new M68kCpuState
            {
                A = { [1] = surface.RastPort },
                D =
                {
                    [0] = 1,
                    [1] = 0,
                    [2] = 0,
                    [3] = 0,
                    [4] = 7,
                    [5] = 0
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ScrollRaster),
                scroll));

            Assert.Equal(0u, scroll.D[0]);
            Assert.Equal((byte)0xAD, bus.ReadByte(plane));
            Assert.Equal((byte)15, ReadRastPortLinePatternCount(bus, surface.RastPort));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + checked((uint)(index * 2)),
                    savedBounds[index]);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

