        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + checked((uint)(index * 2)));

        try
        {
            // ClearEOL should honour the published endpoint clip rather than
            // clearing the rest of the text row.  Its JAM1 clear pen is
            // colour zero; BPen is deliberately different to catch a legacy
            // layer-fill fallback.
            WriteRectangleBounds(bus, clipBounds, 0, 0, 4, 0);
            ClearPlanarBitMap(bus, surface.BitMap);
            for (var row = 0; row < 16; row++)
