            WriteRastPortCurrentY(bus, surface.RastPort, 1);
            WriteRastPortTextMetrics(bus, surface.RastPort, 1, 1);
            WriteRastPortLinePatternCount(bus, surface.RastPort, 4);

            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            var clear = new M68kCpuState
            {
                A = { [1] = surface.RastPort }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ClearEOL),
                clear));

            Assert.Equal(0u, clear.D[0]);
            Assert.Equal((byte)0x07, bus.ReadByte(plane));
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + 2u));
            Assert.Equal((byte)15, ReadRastPortLinePatternCount(bus, surface.RastPort));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
