            0,
            15,
            15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);
        var clipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        uint text = 0;
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + checked((uint)(index * 2)));

        try
        {
            // Keep only x=0 visible while Text projects the synthetic Topaz
            // glyph across the full character width.  The gateway must use
            // the supplied endpoint and preserve the layer bookkeeping.
            WriteRectangleBounds(bus, clipBounds, 0, 0, 0, 7);

            var openFont = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, -72),
                openFont));
            Assert.NotEqual(0u, openFont.D[0]);

            var setFont = new M68kCpuState
            {
                A = { [0] = openFont.D[0], [1] = surface.RastPort }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, -66),
                setFont));

            ClearPlanarBitMap(bus, surface.BitMap);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortBackgroundPen(bus, surface.RastPort, 0);
            WriteRastPortDrawMode(bus, surface.RastPort, 1);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            WriteRastPortCurrentX(bus, surface.RastPort, 0);
            WriteRastPortCurrentY(bus, surface.RastPort, 7);

            text = AllocateGuestMemory(bus, 1);
            bus.WriteByte(text, (byte)'A', 0);
            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            var drawText = new M68kCpuState
            {
                A = { [0] = text, [1] = surface.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.Text),
                drawText));

            Assert.Equal(0u, drawText.D[0]);
            Assert.Equal((byte)0, bus.ReadByte(plane));
            Assert.Equal((byte)0x80, bus.ReadByte(plane + 2u));
            Assert.Equal((ushort)8, ReadRastPortCurrentX(bus, surface.RastPort));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + checked((uint)(index * 2)),
                    savedBounds[index]);
            WriteLayerClipRect(bus, surface.Layer, surface.FirstClipRect);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
            if (text != 0)
                FreeGuestMemory(bus, text, 1);
        }
    }

    [Fact]
    public void LayeredGraphicsGatewayProjectsEraseRectWithoutPublishingDamage()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);
        var clipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + checked((uint)(index * 2)));

        try
        {
            // EraseRect spans x=0..7, but only x=0..4 belongs to the
            // published endpoint.  BPen is deliberately zero here so the
            // clipping result cannot be confused with a foreground fill.
            WriteRectangleBounds(bus, clipBounds, 0, 0, 4, 0);
            ClearPlanarBitMap(bus, surface.BitMap);
            bus.WriteByte(plane, 0xFF, 0);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortBackgroundPen(bus, surface.RastPort, 0);
            WriteRastPortDrawMode(bus, surface.RastPort, 1);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            WriteRastPortLinePatternCount(bus, surface.RastPort, 4);

            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            var erase = new M68kCpuState
            {
                A = { [1] = surface.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 7, [3] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.EraseRect),
                erase));

            Assert.Equal(0u, erase.D[0]);
            Assert.Equal((byte)0x07, bus.ReadByte(plane));
            Assert.Equal((byte)4, ReadRastPortLinePatternCount(bus, surface.RastPort));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + checked((uint)(index * 2)),
                    savedBounds[index]);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

    [Fact]
    public void LayeredGraphicsGatewayProjectsPolyDrawWithoutPublishingDamage()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var points = AllocateGuestMemory(bus, 4);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);
        var clipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + checked((uint)(index * 2)));

        try
        {
            // Draw one point from the current (0,2) position to (4,2), but
            // publish only x=0..2 through the layer endpoint.  COMPLEMENT
            // makes the clipped line distinguishable from a plain fill.
            bus.WriteWord(points, 4, 0);
            bus.WriteWord(points + 2u, 2, 0);
            WriteRectangleBounds(bus, clipBounds, 0, 0, 2, 4);
            ClearPlanarBitMap(bus, surface.BitMap);
            for (var row = 0; row < 16; row++)
                bus.WriteByte(plane + (uint)(row * 2), 0xFF, 0);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 2);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            WriteRastPortCurrentX(bus, surface.RastPort, 0);
            WriteRastPortCurrentY(bus, surface.RastPort, 2);
            WriteRastPortLinePattern(bus, surface.RastPort, 0xFFFF);
            WriteRastPortLinePatternCount(bus, surface.RastPort, 4);

            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            var poly = new M68kCpuState
            {
                A = { [0] = points, [1] = surface.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.PolyDraw),
                poly));

            Assert.Equal(0u, poly.D[0]);
            Assert.Equal((ushort)4, ReadRastPortCurrentX(bus, surface.RastPort));
            Assert.Equal((ushort)2, ReadRastPortCurrentY(bus, surface.RastPort));
            var middleRow = bus.ReadByte(plane + 4u);
            Assert.NotEqual((byte)0xFF, middleRow);
            Assert.Equal((byte)0x18, (byte)(middleRow & 0x18));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + checked((uint)(index * 2)),
                    savedBounds[index]);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
            FreeGuestMemory(bus, points, 4);
        }
    }

    [Fact]
    public void LayeredGraphicsGatewayProjectsPixelAccessWithoutPublishingDamage()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);

        try
        {
            var scroll = new M68kCpuState
            {
                A = { [1] = surface.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                scroll));

            bus.WriteByte(plane, 0, 0);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            // ScrollLayer(2,1) maps logical (2,1) onto the bitmap's local
            // origin.  The real graphics gateway must preserve that mapping
            // for both the write and the read without publishing damage.
            var write = new M68kCpuState
            {
                A = { [1] = surface.RastPort },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixel),
                write));
            Assert.Equal(0u, write.D[0]);
            Assert.Equal((byte)0x80, bus.ReadByte(plane));

            var read = new M68kCpuState
            {
                A = { [1] = surface.RastPort },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ReadPixel),
                read));
            Assert.Equal(1u, read.D[0]);
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

