    [Fact]
    public void LayeredGraphicsGatewayProjectsPixelArraysWithoutPublishingDamage()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var array = AllocateGuestMemory(bus, 16);
        var layerMemory = new LayersTestGuestMemory(bus);
        var clipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + checked((uint)(index * 2)));

        try
        {
            // The endpoint admits only x=0..2 of a five-sample line.  Keep
            // the temporary RastPort register null, matching the portable
            // layer ABI, and exercise the actual graphics.library vectors.
            WriteRectangleBounds(bus, clipBounds, 0, 0, 2, 0);
            ClearPlanarBitMap(bus, surface.BitMap);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            for (uint index = 0; index < 5; index++)
                bus.WriteByte(array + index, 1, 0);

            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            var writeLine = new M68kCpuState
            {
                A = { [0] = surface.RastPort, [2] = array },
                D = { [0] = 0, [1] = 0, [2] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixelLine8),
                writeLine));
            Assert.Equal(5u, writeLine.D[0]);
            Assert.Equal((byte)0xE0, bus.ReadByte(plane));

            for (uint index = 0; index < 5; index++)
                bus.WriteByte(array + index, 0xCC, 0);
            var readArray = new M68kCpuState
            {
                A = { [0] = surface.RastPort, [2] = array },
                D = { [0] = 0, [1] = 0, [2] = 4, [3] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ReadPixelArray8),
                readArray));
            Assert.Equal(5u, readArray.D[0]);
            Assert.Equal((byte)1, bus.ReadByte(array));
            Assert.Equal((byte)1, bus.ReadByte(array + 1u));
            Assert.Equal((byte)1, bus.ReadByte(array + 2u));
            Assert.Equal((byte)0, bus.ReadByte(array + 3u));
            Assert.Equal((byte)0, bus.ReadByte(array + 4u));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + checked((uint)(index * 2)),
                    savedBounds[index]);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
            FreeGuestMemory(bus, array, 16);
        }
    }

