        var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
        var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
            ref layerMemory,
            APTR.FromPointer(surface.Layer)).Raw;
        var clipBounds = LayersClipRectCodec.BoundsAddress(APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + (uint)(index * 2));

        try
        {
            // The endpoint carries the authoritative clip head.  Keep only
            // x=0 visible, then poison Layer.ClipRect to prove Text does not
            // rediscover the stale public field.
            WriteRectangleBounds(bus, clipBounds, 0, 0, 0, 7);
            WriteLayerClipRect(bus, surface.Layer, 0);

            var openFont = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, -72),
                openFont));
            Assert.NotEqual(0u, openFont.D[0]);

            var setFont = new M68kCpuState
            {
                A = { [0] = openFont.D[0], [1] = surface.RastPort }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, -66),
                setFont));

            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortBackgroundPen(bus, surface.RastPort, 0);
            WriteRastPortDrawMode(bus, surface.RastPort, 1);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            WriteRastPortCurrentX(bus, surface.RastPort, 0);
            WriteRastPortCurrentY(bus, surface.RastPort, 7);

            var text = AllocateGuestMemory(bus, 1);
            bus.WriteByte(text, (byte)'A', 0);
            var frame = new PortableLayers.LayersRegisterFrame
            {
                A0 = text,
                A1 = surface.RastPort,
                D0 = 1
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.Text,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    surface.RastPort,
                    surface.Layer,
                    surface.FirstClipRect),
                default));

            // Synthetic Topaz's second A row has its leftmost pixel set.  A
            // stale/unclipped path would also publish neighbouring x=1..3
            // bits; the endpoint clip leaves only the x=0 plane bit.
            Assert.Equal((byte)0, bus.ReadByte(plane));
            Assert.Equal((byte)0x80, bus.ReadByte(plane + 2));
            Assert.Equal((ushort)8, ReadRastPortCurrentX(bus, surface.RastPort));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + (uint)(index * 2),
                    savedBounds[index]);
            WriteLayerClipRect(bus, surface.Layer, surface.FirstClipRect);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

    [Fact]
    public void ValidatedTextPreflightsTheFullProjectedGlyphDestination()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var originalPlane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var text = AllocateGuestMemory(bus, 2);
        const uint oneBytePlane = 0xE100_0300;
        bus.MapWritableMemory(oneBytePlane, new byte[1]);

        try
        {
            WriteBitMapPlane(bus, surface.BitMap, 0, oneBytePlane);
            bus.WriteByte(text, (byte)'A', 0);
            bus.WriteByte(text + 1u, (byte)'A', 0);

            var openFont = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, -72),
                openFont));
            var setFont = new M68kCpuState
            {
                A = { [0] = openFont.D[0], [1] = surface.RastPort }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, -66),
                setFont));
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 1);
            WriteRastPortMask(bus, surface.RastPort, 1);
            WriteRastPortCurrentX(bus, surface.RastPort, 0);
            WriteRastPortCurrentY(bus, surface.RastPort, 7);

            var frame = new PortableLayers.LayersRegisterFrame
            {
                A0 = text,
                A1 = surface.RastPort,
                D0 = 2
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.False(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.Text,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    surface.RastPort,
                    surface.Layer,
                    surface.FirstClipRect),
                default));
            Assert.Equal((byte)0, bus.ReadByte(oneBytePlane));
        }
        finally
        {
            WriteBitMapPlane(bus, surface.BitMap, 0, originalPlane);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
            FreeGuestMemory(bus, text, 2);
        }
    }

    [Fact]
    public void ValidatedDrawUsesPortableLineStateAndSuppliedClipHead()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);
        var clipBounds = LayersClipRectCodec.BoundsAddress(APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + (uint)(index * 2));

        try
        {
            WriteRectangleBounds(bus, clipBounds, 0, 0, 4, 0);
            WriteLayerClipRect(bus, surface.Layer, 0);

            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 0);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            WriteRastPortLinePattern(bus, surface.RastPort, 0x8000);
            WriteRastPortLinePatternCount(bus, surface.RastPort, 15);
            WriteRastPortCurrentX(bus, surface.RastPort, 0);
            WriteRastPortCurrentY(bus, surface.RastPort, 0);
            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            var frame = new PortableLayers.LayersRegisterFrame
            {
                A1 = surface.RastPort,
                D0 = 7,
                D1 = 0
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.Draw,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    surface.RastPort,
                    surface.Layer,
                    surface.FirstClipRect),
                default));

            // The portable line engine consumes the first 0x8000 pattern bit
            // and skips the remaining JAM1 samples.  The endpoint clip keeps
            // x=0..4 available; the legacy callback would paint every one of
            // those pixels and would leave the line phase unchanged.
            Assert.Equal((byte)0x80, bus.ReadByte(plane));
            Assert.Equal((byte)8, ReadRastPortLinePatternCount(bus, surface.RastPort));
            Assert.Equal((ushort)7, ReadRastPortCurrentX(bus, surface.RastPort));
            Assert.Equal((ushort)0, ReadRastPortCurrentY(bus, surface.RastPort));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + (uint)(index * 2),
                    savedBounds[index]);
            WriteLayerClipRect(bus, surface.Layer, surface.FirstClipRect);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

    [Fact]
    public void ValidatedRectFillUsesPortableDrawModeAndSuppliedClipHead()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);
        var clipBounds = LayersClipRectCodec.BoundsAddress(APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + (uint)(index * 2));

        try
        {
            // The endpoint exposes x=0..4 while the public Layer.ClipRect is
            // poisoned.  Seed those pixels so COMPLEMENT semantics are
            // distinguishable from the legacy fill callback, which always
            // writes the foreground pen.
            WriteRectangleBounds(bus, clipBounds, 0, 0, 4, 0);
            WriteLayerClipRect(bus, surface.Layer, 0);

            bus.WriteByte(plane, 0xF8, 0);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 3);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            var frame = new PortableLayers.LayersRegisterFrame
            {
                A1 = surface.RastPort,
                D0 = 0,
                D1 = 0,
                D2 = 7,
                D3 = 0
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.RectFill,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    surface.RastPort,
                    surface.Layer,
                    surface.FirstClipRect),
                default));

            // Portable COMPLEMENT toggles the visible seeded pixels and
            // leaves the clipped-out tail untouched.  A legacy foreground
            // fill would leave 0xF8 here.
            Assert.Equal((byte)0, bus.ReadByte(plane));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + (uint)(index * 2),
                    savedBounds[index]);
            WriteLayerClipRect(bus, surface.Layer, surface.FirstClipRect);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

    [Fact]
    public void ValidatedSetRastFailsAtomicallyOnMalformedSelectedPlane()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var originalDepth = ReadBitMapDepth(bus, surface.BitMap);
        var clipBounds = LayersClipRectCodec.BoundsAddress(APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + (uint)(index * 2));

        try
        {
            // Turn the otherwise valid one-plane layer into a malformed
            // depth-two bitmap with no second plane. SetRast must preflight
            // the selected plane set before touching plane zero.
            WriteBitMapDepth(bus, surface.BitMap, 2);
            bus.WriteByte(plane, 0xAA, 0);
            WriteRectangleBounds(bus, clipBounds, 0, 0, 4, 0);
            WriteLayerClipRect(bus, surface.Layer, 0);

            var frame = new PortableLayers.LayersRegisterFrame
            {
                A1 = surface.RastPort,
                D0 = 1
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.False(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.SetRast,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    surface.RastPort,
                    surface.Layer,
                    surface.FirstClipRect),
                default));
            Assert.Equal((byte)0xAA, bus.ReadByte(plane));
        }
        finally
        {
            WriteBitMapDepth(bus, surface.BitMap, originalDepth);
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + (uint)(index * 2),
                    savedBounds[index]);
            WriteLayerClipRect(bus, surface.Layer, surface.FirstClipRect);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

