            for (var row = 0; row < 16; row++)
                bus.WriteByte(plane + (uint)(row * 2), 0xFF, 0);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 2);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            var frame = new PortableLayers.LayersRegisterFrame
            {
                A1 = surface.RastPort,
                D0 = 2,
                D1 = 2,
                D2 = 2,
                D3 = 2
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.DrawEllipse,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    surface.RastPort,
                    surface.Layer,
                    surface.FirstClipRect),
                default));

            Assert.Equal(0u, frame.D0);
            // COMPLEMENT must toggle the endpoint-visible cardinal points;
            // the old provider callback would have written the foreground pen.
            Assert.NotEqual((byte)0xFF, bus.ReadByte(plane));
            Assert.NotEqual((byte)0xFF, bus.ReadByte(plane + (uint)(4 * 2)));
            // The endpoint clip stops at x=2, so the right-hand tail of the
            // middle row remains untouched even though Layer.ClipRect is
            // deliberately poisoned above.
            Assert.NotEqual((byte)0xFF, bus.ReadByte(plane + (uint)(2 * 2)));
            Assert.Equal(
                (byte)0x18,
                (byte)(bus.ReadByte(plane + (uint)(2 * 2)) & 0x18));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + (uint)(index * 2),
                    savedBounds[index]);
            WriteLayerClipRect(bus, surface.Layer, surface.FirstClipRect);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

    [Fact]
    public void ValidatedPolyDrawUsesPortableLineStateAndSuppliedClipHead()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
