        var points = AllocateGuestMemory(bus, 4);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var clipBounds = LayersClipRectCodec.BoundsAddress(APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + (uint)(index * 2));

        try
        {
            bus.WriteWord(points, 4, 0);
            bus.WriteWord(points + 2, 2, 0);
            WriteRectangleBounds(bus, clipBounds, 0, 0, 2, 4);
            WriteLayerClipRect(bus, surface.Layer, 0);

            for (var row = 0; row < 16; row++)
                bus.WriteByte(plane + (uint)(row * 2), 0xFF, 0);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 2);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            WriteRastPortCurrentX(bus, surface.RastPort, 0);
            WriteRastPortCurrentY(bus, surface.RastPort, 2);
            WriteRastPortLinePattern(bus, surface.RastPort, 0xFFFF);
            WriteRastPortLinePatternCount(bus, surface.RastPort, 4);

            var frame = new PortableLayers.LayersRegisterFrame
            {
                A0 = points,
                A1 = surface.RastPort,
                D0 = 1
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.PolyDraw,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    surface.RastPort,
                    surface.Layer,
                    surface.FirstClipRect),
                default));

            Assert.Equal(0u, frame.D0);
            Assert.Equal((ushort)4, ReadRastPortCurrentX(bus, surface.RastPort));
            Assert.Equal((ushort)2, ReadRastPortCurrentY(bus, surface.RastPort));
            // COMPLEMENT toggles the visible line samples, while x3..x4 in
            // the supplied endpoint tail remain at their seeded values.
            var middleRow = bus.ReadByte(plane + (uint)(2 * 2));
            Assert.NotEqual((byte)0xFF, middleRow);
            Assert.Equal((byte)0x18, (byte)(middleRow & 0x18));
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + (uint)(index * 2),
                    savedBounds[index]);
            WriteLayerClipRect(bus, surface.Layer, surface.FirstClipRect);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
            FreeGuestMemory(bus, points, 4);
        }
    }

    [Fact]
    public void ValidatedPolyDrawProjectsPointStreamThroughLayerScrollWithoutDamageMutation()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var points = AllocateGuestMemory(bus, 4);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);

        try
        {
            var scroll = new M68kCpuState
            {
                A = { [1] = surface.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                scroll));
            Assert.Equal((short)2, ReadLayerScrollX(bus, surface.Layer));
            Assert.Equal((short)1, ReadLayerScrollY(bus, surface.Layer));

            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;
            bus.WriteWord(points, 5, 0);
            bus.WriteWord(points + 2, 1, 0);
            bus.WriteByte(plane, 0, 0);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 1);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            WriteRastPortCurrentX(bus, surface.RastPort, 2);
            WriteRastPortCurrentY(bus, surface.RastPort, 1);
            WriteRastPortLinePattern(bus, surface.RastPort, 0xFFFF);
            WriteRastPortLinePatternCount(bus, surface.RastPort, 15);

            var frame = new PortableLayers.LayersRegisterFrame
            {
                A0 = points,
                A1 = surface.RastPort,
                D0 = 1
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.PolyDraw,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    surface.RastPort,
                    surface.Layer,
                    surface.FirstClipRect),
                default));

            Assert.Equal(0u, frame.D0);
            // Logical (2,1)..(5,1) maps through the layer's (2,1) scroll
            // offset to the first four local pixels. Raw point-stream use
            // would instead paint bits 2..5.
            Assert.Equal((byte)0xF0, bus.ReadByte(plane));
            Assert.Equal((ushort)5, ReadRastPortCurrentX(bus, surface.RastPort));
            Assert.Equal((ushort)1, ReadRastPortCurrentY(bus, surface.RastPort));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
            FreeGuestMemory(bus, points, 4);
        }
    }

    [Fact]
    public void ValidatedPixelAccessProjectsLayerScrollWithoutDamageMutation()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);

        try
        {
            var scroll = new M68kCpuState
            {
                A = { [1] = surface.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                scroll));

            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;
            bus.WriteByte(plane, 0, 0);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);

            var endpoint = new GraphicsValidatedLayerEndpoint(
                surface.RastPort,
                surface.Layer,
                surface.FirstClipRect);
            // The Layers gateway already admitted this head. Poison the
            // public field so the pixel calls can only consume the supplied
            // endpoint instead of rediscovering Layer.ClipRect.
            WriteLayerClipRect(bus, surface.Layer, 0);
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            var write = new PortableLayers.LayersRegisterFrame
            {
                A1 = surface.RastPort,
                D0 = 2,
                D1 = 1
            };
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.WritePixel,
                ref write,
                endpoint,
                default));
            Assert.Equal(0u, write.D0);

            // The caller's logical (2,1) is the top-left viewport sample
            // after ScrollLayer(2,1), not local bitmap pixel (2,1).
            Assert.Equal((byte)0x80, bus.ReadByte(plane));
            var read = new PortableLayers.LayersRegisterFrame
            {
                A1 = surface.RastPort,
                D0 = 2,
                D1 = 1
            };
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.ReadPixel,
                ref read,
                endpoint,
                default));
            Assert.Equal(1u, read.D0);
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            WriteLayerClipRect(bus, surface.Layer, surface.FirstClipRect);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

