    [Fact]
    public void ValidatedBltTemplateUsesPortableTemplateAndSuppliedClipHead()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var template = AllocateGuestMemory(bus, 4);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);
        var clipBounds = LayersClipRectCodec.BoundsAddress(APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + (uint)(index * 2));

        try
        {
            bus.WriteWord(template, 0xF000, 0);
            bus.WriteWord(template + 2, 0xF000, 0);
            WriteRectangleBounds(bus, clipBounds, 0, 0, 2, 1);
            WriteLayerClipRect(bus, surface.Layer, 0);

            for (var row = 0; row < 16; row++)
                bus.WriteByte(plane + (uint)(row * 2), 0, 0);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 0);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(surface.Layer)).Raw;

            var frame = new PortableLayers.LayersRegisterFrame
            {
                A0 = template,
                A1 = surface.RastPort,
                D0 = 0,
                D1 = 0,
                D2 = 0,
                D3 = 0,
                D4 = 4,
                D5 = 2
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.BltTemplate,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    surface.RastPort,
                    surface.Layer,
                    surface.FirstClipRect),
                default));

            Assert.Equal(0u, frame.D0);
            var firstRow = bus.ReadByte(plane);
            var secondRow = bus.ReadByte(plane + 2);
            Assert.Equal((byte)0xE0, firstRow);
            Assert.Equal((byte)0xE0, secondRow);
            // The template covers x0..3, but the supplied endpoint stops at
            // x2; the clipped-out x3 bit must remain clear.
            Assert.Equal((byte)0, (byte)(firstRow & 0x10));
            Assert.Equal((byte)0, (byte)(secondRow & 0x10));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + (uint)(index * 2),
                    savedBounds[index]);
            WriteLayerClipRect(bus, surface.Layer, surface.FirstClipRect);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
            FreeGuestMemory(bus, template, 4);
        }
    }

    [Fact]
    public void ValidatedAreaEndUsesPortableFillAndSuppliedClipHead()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        var areaInfo = AllocateGuestMemory(bus, AreaInfo.Size);
        var areaStorage = AllocateGuestMemory(bus, 64);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var clipBounds = LayersClipRectCodec.BoundsAddress(APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + (uint)(index * 2));

        try
        {
            var initArea = new M68kCpuState
            {
                A = { [0] = areaInfo, [1] = areaStorage },
                D = { [0] = 8 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.InitArea),
                initArea));
            WriteRastPortAreaInfo(bus, surface.RastPort, areaInfo);
            WriteRectangleBounds(bus, clipBounds, 0, 0, 2, 2);
            WriteLayerClipRect(bus, surface.Layer, 0);

            for (var row = 0; row < 16; row++)
                bus.WriteByte(plane + (uint)(row * 2), 0, 0);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 0);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            bus.WriteLong(
                surface.RastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
                0);
            bus.WriteByte(
                surface.RastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
                0,
                0);

            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            ExecuteAreaVector(GraphicsLayersLvo.AreaMove, 0, 0);
            ExecuteAreaVector(GraphicsLayersLvo.AreaDraw, 4, 0);
            ExecuteAreaVector(GraphicsLayersLvo.AreaDraw, 4, 4);
            ExecuteAreaVector(GraphicsLayersLvo.AreaDraw, 0, 4);
            ExecuteAreaVector(GraphicsLayersLvo.AreaDraw, 0, 0);

            var end = new PortableLayers.LayersRegisterFrame
            {
                A1 = surface.RastPort
            };
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.AreaEnd,
                ref end,
                new GraphicsValidatedLayerEndpoint(
                    surface.RastPort,
                    surface.Layer,
                    surface.FirstClipRect),
                default));
            Assert.Equal(0u, end.D0);
            Assert.NotEqual((byte)0, bus.ReadByte(plane + 2));
            Assert.NotEqual((byte)0, bus.ReadByte(plane + 4));
            Assert.Equal((byte)0, bus.ReadByte(plane + 6));

            void ExecuteAreaVector(short lvo, short x, short y)
            {
                var frame = new PortableLayers.LayersRegisterFrame
                {
                    A1 = surface.RastPort,
                    D0 = unchecked((ushort)x),
                    D1 = unchecked((ushort)y)
                };
                Assert.True(executor.TryExecuteLayeredRaster(
                    lvo,
                    ref frame,
                    new GraphicsValidatedLayerEndpoint(
                        surface.RastPort,
                        surface.Layer,
                        surface.FirstClipRect),
                    default));
                Assert.Equal(0u, frame.D0);
            }
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + (uint)(index * 2),
                    savedBounds[index]);
            WriteLayerClipRect(bus, surface.Layer, surface.FirstClipRect);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
            FreeGuestMemory(bus, areaStorage, 64);
            FreeGuestMemory(bus, areaInfo, AreaInfo.Size);
        }
    }

    [Fact]
    public void ValidatedAreaEndProjectsCollectorCoordinatesThroughLayerScroll()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(bus, libraryBase, layerInfo, 0, 0, 15, 15);
        var areaInfo = AllocateGuestMemory(bus, AreaInfo.Size);
        var areaStorage = AllocateGuestMemory(bus, 64);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);
        var flagsBeforeRaster = ReadLayerFlags(bus, surface.Layer);
        var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
            ref layerMemory,
            APTR.FromPointer(surface.Layer)).Raw;
        var clipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(surface.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(clipBounds + (uint)(index * 2));

        try
        {
            var initArea = new M68kCpuState
            {
                A = { [0] = areaInfo, [1] = areaStorage },
                D = { [0] = 8 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.InitArea),
                initArea));
            WriteRastPortAreaInfo(bus, surface.RastPort, areaInfo);

            // Vector coordinates are logical while public ClipRects are in
            // screen coordinates. The screen rectangle (0,0)..(2,2) maps
            // back to logical (2,1)..(4,3) through this layer scroll. The
            // four-pixel fill reaches logical x=5, then the supplied head
            // clips its visible three-column, two-scanline interior to the
            // local bit-map origin.
            WriteLayerScroll(bus, surface.Layer, 2, 1);
            WriteRectangleBounds(bus, clipBounds, 0, 0, 2, 2);
            WriteLayerClipRect(bus, surface.Layer, 0);
            for (var row = 0; row < 16; row++)
                bus.WriteByte(plane + (uint)(row * 2), 0, 0);
            WriteRastPortForegroundPen(bus, surface.RastPort, 1);
            WriteRastPortDrawMode(bus, surface.RastPort, 0);
            WriteRastPortMask(bus, surface.RastPort, 0xFF);
            bus.WriteLong(
                surface.RastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
                0);
            bus.WriteByte(
                surface.RastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
                0,
                0);

            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            ExecuteAreaVector(GraphicsLayersLvo.AreaMove, 2, 1);
            ExecuteAreaVector(GraphicsLayersLvo.AreaDraw, 5, 1);
            ExecuteAreaVector(GraphicsLayersLvo.AreaDraw, 5, 3);
            ExecuteAreaVector(GraphicsLayersLvo.AreaDraw, 2, 3);
            ExecuteAreaVector(GraphicsLayersLvo.AreaDraw, 2, 1);

            var end = new PortableLayers.LayersRegisterFrame
            {
                A1 = surface.RastPort
            };
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.AreaEnd,
                ref end,
                new GraphicsValidatedLayerEndpoint(
                    surface.RastPort,
                    surface.Layer,
                    surface.FirstClipRect),
                default));

            Assert.Equal(0u, end.D0);
            Assert.Equal((byte)0xE0, bus.ReadByte(plane));
            Assert.Equal((byte)0xE0, bus.ReadByte(plane + 2));
            Assert.Equal((byte)0, bus.ReadByte(plane + 4));
            Assert.Equal((byte)0, bus.ReadByte(plane + 6));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);

            void ExecuteAreaVector(short lvo, short x, short y)
            {
                var frame = new PortableLayers.LayersRegisterFrame
                {
                    A1 = surface.RastPort,
                    D0 = unchecked((ushort)x),
                    D1 = unchecked((ushort)y)
                };
                Assert.True(executor.TryExecuteLayeredRaster(
                    lvo,
                    ref frame,
                    new GraphicsValidatedLayerEndpoint(
                        surface.RastPort,
                        surface.Layer,
                        surface.FirstClipRect),
                    default));
                Assert.Equal(0u, frame.D0);
            }
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(clipBounds + (uint)(index * 2), savedBounds[index]);
            WriteLayerScroll(bus, surface.Layer, 0, 0);
            WriteLayerClipRect(bus, surface.Layer, surface.FirstClipRect);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
            FreeGuestMemory(bus, areaStorage, 64);
            FreeGuestMemory(bus, areaInfo, AreaInfo.Size);
        }
    }

    [Fact]
    public void ValidatedBltBitMapRastPortUsesPortableSourceAndSuppliedDestinationHead()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var sourceLayerInfo = NewLayerInfo(bus, libraryBase);
        var destinationLayerInfo = NewLayerInfo(bus, libraryBase);
        var source = CreateLayer(
            bus,
            libraryBase,
            sourceLayerInfo,
            0,
            0,
            15,
            15);
        var destination = CreateLayer(
            bus,
            libraryBase,
            destinationLayerInfo,
            0,
            0,
            15,
            15);
        var sourcePlane = ReadBitMapPlane(bus, source.BitMap, 0);
        var destinationPlane = ReadBitMapPlane(bus, destination.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);
        var clipBounds = LayersClipRectCodec.BoundsAddress(APTR.FromPointer(destination.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + (uint)(index * 2));

        try
        {
            // Source is read directly from the supplied BitMap argument. The
            // destination must use the already-admitted ClipRect head even
            // when Layer.ClipRect is poisoned before dispatch.
            bus.WriteByte(sourcePlane, 0xE0, 0);
            bus.WriteByte(destinationPlane, 0x10, 0);
            WriteRectangleBounds(bus, clipBounds, 0, 0, 2, 0);
            WriteLayerClipRect(bus, destination.Layer, 0);
            var sourceFlagsBeforeRaster = ReadLayerFlags(bus, source.Layer);
            var sourceDamageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(source.Layer)).Raw;
            var destinationFlagsBeforeRaster = ReadLayerFlags(bus, destination.Layer);
            var destinationDamageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(destination.Layer)).Raw;

            var frame = new PortableLayers.LayersRegisterFrame
            {
                A0 = source.BitMap,
                A1 = destination.RastPort,
                D0 = 0,
                D1 = 0,
                D2 = 0,
                D3 = 0,
                D4 = 4,
                D5 = 1,
                D6 = 0xC0
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.BltBitMapRastPort,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    destination.RastPort,
                    destination.Layer,
                    destination.FirstClipRect),
                default));

            Assert.Equal(1u, frame.D0);
            // x0..x2 came from the source; x3 is outside the supplied head
            // and retains its original destination bit.
            Assert.Equal((byte)0xF0, bus.ReadByte(destinationPlane));
            Assert.Equal((byte)0xE0, bus.ReadByte(sourcePlane));
            Assert.Equal(sourceFlagsBeforeRaster, ReadLayerFlags(bus, source.Layer));
            Assert.Equal(
                sourceDamageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(source.Layer)).Raw);
            Assert.Equal(destinationFlagsBeforeRaster, ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(
                destinationDamageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(destination.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + (uint)(index * 2),
                    savedBounds[index]);
            WriteLayerClipRect(bus, destination.Layer, destination.FirstClipRect);
            DeleteLayer(bus, libraryBase, destination.Layer);
            DeleteLayer(bus, libraryBase, source.Layer);
            DisposeLayerInfo(bus, libraryBase, destinationLayerInfo);
            DisposeLayerInfo(bus, libraryBase, sourceLayerInfo);
            FreeBitMap(bus, destination.BitMap);
            FreeBitMap(bus, source.BitMap);
        }
    }

    [Fact]
    public void ValidatedBltMaskBitMapRastPortUsesPortableMaskAndSuppliedDestinationHead()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var sourceLayerInfo = NewLayerInfo(bus, libraryBase);
        var destinationLayerInfo = NewLayerInfo(bus, libraryBase);
        var source = CreateLayer(
            bus,
            libraryBase,
            sourceLayerInfo,
            0,
            0,
            15,
            15);
        var destination = CreateLayer(
            bus,
            libraryBase,
            destinationLayerInfo,
            0,
            0,
            15,
            15);
        var maskPlane = AllocateGuestMemory(bus, 32);
        var sourcePlane = ReadBitMapPlane(bus, source.BitMap, 0);
        var destinationPlane = ReadBitMapPlane(bus, destination.BitMap, 0);
        var clipBounds = LayersClipRectCodec.BoundsAddress(APTR.FromPointer(destination.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(
                clipBounds + (uint)(index * 2));

        try
        {
            bus.WriteByte(sourcePlane, 0xF0, 0);
            bus.WriteByte(destinationPlane, 0x10, 0);
            bus.WriteByte(maskPlane, 0xCC, 0);
            WriteRectangleBounds(bus, clipBounds, 0, 0, 2, 0);
            WriteLayerClipRect(bus, destination.Layer, 0);

            var frame = new PortableLayers.LayersRegisterFrame
            {
                A0 = source.BitMap,
                A1 = destination.RastPort,
                A2 = maskPlane,
                D0 = 0,
                D1 = 0,
                D2 = 0,
                D3 = 0,
                D4 = 4,
                D5 = 1,
                D6 = 0xC0
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.BltMaskBitMapRastPort,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    destination.RastPort,
                    destination.Layer,
                    destination.FirstClipRect),
                default));

            Assert.Equal(0u, frame.D0);
            // The mask selects x0 and x1 inside the supplied endpoint. x2 is
            // masked off, while x3 is clipped out and retains its seed bit.
            Assert.Equal((byte)0xD0, bus.ReadByte(destinationPlane));
            Assert.Equal((byte)0xF0, bus.ReadByte(sourcePlane));
            Assert.Equal((byte)0xCC, bus.ReadByte(maskPlane));

        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(
                    clipBounds + (uint)(index * 2),
                    savedBounds[index]);
            WriteLayerClipRect(bus, destination.Layer, destination.FirstClipRect);
            DeleteLayer(bus, libraryBase, destination.Layer);
            DeleteLayer(bus, libraryBase, source.Layer);
            DisposeLayerInfo(bus, libraryBase, destinationLayerInfo);
            DisposeLayerInfo(bus, libraryBase, sourceLayerInfo);
            FreeBitMap(bus, destination.BitMap);
            FreeBitMap(bus, source.BitMap);
            FreeGuestMemory(bus, maskPlane, 32);
        }
    }

    [Fact]
    public void ValidatedBltMaskBitMapRastPortProjectsScrolledDestinationCoordinates()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var sourceLayerInfo = NewLayerInfo(bus, libraryBase);
        var destinationLayerInfo = NewLayerInfo(bus, libraryBase);
        var source = CreateLayer(bus, libraryBase, sourceLayerInfo, 0, 0, 15, 15);
        var destination = CreateLayer(
            bus,
            libraryBase,
            destinationLayerInfo,
            0,
            0,
            15,
            15);
        var maskPlane = AllocateGuestMemory(bus, 32);
        var sourcePlane = ReadBitMapPlane(bus, source.BitMap, 0);
        var destinationPlane = ReadBitMapPlane(bus, destination.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);
        var flagsBeforeRaster = ReadLayerFlags(bus, destination.Layer);
        var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
            ref layerMemory,
            APTR.FromPointer(destination.Layer)).Raw;
        var clipBounds = LayersClipRectCodec.BoundsAddress(
            APTR.FromPointer(destination.FirstClipRect)).Raw;
        var savedBounds = new ushort[4];
        for (var index = 0; index < savedBounds.Length; index++)
            savedBounds[index] = bus.ReadWord(clipBounds + (uint)(index * 2));

        try
        {
            // The screen clip at x=0..2 is logical x=2..4 after scroll.
            // The masked source starts at x=0, while its logical destination
            // begins at (2,1), so selected source bits must land at local
            // destination x=0 and x=1.
            WriteLayerScroll(bus, destination.Layer, 2, 1);
            WriteRectangleBounds(bus, clipBounds, 0, 0, 2, 0);
            WriteLayerClipRect(bus, destination.Layer, 0);
            bus.WriteByte(sourcePlane, 0xF0, 0);
            bus.WriteByte(destinationPlane, 0, 0);
            bus.WriteByte(maskPlane, 0xCC, 0);

            var frame = new PortableLayers.LayersRegisterFrame
            {
                A0 = source.BitMap,
                A1 = destination.RastPort,
                A2 = maskPlane,
                D0 = 0,
                D1 = 0,
                D2 = 2,
                D3 = 1,
                D4 = 4,
                D5 = 1,
                D6 = 0xC0
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.BltMaskBitMapRastPort,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    destination.RastPort,
                    destination.Layer,
                    destination.FirstClipRect),
                default));

            Assert.Equal(0u, frame.D0);
            Assert.Equal((byte)0xC0, bus.ReadByte(destinationPlane));
            Assert.Equal((byte)0xF0, bus.ReadByte(sourcePlane));
            Assert.Equal((byte)0xCC, bus.ReadByte(maskPlane));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(destination.Layer)).Raw);
        }
        finally
        {
            for (var index = 0; index < savedBounds.Length; index++)
                bus.WriteWord(clipBounds + (uint)(index * 2), savedBounds[index]);
            WriteLayerScroll(bus, destination.Layer, 0, 0);
            WriteLayerClipRect(bus, destination.Layer, destination.FirstClipRect);
            DeleteLayer(bus, libraryBase, destination.Layer);
            DeleteLayer(bus, libraryBase, source.Layer);
            DisposeLayerInfo(bus, libraryBase, destinationLayerInfo);
            DisposeLayerInfo(bus, libraryBase, sourceLayerInfo);
            FreeBitMap(bus, destination.BitMap);
            FreeBitMap(bus, source.BitMap);
            FreeGuestMemory(bus, maskPlane, 32);
        }
    }

    [Fact]
    public void ValidatedClipBlitConsumesBothSuppliedEndpointHeadsExactlyOnce()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;

        var sourceLayerInfo = NewLayerInfo(bus, libraryBase);
        var destinationLayerInfo = NewLayerInfo(bus, libraryBase);
        var source = CreateLayer(
            bus,
            libraryBase,
            sourceLayerInfo,
            0,
            0,
            15,
            15);
        var destination = CreateLayer(
            bus,
            libraryBase,
            destinationLayerInfo,
            0,
            0,
            15,
            15);
        var sourcePlane = ReadBitMapPlane(bus, source.BitMap, 0);
        var destinationPlane = ReadBitMapPlane(bus, destination.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);
        bus.WriteByte(sourcePlane, 0x80, 0);
        Assert.Equal((byte)0, bus.ReadByte(destinationPlane));

        WriteLayerClipRect(bus, source.Layer, 0);
        WriteLayerClipRect(bus, destination.Layer, 0);
        var sourceFlagsBeforeRaster = ReadLayerFlags(bus, source.Layer);
        var sourceDamageBeforeRaster = LayersLayerCodec.ReadDamageList(
            ref layerMemory,
            APTR.FromPointer(source.Layer)).Raw;
        var destinationFlagsBeforeRaster = ReadLayerFlags(bus, destination.Layer);
        var destinationDamageBeforeRaster = LayersLayerCodec.ReadDamageList(
            ref layerMemory,
            APTR.FromPointer(destination.Layer)).Raw;
        var frame = new PortableLayers.LayersRegisterFrame
        {
            A0 = source.RastPort,
            A1 = destination.RastPort,
            D0 = 0,
            D1 = 0,
            D2 = 0,
            D3 = 0,
            D4 = 1,
            D5 = 1,
            D6 = 0xC0
        };
        var executor = (IGraphicsValidatedLayerRasterBackend)boot;
        Assert.True(executor.TryExecuteLayeredRaster(
            GraphicsLayersLvo.ClipBlit,
            ref frame,
            new GraphicsValidatedLayerEndpoint(
                destination.RastPort,
                destination.Layer,
                destination.FirstClipRect),
            new GraphicsValidatedLayerEndpoint(
                source.RastPort,
                source.Layer,
                source.FirstClipRect)));
        Assert.Equal((byte)0x80, bus.ReadByte(destinationPlane));
        Assert.Equal(sourceFlagsBeforeRaster, ReadLayerFlags(bus, source.Layer));
        Assert.Equal(
            sourceDamageBeforeRaster,
            LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(source.Layer)).Raw);
        Assert.Equal(destinationFlagsBeforeRaster, ReadLayerFlags(bus, destination.Layer));
        Assert.Equal(
            destinationDamageBeforeRaster,
            LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(destination.Layer)).Raw);

        WriteLayerClipRect(bus, source.Layer, source.FirstClipRect);
        WriteLayerClipRect(bus, destination.Layer, destination.FirstClipRect);
        DeleteLayer(bus, libraryBase, destination.Layer);
        DeleteLayer(bus, libraryBase, source.Layer);
        DisposeLayerInfo(bus, libraryBase, destinationLayerInfo);
        DisposeLayerInfo(bus, libraryBase, sourceLayerInfo);
        FreeBitMap(bus, destination.BitMap);
        FreeBitMap(bus, source.BitMap);
    }

    [Fact]
    public void ValidatedClipBlitProjectsIndependentSourceAndDestinationLayerScroll()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var sourceLayerInfo = NewLayerInfo(bus, libraryBase);
        var destinationLayerInfo = NewLayerInfo(bus, libraryBase);
        var source = CreateLayer(
            bus,
            libraryBase,
            sourceLayerInfo,
            0,
            0,
            15,
            15);
        var destination = CreateLayer(
            bus,
            libraryBase,
            destinationLayerInfo,
            0,
            0,
            15,
            15);
        var sourcePlane = ReadBitMapPlane(bus, source.BitMap, 0);
        var destinationPlane = ReadBitMapPlane(bus, destination.BitMap, 0);
        var layerMemory = new LayersTestGuestMemory(bus);

        try
        {
            var sourceScroll = new M68kCpuState
            {
                A = { [1] = source.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            var destinationScroll = new M68kCpuState
            {
                A = { [1] = destination.Layer },
                D = { [0] = 3, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                sourceScroll));
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                destinationScroll));

            // Logical source (2,1) and destination (3,1) both name the
            // first local bitmap pixel, but only after each Layer's own
            // independent scroll transform has been applied.
            bus.WriteByte(sourcePlane, 0x80, 0);
            bus.WriteByte(destinationPlane, 0, 0);
            var sourceFlags = ReadLayerFlags(bus, source.Layer);
            var destinationFlags = ReadLayerFlags(bus, destination.Layer);
            var sourceDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(source.Layer)).Raw;
            var destinationDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(destination.Layer)).Raw;
            var sourceEndpoint = new GraphicsValidatedLayerEndpoint(
                source.RastPort,
                source.Layer,
                source.FirstClipRect);
            var destinationEndpoint = new GraphicsValidatedLayerEndpoint(
                destination.RastPort,
                destination.Layer,
                destination.FirstClipRect);

            // The backend must consume the admitted endpoint heads and may
            // not rediscover either Layer.ClipRect while it is executing.
            WriteLayerClipRect(bus, source.Layer, 0);
            WriteLayerClipRect(bus, destination.Layer, 0);
            var frame = new PortableLayers.LayersRegisterFrame
            {
                A0 = source.RastPort,
                A1 = destination.RastPort,
                D0 = 2,
                D1 = 1,
                D2 = 3,
                D3 = 1,
                D4 = 1,
                D5 = 1,
                D6 = 0xC0
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.ClipBlit,
                ref frame,
                destinationEndpoint,
                sourceEndpoint));

            Assert.Equal((byte)0x80, bus.ReadByte(destinationPlane));
            Assert.Equal(sourceFlags, ReadLayerFlags(bus, source.Layer));
            Assert.Equal(destinationFlags, ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(
                sourceDamage,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(source.Layer)).Raw);
            Assert.Equal(
                destinationDamage,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(destination.Layer)).Raw);
        }
        finally
        {
            WriteLayerClipRect(bus, source.Layer, source.FirstClipRect);
            WriteLayerClipRect(bus, destination.Layer, destination.FirstClipRect);
            DeleteLayer(bus, libraryBase, destination.Layer);
            DeleteLayer(bus, libraryBase, source.Layer);
            DisposeLayerInfo(bus, libraryBase, destinationLayerInfo);
            DisposeLayerInfo(bus, libraryBase, sourceLayerInfo);
            FreeBitMap(bus, destination.BitMap);
            FreeBitMap(bus, source.BitMap);
        }
    }

    [Fact]
    public void ValidatedSelfClipBlitUsesOneEndpointAndRollsBackTheWholeOverlap()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
