            boot.FailNextValidatedRasterAfterFirstBlitForTest();
            Assert.False(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.ClipBlit,
                ref frame,
                endpoint,
                default));
            Assert.Equal(originalFrame, frame);
            Assert.Equal((byte)0x80, bus.ReadByte(plane));
            Assert.Equal(0, boot.CopperStartLayersPixelTransactionCountForTest);
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);

            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.ClipBlit,
                ref frame,
                endpoint,
                default));
            Assert.Equal((byte)0xC0, bus.ReadByte(plane));
            Assert.Equal(0, boot.CopperStartLayersPixelTransactionCountForTest);
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, surface.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(surface.Layer)).Raw);

            // The installed gateway must normalize A0 == A1 to one unique
            // RasterCore guard while leaving the original ABI frame intact.
            bus.WriteByte(plane, 0x80, 0);
            var installed = new M68kCpuState();
            installed.A[0] = surface.RastPort;
            installed.A[1] = surface.RastPort;
            installed.D[0] = 0;
            installed.D[1] = 0;
            installed.D[2] = 1;
            installed.D[3] = 0;
            installed.D[4] = 8;
            installed.D[5] = 1;
            installed.D[6] = 0xC0;
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(
                    AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ClipBlit),
                installed));
            Assert.Equal(0u, installed.D[0]);
            Assert.Equal(surface.RastPort, installed.A[0]);
            Assert.Equal(surface.RastPort, installed.A[1]);
            Assert.Equal((byte)0xC0, bus.ReadByte(plane));
            Assert.Equal(1, boot.CopperStartLayersLastRasterProviderGuardCountForTest);
            Assert.Equal(
                (ushort)1,
                boot.CopperStartLayersLastRasterProviderPrimaryGuardDepthForTest);
            Assert.Equal(
                0,
                boot.CopperStartLayersCompatibilityRasterDispatchCountForTest);
            Assert.Equal(0u, ReadLayerLockOwner(bus, surface.Layer));

            bus.WriteByte(plane, 0x80, 0);
            var declined = new M68kCpuState
            {
                ProgramCounter = 0x0000_2468,
                StatusRegister = (ushort)(M68kCpuState.Supervisor |
                    M68kCpuState.Extend)
            };
            declined.A[0] = surface.RastPort;
            declined.A[1] = surface.RastPort;
            declined.A[2] = 0x0002_A200;
            declined.A[5] = 0x0002_A500;
            declined.D[0] = 0;
            declined.D[1] = 0;
            declined.D[2] = 1;
            declined.D[3] = 0;
            declined.D[4] = 8;
            declined.D[5] = 1;
            declined.D[6] = 0xC0;
            declined.D[7] = 0xD7D7_A700;
            boot.FailNextValidatedRasterAfterFirstBlitForTest();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(
                    AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ClipBlit),
                declined));
            Assert.Equal(0u, declined.D[0]);
            Assert.Equal(0u, declined.D[1]);
            Assert.Equal(1u, declined.D[2]);
            Assert.Equal(0u, declined.D[3]);
            Assert.Equal(8u, declined.D[4]);
            Assert.Equal(1u, declined.D[5]);
            Assert.Equal(0xC0u, declined.D[6]);
            Assert.Equal(0xD7D7_A700u, declined.D[7]);
            Assert.Equal(surface.RastPort, declined.A[0]);
            Assert.Equal(surface.RastPort, declined.A[1]);
            Assert.Equal(0x0002_A200u, declined.A[2]);
            Assert.Equal(0x0002_A500u, declined.A[5]);
            Assert.Equal(0x0000_2468u, declined.ProgramCounter);
            Assert.Equal(
                (ushort)(M68kCpuState.Supervisor | M68kCpuState.Extend),
                declined.StatusRegister);
            Assert.Equal((byte)0x80, bus.ReadByte(plane));
            Assert.Equal(0, boot.CopperStartLayersPixelTransactionCountForTest);
            Assert.Equal(
                0,
                boot.CopperStartLayersCompatibilityRasterDispatchCountForTest);
            Assert.Equal(0u, ReadLayerLockOwner(bus, surface.Layer));
        }
        finally
        {
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

    [Fact]
    public void ValidatedGetRpAttrsDrawBoundsUsesTheSuppliedLayerEndpoint()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            5,
            7,
            20,
            22);
        var tags = AllocateGuestMemory(bus, 24);
        var rectangle = tags + 16;

        try
        {
            bus.WriteLong(
                tags,
                GraphicsRastPortAttributeOperations.RptagDrawBounds,
                0);
            bus.WriteLong(tags + 4, rectangle, 0);
            bus.WriteLong(tags + 8, GraphicsRastPortAttributeOperations.TagDone, 0);
            bus.WriteLong(tags + 12, 0, 0);
            for (var offset = 0u; offset < 8; offset += 2)
                bus.WriteWord(rectangle + offset, 0x7FFF, 0);

            // The provider must consume the already-admitted layer endpoint,
            // not rediscover the public ClipRect head from Layer/RastPort.
            WriteLayerClipRect(bus, surface.Layer, 0);
            var frame = new PortableLayers.LayersRegisterFrame
            {
                A0 = tags,
                A1 = surface.RastPort
            };
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.GetRPAttrsA,
                ref frame,
                new GraphicsValidatedLayerEndpoint(
                    surface.RastPort,
                    surface.Layer,
                    surface.FirstClipRect),
                default));
            Assert.Equal(0u, frame.D0);
            Assert.Equal((ushort)5, bus.ReadWord(rectangle));
            Assert.Equal((ushort)7, bus.ReadWord(rectangle + 2));
            Assert.Equal((ushort)20, bus.ReadWord(rectangle + 4));
            Assert.Equal((ushort)22, bus.ReadWord(rectangle + 6));
        }
        finally
        {
            WriteLayerClipRect(bus, surface.Layer, surface.FirstClipRect);
            FreeGuestMemory(bus, tags, 24);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

    [Fact]
    public void ValidatedSuperProjectionCoversPublicBackingAndWholeCallerDomainAtomically()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 32);
        var superBitMap = AllocatePlanarBitMap(bus, 32, 24);
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            5,
            7,
            20,
            22);
        LayerSurface blocker = default;

        try
        {
            var scroll = new M68kCpuState
            {
                A = { [1] = bottom.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                scroll));
            Assert.Equal((short)2, ReadLayerScrollX(bus, bottom.Layer));
            Assert.Equal((short)1, ReadLayerScrollY(bus, bottom.Layer));

            blocker = CreateLayerOnBitMaps(
                bus,
                libraryBase,
                layerInfo,
                displayBitMap,
                0,
                LayerCreationFlags.Simple,
                8,
                10,
                12,
                14);
            var publicHead = ReadLayerClipRect(bus, bottom.Layer);
            var superHead = ReadLayerSuperClipRect(bus, bottom.Layer);
            var obscured = FindObscuredClipRect(bus, bottom.Layer);
            var backing = ReadClipRectBitMap(bus, obscured);
            var layerMemory = new LayersTestGuestMemory(bus);
            var flagsBeforeRaster = ReadLayerFlags(bus, bottom.Layer);
            var damageBeforeRaster = LayersLayerCodec
                .ReadDamageList(ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw;
            Assert.NotEqual(0u, damageBeforeRaster);
            var damageBeforeRasterBytes = Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(
                    damageBeforeRaster + checked((uint)offset)))
                .ToArray();
            Assert.NotEqual(0u, publicHead);
            Assert.NotEqual(0u, superHead);
            Assert.NotEqual(0u, backing);
            ClearPlanarBitMap(bus, displayBitMap);
            ClearPlanarBitMap(bus, superBitMap);
            ClearPlanarBitMap(bus, backing);

            var frame = new PortableLayers.LayersRegisterFrame
            {
                A1 = bottom.RastPort,
                D0 = 1
            };
            var endpoint = new GraphicsValidatedLayerEndpoint(
                bottom.RastPort,
                bottom.Layer,
                publicHead,
                superHead);
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.SetRast,
                ref frame,
                endpoint,
                default));

            // Public logical (2,1)..(17,16) maps to screen bounds 5,7..20,22.
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 5, 7));
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 20, 22));
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 4, 7));
            // The obscured public partition goes to its owned compact bitmap,
            // not through the top layer's visible display pixels.
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 10, 12));
            Assert.Contains(
                SnapshotPlanarBitMap(bus, backing),
                value => value != 0);
            // All four complements use caller-Super coordinates; the current
            // viewport inside the SuperBitMap remains untouched.
            Assert.True(ReadPlanarBitMapPixel(bus, superBitMap, 0, 1));
            Assert.True(ReadPlanarBitMapPixel(bus, superBitMap, 31, 16));
            Assert.True(ReadPlanarBitMapPixel(bus, superBitMap, 5, 0));
            Assert.True(ReadPlanarBitMapPixel(bus, superBitMap, 5, 23));
            Assert.False(ReadPlanarBitMapPixel(bus, superBitMap, 2, 1));
            Assert.False(ReadPlanarBitMapPixel(bus, superBitMap, 17, 16));
            // Rasterization updates the exact public/backing fragments only.
            // DamageList and Refresh ownership remain in layers.library for
            // topology changes and BeginUpdate/EndUpdate; graphics must not
            // manufacture a dirty region merely by painting this layer.
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(
                damageBeforeRasterBytes,
                Enumerable.Range(0, checked((int)LayersRegionCodec.Size))
                    .Select(offset => bus.ReadByte(
                        damageBeforeRaster + checked((uint)offset)))
                    .ToArray());

            // ReadPixel must use the identical supplied ClipRect projection.
            // (5,4) is under the blocker in the bottom layer's logical
            // domain, so the read comes from its compact backing bitmap—not
            // from the display bitmap that the blocker currently owns.
            var readFrame = new PortableLayers.LayersRegisterFrame
            {
                A1 = bottom.RastPort,
                D0 = 5,
                D1 = 4
            };
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.ReadPixel,
                ref readFrame,
                endpoint,
                default));
            Assert.Equal(1u, readFrame.D0);
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(
                damageBeforeRasterBytes,
                Enumerable.Range(0, checked((int)LayersRegionCodec.Size))
                    .Select(offset => bus.ReadByte(
                        damageBeforeRaster + checked((uint)offset)))
                    .ToArray());

            // The matching write path must target the same hidden backing
            // fragment. Switch only the public foreground pen, so the result
            // is observable without altering the validated layer topology.
            bus.WriteByte(
                bottom.RastPort + (uint)GraphicsLayouts.RastPortFgPen,
                0,
                0);
            var writeFrame = new PortableLayers.LayersRegisterFrame
            {
                A1 = bottom.RastPort,
                D0 = 5,
                D1 = 4
            };
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.WritePixel,
                ref writeFrame,
                endpoint,
                default));
            Assert.Equal(0u, writeFrame.D0);

            readFrame = new PortableLayers.LayersRegisterFrame
            {
                A1 = bottom.RastPort,
                D0 = 5,
                D1 = 4
            };
            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.ReadPixel,
                ref readFrame,
                endpoint,
                default));
            Assert.Equal(0u, readFrame.D0);
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(
                damageBeforeRasterBytes,
                Enumerable.Range(0, checked((int)LayersRegionCodec.Size))
                    .Select(offset => bus.ReadByte(
                        damageBeforeRaster + checked((uint)offset)))
                    .ToArray());

            var displayBefore = SnapshotPlanarBitMap(bus, displayBitMap);
            var superBefore = SnapshotPlanarBitMap(bus, superBitMap);
            var backingBefore = SnapshotPlanarBitMap(bus, backing);
            frame = new PortableLayers.LayersRegisterFrame
            {
                A0 = bottom.RastPort,
                A1 = bottom.RastPort,
                D0 = 0,
                D1 = 0,
                D2 = 1,
                D3 = 0,
                D4 = 31,
                D5 = 24,
                D6 = 0xC0
            };
            boot.FailNextValidatedRasterAfterAllBlitsForTest();
            Assert.False(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.ClipBlit,
                ref frame,
                endpoint,
                default));
            Assert.Equal(displayBefore, SnapshotPlanarBitMap(bus, displayBitMap));
            Assert.Equal(superBefore, SnapshotPlanarBitMap(bus, superBitMap));
            Assert.Equal(backingBefore, SnapshotPlanarBitMap(bus, backing));
            // A failed projected operation is still graphics work, not a
            // topology mutation. Its undo path must leave Layers-owned
            // refresh/damage state exactly as it found it.
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(
                damageBeforeRaster,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(
                damageBeforeRasterBytes,
                Enumerable.Range(0, checked((int)LayersRegionCodec.Size))
                    .Select(offset => bus.ReadByte(
                        damageBeforeRaster + checked((uint)offset)))
                    .ToArray());
            Assert.Equal(0, boot.CopperStartLayersPixelTransactionCountForTest);
        }
        finally
        {
            if (blocker.Layer != 0)
                DeleteLayer(bus, libraryBase, blocker.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void LayeredSuperBitMapRectFillDuringBeginUpdateStaysWithinDamageProjection()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var superBitMap = AllocatePlanarBitMap(bus, 48, 32);
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            0,
            0,
            31,
            19);
        var scroll = new M68kCpuState
        {
            A = { [1] = bottom.Layer },
            D = { [0] = 2, [1] = 1 }
        };
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.ScrollLayer),
            scroll));
        Assert.Equal((short)2, ReadLayerScrollX(bus, bottom.Layer));
        Assert.Equal((short)1, ReadLayerScrollY(bus, bottom.Layer));
        var top = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            15,
            15);
        var updateActive = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNull);

            var obscured = FindObscuredClipRect(bus, bottom.Layer);
            var backing = ReadClipRectBitMap(bus, obscured);
            Assert.NotEqual(0u, backing);
            ClearPlanarBitMap(bus, displayBitMap);
            ClearPlanarBitMap(bus, superBitMap);
            ClearPlanarBitMap(bus, backing);

            var damageBytesBeforeRaster = Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray();
            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updateActive = true;
            var updateHead = ReadLayerClipRect(bus, bottom.Layer);
            Assert.Equal(0u, updateHead);
            var flagsBeforeRaster = ReadLayerFlags(bus, bottom.Layer);

            // Request the full SuperBitMap. During BeginUpdate the ordinary
            // graphics gateway must still restrict display, compact backing,
            // and off-viewport SuperBitMap writes to the damage projection.
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            WriteRastPortDrawMode(bus, bottom.RastPort, 0);
            WriteRastPortMask(bus, bottom.RastPort, 0xFF);
            var fill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 47, [3] = 31 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);
            Assert.DoesNotContain(
                SnapshotPlanarBitMap(bus, displayBitMap),
                value => value != 0);
            Assert.DoesNotContain(
                SnapshotPlanarBitMap(bus, superBitMap),
                value => value != 0);
            Assert.DoesNotContain(
                SnapshotPlanarBitMap(bus, backing),
                value => value != 0);
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(
                damage.Raw,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(
                damageBytesBeforeRaster,
                Enumerable.Range(0, checked((int)LayersRegionCodec.Size))
                    .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                    .ToArray());

            var end = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, end);
            updateActive = false;

        }
        finally
        {
            if (updateActive)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.EndUpdate),
                    end);
            }
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void ValidatedDualRtgClipBlitTranslatesSignedEndpointsAndRollsBackAtomically()
    {
        var machine = CreateRtgMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var sourceBitMap = AllocateRtgBitMap(boot, bus, 16, 16);
        var destinationBitMap = AllocateRtgBitMap(boot, bus, 32, 24);
        var sourceLayerInfo = NewLayerInfo(bus, libraryBase);
        var destinationLayerInfo = NewLayerInfo(bus, libraryBase);
        var source = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            sourceLayerInfo,
            sourceBitMap,
            0,
            LayerCreationFlags.Simple,
            3,
            4,
            10,
            11);
        var destination = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            destinationLayerInfo,
            destinationBitMap,
            0,
            LayerCreationFlags.Simple,
            20,
            10,
            27,
            17);

        try
        {
            // source screen = logical + (3,4) - (-2,-1)
            // destination screen = logical + (20,10) - (3,2)
            WriteLayerScroll(bus, source.Layer, -2, -1);
            WriteLayerScroll(bus, destination.Layer, 3, 2);
            FillRtgBitMap(
                boot,
                bus,
                sourceBitMap,
                (x, y) => checked((byte)(1 + ((y * 16 + x) & 0x7F))));
            FillRtgBitMap(boot, bus, destinationBitMap, (_, _) => 0xEE);
            var destinationBefore = SnapshotRtgBitMap(
                boot,
                bus,
                destinationBitMap);

            var frame = new PortableLayers.LayersRegisterFrame
            {
                A0 = source.RastPort,
                A1 = destination.RastPort,
                D0 = unchecked((uint)-2),
                D1 = unchecked((uint)-1),
                D2 = 3,
                D3 = 2,
                D4 = 8,
                D5 = 8,
                D6 = 0xC0
            };
            var sourceEndpoint = new GraphicsValidatedLayerEndpoint(
                source.RastPort,
                source.Layer,
                source.FirstClipRect);
            var destinationEndpoint = new GraphicsValidatedLayerEndpoint(
                destination.RastPort,
                destination.Layer,
                destination.FirstClipRect);
            var executor = (IGraphicsValidatedLayerRasterBackend)boot;

            WriteLayerClipRect(bus, source.Layer, 0);
            WriteLayerClipRect(bus, destination.Layer, 0);
            boot.FailNextValidatedRasterAfterAllBlitsForTest();
            Assert.False(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.ClipBlit,
                ref frame,
                destinationEndpoint,
                sourceEndpoint));
            Assert.Equal(
                destinationBefore,
                SnapshotRtgBitMap(boot, bus, destinationBitMap));
            Assert.Equal(0, boot.CopperStartLayersPixelTransactionCountForTest);

            Assert.True(executor.TryExecuteLayeredRaster(
                GraphicsLayersLvo.ClipBlit,
                ref frame,
                destinationEndpoint,
                sourceEndpoint));
            AssertRtgRectangle(
                boot,
                bus,
                destinationBitMap,
                20,
                10,
                8,
                8,
                (x, y) => checked((byte)(1 + (((y + 4) * 16 + x + 3) & 0x7F))));
        }
        finally
        {
            WriteLayerClipRect(bus, source.Layer, source.FirstClipRect);
            WriteLayerClipRect(bus, destination.Layer, destination.FirstClipRect);
            DeleteLayer(bus, libraryBase, destination.Layer);
            DeleteLayer(bus, libraryBase, source.Layer);
            DisposeLayerInfo(bus, libraryBase, destinationLayerInfo);
            DisposeLayerInfo(bus, libraryBase, sourceLayerInfo);
            FreeBitMap(bus, destinationBitMap);
            FreeBitMap(bus, sourceBitMap);
        }
    }

    [Fact]
    public void ResetReleasesEveryLayersOwnedGuestAllocationBeforeReinstall()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var baseline = boot.CopperStartAvailablePublicMemory;

        var pooledTransaction =
            boot.BeginCopperStartLayersPixelTransactionForTest(4);
        Assert.NotEqual(0u, pooledTransaction);
        Assert.True(boot.ApplyCopperStartLayersPixelTransactionForTest(
            pooledTransaction));
        boot.CompleteCopperStartLayersPixelTransactionForTest(
            pooledTransaction);
        Assert.Equal(1, boot.CopperStartLayersPixelTransactionPoolCountForTest);

        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(
            bus,
            libraryBase,
            layerInfo,
            0,
            0,
            15,
            15);
        Assert.True(boot.CopperStartAvailablePublicMemory < baseline);

        // The display BitMap is caller-owned; Layers must retire the
        // LayerInfo/layer/RastPort/ClipRects/descriptors while leaving that
        // one allocation available to its original graphics owner.
        boot.ResetCopperStartLayersForTest();
        Assert.False(boot.HasCopperStartLayers);
        Assert.Equal(0, boot.CopperStartLayersGatewayCount);
        Assert.Equal(0, boot.CopperStartLayersPixelTransactionPoolCountForTest);
        FreeBitMap(bus, surface.BitMap);

        Assert.True(boot.ReinstallCopperStartLayersForTest());
        Assert.Equal(baseline, boot.CopperStartAvailablePublicMemory);
        Assert.Equal(0, boot.CopperStartLayersPixelTransactionPoolCountForTest);
    }

    [Fact]
    public void SmartObscuredBackingUsesClassicCompactWordAlignedStride()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var allocate = new M68kCpuState
        {
            D =
            {
                [0] = 32,
                [1] = 16,
                [2] = 1,
                [3] = (uint)BitMapFlags.Clear
            }
        };
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(AmigaKickstartHost.GraphicsLibraryBase, -918),
            allocate));
        var displayBitMap = allocate.D[0];
        Assert.NotEqual(0u, displayBitMap);
        Assert.Equal((ushort)4, ReadBitMapBytesPerRow(bus, displayBitMap));

        var layerInfo = NewLayerInfo(bus, libraryBase);
        var smart = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Smart,
            0,
            0,
            15,
            15);
        var blocker = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            11,
            11);

        var obscured = ReadLayerClipRect(bus, smart.Layer);
        while (obscured != 0 && ReadClipRectObscuringLayer(bus, obscured) == 0)
        {
            obscured = ReadClipRectNext(bus, obscured);
        }
        Assert.NotEqual(0u, obscured);
        var backing = ReadClipRectBitMap(bus, obscured);
        Assert.NotEqual(0u, backing);
        Assert.NotEqual(displayBitMap, backing);
        Assert.Equal((ushort)2, ReadBitMapBytesPerRow(bus, backing));
        Assert.Equal((ushort)8, ReadBitMapRows(bus, backing));
        Assert.Equal((byte)1, ReadBitMapDepth(bus, backing));

        DeleteLayer(bus, libraryBase, blocker.Layer);
        DeleteLayer(bus, libraryBase, smart.Layer);
        DisposeLayerInfo(bus, libraryBase, layerInfo);
        FreeBitMap(bus, displayBitMap);
    }

    [Fact]
    public void RtgTopologyFailureRestoresProviderPixelsAndPublishesNoLayer()
    {
        var machine = new Machine(MachineOptions
            .ForProfile(MachineProfile.A500Pal512KBoot)
            .WithRtgVram(16L * 1024 * 1024)
            .WithCpu(AmigaM68kCoreFactory.Default, M68kBackendKind.AccurateM68040)
            .WithLiveAgnusDma(false));
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;

        var allocateBitMap = new M68kCpuState();
        allocateBitMap.D[0] = 8;
        allocateBitMap.D[1] = 4;
        allocateBitMap.D[2] = 8;
        allocateBitMap.D[3] = (uint)BitMapFlags.Clear;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(AmigaKickstartHost.GraphicsLibraryBase, -918),
            allocateBitMap));
        var bitMap = allocateBitMap.D[0];
        Assert.True(boot.CyberGraphics.TryGetBitMapSurface(
            bitMap,
            out var surface));
        var expected = Enumerable.Range(0, surface.BytesPerRow * surface.Height)
            .Select(index => unchecked((byte)(0x40 + index)))
            .ToArray();
        for (var offset = 0; offset < expected.Length; offset++)
        {
            bus.WriteByte(
                surface.GuestBaseAddress + checked((uint)offset),
                expected[offset],
                0);
        }

        var layerInfo = NewLayerInfo(bus, libraryBase);
        var availableBeforeCreate = boot.CopperStartAvailablePublicMemory;
        boot.FailNextCopperStartLayersPixelTransactionAfterApplyForTest();
        var create = new M68kCpuState();
        create.A[0] = layerInfo;
        create.A[1] = bitMap;
        create.D[0] = 0;
        create.D[1] = 0;
        create.D[2] = 7;
        create.D[3] = 3;
        create.D[4] = (uint)LayerCreationFlags.Simple;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.CreateUpfrontLayer),
            create));

        Assert.Equal(0u, create.D[0]);
        Assert.Equal(0u, ReadTopLayer(bus, layerInfo));
        Assert.Equal(availableBeforeCreate, boot.CopperStartAvailablePublicMemory);
        Assert.Equal(
            expected,
            Enumerable.Range(0, expected.Length)
                .Select(offset => bus.ReadByte(
                    surface.GuestBaseAddress + checked((uint)offset)))
                .ToArray());

        DisposeLayerInfo(bus, libraryBase, layerInfo);
        FreeBitMap(bus, bitMap);
    }

    [Fact]
    public void RtgSuperBitMapJournalCommitsSyncCopyAndScrollAndRollsBackFailures()
    {
        var machine = CreateRtgMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var displayBitMap = AllocateRtgBitMap(boot, bus, 8, 4);
        var superBitMap = AllocateRtgBitMap(boot, bus, 16, 8);
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            0,
            0,
            7,
            3);
        LockLayer(bus, libraryBase, surface.Layer);

        try
        {
            FillRtgBitMap(boot, bus, displayBitMap,
                (x, y) => checked((byte)(0x10 + y * 8 + x)));
            FillRtgBitMap(boot, bus, superBitMap, (_, _) => 0xE1);

            var sync = new M68kCpuState { A = { [0] = surface.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(
                    AmigaKickstartHost.GraphicsLibraryBase,
                    GraphicsLayersLvo.SyncSBitMap),
                sync));
            AssertRtgRectangle(
                boot,
                bus,
                superBitMap,
                0,
                0,
                8,
                4,
                (x, y) => checked((byte)(0x10 + y * 8 + x)));

            FillRtgBitMap(boot, bus, displayBitMap,
                (x, y) => checked((byte)(0x40 + y * 8 + x)));
            var superBeforeFailedSync = SnapshotRtgBitMap(
                boot,
                bus,
                superBitMap);
            boot.FailNextCopperStartLayersPixelTransactionAfterApplyForTest();
            sync.D[0] = 0xFFFF_FFFF;
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(
                    AmigaKickstartHost.GraphicsLibraryBase,
                    GraphicsLayersLvo.SyncSBitMap),
                sync));
            Assert.Equal(0u, sync.D[0]);
            Assert.Equal(
                superBeforeFailedSync,
                SnapshotRtgBitMap(boot, bus, superBitMap));

            FillRtgBitMap(boot, bus, superBitMap,
                (x, y) => checked((byte)(0x60 + ((y * 16 + x) & 0x3F))));
            FillRtgBitMap(boot, bus, displayBitMap, (_, _) => 0x05);
            var copy = new M68kCpuState { A = { [0] = surface.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(
                    AmigaKickstartHost.GraphicsLibraryBase,
                    GraphicsLayersLvo.CopySBitMap),
                copy));
            AssertRtgRectangle(
                boot,
                bus,
                displayBitMap,
                0,
                0,
                8,
                4,
                (x, y) => checked((byte)(0x60 + y * 16 + x)));

            FillRtgBitMap(boot, bus, superBitMap,
                (x, y) => checked((byte)(0xA0 + ((y * 16 + x) & 0x3F))));
            var displayBeforeFailedCopy = SnapshotRtgBitMap(
                boot,
                bus,
                displayBitMap);
            boot.FailNextCopperStartLayersPixelTransactionAfterApplyForTest();
            copy.D[0] = 0xFFFF_FFFF;
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(
                    AmigaKickstartHost.GraphicsLibraryBase,
                    GraphicsLayersLvo.CopySBitMap),
                copy));
            Assert.Equal(0u, copy.D[0]);
            Assert.Equal(
                displayBeforeFailedCopy,
                SnapshotRtgBitMap(boot, bus, displayBitMap));

            FillRtgBitMap(boot, bus, displayBitMap,
                (x, y) => checked((byte)(0x20 + y * 8 + x)));
            FillRtgBitMap(boot, bus, superBitMap,
                (x, y) => checked((byte)(0x80 + ((y * 16 + x) & 0x7F))));
            var displayBeforeFailedScroll = SnapshotRtgBitMap(
                boot,
                bus,
                displayBitMap);
            var superBeforeFailedScroll = SnapshotRtgBitMap(
                boot,
                bus,
                superBitMap);
            var scroll = new M68kCpuState
            {
                A = { [1] = surface.Layer },
                D = { [0] = 8, [1] = 4 }
            };
            boot.FailNextCopperStartLayersPixelTransactionAfterApplyForTest();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                scroll));
            Assert.Equal(8u, scroll.D[0]);
            Assert.Equal(
                displayBeforeFailedScroll,
                SnapshotRtgBitMap(boot, bus, displayBitMap));
            Assert.Equal(
                superBeforeFailedScroll,
                SnapshotRtgBitMap(boot, bus, superBitMap));
            Assert.Equal((short)0, ReadLayerScrollX(bus, surface.Layer));
            Assert.Equal((short)0, ReadLayerScrollY(bus, surface.Layer));

            scroll.D[0] = 8;
            scroll.D[1] = 4;
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                scroll));
            Assert.Equal(8u, scroll.D[0]);
            AssertRtgRectangle(
                boot,
                bus,
                superBitMap,
                0,
                0,
                8,
                4,
                (x, y) => checked((byte)(0x20 + y * 8 + x)));
            AssertRtgRectangle(
                boot,
                bus,
                displayBitMap,
                0,
                0,
                8,
                4,
                (x, y) => checked((byte)(0x80 + (y + 4) * 16 + x + 8)));
            Assert.Equal((short)8, ReadLayerScrollX(bus, surface.Layer));
            Assert.Equal((short)4, ReadLayerScrollY(bus, surface.Layer));
        }
        finally
        {
            UnlockLayer(bus, libraryBase, surface.Layer);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SuperScrollPixelJournalAcceptsPartialFullOppositeAndOriginViewports()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var displayBitMap = AllocatePlanarBitMap(bus, 16, 16);
        var superBitMap = AllocatePlanarBitMap(bus, 32, 16);
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            0,
            0,
            15,
            15);
        LockLayer(bus, libraryBase, surface.Layer);

        try
        {
            Scroll(17, 0, 17, 0);  // Partially beyond the right edge.
            Scroll(15, 0, 32, 0);  // Fully beyond the right edge.
            Scroll(-33, 0, -1, 0); // Partially beyond the opposite edge.
            Scroll(1, 0, 0, 0);    // Return to the origin.
        }
        finally
        {
            UnlockLayer(bus, libraryBase, surface.Layer);
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }

        void Scroll(int deltaX, int deltaY, short expectedX, short expectedY)
        {
            var state = new M68kCpuState
            {
                A = { [1] = surface.Layer },
                D =
                {
                    [0] = unchecked((uint)deltaX),
                    [1] = unchecked((uint)deltaY)
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                state));
            Assert.Equal(unchecked((uint)deltaX), state.D[0]);
            Assert.Equal(unchecked((uint)deltaY), state.D[1]);
            Assert.Equal(unchecked((short)expectedX),
                ReadLayerScrollX(bus, surface.Layer));
            Assert.Equal(unchecked((short)expectedY),
                ReadLayerScrollY(bus, surface.Layer));
            Assert.Equal(0, boot.CopperStartLayersPixelTransactionCountForTest);
        }
    }

    [Fact]
    public void EmptyPixelJournalsApplyAndLeaveNoCompletionOrRollbackLedgerEntries()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        Assert.Equal(0, boot.CopperStartLayersPixelTransactionCountForTest);

        var completed = boot.BeginCopperStartLayersPixelTransactionForTest(4);
        Assert.NotEqual(0u, completed);
        Assert.Equal(1, boot.CopperStartLayersPixelTransactionCountForTest);
        Assert.True(boot.ApplyCopperStartLayersPixelTransactionForTest(completed));
        boot.CompleteCopperStartLayersPixelTransactionForTest(completed);
        Assert.Equal(0, boot.CopperStartLayersPixelTransactionCountForTest);
        Assert.Equal(1, boot.CopperStartLayersPixelTransactionPoolCountForTest);
        Assert.False(boot.ApplyCopperStartLayersPixelTransactionForTest(completed));

        var canceled = boot.BeginCopperStartLayersPixelTransactionForTest(4);
        Assert.NotEqual(0u, canceled);
        Assert.Equal(1, boot.CopperStartLayersPixelTransactionCountForTest);
        Assert.Equal(0, boot.CopperStartLayersPixelTransactionPoolCountForTest);
        Assert.True(boot.ApplyCopperStartLayersPixelTransactionForTest(canceled));
        boot.CancelCopperStartLayersPixelTransactionForTest(canceled);
        Assert.Equal(0, boot.CopperStartLayersPixelTransactionCountForTest);
        Assert.Equal(1, boot.CopperStartLayersPixelTransactionPoolCountForTest);
        Assert.False(boot.ApplyCopperStartLayersPixelTransactionForTest(canceled));
    }

    [Fact]
    public void LatePlanarCaptureFailureDoesNotPoolOversizedBufferAndResetReleasesIt()
    {
        var machine = CreateExpandedMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;

        const ushort bytesPerRow = 32768;
        const ushort rows = 160;
        var bytesPerPlane = checked((int)bytesPerRow * rows);
        Assert.True(bytesPerPlane > 4 * 1024 * 1024);
        Assert.True(bus.RealFastRam.Length >= bytesPerPlane);

        var bitMap = AllocateGuestMemory(bus, BitMap.Size);
        var rastPort = AllocateGuestMemory(bus, RastPort.Size);
        WriteBitMapBytesPerRow(bus, bitMap, bytesPerRow);
        WriteBitMapRows(bus, bitMap, rows);
        WriteBitMapDepth(bus, bitMap, 2);
        WriteBitMapPlane(bus, bitMap, 0, bus.RealFastRamBase);
        // The second header is readable, but its declared complete plane span
        // extends beyond the configured Fast RAM mapping. Capture therefore
        // fails only after the first >4 MiB plane buffer has grown and filled.
        WriteBitMapPlane(
            bus,
            bitMap,
            1,
            bus.RealFastRamBase + 6u * 1024u * 1024u);

        var transaction =
            boot.BeginCopperStartLayersPixelTransactionForTest(1);
        Assert.NotEqual(0u, transaction);
        Assert.False(boot.StageCopperStartLayersPixelBackfillForTest(
            transaction,
            rastPort,
            bitMap,
            LayerBackfillHook.Backfill,
            0,
            0,
            1,
            1));
        Assert.Equal(1, boot.CopperStartLayersPixelTransactionCountForTest);
        Assert.Equal(0, boot.CopperStartLayersPixelTransactionPoolCountForTest);
        Assert.True(
            boot.CopperStartLayersPixelTransactionRetainedSnapshotBytesForTest >=
            bytesPerPlane);

        boot.ResetCopperStartLayersForTest();
        Assert.False(boot.HasCopperStartLayers);
        Assert.Equal(0, boot.CopperStartLayersPixelTransactionCountForTest);
        Assert.Equal(0, boot.CopperStartLayersPixelTransactionPoolCountForTest);
        Assert.Equal(
            0,
            boot.CopperStartLayersPixelTransactionRetainedSnapshotBytesForTest);
    }

