    [Fact]
    public void OpaqueResourceLedgerRejectsForgedPrefixesAndResetReleasesExactHostExtent()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var baseline = boot.CopperStartAvailablePublicMemory;

        var payload = boot.AllocateCopperStartLayersOpaqueForTest(64);
        Assert.NotEqual(0u, payload);
        Assert.Equal(1, boot.CopperStartLayersOpaqueAllocationCountForTest);
        Assert.True(boot.IsCopperStartLayersOpaqueAllocationForTest(payload, 64));
        Assert.False(boot.IsCopperStartLayersOpaqueAllocationForTest(payload, 63));
        Assert.False(boot.IsCopperStartLayersOpaqueAllocationForTest(payload, 65));

        // A guest can reproduce every diagnostic-prefix byte. Authority is
        // the controller-owned payload/size ledger, so neither a smaller nor
        // a larger forged extent becomes releasable.
        var forgedAllocation = AllocateGuestMemory(bus, 16 + 96);
        var forgedPayload = forgedAllocation + 16;
        bus.WriteLong(forgedAllocation, 0x4353_4F50, 0);
        bus.WriteLong(forgedAllocation + 4, 32, 0);
        bus.WriteLong(forgedAllocation + 8, forgedPayload, 0);
        bus.WriteLong(forgedAllocation + 12, 48, 0);
        Assert.False(boot.IsCopperStartLayersOpaqueAllocationForTest(
            forgedPayload,
            32));
        bus.WriteLong(forgedAllocation + 4, 96, 0);
        bus.WriteLong(forgedAllocation + 12, 112, 0);
        Assert.False(boot.IsCopperStartLayersOpaqueAllocationForTest(
            forgedPayload,
            96));
        boot.FreeCopperStartLayersOpaqueForTest(forgedPayload);
        Assert.Equal(1, boot.CopperStartLayersOpaqueAllocationCountForTest);

        // Corrupt the real diagnostic size in both directions. FreeOpaque
        // must ignore it, remove exactly the host-ledger entry, and pass the
        // host-ledger extent to Exec FreeMem.
        bus.WriteLong(payload - 12, uint.MaxValue, 0);
        bus.WriteLong(payload - 4, uint.MaxValue, 0);
        boot.FreeCopperStartLayersOpaqueForTest(payload);
        Assert.Equal(0, boot.CopperStartLayersOpaqueAllocationCountForTest);
        Assert.False(boot.IsCopperStartLayersOpaqueAllocationForTest(payload, 64));
        Assert.Equal(baseline - 112u, boot.CopperStartAvailablePublicMemory);
        FreeGuestMemory(bus, forgedAllocation, 16 + 96);
        Assert.Equal(baseline, boot.CopperStartAvailablePublicMemory);

        var leaked = boot.AllocateCopperStartLayersOpaqueForTest(80);
        Assert.NotEqual(0u, leaked);
        Assert.Equal(1, boot.CopperStartLayersOpaqueAllocationCountForTest);
        boot.ResetCopperStartLayersForTest();
        Assert.Equal(0, boot.CopperStartLayersOpaqueAllocationCountForTest);
        Assert.True(boot.ReinstallCopperStartLayersForTest());
        Assert.Equal(baseline, boot.CopperStartAvailablePublicMemory);
    }

    [Fact]
    public void OpaqueResourceLedgerCapacityIsAllocationFreeAtomicReusableAndResetBounded()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var baseline = boot.CopperStartAvailablePublicMemory;
        var capacity = boot.CopperStartLayersOpaqueAllocationCapacityForTest;
        Assert.Equal(16_384, capacity);
        var payloads = new uint[capacity];

        // Warm the fixed ledger/hash/free-list path before measuring it.
        var warm = boot.AllocateCopperStartLayersOpaqueForTest(1);
        Assert.NotEqual(0u, warm);
        boot.FreeCopperStartLayersOpaqueForTest(warm);
        Assert.Equal(0, boot.CopperStartLayersOpaqueAllocationCountForTest);
        Assert.Equal(baseline, boot.CopperStartAvailablePublicMemory);

        GC.Collect();
        GC.WaitForPendingFinalizers();
        GC.Collect();
        var allocationBytesBefore = GC.GetAllocatedBytesForCurrentThread();
        for (var index = 0; index < payloads.Length; index++)
            payloads[index] = boot.AllocateCopperStartLayersOpaqueForTest(1);
        var allocationBytesAfter = GC.GetAllocatedBytesForCurrentThread();

        Assert.Equal(allocationBytesBefore, allocationBytesAfter);
        Assert.All(payloads, payload => Assert.NotEqual(0u, payload));
        Assert.Equal(capacity, boot.CopperStartLayersOpaqueAllocationCountForTest);
        Assert.Equal(0u, boot.AllocateCopperStartLayersOpaqueForTest(1));
        Assert.Equal(capacity, boot.CopperStartLayersOpaqueAllocationCountForTest);

        var reusableIndex = capacity / 2;
        var released = payloads[reusableIndex];
        boot.FreeCopperStartLayersOpaqueForTest(released);
        Assert.Equal(capacity - 1, boot.CopperStartLayersOpaqueAllocationCountForTest);
        var replacement = boot.AllocateCopperStartLayersOpaqueForTest(1);
        Assert.NotEqual(0u, replacement);
        payloads[reusableIndex] = replacement;
        Assert.Equal(capacity, boot.CopperStartLayersOpaqueAllocationCountForTest);

        allocationBytesBefore = GC.GetAllocatedBytesForCurrentThread();
        for (var index = 0; index < payloads.Length; index++)
            boot.FreeCopperStartLayersOpaqueForTest(payloads[index]);
        allocationBytesAfter = GC.GetAllocatedBytesForCurrentThread();
        Assert.Equal(allocationBytesBefore, allocationBytesAfter);
        Assert.Equal(0, boot.CopperStartLayersOpaqueAllocationCountForTest);
        Assert.Equal(baseline, boot.CopperStartAvailablePublicMemory);

        var leaked = boot.AllocateCopperStartLayersOpaqueForTest(1);
        Assert.NotEqual(0u, leaked);
        boot.ResetCopperStartLayersForTest();
        Assert.Equal(0, boot.CopperStartLayersOpaqueAllocationCountForTest);
        Assert.True(boot.ReinstallCopperStartLayersForTest());
        Assert.Equal(baseline, boot.CopperStartAvailablePublicMemory);
    }

    [Fact]
    public void NoDamageSimpleLayerLockRoundTripsPreserveFlagsAndBeginUpdateLifecycle()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var fatten = new M68kCpuState { A = { [0] = layerInfo } };
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.FattenLayerInfo),
            fatten));
        Assert.NotEqual(0u, fatten.D[0]);
        var thin = new M68kCpuState { A = { [0] = layerInfo } };
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.ThinLayerInfo),
            thin));
        var surface = CreateLayer(bus, libraryBase, layerInfo, 2, 3, 25, 13);
        var expectedFlags = ReadLayerFlags(bus, surface.Layer);
        Assert.Equal((ushort)LayerCreationFlags.Simple, expectedFlags);

        try
        {
            InvokeAndAssertFlags(LayersLvo.LockLayer,
                state => state.A[1] = surface.Layer);
            InvokeAndAssertFlags(LayersLvo.UnlockLayer,
                state => state.A[0] = surface.Layer);
            InvokeAndAssertFlags(LayersLvo.LockLayers,
                state => state.A[0] = layerInfo);
            InvokeAndAssertFlags(LayersLvo.UnlockLayers,
                state => state.A[0] = layerInfo);
            InvokeAndAssertFlags(LayersLvo.LockLayerInfo,
                state => state.A[0] = layerInfo);
            InvokeAndAssertFlags(LayersLvo.UnlockLayerInfo,
                state => state.A[0] = layerInfo);

            var begin = new M68kCpuState
            {
                A = { [0] = surface.Layer },
                D = { [0] = 0xA5A5_A5A5 }
            };
            var gatewayCompleted = InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin);
            Assert.True(gatewayCompleted);
            Assert.Equal(1u, begin.D[0]);
            Assert.Equal((ushort)(expectedFlags | (ushort)LayerFlags.Updating),
                ReadLayerFlags(bus, surface.Layer));

            var end = new M68kCpuState
            {
                A = { [0] = surface.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                end));
            Assert.Equal(expectedFlags, ReadLayerFlags(bus, surface.Layer));
        }
        finally
        {
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }

        void InvokeAndAssertFlags(int lvo, Action<M68kCpuState> initialize)
        {
            var state = new M68kCpuState();
            initialize(state);
            Assert.True(InvokeHostTrap(bus, Lvo(libraryBase, lvo), state));
            Assert.Equal(expectedFlags, ReadLayerFlags(bus, surface.Layer));
        }
    }

    [Fact]
    public void LayeredGraphicsGatewayClipBlitIntersectsBothActiveDamagePartitions()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var sourceInfo = NewLayerInfo(bus, libraryBase);
        var destinationInfo = NewLayerInfo(bus, libraryBase);
        var sourceBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var destinationBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var source = CreateLayerOnBitMaps(
            bus, libraryBase, sourceInfo, sourceBitMap, 0,
            LayerCreationFlags.Simple, 0, 0, 31, 19);
        var sourceOccluder = CreateLayerOnBitMaps(
            bus, libraryBase, sourceInfo, sourceBitMap, 0,
            LayerCreationFlags.Simple, 4, 4, 15, 15);
        var destination = CreateLayerOnBitMaps(
            bus, libraryBase, destinationInfo, destinationBitMap, 0,
            LayerCreationFlags.Simple, 0, 0, 31, 19);
        var destinationOccluder = CreateLayerOnBitMaps(
            bus, libraryBase, destinationInfo, destinationBitMap, 0,
            LayerCreationFlags.Simple, 6, 4, 17, 15);
        var layerMemory = new LayersTestGuestMemory(bus);
        var sourceUpdateActive = false;
        var destinationUpdateActive = false;

        try
        {
            foreach (var occluder in new[] { sourceOccluder, destinationOccluder })
            {
                var move = new M68kCpuState
                {
                    A = { [1] = occluder.Layer },
                    D = { [0] = 2, [1] = 1 }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.MoveLayer),
                    move));
                Assert.Equal(1u, move.D[0]);
            }

            var sourceDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(source.Layer));
            var destinationDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(destination.Layer));
            Assert.True(sourceDamage.IsNotNull);
            Assert.True(destinationDamage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, sourceDamage).IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, destinationDamage).IsNotNull);
            var sourceDamageBytes = ReadRegionBytes(sourceDamage.Raw);
            var destinationDamageBytes = ReadRegionBytes(destinationDamage.Raw);

            var beginSource = new M68kCpuState { A = { [0] = source.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), beginSource));
            Assert.Equal(1u, beginSource.D[0]);
            sourceUpdateActive = true;
            var beginDestination = new M68kCpuState
            {
                A = { [0] = destination.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), beginDestination));
            Assert.Equal(1u, beginDestination.D[0]);
            destinationUpdateActive = true;

            var sourceHead = ReadLayerClipRect(bus, source.Layer);
            var destinationHead = ReadLayerClipRect(bus, destination.Layer);
            var sourceBounds = ReadBounds(sourceHead);
            var destinationBounds = ReadBounds(destinationHead);
            Assert.NotEmpty(sourceBounds);
            Assert.NotEmpty(destinationBounds);
            bool InBounds(
                List<(short MinX, short MinY, short MaxX, short MaxY)> bounds,
                int x,
                int y) => bounds.Any(rect =>
                    x >= rect.MinX && x <= rect.MaxX &&
                    y >= rect.MinY && y <= rect.MaxY);

            var overlapCount = 0;
            var sourceOnlyCount = 0;
            var destinationOnlyCount = 0;
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                var inSource = InBounds(sourceBounds, x, y);
                var inDestination = InBounds(destinationBounds, x, y);
                if (inSource && inDestination) overlapCount++;
                else if (inSource) sourceOnlyCount++;
                else if (inDestination) destinationOnlyCount++;
            }
            Assert.True(overlapCount > 0);
            Assert.True(sourceOnlyCount > 0);
            Assert.True(destinationOnlyCount > 0);

            ClearPlanarBitMap(bus, sourceBitMap);
            ClearPlanarBitMap(bus, destinationBitMap);
            var sourcePlane = ReadBitMapPlane(bus, sourceBitMap, 0);
            for (uint offset = 0; offset < 4u * 20u; offset++)
                bus.WriteByte(sourcePlane + offset, 0xFF, 0);

            var sourceFlags = ReadLayerFlags(bus, source.Layer);
            var destinationFlags = ReadLayerFlags(bus, destination.Layer);
            var blit = new M68kCpuState
            {
                A = { [0] = source.RastPort, [1] = destination.RastPort },
                D =
                {
                    [0] = 0, [1] = 0, [2] = 0, [3] = 0,
                    [4] = 32, [5] = 20, [6] = 0xC0, [7] = 0xB2B2_7007
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ClipBlit),
                blit));

            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                var expected = InBounds(sourceBounds, x, y) &&
                    InBounds(destinationBounds, x, y);
                Assert.Equal(expected,
                    ReadPlanarBitMapPixel(bus, destinationBitMap, x, y));
            }

            // Re-run the same active projections with independent logical
            // scroll transforms and a coordinate-patterned source. ClipRects
            // remain in screen coordinates; both endpoint transforms must
            // still meet in the correct logical transfer cells.
            const short sourceScrollX = 2;
            const short sourceScrollY = 1;
            const short destinationScrollX = -1;
            const short destinationScrollY = 2;
            WriteLayerScroll(bus, source.Layer, sourceScrollX, sourceScrollY);
            WriteLayerScroll(
                bus,
                destination.Layer,
                destinationScrollX,
                destinationScrollY);
            ClearPlanarBitMap(bus, sourceBitMap);
            var sourcePattern = new bool[20, 32];
            var sourceStride = ReadBitMapBytesPerRow(bus, sourceBitMap);
            sourcePlane = ReadBitMapPlane(bus, sourceBitMap, 0);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                var set = (x + (2 * y)) % 3 == 0;
                sourcePattern[y, x] = set;
                if (!set) continue;
                var byteAddress = sourcePlane +
                    checked((uint)(y * sourceStride + (x >> 3)));
                var value = bus.ReadByte(byteAddress);
                bus.WriteByte(
                    byteAddress,
                    (byte)(value | (0x80 >> (x & 7))),
                    0);
            }
            ClearPlanarBitMap(bus, destinationBitMap);
            blit = new M68kCpuState
            {
                A = { [0] = source.RastPort, [1] = destination.RastPort },
                D =
                {
                    [0] = 0, [1] = 0, [2] = 0, [3] = 0,
                    [4] = 32, [5] = 20, [6] = 0xC0, [7] = 0xB2B2_7007
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ClipBlit),
                blit));
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                var logicalX = x + destinationScrollX;
                var logicalY = y + destinationScrollY;
                var sourceScreenX = logicalX - sourceScrollX;
                var sourceScreenY = logicalY - sourceScrollY;
                var expected = InBounds(destinationBounds, x, y) &&
                    logicalX >= 0 && logicalX < 32 &&
                    logicalY >= 0 && logicalY < 20 &&
                    InBounds(sourceBounds, sourceScreenX, sourceScreenY) &&
                    sourcePattern[sourceScreenY, sourceScreenX];
                Assert.True(expected == ReadPlanarBitMapPixel(
                    bus, destinationBitMap, x, y),
                    $"scroll mismatch at screen ({x},{y}), logical ({logicalX},{logicalY})");
            }

            Assert.Equal(sourceHead, ReadLayerClipRect(bus, source.Layer));
            Assert.Equal(destinationHead, ReadLayerClipRect(bus, destination.Layer));
            Assert.Equal(sourceFlags, ReadLayerFlags(bus, source.Layer));
            Assert.Equal(destinationFlags, ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(sourceDamage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(source.Layer)).Raw);
            Assert.Equal(destinationDamage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(destination.Layer)).Raw);
            Assert.Equal(sourceDamageBytes, ReadRegionBytes(sourceDamage.Raw));
            Assert.Equal(destinationDamageBytes, ReadRegionBytes(destinationDamage.Raw));

            var endDestination = new M68kCpuState
            {
                A = { [0] = destination.Layer }, D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, endDestination);
            destinationUpdateActive = false;
            var endSource = new M68kCpuState
            {
                A = { [0] = source.Layer }, D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, endSource);
            sourceUpdateActive = false;


        }
        finally
        {
            if (destinationUpdateActive)
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate),
                    new M68kCpuState { A = { [0] = destination.Layer } });
            if (sourceUpdateActive)
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate),
                    new M68kCpuState { A = { [0] = source.Layer } });
            DeleteLayer(bus, libraryBase, destinationOccluder.Layer);
            DeleteLayer(bus, libraryBase, destination.Layer);
            DeleteLayer(bus, libraryBase, sourceOccluder.Layer);
            DeleteLayer(bus, libraryBase, source.Layer);
            DisposeLayerInfo(bus, libraryBase, destinationInfo);
            DisposeLayerInfo(bus, libraryBase, sourceInfo);
            FreeBitMap(bus, destinationBitMap);
            FreeBitMap(bus, sourceBitMap);
        }

        List<(short MinX, short MinY, short MaxX, short MaxY)> ReadBounds(uint head)
        {
            var result = new List<(short MinX, short MinY, short MaxX, short MaxY)>();
            for (var clipRect = head;
                clipRect != 0;
                clipRect = ReadClipRectNext(bus, clipRect))
            {
                var bounds = LayersClipRectCodec.BoundsAddress(
                    APTR.FromPointer(clipRect)).Raw;
                result.Add((
                    unchecked((short)bus.ReadWord(bounds)),
                    unchecked((short)bus.ReadWord(bounds + 2)),
                    unchecked((short)bus.ReadWord(bounds + 4)),
                    unchecked((short)bus.ReadWord(bounds + 6))));
            }
            return result;
        }

        byte[] ReadRegionBytes(uint region) => Enumerable.Range(
                0, checked((int)LayersRegionCodec.Size))
            .Select(offset => bus.ReadByte(region + (uint)offset))
            .ToArray();
    }

    [Fact]
    public void LayeredSuperBitMapClipBlitDuringEmptyBeginUpdateHasNoEndpointAccess()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var sourceInfo = NewLayerInfo(bus, libraryBase);
        var destinationInfo = NewLayerInfo(bus, libraryBase);
        var copySourceInfo = NewLayerInfo(bus, libraryBase);
        var sourceDisplay = AllocatePlanarBitMap(bus, 32, 20);
        var sourceSuper = AllocatePlanarBitMap(bus, 48, 32);
        var destinationDisplay = AllocatePlanarBitMap(bus, 32, 20);
        var destinationSuper = AllocatePlanarBitMap(bus, 48, 32);
        var copySourceBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var source = CreateLayerOnBitMaps(
            bus, libraryBase, sourceInfo, sourceDisplay, sourceSuper,
            LayerCreationFlags.Super, 0, 0, 31, 19);
        var sourceScroll = new M68kCpuState
        {
            A = { [1] = source.Layer }, D = { [0] = 2, [1] = 1 }
        };
        Assert.True(InvokeHostTrap(
            bus, Lvo(libraryBase, LayersLvo.ScrollLayer), sourceScroll));
        var sourceOccluder = CreateLayerOnBitMaps(
            bus, libraryBase, sourceInfo, sourceDisplay, 0,
            LayerCreationFlags.Simple, 4, 4, 15, 15);
        var destination = CreateLayerOnBitMaps(
            bus, libraryBase, destinationInfo, destinationDisplay, destinationSuper,
            LayerCreationFlags.Super, 0, 0, 31, 19);
        var destinationScroll = new M68kCpuState
        {
            A = { [1] = destination.Layer }, D = { [0] = 2, [1] = 1 }
        };
        Assert.True(InvokeHostTrap(
            bus, Lvo(libraryBase, LayersLvo.ScrollLayer), destinationScroll));
        var destinationOccluder = CreateLayerOnBitMaps(
            bus, libraryBase, destinationInfo, destinationDisplay, 0,
            LayerCreationFlags.Simple, 4, 4, 15, 15);
        var copySource = CreateLayerOnBitMaps(
            bus, libraryBase, copySourceInfo, copySourceBitMap, 0,
            LayerCreationFlags.Simple, 0, 0, 31, 19);
        var sourceBacking = ReadClipRectBitMap(
            bus, FindObscuredClipRect(bus, source.Layer));
        var destinationBacking = ReadClipRectBitMap(
            bus, FindObscuredClipRect(bus, destination.Layer));
        Assert.NotEqual(0u, sourceBacking);
        Assert.NotEqual(0u, destinationBacking);
        var layerMemory = new LayersTestGuestMemory(bus);
        var sourceUpdateActive = false;
        var destinationUpdateActive = false;

        try
        {
            var sourceDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(source.Layer));
            var destinationDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(destination.Layer));
            Assert.True(sourceDamage.IsNotNull);
            Assert.True(destinationDamage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, sourceDamage).IsNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, destinationDamage).IsNull);
            var sourceDamageBytes = ReadRegionBytes(sourceDamage.Raw);
            var destinationDamageBytes = ReadRegionBytes(destinationDamage.Raw);

            ClearPlanarBitMap(bus, sourceDisplay);
            ClearPlanarBitMap(bus, sourceSuper);
            ClearPlanarBitMap(bus, sourceBacking);
            ClearPlanarBitMap(bus, destinationDisplay);
            ClearPlanarBitMap(bus, destinationSuper);
            ClearPlanarBitMap(bus, destinationBacking);
            var sourceSuperPlane = ReadBitMapPlane(bus, sourceSuper, 0);
            for (var offset = 0;
                offset < ReadBitMapBytesPerRow(bus, sourceSuper) *
                    ReadBitMapRows(bus, sourceSuper);
                offset++)
            {
                bus.WriteByte(sourceSuperPlane + checked((uint)offset), 0xFF, 0);
            }

            var sourceSurfacesBefore = SnapshotBitMaps(
                sourceDisplay, sourceSuper, sourceBacking);
            var destinationSurfacesBefore = SnapshotBitMaps(
                destinationDisplay, destinationSuper, destinationBacking);
            var beginSource = new M68kCpuState { A = { [0] = source.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), beginSource));
            Assert.Equal(1u, beginSource.D[0]);
            sourceUpdateActive = true;
            Assert.Equal(0u, ReadLayerClipRect(bus, source.Layer));
            var sourceFlags = ReadLayerFlags(bus, source.Layer);
            var destinationFlags = ReadLayerFlags(bus, destination.Layer);

            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ClipBlit),
                MakeClipBlit(source.RastPort, destination.RastPort)));
            Assert.Equal(sourceSurfacesBefore,
                SnapshotBitMaps(sourceDisplay, sourceSuper, sourceBacking));
            Assert.Equal(destinationSurfacesBefore,
                SnapshotBitMaps(destinationDisplay, destinationSuper, destinationBacking));
            Assert.Equal(sourceFlags, ReadLayerFlags(bus, source.Layer));
            Assert.Equal(destinationFlags, ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(sourceDamage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(source.Layer)).Raw);
            Assert.Equal(sourceDamageBytes, ReadRegionBytes(sourceDamage.Raw));
            Assert.Equal(destinationDamage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(destination.Layer)).Raw);
            Assert.Equal(destinationDamageBytes, ReadRegionBytes(destinationDamage.Raw));

            var endSource = new M68kCpuState
            {
                A = { [0] = source.Layer }, D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, endSource);
            sourceUpdateActive = false;

            ClearPlanarBitMap(bus, destinationDisplay);
            ClearPlanarBitMap(bus, destinationSuper);
            ClearPlanarBitMap(bus, destinationBacking);
            ClearPlanarBitMap(bus, copySourceBitMap);
            var copySourcePlane = ReadBitMapPlane(bus, copySourceBitMap, 0);
            for (var offset = 0;
                offset < ReadBitMapBytesPerRow(bus, copySourceBitMap) *
                    ReadBitMapRows(bus, copySourceBitMap);
                offset++)
            {
                bus.WriteByte(copySourcePlane + checked((uint)offset), 0xFF, 0);
            }
            destinationSurfacesBefore = SnapshotBitMaps(
                destinationDisplay, destinationSuper, destinationBacking);
            var simpleSourceBefore = SnapshotPlanarBitMap(bus, copySourceBitMap);

            var beginDestination = new M68kCpuState
            {
                A = { [0] = destination.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), beginDestination));
            Assert.Equal(1u, beginDestination.D[0]);
            destinationUpdateActive = true;
            Assert.Equal(0u, ReadLayerClipRect(bus, destination.Layer));
            sourceFlags = ReadLayerFlags(bus, copySource.Layer);
            destinationFlags = ReadLayerFlags(bus, destination.Layer);

            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ClipBlit),
                MakeClipBlit(copySource.RastPort, destination.RastPort)));
            Assert.Equal(destinationSurfacesBefore,
                SnapshotBitMaps(destinationDisplay, destinationSuper, destinationBacking));
            Assert.Equal(simpleSourceBefore, SnapshotPlanarBitMap(bus, copySourceBitMap));
            Assert.Equal(sourceFlags, ReadLayerFlags(bus, copySource.Layer));
            Assert.Equal(destinationFlags, ReadLayerFlags(bus, destination.Layer));
            Assert.Equal(destinationDamage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(destination.Layer)).Raw);
            Assert.Equal(destinationDamageBytes, ReadRegionBytes(destinationDamage.Raw));

            var endDestination = new M68kCpuState
            {
                A = { [0] = destination.Layer }, D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, endDestination);
            destinationUpdateActive = false;


        }
        finally
        {
            if (destinationUpdateActive)
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate),
                    new M68kCpuState { A = { [0] = destination.Layer } });
            if (sourceUpdateActive)
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate),
                    new M68kCpuState { A = { [0] = source.Layer } });
            DeleteLayer(bus, libraryBase, copySource.Layer);
            DeleteLayer(bus, libraryBase, destinationOccluder.Layer);
            DeleteLayer(bus, libraryBase, destination.Layer);
            DeleteLayer(bus, libraryBase, sourceOccluder.Layer);
            DeleteLayer(bus, libraryBase, source.Layer);
            DisposeLayerInfo(bus, libraryBase, copySourceInfo);
            DisposeLayerInfo(bus, libraryBase, destinationInfo);
            DisposeLayerInfo(bus, libraryBase, sourceInfo);
            FreeBitMap(bus, copySourceBitMap);
            FreeBitMap(bus, destinationSuper);
            FreeBitMap(bus, destinationDisplay);
            FreeBitMap(bus, sourceSuper);
            FreeBitMap(bus, sourceDisplay);
        }

        M68kCpuState MakeClipBlit(uint sourceRastPort, uint destinationRastPort) =>
            new()
            {
                A = { [0] = sourceRastPort, [1] = destinationRastPort },
                D =
                {
                    [0] = 0, [1] = 0, [2] = 0, [3] = 0,
                    [4] = 32, [5] = 20, [6] = 0xC0, [7] = 0xB5B5_7007
                }
            };

        byte[][] SnapshotBitMaps(params uint[] bitMaps) => bitMaps
            .Select(bitMap => SnapshotPlanarBitMap(bus, bitMap))
            .ToArray();

        byte[] ReadRegionBytes(uint region) => Enumerable.Range(
                0, checked((int)LayersRegionCodec.Size))
            .Select(offset => bus.ReadByte(region + (uint)offset))
            .ToArray();
    }

    [Fact]
    public void MoveLayerPublishesDamageForBeginUpdateAndEndUpdateConsumesIt()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var sourceBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            31,
            19);
        var top = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            15,
            15);

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            var stableHead = ReadLayerClipRect(bus, bottom.Layer);
            var stableFlags = ReadLayerFlags(bus, bottom.Layer);
            var stableDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(LayersRegionCodec.ReadFirst(
                ref layerMemory,
                stableDamage).IsNull);

            var move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveLayer),
                move));
            Assert.Equal(1u, move.D[0]);

            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNotNull);
            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);
            var damageBytesBeforeRaster = Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray();

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            var updateHead = ReadLayerClipRect(bus, bottom.Layer);
            Assert.NotEqual(stableHead, updateHead);
            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Updating);

            // While the update is active graphics.library sees only the
            // temporary damage ClipRects. Painting must reach the newly
            // exposed strip but not the stable visible projection, and it
            // must leave the Layers-owned DamageList unchanged for EndUpdate.
            var flagsBeforeRaster = ReadLayerFlags(bus, bottom.Layer);
            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var writePixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 4, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.WritePixel),
                writePixel));
            Assert.Equal(0u, writePixel.D[0]);
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 4, 4));
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 3, 3));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(
                damage.Raw,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(
                damageBytesBeforeRaster,
                Enumerable.Range(0, checked((int)LayersRegionCodec.Size))
                    .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                    .ToArray());

            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 4, 4));
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 3, 3));
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 10, 10));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(
                damage.Raw,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(
                damageBytesBeforeRaster,
                Enumerable.Range(0, checked((int)LayersRegionCodec.Size))
                    .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                    .ToArray());

            // Exercise a full-area primitive through graphics.library while
            // BeginUpdate has published its temporary damage ClipRects. Seed
            // every display pixel so a fallback to the stable/full layer
            // surface would be visible outside the admitted damage islands.
            var displayPlane = ReadBitMapPlane(bus, displayBitMap, 0);
            for (uint offset = 0; offset < 4u * 20u; offset++)
                bus.WriteByte(displayPlane + offset, 0xFF, 0);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 0);
            WriteRastPortDrawMode(bus, bottom.RastPort, 0);
            WriteRastPortMask(bus, bottom.RastPort, 0xFF);

            var admittedBounds = new List<(short MinX, short MinY, short MaxX, short MaxY)>();
            for (var clipRect = updateHead; clipRect != 0; clipRect = ReadClipRectNext(bus, clipRect))
            {
                var bounds = LayersClipRectCodec.BoundsAddress(
                    APTR.FromPointer(clipRect)).Raw;
                admittedBounds.Add((
                    unchecked((short)bus.ReadWord(bounds)),
                    unchecked((short)bus.ReadWord(bounds + 2)),
                    unchecked((short)bus.ReadWord(bounds + 4)),
                    unchecked((short)bus.ReadWord(bounds + 6))));
            }
            Assert.NotEmpty(admittedBounds);

            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);

            for (var y = 0; y < 20; y++)
            {
                for (var x = 0; x < 32; x++)
                {
                    var admitted = admittedBounds.Any(bounds =>
                        x >= bounds.MinX && x <= bounds.MaxX &&
                        y >= bounds.MinY && y <= bounds.MaxY);
                    Assert.Equal(
                        !admitted,
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
                }
            }
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(
                damage.Raw,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(
                damageBytesBeforeRaster,
                Enumerable.Range(0, checked((int)LayersRegionCodec.Size))
                    .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                    .ToArray());

            // A source-bitmap transfer must use the same active ClipRect
            // projection as native primitives. The source covers the entire
            // destination, but only pixels in the damage islands may copy.
            ClearPlanarBitMap(bus, displayBitMap);
            ClearPlanarBitMap(bus, sourceBitMap);
            var sourcePlane = ReadBitMapPlane(bus, sourceBitMap, 0);
            for (uint offset = 0; offset < 4u * 20u; offset++)
                bus.WriteByte(sourcePlane + offset, 0xFF, 0);
            var blit = new M68kCpuState
            {
                A = { [0] = sourceBitMap, [1] = bottom.RastPort },
                D =
                {
                    [0] = 0,
                    [1] = 0,
                    [2] = 0,
                    [3] = 0,
                    [4] = 32,
                    [5] = 20,
                    [6] = 0xC0,
                    [7] = 0xB6B6_7007
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltBitMapRastPort),
                blit));
            Assert.Equal(1u, blit.D[0]);
            for (var y = 0; y < 20; y++)
            {
                for (var x = 0; x < 32; x++)
                {
                    var admitted = admittedBounds.Any(bounds =>
                        x >= bounds.MinX && x <= bounds.MaxX &&
                        y >= bounds.MinY && y <= bounds.MaxY);
                    Assert.Equal(
                        admitted,
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
                }
            }
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(
                damage.Raw,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(
                damageBytesBeforeRaster,
                Enumerable.Range(0, checked((int)LayersRegionCodec.Size))
                    .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                    .ToArray());

            // A repeated BeginUpdate reuses the current projection without
            // adding a nesting level. The first partial EndUpdate closes the
            // update while preserving damage for a later complete refresh.
            var nestedBegin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                nestedBegin));
            Assert.Equal(1u, nestedBegin.D[0]);
            Assert.Equal(updateHead, ReadLayerClipRect(bus, bottom.Layer));

            var nestedPartialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                nestedPartialEnd));
            Assert.Equal(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Updating);
            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);
            Assert.Equal(
                damage.Raw,
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
            var restoredHead = ReadLayerClipRect(bus, bottom.Layer);
            Assert.NotEqual(0u, restoredHead);
            Assert.NotEqual(updateHead, restoredHead);

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            Assert.NotEqual(restoredHead, ReadLayerClipRect(bus, bottom.Layer));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));

            Assert.Equal((ushort)(stableFlags | (ushort)LayerFlags.Refresh),
                ReadLayerFlags(bus, bottom.Layer));
        }
        finally
        {
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, sourceBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void PartialLayerRefreshRetainsDamageWhenMoveLayerAddsAnotherUncover()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            31,
            19);
        var top = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            15,
            15);

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            void MoveTop(uint dx, uint dy)
            {
                var move = new M68kCpuState
                {
                    A = { [1] = top.Layer },
                    D = { [0] = dx, [1] = dy }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.MoveLayer),
                    move));
                Assert.Equal(1u, move.D[0]);
            }

            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head;
                    clipRect != 0;
                    clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                        y <= Math.Min(19, (int)maxY);
                        y++)
                        for (var x = Math.Max(0, (int)minX);
                            x <= Math.Min(31, (int)maxX);
                            x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            var firstExposure = new HashSet<(int X, int Y)>();
            for (var y = 4; y <= 15; y++)
            {
                firstExposure.Add((4, y));
                firstExposure.Add((5, y));
            }
            for (var x = 6; x <= 15; x++)
                firstExposure.Add((x, 4));

            MoveTop(2, 1);
            var firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(firstDamage.IsNotNull);
            var firstDamageBytes = SnapshotGraphicsRegion(bus, firstDamage.Raw);
            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            var firstProjection = CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer));
            Assert.True(firstExposure.SetEquals(firstProjection));

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var writePixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 4, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixel),
                writePixel));
            Assert.Equal(0u, writePixel.D[0]);
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 4, 4));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                partialEnd));
            Assert.Equal(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Updating);
            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);
            Assert.Equal(firstDamage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(firstDamageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));

            // The first partial pass leaves its generated DamageList in place.
            // Moving the occluder again must add its newly exposed strips rather
            // than invalidating the retained work from the first move.
            MoveTop(1, 1);
            var combinedDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(combinedDamage.IsNotNull);
            Assert.Equal(0u, ReadLayerLockOwner(bus, bottom.Layer));
            var expectedCombinedExposure = new HashSet<(int X, int Y)>(firstExposure);
            for (var y = 5; y <= 16; y++)
                expectedCombinedExposure.Add((6, y));
            for (var x = 7; x <= 17; x++)
                expectedCombinedExposure.Add((x, 5));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            var secondProjection = CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer));
            Assert.True(expectedCombinedExposure.SetEquals(secondProjection));

            var damageBytesBeforeRaster = SnapshotGraphicsRegion(
                bus,
                combinedDamage.Raw);
            ClearPlanarBitMap(bus, displayBitMap);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(
                        expectedCombinedExposure.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytesBeforeRaster,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));

        }
        finally
        {
            if ((ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Updating) != 0)
            {
                var cleanupEnd = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.EndUpdate),
                    cleanupEnd);
            }
            if ((ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Updating) == 0)
            {
                DeleteLayer(bus, libraryBase, top.Layer);
                DeleteLayer(bus, libraryBase, bottom.Layer);
                DisposeLayerInfo(bus, libraryBase, layerInfo);
                FreeBitMap(bus, displayBitMap);
            }
        }
    }

    [Fact]
    public void PartialRefreshRetainsDamageAcrossMoveLayerWithCallerClipRegion()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 0, 0, 31, 19);
        var top = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 4, 4, 15, 15);
        uint callerClipRegion = 0;
        uint rectangle = 0;
        var callerClipInstalled = false;
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            void MoveTop(uint dx, uint dy)
            {
                var move = new M68kCpuState
                {
                    A = { [1] = top.Layer },
                    D = { [0] = dx, [1] = dy }
                };
                Assert.True(InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.MoveLayer), move));
                Assert.Equal(1u, move.D[0]);
            }

            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head; clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                         y <= Math.Min(19, (int)maxY); y++)
                        for (var x = Math.Max(0, (int)minX);
                             x <= Math.Min(31, (int)maxX); x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            HashSet<(int X, int Y)> CaptureDamagePixels(uint region)
            {
                var pixels = new HashSet<(int X, int Y)>();
                var regionAddress = APTR.FromPointer(region);
                var regionBounds = LayersRegionCodec.ReadBounds(
                    ref layerMemory, regionAddress);
                var rectangleNode = LayersRegionCodec.ReadFirst(
                    ref layerMemory, regionAddress);
                var visited = new HashSet<uint>();
                while (rectangleNode.IsNotNull)
                {
                    Assert.True(visited.Add(rectangleNode.Raw),
                        "Damage Region rectangle chain must be acyclic.");
                    var bounds = LayersRegionRectangleCodec.ReadBounds(
                        ref layerMemory, rectangleNode);
                    for (var y = regionBounds.MinY + bounds.MinY;
                         y <= regionBounds.MinY + bounds.MaxY; y++)
                        for (var x = regionBounds.MinX + bounds.MinX;
                             x <= regionBounds.MinX + bounds.MaxX; x++)
                            pixels.Add((x, y));
                    rectangleNode = LayersRegionRectangleCodec.ReadNext(
                        ref layerMemory, rectangleNode);
                }
                return pixels;
            }

            var firstExposure = new HashSet<(int X, int Y)>();
            for (var y = 4; y <= 15; y++)
            {
                firstExposure.Add((4, y));
                firstExposure.Add((5, y));
            }
            for (var x = 6; x <= 15; x++)
                firstExposure.Add((x, 4));

            MoveTop(2, 1);
            var firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(firstDamage.IsNotNull);
            var firstDamagePixels = CaptureDamagePixels(firstDamage.Raw);
            Assert.True(firstDamagePixels.IsSupersetOf(firstExposure));

            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            callerClipRegion = newRegion.D[0];
            Assert.NotEqual(0u, callerClipRegion);
            rectangle = AllocateGuestMemory(
                bus, (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 4, 4, 4, 4);
            var includeFirst = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeFirst));
            Assert.Equal(1u, includeFirst.D[0]);
            WriteRectangleBounds(bus, rectangle, 6, 5, 6, 5);
            var includeSecondMove = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeSecondMove));
            Assert.Equal(1u, includeSecondMove.D[0]);
            var callerClipBytes = SnapshotGraphicsRegion(
                bus, callerClipRegion);
            var installClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = callerClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installClip));
            Assert.Equal(0u, installClip.D[0]);
            callerClipInstalled = true;
            Assert.True(firstDamagePixels.SetEquals(CaptureDamagePixels(
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw)));
            firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));

            var selectedFirst = new HashSet<(int X, int Y)> { (4, 4) };
            var selectedBoth = new HashSet<(int X, int Y)>
            {
                (4, 4),
                (6, 5)
            };
            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedFirst.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var damageBytes = SnapshotGraphicsRegion(bus, firstDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var writePixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 4, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixel),
                writePixel));
            Assert.Equal(0u, writePixel.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(selectedFirst.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));

            MoveTop(1, 1);
            var expectedDamage = new HashSet<(int X, int Y)>(firstExposure);
            for (var y = 5; y <= 16; y++)
                expectedDamage.Add((6, y));
            for (var x = 7; x <= 17; x++)
                expectedDamage.Add((x, 5));
            var combinedDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(combinedDamage.IsNotNull);
            Assert.True(CaptureDamagePixels(combinedDamage.Raw)
                .IsSupersetOf(expectedDamage));
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedBoth.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            damageBytes = SnapshotGraphicsRegion(
                bus, combinedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(selectedBoth.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));

            var removeClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                removeClip));
            Assert.Equal(callerClipRegion, removeClip.D[0]);
            callerClipInstalled = false;
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(expectedDamage.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var damageBytesBeforeRaster = SnapshotGraphicsRegion(
                bus, combinedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(expectedDamage.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytesBeforeRaster,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;

            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (callerClipInstalled)
            {
                var removeClip = new M68kCpuState
                {
                    A = { [0] = bottom.Layer }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    removeClip);
            }
            if (callerClipRegion != 0)
            {
                var disposeClip = new M68kCpuState
                {
                    A = { [0] = callerClipRegion }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    disposeClip);
            }
            if (rectangle != 0)
                FreeGuestMemory(
                    bus, rectangle, (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void PartialRefreshMoveLayerDamageClipsAcrossNegativeLayerOrigin()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 64, 32);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, -2, -1, 29, 17);
        var top = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, -1, 0, 2, 3);
        uint callerClipRegion = 0;
        uint rectangle = 0;
        var callerClipInstalled = false;
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            void MoveTop(uint dx, uint dy)
            {
                var move = new M68kCpuState
                {
                    A = { [1] = top.Layer },
                    D = { [0] = dx, [1] = dy }
                };
                Assert.True(InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.MoveLayer), move));
                Assert.Equal(1u, move.D[0]);
            }

            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head; clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                         y <= Math.Min(31, (int)maxY); y++)
                        for (var x = Math.Max(0, (int)minX);
                             x <= Math.Min(63, (int)maxX); x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            HashSet<(int X, int Y)> CaptureDamagePixels(uint region)
            {
                var pixels = new HashSet<(int X, int Y)>();
                var regionAddress = APTR.FromPointer(region);
                var regionBounds = LayersRegionCodec.ReadBounds(
                    ref layerMemory, regionAddress);
                var rectangleNode = LayersRegionCodec.ReadFirst(
                    ref layerMemory, regionAddress);
                var visited = new HashSet<uint>();
                while (rectangleNode.IsNotNull)
                {
                    Assert.True(visited.Add(rectangleNode.Raw),
                        "Damage Region rectangle chain must be acyclic.");
                    var bounds = LayersRegionRectangleCodec.ReadBounds(
                        ref layerMemory, rectangleNode);
                    for (var y = regionBounds.MinY + bounds.MinY - 1;
                         y <= regionBounds.MinY + bounds.MaxY - 1; y++)
                        for (var x = regionBounds.MinX + bounds.MinX - 2;
                             x <= regionBounds.MinX + bounds.MaxX - 2; x++)
                            pixels.Add((x, y));
                    rectangleNode = LayersRegionRectangleCodec.ReadNext(
                        ref layerMemory, rectangleNode);
                }
                return pixels;
            }

            HashSet<(int X, int Y)> Difference(
                int minX, int minY, int maxX, int maxY,
                int cutMinX, int cutMinY, int cutMaxX, int cutMaxY)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var y = minY; y <= maxY; y++)
                    for (var x = minX; x <= maxX; x++)
                        if (x < cutMinX || x > cutMaxX ||
                            y < cutMinY || y > cutMaxY)
                            pixels.Add((x, y));
                return pixels;
            }

            var firstExposure = Difference(-1, 0, 2, 3, 1, 1, 4, 4);
            var firstVisibleExposure = new HashSet<(int X, int Y)>(
                firstExposure.Where(point =>
                    point.X >= 0 && point.Y >= 0));
            MoveTop(2, 1);
            var firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(firstDamage.IsNotNull);
            var firstDamagePixels = CaptureDamagePixels(firstDamage.Raw);
            Assert.True(firstDamagePixels.IsSupersetOf(firstVisibleExposure));

            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            callerClipRegion = newRegion.D[0];
            Assert.NotEqual(0u, callerClipRegion);
            rectangle = AllocateGuestMemory(
                bus, (uint)GraphicsLayouts.RectangleSize);
            // Layer-local (2,1) maps to screen (0,0); (1,2) maps to
            // screen (-1,1) and must never rasterize outside the viewport.
            WriteRectangleBounds(bus, rectangle, 2, 1, 2, 1);
            var includeFirst = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeFirst));
            Assert.Equal(1u, includeFirst.D[0]);
            WriteRectangleBounds(bus, rectangle, 1, 2, 1, 2);
            var includeOffscreenExposure = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeOffscreenExposure));
            Assert.Equal(1u, includeOffscreenExposure.D[0]);
            WriteRectangleBounds(bus, rectangle, 3, 2, 3, 2);
            var includeSecondMove = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeSecondMove));
            Assert.Equal(1u, includeSecondMove.D[0]);
            var callerClipBytes = SnapshotGraphicsRegion(
                bus, callerClipRegion);
            var installClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = callerClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installClip));
            Assert.Equal(0u, installClip.D[0]);
            callerClipInstalled = true;
            Assert.True(firstDamagePixels.SetEquals(
                CaptureDamagePixels(LayersLayerCodec.ReadDamageList(
                    ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw)));
            firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));

            var selectedFirst = new HashSet<(int X, int Y)> { (0, 0) };
            var selectedBoth = new HashSet<(int X, int Y)>
            {
                (0, 0),
                (1, 1)
            };
            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedFirst.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var damageBytes = SnapshotGraphicsRegion(bus, firstDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var writePixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixel),
                writePixel));
            Assert.Equal(0u, writePixel.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(selectedFirst.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));

            MoveTop(1, 1);
            var secondExposure = Difference(1, 1, 4, 4, 2, 2, 5, 5);
            var expectedVisibleExposure = new HashSet<(int X, int Y)>(
                firstExposure);
            expectedVisibleExposure.UnionWith(secondExposure);
            var expectedDamage = new HashSet<(int X, int Y)>(
                expectedVisibleExposure.Where(point =>
                    point.X >= 0 && point.Y >= 0));
            var combinedDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(combinedDamage.IsNotNull);
            Assert.True(CaptureDamagePixels(combinedDamage.Raw)
                .IsSupersetOf(expectedDamage));
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedBoth.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            damageBytes = SnapshotGraphicsRegion(
                bus, combinedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(selectedBoth.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));

            var removeClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                removeClip));
            Assert.Equal(callerClipRegion, removeClip.D[0]);
            callerClipInstalled = false;
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));
            combinedDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            var damageAfterClipRemovalPixels = CaptureDamagePixels(
                combinedDamage.Raw);
            Assert.True(
                damageAfterClipRemovalPixels.IsSupersetOf(expectedDamage),
                "The DamageList must retain all visible exposure; it may also " +
                "include coverage concealed by the final Simple occluder.");

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(expectedDamage.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var damageBytesBeforeRaster = SnapshotGraphicsRegion(
                bus, combinedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(expectedDamage.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytesBeforeRaster,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;

            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (callerClipInstalled)
            {
                var removeClip = new M68kCpuState
                {
                    A = { [0] = bottom.Layer }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    removeClip);
            }
            if (callerClipRegion != 0)
            {
                var disposeClip = new M68kCpuState
                {
                    A = { [0] = callerClipRegion }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    disposeClip);
            }
            if (rectangle != 0)
                FreeGuestMemory(
                    bus, rectangle, (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void PartialRefreshMoveLayerDamageClipsAcrossPositiveDisplayEdge()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 64, 32);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 40, 0, 71, 19);
        var top = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 58, 4, 69, 15);
        uint callerClipRegion = 0;
        uint rectangle = 0;
        var callerClipInstalled = false;
        var updating = false;

        try
        {
            void MoveTop(uint dx, uint dy)
            {
                var move = new M68kCpuState
                {
                    A = { [1] = top.Layer },
                    D = { [0] = dx, [1] = dy }
                };
                Assert.True(InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.MoveLayer), move));
                Assert.Equal(1u, move.D[0]);
            }

            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head; clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                         y <= Math.Min(31, (int)maxY); y++)
                        for (var x = Math.Max(0, (int)minX);
                             x <= Math.Min(63, (int)maxX); x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            var firstExposure = new HashSet<(int X, int Y)>();
            for (var x = 58; x <= 63; x++)
                firstExposure.Add((x, 4));
            for (var y = 5; y <= 15; y++)
                foreach (var x in new[] { 58, 59 })
                    firstExposure.Add((x, y));
            MoveTop(2, 1);
            var layerMemory = new LayersTestGuestMemory(bus);
            var firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(firstDamage.IsNotNull);

            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            callerClipRegion = newRegion.D[0];
            Assert.NotEqual(0u, callerClipRegion);
            rectangle = AllocateGuestMemory(
                bus, (uint)GraphicsLayouts.RectangleSize);
            // Layer-local (18,4) maps to screen (58,4), while (26,4)
            // maps to off-screen x=66 and must not write past the display.
            WriteRectangleBounds(bus, rectangle, 18, 4, 18, 4);
            var includeFirst = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeFirst));
            Assert.Equal(1u, includeFirst.D[0]);
            WriteRectangleBounds(bus, rectangle, 26, 4, 26, 4);
            var includeOffscreen = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeOffscreen));
            Assert.Equal(1u, includeOffscreen.D[0]);
            WriteRectangleBounds(bus, rectangle, 20, 5, 20, 5);
            var includeSecondMove = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeSecondMove));
            Assert.Equal(1u, includeSecondMove.D[0]);
            var callerClipBytes = SnapshotGraphicsRegion(
                bus, callerClipRegion);
            var installClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = callerClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installClip));
            Assert.Equal(0u, installClip.D[0]);
            callerClipInstalled = true;

            var selectedFirst = new HashSet<(int X, int Y)> { (58, 4) };
            var selectedBoth = new HashSet<(int X, int Y)>
            {
                (58, 4),
                (60, 5)
            };
            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedFirst.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var writePixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 18, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixel),
                writePixel));
            Assert.Equal(0u, writePixel.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(selectedFirst.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.True(LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).IsNotNull);

            // The second move exposes screen x=60..61 from the old occluder;
            // its new footprint extends beyond the display's right edge.
            MoveTop(2, 0);
            var expectedDamage = new HashSet<(int X, int Y)>(firstExposure);
            for (var y = 5; y <= 16; y++)
                foreach (var x in new[] { 60, 61 })
                    expectedDamage.Add((x, y));
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedBoth.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(selectedBoth.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var removeClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                removeClip));
            Assert.Equal(callerClipRegion, removeClip.D[0]);
            callerClipInstalled = false;
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(expectedDamage.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(expectedDamage.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;

            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (callerClipInstalled)
            {
                var removeClip = new M68kCpuState
                {
                    A = { [0] = bottom.Layer }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    removeClip);
            }
            if (callerClipRegion != 0)
            {
                var disposeClip = new M68kCpuState
                {
                    A = { [0] = callerClipRegion }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    disposeClip);
            }
            if (rectangle != 0)
                FreeGuestMemory(
                    bus, rectangle, (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void PartialRefreshMoveLayerDamageClipsAcrossPositiveBottomEdge()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 64, 32);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 0, 20, 31, 39);
        var top = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 4, 24, 15, 35);
        uint callerClipRegion = 0;
        uint rectangle = 0;
        var callerClipInstalled = false;
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            void MoveTop(uint dx, uint dy)
            {
                var move = new M68kCpuState
                {
                    A = { [1] = top.Layer },
                    D = { [0] = dx, [1] = dy }
                };
                Assert.True(InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.MoveLayer), move));
                Assert.Equal(1u, move.D[0]);
            }

            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head; clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                         y <= Math.Min(31, (int)maxY); y++)
                        for (var x = Math.Max(0, (int)minX);
                             x <= Math.Min(63, (int)maxX); x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            var firstExposure = new HashSet<(int X, int Y)>();
            for (var y = 24; y <= 25; y++)
                for (var x = 4; x <= 15; x++)
                    firstExposure.Add((x, y));
            for (var y = 26; y <= 31; y++)
                firstExposure.Add((4, y));
            MoveTop(1, 2);
            var firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(firstDamage.IsNotNull);

            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            callerClipRegion = newRegion.D[0];
            Assert.NotEqual(0u, callerClipRegion);
            rectangle = AllocateGuestMemory(
                bus, (uint)GraphicsLayouts.RectangleSize);
            // Layer-local (4,4) maps to screen (4,24); (4,14) maps
            // below the screen at (4,34) and must not rasterize there.
            WriteRectangleBounds(bus, rectangle, 4, 4, 4, 4);
            var includeFirst = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeFirst));
            Assert.Equal(1u, includeFirst.D[0]);
            WriteRectangleBounds(bus, rectangle, 4, 14, 4, 14);
            var includeOffscreen = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeOffscreen));
            Assert.Equal(1u, includeOffscreen.D[0]);
            WriteRectangleBounds(bus, rectangle, 5, 6, 5, 6);
            var includeSecondMove = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeSecondMove));
            Assert.Equal(1u, includeSecondMove.D[0]);
            var callerClipBytes = SnapshotGraphicsRegion(
                bus, callerClipRegion);
            var installClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = callerClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installClip));
            Assert.Equal(0u, installClip.D[0]);
            callerClipInstalled = true;
            firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(firstDamage.IsNotNull);

            var selectedFirst = new HashSet<(int X, int Y)> { (4, 24) };
            var selectedBoth = new HashSet<(int X, int Y)>
            {
                (4, 24),
                (5, 26)
            };
            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedFirst.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var damageBytes = SnapshotGraphicsRegion(bus, firstDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var writePixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 4, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixel),
                writePixel));
            Assert.Equal(0u, writePixel.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(selectedFirst.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.True(LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).IsNotNull);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));

            // The second downward move exposes y=26..27 while its new
            // footprint extends below the physical 32-line viewport.
            MoveTop(0, 2);
            for (var y = 26; y <= 27; y++)
                for (var x = 5; x <= 16; x++)
                    firstExposure.Add((x, y));
            var combinedDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(combinedDamage.IsNotNull);
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedBoth.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var combinedDamageBytes = SnapshotGraphicsRegion(
                bus, combinedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(selectedBoth.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(combinedDamageBytes,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(combinedDamageBytes,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var removeClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                removeClip));
            Assert.Equal(callerClipRegion, removeClip.D[0]);
            callerClipInstalled = false;
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(firstExposure.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var completedDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(completedDamage.IsNotNull);
            var completedDamageBytes = SnapshotGraphicsRegion(
                bus, completedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(firstExposure.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(completedDamageBytes,
                SnapshotGraphicsRegion(bus, completedDamage.Raw));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;

            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (callerClipInstalled)
            {
                var removeClip = new M68kCpuState
                {
                    A = { [0] = bottom.Layer }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    removeClip);
            }
            if (callerClipRegion != 0)
            {
                var disposeClip = new M68kCpuState
                {
                    A = { [0] = callerClipRegion }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    disposeClip);
            }
            if (rectangle != 0)
                FreeGuestMemory(
                    bus, rectangle, (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void PartialRefreshMoveLayerDamageClipsAcrossNegativeTopEdge()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 64, 32);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 0, -8, 31, 11);
        var top = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 4, -4, 15, 7);
        uint callerClipRegion = 0;
        uint rectangle = 0;
        var callerClipInstalled = false;
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            void MoveTop(int dx, int dy)
            {
                var move = new M68kCpuState
                {
                    A = { [1] = top.Layer },
                    D =
                    {
                        [0] = unchecked((uint)dx),
                        [1] = unchecked((uint)dy)
                    }
                };
                Assert.True(InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.MoveLayer), move));
                Assert.Equal(1u, move.D[0]);
            }

            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head; clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                         y <= Math.Min(31, (int)maxY); y++)
                        for (var x = Math.Max(0, (int)minX);
                             x <= Math.Min(63, (int)maxX); x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            void AddClipPoint(int x, int y)
            {
                WriteRectangleBounds(
                    bus, rectangle, (short)x, (short)y, (short)x, (short)y);
                var include = new M68kCpuState
                {
                    A = { [0] = callerClipRegion, [1] = rectangle }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.OrRectRegion),
                    include));
                Assert.Equal(1u, include.D[0]);
            }

            void AssertSetRastPixels(HashSet<(int X, int Y)> expected)
            {
                ClearPlanarBitMap(bus, displayBitMap);
                WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
                var setRast = new M68kCpuState
                {
                    A = { [1] = bottom.RastPort },
                    D = { [0] = 1 }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.SetRast),
                    setRast));
                Assert.Equal(0u, setRast.D[0]);
                for (var y = 0; y < 32; y++)
                    for (var x = 0; x < 64; x++)
                        Assert.Equal(expected.Contains((x, y)),
                            ReadPlanarBitMapPixel(
                                bus, displayBitMap, x, y));
            }

            // Keep x on-screen while the layer and its occluder cross y=0.
            MoveTop(1, 2);
            var firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(firstDamage.IsNotNull);

            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            callerClipRegion = newRegion.D[0];
            Assert.NotEqual(0u, callerClipRegion);
            rectangle = AllocateGuestMemory(
                bus, (uint)GraphicsLayouts.RectangleSize);
            // Region-local (4,8) maps to screen (4,0); (4,7) maps to
            // off-screen row -1; (5,16) is exposed by the later move at y=8.
            AddClipPoint(4, 8);
            AddClipPoint(4, 7);
            AddClipPoint(5, 16);
            var callerClipBytes = SnapshotGraphicsRegion(
                bus, callerClipRegion);
            var installClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = callerClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installClip));
            Assert.Equal(0u, installClip.D[0]);
            callerClipInstalled = true;

            var selectedFirst = new HashSet<(int X, int Y)> { (4, 0) };
            var selectedBoth = new HashSet<(int X, int Y)>
            {
                (4, 0),
                (5, 8)
            };
            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedFirst.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            AssertSetRastPixels(selectedFirst);
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;

            // Moving the occluder up exposes its bottom strip at y=8..9.
            MoveTop(0, -2);
            var combinedDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(combinedDamage.IsNotNull);
            var combinedDamageBytes = SnapshotGraphicsRegion(
                bus, combinedDamage.Raw);
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedBoth.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            AssertSetRastPixels(selectedBoth);
            Assert.Equal(combinedDamageBytes,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(combinedDamageBytes,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));

            var removeClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                removeClip));
            Assert.Equal(callerClipRegion, removeClip.D[0]);
            callerClipInstalled = false;

            var expectedDamage = new HashSet<(int X, int Y)>();
            for (var y = 0; y <= 7; y++)
                expectedDamage.Add((4, y));
            for (var y = 8; y <= 9; y++)
                for (var x = 5; x <= 16; x++)
                    expectedDamage.Add((x, y));
            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(expectedDamage.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(expectedDamage.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;

        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (callerClipInstalled)
            {
                var removeClip = new M68kCpuState
                {
                    A = { [0] = bottom.Layer }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    removeClip);
            }
            if (callerClipRegion != 0)
            {
                var disposeClip = new M68kCpuState
                {
                    A = { [0] = callerClipRegion }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    disposeClip);
            }
            if (rectangle != 0)
                FreeGuestMemory(
                    bus, rectangle, (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void PartialRefreshCallerClipRegionTracksMovedDamageLayerOrigin()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 0, 0, 31, 19);
        var top = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 4, 4, 15, 15);
        uint callerClipRegion = 0;
        uint rectangle = 0;
        var callerClipInstalled = false;
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            void MoveLayer(uint layer, int dx, int dy)
            {
                var move = new M68kCpuState
                {
                    A = { [1] = layer },
                    D =
                    {
                        [0] = unchecked((uint)dx),
                        [1] = unchecked((uint)dy)
                    }
                };
                Assert.True(InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.MoveLayer), move));
                Assert.Equal(1u, move.D[0]);
            }

            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head; clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                         y <= Math.Min(19, (int)maxY); y++)
                        for (var x = Math.Max(0, (int)minX);
                             x <= Math.Min(31, (int)maxX); x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            void AddClipPoint(int x, int y)
            {
                WriteRectangleBounds(
                    bus, rectangle, (short)x, (short)y, (short)x, (short)y);
                var include = new M68kCpuState
                {
                    A = { [0] = callerClipRegion, [1] = rectangle }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.OrRectRegion),
                    include));
                Assert.Equal(1u, include.D[0]);
            }

            void AssertSetRastPixels(HashSet<(int X, int Y)> expected)
            {
                ClearPlanarBitMap(bus, displayBitMap);
                WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
                var setRast = new M68kCpuState
                {
                    A = { [1] = bottom.RastPort },
                    D = { [0] = 1 }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.SetRast),
                    setRast));
                Assert.Equal(0u, setRast.D[0]);
                for (var y = 0; y < 20; y++)
                    for (var x = 0; x < 32; x++)
                        Assert.Equal(expected.Contains((x, y)),
                            ReadPlanarBitMapPixel(
                                bus, displayBitMap, x, y));
            }

            MoveLayer(top.Layer, 2, 1);
            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);

            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            callerClipRegion = newRegion.D[0];
            Assert.NotEqual(0u, callerClipRegion);
            rectangle = AllocateGuestMemory(
                bus, (uint)GraphicsLayouts.RectangleSize);
            // These are layer-local: after moving the target +1 in x they map
            // to screen (5,4) and (16,5). The latter remains occluded.
            AddClipPoint(4, 4);
            AddClipPoint(15, 5);
            var callerClipBytes = SnapshotGraphicsRegion(
                bus, callerClipRegion);
            var installClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = callerClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installClip));
            Assert.Equal(0u, installClip.D[0]);
            callerClipInstalled = true;

            MoveLayer(bottom.Layer, 1, 0);
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            var selected = new HashSet<(int X, int Y)> { (5, 4) };
            Assert.True(selected.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            var damageBytes = SnapshotGraphicsRegion(bus, damage.Raw);
            AssertSetRastPixels(selected);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damage.Raw));
            Assert.True(LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).IsNotNull);

            var removeClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                removeClip));
            Assert.Equal(callerClipRegion, removeClip.D[0]);
            callerClipInstalled = false;

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            var visibleDamage = CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer));
            Assert.Contains((5, 4), visibleDamage);
            Assert.Contains((6, 4), visibleDamage);
            Assert.Contains((16, 4), visibleDamage);
            Assert.DoesNotContain((6, 5), visibleDamage);
            AssertSetRastPixels(visibleDamage);

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;

        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (callerClipInstalled)
            {
                var removeClip = new M68kCpuState
                {
                    A = { [0] = bottom.Layer }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    removeClip);
            }
            if (callerClipRegion != 0)
            {
                var disposeClip = new M68kCpuState
                {
                    A = { [0] = callerClipRegion }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    disposeClip);
            }
            if (rectangle != 0)
                FreeGuestMemory(
                    bus, rectangle, (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Theory]
    [InlineData(LayerBackfillHook.Backfill, 4, 4)]
    [InlineData(LayerBackfillHook.NoBackfill, 4, 4)]
    [InlineData(LayerBackfillHook.NeverBackfill, 4, 4)]
    [InlineData(LayerBackfillHook.Backfill, 12, 8)]
    [InlineData(LayerBackfillHook.NoBackfill, 12, 8)]
    [InlineData(LayerBackfillHook.NeverBackfill, 12, 8)]
    public void PartialRefreshCallerClipRegionTracksResizedDamageLayerBounds(
        uint backfillHook, int rightGrowth, int bottomGrowth)
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 0, 0, 23, 15);
        var installBackfill = new M68kCpuState
        {
            A = { [0] = bottom.Layer, [1] = backfillHook }
        };
        Assert.True(InvokeHostTrap(
            bus, Lvo(libraryBase, LayersLvo.InstallLayerHook),
            installBackfill));
        var top = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 4, 4, 15, 11);
        var finalMaxX = 23 + 2 * rightGrowth;
        var finalMaxY = 15 + 2 * bottomGrowth;
        uint callerClipRegion = 0;
        uint rectangle = 0;
        var callerClipInstalled = false;
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            void MoveTop(int dx, int dy)
            {
                var move = new M68kCpuState
                {
                    A = { [1] = top.Layer },
                    D =
                    {
                        [0] = unchecked((uint)dx),
                        [1] = unchecked((uint)dy)
                    }
                };
                Assert.True(InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.MoveLayer), move));
                Assert.Equal(1u, move.D[0]);
            }

            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head; clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                         y <= Math.Min(19, (int)maxY); y++)
                        for (var x = Math.Max(0, (int)minX);
                             x <= Math.Min(31, (int)maxX); x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            HashSet<(int X, int Y)> CaptureRawClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head; clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = (int)minY; y <= maxY; y++)
                        for (var x = (int)minX; x <= maxX; x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            void AssertClipRectsStayWithinLayerBounds(uint head)
            {
                for (var clipRect = head; clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    Assert.InRange((int)minX, 0, finalMaxX);
                    Assert.InRange((int)minY, 0, finalMaxY);
                    Assert.InRange((int)maxX, 0, finalMaxX);
                    Assert.InRange((int)maxY, 0, finalMaxY);
                }
            }

            void AddClipPoint(int x, int y)
            {
                WriteRectangleBounds(
                    bus, rectangle, (short)x, (short)y, (short)x, (short)y);
                var include = new M68kCpuState
                {
                    A = { [0] = callerClipRegion, [1] = rectangle }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.OrRectRegion),
                    include));
                Assert.Equal(1u, include.D[0]);
            }

            void AssertSetRastPixels(HashSet<(int X, int Y)> expected)
            {
                ClearPlanarBitMap(bus, displayBitMap);
                WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
                var setRast = new M68kCpuState
                {
                    A = { [1] = bottom.RastPort },
                    D = { [0] = 1 }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.SetRast),
                    setRast));
                Assert.Equal(0u, setRast.D[0]);
                for (var y = 0; y < 20; y++)
                    for (var x = 0; x < 32; x++)
                        Assert.Equal(expected.Contains((x, y)),
                            ReadPlanarBitMapPixel(
                                bus, displayBitMap, x, y));
            }

            // The first MoveLayer gives the smaller target retained damage.
            MoveTop(2, 1);
            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);

            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            callerClipRegion = newRegion.D[0];
            Assert.NotEqual(0u, callerClipRegion);
            rectangle = AllocateGuestMemory(
                bus, (uint)GraphicsLayouts.RectangleSize);
            // (4,4) is currently exposed; (26,18) becomes visible only when
            // SizeLayer extends the target's right and bottom edges.
            AddClipPoint(4, 4);
            AddClipPoint(26, 18);
            var callerClipBytes = SnapshotGraphicsRegion(
                bus, callerClipRegion);
            var installClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = callerClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installClip));
            Assert.Equal(0u, installClip.D[0]);
            callerClipInstalled = true;

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            var selectedFirst = new HashSet<(int X, int Y)> { (4, 4) };
            Assert.True(selectedFirst.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            AssertSetRastPixels(selectedFirst);
            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.True(LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).IsNotNull);
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var size = new M68kCpuState
            {
                A = { [1] = bottom.Layer },
                D =
                {
                    [0] = unchecked((uint)rightGrowth),
                    [1] = unchecked((uint)bottomGrowth)
                }
            };
            var displayBeforeFirstResize = SnapshotPlanarBitMap(
                bus, displayBitMap);
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.SizeLayer), size));
            Assert.Equal(1u, size.D[0]);
            Assert.Equal(displayBeforeFirstResize,
                SnapshotPlanarBitMap(bus, displayBitMap));
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            var selectedBoth = new HashSet<(int X, int Y)>
            {
                (4, 4),
                (26, 18)
            };
            Assert.True(selectedBoth.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            var damageBytes = SnapshotGraphicsRegion(bus, damage.Raw);
            AssertSetRastPixels(selectedBoth);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damage.Raw));

            partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var sizeAgain = new M68kCpuState
            {
                A = { [1] = bottom.Layer },
                D =
                {
                    [0] = unchecked((uint)rightGrowth),
                    [1] = unchecked((uint)bottomGrowth)
                }
            };
            var displayBeforeSecondResize = SnapshotPlanarBitMap(
                bus, displayBitMap);
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.SizeLayer), sizeAgain));
            Assert.Equal(1u, sizeAgain.D[0]);
            Assert.Equal(displayBeforeSecondResize,
                SnapshotPlanarBitMap(bus, displayBitMap));
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedBoth.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var damageAfterSecondResize = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(damageAfterSecondResize.IsNotNull);
            var damageAfterSecondResizeBytes = SnapshotGraphicsRegion(
                bus, damageAfterSecondResize.Raw);
            AssertSetRastPixels(selectedBoth);
            Assert.Equal(damageAfterSecondResizeBytes,
                SnapshotGraphicsRegion(bus, damageAfterSecondResize.Raw));

            partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(damageAfterSecondResizeBytes,
                SnapshotGraphicsRegion(bus, damageAfterSecondResize.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var removeClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                removeClip));
            Assert.Equal(callerClipRegion, removeClip.D[0]);
            callerClipInstalled = false;

            var expectedDamage = new HashSet<(int X, int Y)>();
            for (var y = 4; y <= 11; y++)
                for (var x = 4; x <= 5; x++)
                    expectedDamage.Add((x, y));
            for (var x = 6; x <= 15; x++)
                expectedDamage.Add((x, 4));
            var visibleMaxX = Math.Min(31, finalMaxX);
            var visibleMaxY = Math.Min(19, finalMaxY);
            for (var y = 0; y <= 15; y++)
                for (var x = 24; x <= visibleMaxX; x++)
                    expectedDamage.Add((x, y));
            for (var y = 16; y <= visibleMaxY; y++)
                for (var x = 0; x <= visibleMaxX; x++)
                    expectedDamage.Add((x, y));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            var publishedClipPixels = CaptureRawClipPixels(
                ReadLayerClipRect(bus, bottom.Layer));
            AssertClipRectsStayWithinLayerBounds(
                ReadLayerClipRect(bus, bottom.Layer));
            if (finalMaxX > 31 || finalMaxY > 19)
                Assert.Contains((finalMaxX, finalMaxY), publishedClipPixels);
            var finalVisibleDamage = CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer));
            Assert.Empty(expectedDamage.Except(finalVisibleDamage));
            Assert.Empty(finalVisibleDamage.Except(expectedDamage));
            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(expectedDamage.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;

        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (callerClipInstalled)
            {
                var removeClip = new M68kCpuState
                {
                    A = { [0] = bottom.Layer }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    removeClip);
            }
            if (callerClipRegion != 0)
            {
                var disposeClip = new M68kCpuState
                {
                    A = { [0] = callerClipRegion }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    disposeClip);
            }
            if (rectangle != 0)
                FreeGuestMemory(
                    bus, rectangle, (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void PartialRefreshCallerClipRegionTracksMoveSizeTargetGrowth()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 0, 0, 23, 15);
        var top = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 4, 4, 15, 11);
        uint callerClipRegion = 0;
        uint rectangle = 0;
        var callerClipInstalled = false;
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            var moveTop = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.MoveLayer), moveTop));
            Assert.Equal(1u, moveTop.D[0]);
            Assert.True(LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).IsNotNull);

            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            callerClipRegion = newRegion.D[0];
            Assert.NotEqual(0u, callerClipRegion);
            rectangle = AllocateGuestMemory(
                bus, (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 4, 4, 4, 4);
            var include = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                include));
            Assert.Equal(1u, include.D[0]);
            var callerClipBytes = SnapshotGraphicsRegion(
                bus, callerClipRegion);
            var installClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = callerClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installClip));
            Assert.Equal(0u, installClip.D[0]);
            callerClipInstalled = true;

            // Translate the old bounds first, then grow right and down. The
            // installed Region selects old damage, not either new strip.
            var moveSize = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1, [1] = 1, [2] = 4, [3] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.MoveSizeLayer), moveSize));
            Assert.Equal(1u, moveSize.D[0]);
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head; clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                         y <= Math.Min(19, (int)maxY); y++)
                        for (var x = Math.Max(0, (int)minX);
                             x <= Math.Min(31, (int)maxX); x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            void SetRastAndAssert(HashSet<(int X, int Y)> expected)
            {
                ClearPlanarBitMap(bus, displayBitMap);
                WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
                var setRast = new M68kCpuState
                {
                    A = { [1] = bottom.RastPort },
                    D = { [0] = 1 }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.SetRast),
                    setRast));
                Assert.Equal(0u, setRast.D[0]);
                for (var y = 0; y < 20; y++)
                    for (var x = 0; x < 32; x++)
                        Assert.Equal(expected.Contains((x, y)),
                            ReadPlanarBitMapPixel(
                                bus, displayBitMap, x, y));
            }

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            var selected = new HashSet<(int X, int Y)> { (5, 5) };
            Assert.True(selected.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            var damageBytes = SnapshotGraphicsRegion(bus, damage.Raw);
            SetRastAndAssert(selected);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damage.Raw));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var removeClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                removeClip));
            Assert.Equal(callerClipRegion, removeClip.D[0]);
            callerClipInstalled = false;

            var expectedDamage = new HashSet<(int X, int Y)>();
            for (var y = 5; y <= 12; y++)
                expectedDamage.Add((5, y));
            for (var y = 1; y <= 16; y++)
                for (var x = 25; x <= 28; x++)
                    expectedDamage.Add((x, y));
            for (var y = 17; y <= 19; y++)
                for (var x = 1; x <= 28; x++)
                    expectedDamage.Add((x, y));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            var finalDamageProjection = CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer));
            Assert.True(finalDamageProjection.IsSupersetOf(expectedDamage));
            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 27, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(finalDamageProjection.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;

        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (callerClipInstalled)
            {
                var removeClip = new M68kCpuState
                {
                    A = { [0] = bottom.Layer }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    removeClip);
            }
            if (callerClipRegion != 0)
            {
                var disposeClip = new M68kCpuState
                {
                    A = { [0] = callerClipRegion }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    disposeClip);
            }
            if (rectangle != 0)
                FreeGuestMemory(
                    bus, rectangle, (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void PartialLayerRefreshRetainsDamageWhenSizeLayerAddsResizeExposure()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            31,
            19);
        var top = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            15,
            15);
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            void MoveTop(uint dx, uint dy)
            {
                var move = new M68kCpuState
                {
                    A = { [1] = top.Layer },
                    D = { [0] = dx, [1] = dy }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.MoveLayer),
                    move));
                Assert.Equal(1u, move.D[0]);
            }

            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head;
                    clipRect != 0;
                    clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                        y <= Math.Min(19, (int)maxY);
                        y++)
                        for (var x = Math.Max(0, (int)minX);
                            x <= Math.Min(31, (int)maxX);
                            x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            var firstExposure = new HashSet<(int X, int Y)>();
            for (var y = 4; y <= 15; y++)
            {
                firstExposure.Add((4, y));
                firstExposure.Add((5, y));
            }
            for (var x = 6; x <= 15; x++)
                firstExposure.Add((x, 4));

            MoveTop(2, 1);
            var firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(firstDamage.IsNotNull);
            var firstDamageBytes = SnapshotGraphicsRegion(bus, firstDamage.Raw);
            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(firstExposure.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var writePixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 4, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixel),
                writePixel));
            Assert.Equal(0u, writePixel.D[0]);

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                partialEnd));
            updating = false;
            Assert.Equal(firstDamage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(firstDamageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));

            // Shrinking the moved occluder reveals its right and bottom edges;
            // the resumed update must include them with the retained move damage.
            var resize = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = unchecked((uint)-1), [1] = unchecked((uint)-1) }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.SizeLayer),
                resize));
            Assert.Equal(1u, resize.D[0]);

            var expectedDamage = new HashSet<(int X, int Y)>(firstExposure);
            for (var y = 5; y <= 16; y++)
                expectedDamage.Add((17, y));
            for (var x = 6; x <= 16; x++)
                expectedDamage.Add((x, 16));
            var combinedDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(combinedDamage.IsNotNull);

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            updating = begin.D[0] == 1u;
            Assert.Equal(1u, begin.D[0]);
            Assert.True(expectedDamage.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var damageBytesBeforeRaster = SnapshotGraphicsRegion(
                bus,
                combinedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(
                        expectedDamage.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytesBeforeRaster,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;
            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));

        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.EndUpdate),
                    end);
            }
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void PartialRefreshRetainsDamageAcrossSizeLayerWithCallerClipRegion()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 0, 0, 31, 19);
        var top = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 4, 4, 15, 15);
        uint callerClipRegion = 0;
        uint rectangle = 0;
        var callerClipInstalled = false;
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head; clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                         y <= Math.Min(19, (int)maxY); y++)
                        for (var x = Math.Max(0, (int)minX);
                             x <= Math.Min(31, (int)maxX); x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            HashSet<(int X, int Y)> CaptureDamagePixels(uint region)
            {
                var pixels = new HashSet<(int X, int Y)>();
                var regionAddress = APTR.FromPointer(region);
                var regionBounds = LayersRegionCodec.ReadBounds(
                    ref layerMemory, regionAddress);
                var rectangleNode = LayersRegionCodec.ReadFirst(
                    ref layerMemory, regionAddress);
                var visited = new HashSet<uint>();
                while (rectangleNode.IsNotNull)
                {
                    Assert.True(visited.Add(rectangleNode.Raw),
                        "Damage Region rectangle chain must be acyclic.");
                    var bounds = LayersRegionRectangleCodec.ReadBounds(
                        ref layerMemory, rectangleNode);
                    for (var y = regionBounds.MinY + bounds.MinY;
                         y <= regionBounds.MinY + bounds.MaxY; y++)
                        for (var x = regionBounds.MinX + bounds.MinX;
                             x <= regionBounds.MinX + bounds.MaxX; x++)
                            pixels.Add((x, y));
                    rectangleNode = LayersRegionRectangleCodec.ReadNext(
                        ref layerMemory, rectangleNode);
                }
                return pixels;
            }

            var move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.MoveLayer), move));
            Assert.Equal(1u, move.D[0]);

            var expectedDamage = new HashSet<(int X, int Y)>();
            for (var y = 4; y <= 15; y++)
                foreach (var x in new[] { 4, 5 })
                    expectedDamage.Add((x, y));
            for (var x = 6; x <= 15; x++)
                expectedDamage.Add((x, 4));
            var firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(firstDamage.IsNotNull);
            var firstDamagePixels = CaptureDamagePixels(firstDamage.Raw);
            Assert.True(firstDamagePixels.IsSupersetOf(expectedDamage));

            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            callerClipRegion = newRegion.D[0];
            Assert.NotEqual(0u, callerClipRegion);
            rectangle = AllocateGuestMemory(
                bus, (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 4, 4, 4, 4);
            var includeFirst = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeFirst));
            Assert.Equal(1u, includeFirst.D[0]);
            WriteRectangleBounds(bus, rectangle, 17, 5, 17, 5);
            var includeResizeExposure = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeResizeExposure));
            Assert.Equal(1u, includeResizeExposure.D[0]);
            var callerClipBytes = SnapshotGraphicsRegion(
                bus, callerClipRegion);
            var installClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = callerClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installClip));
            Assert.Equal(0u, installClip.D[0]);
            callerClipInstalled = true;
            Assert.True(firstDamagePixels.SetEquals(CaptureDamagePixels(
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw)));
            firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));

            var selectedBeforeResize = new HashSet<(int X, int Y)> { (4, 4) };
            var selectedAfterResize = new HashSet<(int X, int Y)>
            {
                (4, 4),
                (17, 5)
            };
            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedBeforeResize.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var damageBytes = SnapshotGraphicsRegion(bus, firstDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var writePixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 4, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixel),
                writePixel));
            Assert.Equal(0u, writePixel.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(selectedBeforeResize.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));

            var resize = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = unchecked((uint)-1), [1] = unchecked((uint)-1) }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.SizeLayer), resize));
            Assert.Equal(1u, resize.D[0]);
            for (var y = 5; y <= 16; y++)
                expectedDamage.Add((17, y));
            for (var x = 6; x <= 16; x++)
                expectedDamage.Add((x, 16));
            var combinedDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(combinedDamage.IsNotNull);
            Assert.True(CaptureDamagePixels(combinedDamage.Raw)
                .IsSupersetOf(expectedDamage));
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedAfterResize.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            damageBytes = SnapshotGraphicsRegion(
                bus, combinedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(selectedAfterResize.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));

            var removeClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                removeClip));
            Assert.Equal(callerClipRegion, removeClip.D[0]);
            callerClipInstalled = false;
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(expectedDamage.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var damageBytesBeforeRaster = SnapshotGraphicsRegion(
                bus, combinedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(expectedDamage.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytesBeforeRaster,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;

            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (callerClipInstalled)
            {
                var removeClip = new M68kCpuState
                {
                    A = { [0] = bottom.Layer }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    removeClip);
            }
            if (callerClipRegion != 0)
            {
                var disposeClip = new M68kCpuState
                {
                    A = { [0] = callerClipRegion }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    disposeClip);
            }
            if (rectangle != 0)
                FreeGuestMemory(
                    bus, rectangle, (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void BeginUpdateRejectsMalformedDamagePredecessorBeforeProjectionMutation()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 0, 0, 31, 19);
        var top = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 4, 4, 15, 15);

        try
        {
            var move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.MoveLayer), move));
            Assert.Equal(1u, move.D[0]);

            var memory = new LayersTestGuestMemory(bus);
            var bottomAddress = APTR.FromPointer(bottom.Layer);
            var damage = LayersLayerCodec.ReadDamageList(ref memory, bottomAddress);
            Assert.True(damage.IsNotNull);
            var damageHead = LayersRegionCodec.ReadFirst(ref memory, damage);
            Assert.True(damageHead.IsNotNull);
            var expectedPrevious = LayersRegionCodec.HeadAnchor(damage);
            Assert.Equal(expectedPrevious.Raw,
                LayersRegionRectangleCodec.ReadPrevious(ref memory, damageHead).Raw);

            var clipHeadBefore = ReadLayerClipRect(bus, bottom.Layer);
            var flagsBefore = ReadLayerFlags(bus, bottom.Layer);
            var badPrevious = APTR.FromPointer(0x0000_1234u);
            LayersRegionRectangleCodec.WritePrevious(ref memory, damageHead, badPrevious);

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(0u, begin.D[0]);
            Assert.Equal(clipHeadBefore, ReadLayerClipRect(bus, bottom.Layer));
            Assert.Equal(flagsBefore, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(damage.Raw,
                LayersLayerCodec.ReadDamageList(ref memory, bottomAddress).Raw);
            Assert.Equal(badPrevious.Raw,
                LayersRegionRectangleCodec.ReadPrevious(ref memory, damageHead).Raw);

            // Restore the owned Region before normal layer teardown. The
            // failed admission must not consume or repair provider damage.
            LayersRegionRectangleCodec.WritePrevious(ref memory, damageHead,
                expectedPrevious);
        }
        finally
        {
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void BeginUpdateRejectsCyclicDamageListBeforeProjectionMutation()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 0, 0, 31, 19);
        var top = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 4, 4, 15, 15);

        try
        {
            var move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.MoveLayer), move));
            Assert.Equal(1u, move.D[0]);

            var memory = new LayersTestGuestMemory(bus);
            var bottomAddress = APTR.FromPointer(bottom.Layer);
            var damage = LayersLayerCodec.ReadDamageList(ref memory, bottomAddress);
            Assert.True(damage.IsNotNull);
            var damageHead = LayersRegionCodec.ReadFirst(ref memory, damage);
            Assert.True(damageHead.IsNotNull);
            var expectedPrevious = LayersRegionCodec.HeadAnchor(damage);
            Assert.Equal(expectedPrevious.Raw,
                LayersRegionRectangleCodec.ReadPrevious(ref memory, damageHead).Raw);

            var clipHeadBefore = ReadLayerClipRect(bus, bottom.Layer);
            var flagsBefore = ReadLayerFlags(bus, bottom.Layer);
            var originalNext = LayersRegionRectangleCodec.ReadNext(
                ref memory, damageHead);
            LayersRegionRectangleCodec.WriteNext(
                ref memory, damageHead, damageHead);

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(0u, begin.D[0]);
            Assert.Equal(clipHeadBefore, ReadLayerClipRect(bus, bottom.Layer));
            Assert.Equal(flagsBefore, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(damage.Raw,
                LayersLayerCodec.ReadDamageList(ref memory, bottomAddress).Raw);
            Assert.Equal(damageHead.Raw,
                LayersRegionRectangleCodec.ReadNext(ref memory, damageHead).Raw);

            // Restore the owned Region before normal layer teardown. The
            // failed admission must not consume or repair provider damage.
            LayersRegionRectangleCodec.WriteNext(
                ref memory, damageHead, originalNext);
        }
        finally
        {
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void NonzeroOriginMoveAndShrinkAccumulateDamageForLowerLayerRefresh()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 64, 32);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            8,
            4,
            39,
            23);
        var top = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            12,
            8,
            23,
            19);
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            var stableFlags = ReadLayerFlags(bus, bottom.Layer);
            Assert.True(LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).IsNotNull);

            // Move first to create retained damage for the newly exposed old
            // position, then shrink the moved layer. The second operation
            // must union its reveal with the existing DamageList.
            var move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveLayer),
                move));
            Assert.Equal(1u, move.D[0]);
            var movedDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(movedDamage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, movedDamage).IsNotNull);

            // Shrinking the moved upper layer reveals its former right/bottom
            // edge while preserving the move's already-published damage.
            var size = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = unchecked((uint)-2), [1] = unchecked((uint)-1) }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.SizeLayer),
                size));
            Assert.Equal(1u, size.D[0]);

            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNotNull);
            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);
            var stableHead = ReadLayerClipRect(bus, bottom.Layer);

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            var updateHead = ReadLayerClipRect(bus, bottom.Layer);
            Assert.NotEqual(stableHead, updateHead);
            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Updating);
            var damageBytesBeforeRaster = SnapshotGraphicsRegion(bus, damage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 12, 8));
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 16, 8));
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 24, 10));
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 16, 20));
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 10, 6));
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 18, 14));
            var admittedBounds = new List<(short MinX, short MinY, short MaxX, short MaxY)>();
            for (var clipRect = updateHead; clipRect != 0;
                 clipRect = ReadClipRectNext(bus, clipRect))
            {
                var bounds = LayersClipRectCodec.BoundsAddress(
                    APTR.FromPointer(clipRect)).Raw;
                admittedBounds.Add((
                    unchecked((short)bus.ReadWord(bounds)),
                    unchecked((short)bus.ReadWord(bounds + 2)),
                    unchecked((short)bus.ReadWord(bounds + 4)),
                    unchecked((short)bus.ReadWord(bounds + 6))));
            }
            Assert.NotEmpty(admittedBounds);
            var expectedDamage = new (int MinX, int MinY, int MaxX, int MaxY)[]
            {
                (12, 8, 13, 19),
                (14, 8, 23, 8),
                (24, 9, 25, 20),
                (14, 20, 23, 20)
            };
            for (var y = 0; y < 32; y++)
            {
                for (var x = 0; x < 64; x++)
                {
                    var admitted = expectedDamage.Any(bounds =>
                        x >= bounds.MinX && x <= bounds.MaxX &&
                        y >= bounds.MinY && y <= bounds.MaxY);
                    Assert.Equal(admitted,
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
                }
            }
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytesBeforeRaster,
                SnapshotGraphicsRegion(bus, damage.Raw));

            var end = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, end);
            updating = false;
            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));

            Assert.Equal((ushort)(stableFlags | (ushort)LayerFlags.Refresh),
                ReadLayerFlags(bus, bottom.Layer));
            Assert.NotEqual(0u, ReadLayerClipRect(bus, bottom.Layer));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void PartialRefreshRetainsDamageAcrossTwoMoveSizeCallerClipPasses()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 64, 32);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 8, 4, 39, 23);
        var top = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 12, 8, 23, 19);
        uint callerClipRegion = 0;
        uint rectangle = 0;
        var callerClipInstalled = false;
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head;
                    clipRect != 0;
                    clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                        y <= Math.Min(31, (int)maxY);
                        y++)
                        for (var x = Math.Max(0, (int)minX);
                            x <= Math.Min(63, (int)maxX);
                            x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            HashSet<(int X, int Y)> CaptureDamagePixels(uint region)
            {
                var pixels = new HashSet<(int X, int Y)>();
                var regionAddress = APTR.FromPointer(region);
                var regionBounds = LayersRegionCodec.ReadBounds(
                    ref layerMemory,
                    regionAddress);
                var rectangle = LayersRegionCodec.ReadFirst(
                    ref layerMemory,
                    regionAddress);
                var visited = new HashSet<uint>();
                while (rectangle.IsNotNull)
                {
                    Assert.True(visited.Add(rectangle.Raw),
                        "Damage Region rectangle chain must be acyclic.");
                    var bounds = LayersRegionRectangleCodec.ReadBounds(
                        ref layerMemory,
                        rectangle);
                    for (var y = regionBounds.MinY + bounds.MinY + 4;
                        y <= regionBounds.MinY + bounds.MaxY + 4;
                        y++)
                        for (var x = regionBounds.MinX + bounds.MinX + 8;
                            x <= regionBounds.MinX + bounds.MaxX + 8;
                            x++)
                            pixels.Add((x, y));
                    rectangle = LayersRegionRectangleCodec.ReadNext(
                        ref layerMemory,
                        rectangle);
                }
                return pixels;
            }

            var move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.MoveLayer), move));
            Assert.Equal(1u, move.D[0]);

            var firstExposure = new HashSet<(int X, int Y)>();
            for (var y = 8; y <= 19; y++)
                for (var x = 12; x <= 13; x++)
                    firstExposure.Add((x, y));
            for (var x = 14; x <= 23; x++)
                firstExposure.Add((x, 8));

            var firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(firstDamage.IsNotNull);
            var firstDamageBytes = SnapshotGraphicsRegion(bus, firstDamage.Raw);
            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            var firstProjection = CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer));
            Assert.True(
                firstExposure.SetEquals(firstProjection),
                $"Expected {string.Join(",", firstExposure.OrderBy(p => p.Y).ThenBy(p => p.X))}; " +
                $"got {string.Join(",", firstProjection.OrderBy(p => p.Y).ThenBy(p => p.X))}");

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(
                        firstExposure.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(firstDamage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(firstDamageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));

            // Moving and shrinking the translated occluder in one transaction
            // reveals its former left, right, and bottom edges. They must join
            // the paused old-position exposure before projection is rebuilt.
            var moveSize = new M68kCpuState
            {
                A = { [0] = top.Layer },
                D =
                {
                    [0] = 1,
                    [1] = 0,
                    [2] = unchecked((uint)-2),
                    [3] = unchecked((uint)-1)
                }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.MoveSizeLayer), moveSize));
            Assert.Equal(1u, moveSize.D[0]);

            var expectedDamage = new HashSet<(int X, int Y)>(firstExposure);
            for (var y = 9; y <= 19; y++)
                foreach (var x in new[] { 14, 25 })
                    expectedDamage.Add((x, y));
            for (var x = 14; x <= 25; x++)
                expectedDamage.Add((x, 20));

            var combinedDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(combinedDamage.IsNotNull);

            var newClip = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newClip));
            callerClipRegion = newClip.D[0];
            Assert.NotEqual(0u, callerClipRegion);
            rectangle = AllocateGuestMemory(
                bus,
                (uint)GraphicsLayouts.RectangleSize);
            // ClipRegion bounds are local to the Layer at (8,4), so these
            // select screen pixels (12,8), (14,9), and (15,10).
            WriteRectangleBounds(bus, rectangle, 4, 4, 4, 4);
            var includeFirstExposure = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeFirstExposure));
            Assert.Equal(1u, includeFirstExposure.D[0]);
            WriteRectangleBounds(bus, rectangle, 6, 5, 6, 5);
            var includeMoveSizeExposure = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeMoveSizeExposure));
            Assert.Equal(1u, includeMoveSizeExposure.D[0]);
            WriteRectangleBounds(bus, rectangle, 7, 6, 7, 6);
            var includeSecondMoveSizeExposure = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeSecondMoveSizeExposure));
            Assert.Equal(1u, includeSecondMoveSizeExposure.D[0]);
            var callerClipBytes = SnapshotGraphicsRegion(
                bus,
                callerClipRegion);
            var clippedDamage = new HashSet<(int X, int Y)>
            {
                (12, 8),
                (14, 9)
            };
            var clippedDamageAfterSecondMoveSize =
                new HashSet<(int X, int Y)>(clippedDamage)
                {
                    (15, 10)
                };
            Assert.All(clippedDamage, point =>
                Assert.Contains(point, expectedDamage));
            Assert.DoesNotContain((15, 10), expectedDamage);
            var retainedDamagePixels = CaptureDamagePixels(combinedDamage.Raw);
            Assert.True(
                retainedDamagePixels.IsSupersetOf(expectedDamage),
                "The retained DamageList must include each newly exposed pixel.");
            var installClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = callerClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installClip));
            Assert.Equal(0u, installClip.D[0]);
            callerClipInstalled = true;
            var damageAfterClipInstall = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(
                retainedDamagePixels.SetEquals(CaptureDamagePixels(
                    damageAfterClipInstall.Raw)),
                "Installing the caller Region must preserve pending damage geometry.");
            combinedDamage = damageAfterClipInstall;

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.Equal(combinedDamage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            // InstallClipRegion controls admitted raster pixels, while the
            // Layers-owned DamageList remains the pending exposure union.
            var damageBytesBeforeRaster = SnapshotGraphicsRegion(
                bus, combinedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var clippedSetRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                clippedSetRast));
            Assert.Equal(0u, clippedSetRast.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(
                        clippedDamage.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(combinedDamage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytesBeforeRaster,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var clippedEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                clippedEnd));
            updating = false;
            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);
            Assert.Equal(combinedDamage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytesBeforeRaster,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            // The caller Region remains installed during another topology
            // transaction. Only now does its third selected pixel join the
            // retained exposure union.
            var secondMoveSize = new M68kCpuState
            {
                A = { [0] = top.Layer },
                D =
                {
                    [0] = 1,
                    [1] = 0,
                    [2] = unchecked((uint)-1),
                    [3] = unchecked((uint)-1)
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveSizeLayer),
                secondMoveSize));
            Assert.Equal(1u, secondMoveSize.D[0]);
            for (var y = 9; y <= 19; y++)
                expectedDamage.Add((15, y));
            for (var x = 16; x <= 24; x++)
                expectedDamage.Add((x, 19));
            var damageAfterSecondMoveSize = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(
                CaptureDamagePixels(damageAfterSecondMoveSize.Raw)
                    .IsSupersetOf(expectedDamage),
                "The second MoveSizeLayer must add its exposed pixels to damage.");
            combinedDamage = damageAfterSecondMoveSize;
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            damageBytesBeforeRaster = SnapshotGraphicsRegion(
                bus, combinedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var secondClippedSetRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                secondClippedSetRast));
            Assert.Equal(0u, secondClippedSetRast.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(
                        clippedDamageAfterSecondMoveSize.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(combinedDamage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytesBeforeRaster,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var secondClippedEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                secondClippedEnd));
            updating = false;
            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);
            Assert.Equal(combinedDamage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytesBeforeRaster,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var removeClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                removeClip));
            Assert.Equal(callerClipRegion, removeClip.D[0]);
            callerClipInstalled = false;
            Assert.Equal(0u, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));
            var damageAfterClipRemoval = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(CaptureDamagePixels(damageAfterClipRemoval.Raw)
                .IsSupersetOf(expectedDamage));
            combinedDamage = damageAfterClipRemoval;

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            var completedProjection = CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer));
            Assert.True(
                expectedDamage.SetEquals(completedProjection),
                $"Expected {string.Join(",", expectedDamage.OrderBy(p => p.Y).ThenBy(p => p.X))}; " +
                $"got {string.Join(",", completedProjection.OrderBy(p => p.Y).ThenBy(p => p.X))}");
            damageBytesBeforeRaster = SnapshotGraphicsRegion(
                bus, combinedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 63, [3] = 31 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(
                        expectedDamage.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytesBeforeRaster,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;
            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));

            Assert.Equal(0u, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.EndUpdate),
                    end);
            }
            if (callerClipInstalled)
            {
                var removeClip = new M68kCpuState
                {
                    A = { [0] = bottom.Layer }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    removeClip);
            }
            if (callerClipRegion != 0)
            {
                var disposeClip = new M68kCpuState
                {
                    A = { [0] = callerClipRegion }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    disposeClip);
            }
            if (rectangle != 0)
                FreeGuestMemory(
                    bus,
                    rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void EmptyCallerClipRetainsDamageAcrossOccluderMoveSize()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 64, 32);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 0, 0, 31, 23);
        var top = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 4, 4, 15, 15);
        uint emptyClipRegion = 0;
        var emptyClipInstalled = false;
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head; clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                         y <= Math.Min(31, (int)maxY); y++)
                        for (var x = Math.Max(0, (int)minX);
                             x <= Math.Min(63, (int)maxX); x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            HashSet<(int X, int Y)> CaptureDamagePixels(uint region)
            {
                var pixels = new HashSet<(int X, int Y)>();
                var regionAddress = APTR.FromPointer(region);
                var regionBounds = LayersRegionCodec.ReadBounds(
                    ref layerMemory, regionAddress);
                var rectangle = LayersRegionCodec.ReadFirst(
                    ref layerMemory, regionAddress);
                var visited = new HashSet<uint>();
                while (rectangle.IsNotNull)
                {
                    Assert.True(visited.Add(rectangle.Raw),
                        "Damage Region rectangle chain must be acyclic.");
                    var bounds = LayersRegionRectangleCodec.ReadBounds(
                        ref layerMemory, rectangle);
                    for (var y = regionBounds.MinY + bounds.MinY;
                         y <= regionBounds.MinY + bounds.MaxY; y++)
                        for (var x = regionBounds.MinX + bounds.MinX;
                             x <= regionBounds.MinX + bounds.MaxX; x++)
                            pixels.Add((x, y));
                    rectangle = LayersRegionRectangleCodec.ReadNext(
                        ref layerMemory, rectangle);
                }
                return pixels;
            }

            var move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.MoveLayer), move));
            Assert.Equal(1u, move.D[0]);

            var expectedDamage = new HashSet<(int X, int Y)>();
            for (var y = 4; y <= 15; y++)
                foreach (var x in new[] { 4, 5 })
                    expectedDamage.Add((x, y));
            for (var x = 6; x <= 15; x++)
                expectedDamage.Add((x, 4));

            var initialDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(initialDamage.IsNotNull);
            var initialDamagePixels = CaptureDamagePixels(initialDamage.Raw);
            Assert.True(initialDamagePixels.IsSupersetOf(expectedDamage));

            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            emptyClipRegion = newRegion.D[0];
            Assert.NotEqual(0u, emptyClipRegion);
            var emptyClipBytes = SnapshotGraphicsRegion(bus, emptyClipRegion);

            var installEmptyClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = emptyClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installEmptyClip));
            Assert.Equal(0u, installEmptyClip.D[0]);
            emptyClipInstalled = true;
            Assert.Equal(emptyClipRegion,
                ReadLayerClipRegion(bus, bottom.Layer));
            Assert.True(initialDamagePixels.SetEquals(CaptureDamagePixels(
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw)));

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.Empty(CaptureClipPixels(ReadLayerClipRect(bus, bottom.Layer)));
            var retainedDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            var damageBytes = SnapshotGraphicsRegion(bus, retainedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.False(ReadPlanarBitMapPixel(
                        bus, displayBitMap, x, y));
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, retainedDamage.Raw));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.True(LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).IsNotNull);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, retainedDamage.Raw));
            Assert.Equal(emptyClipBytes,
                SnapshotGraphicsRegion(bus, emptyClipRegion));

            var moveSize = new M68kCpuState
            {
                A = { [0] = top.Layer },
                D =
                {
                    [0] = 1,
                    [1] = 0,
                    [2] = unchecked((uint)-2),
                    [3] = unchecked((uint)-1)
                }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.MoveSizeLayer), moveSize));
            Assert.Equal(1u, moveSize.D[0]);
            for (var y = 5; y <= 15; y++)
                foreach (var x in new[] { 6, 17 })
                    expectedDamage.Add((x, y));
            for (var x = 6; x <= 17; x++)
                expectedDamage.Add((x, 16));

            var damageAfterMoveSize = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(CaptureDamagePixels(damageAfterMoveSize.Raw)
                .IsSupersetOf(expectedDamage));
            Assert.Equal(emptyClipRegion,
                ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(emptyClipBytes,
                SnapshotGraphicsRegion(bus, emptyClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.Empty(CaptureClipPixels(ReadLayerClipRect(bus, bottom.Layer)));
            damageBytes = SnapshotGraphicsRegion(
                bus, damageAfterMoveSize.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.False(ReadPlanarBitMapPixel(
                        bus, displayBitMap, x, y));
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageAfterMoveSize.Raw));

            partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageAfterMoveSize.Raw));
            Assert.Equal(emptyClipBytes,
                SnapshotGraphicsRegion(bus, emptyClipRegion));

            var removeClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                removeClip));
            Assert.Equal(emptyClipRegion, removeClip.D[0]);
            emptyClipInstalled = false;
            var finalDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(CaptureDamagePixels(finalDamage.Raw)
                .IsSupersetOf(expectedDamage));
            Assert.Equal(emptyClipBytes,
                SnapshotGraphicsRegion(bus, emptyClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(expectedDamage.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 23 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(expectedDamage.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;
            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Refresh | LayerFlags.Updating));

        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (emptyClipInstalled)
            {
                var removeClip = new M68kCpuState
                {
                    A = { [0] = bottom.Layer }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    removeClip);
            }
            if (emptyClipRegion != 0)
            {
                var disposeClip = new M68kCpuState
                {
                    A = { [0] = emptyClipRegion }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    disposeClip);
            }
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void ClipRegionSurvivesOccluderDeletionDuringPausedRefresh()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 64, 32);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 8, 4, 39, 23);
        var top = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 12, 8, 23, 19);
        uint callerClipRegion = 0;
        uint rectangle = 0;
        var callerClipInstalled = false;
        var topExists = true;
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head; clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                         y <= Math.Min(31, (int)maxY); y++)
                        for (var x = Math.Max(0, (int)minX);
                             x <= Math.Min(63, (int)maxX); x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            HashSet<(int X, int Y)> CaptureDamagePixels(uint region)
            {
                var pixels = new HashSet<(int X, int Y)>();
                var regionAddress = APTR.FromPointer(region);
                var regionBounds = LayersRegionCodec.ReadBounds(
                    ref layerMemory, regionAddress);
                var rectangleNode = LayersRegionCodec.ReadFirst(
                    ref layerMemory, regionAddress);
                var visited = new HashSet<uint>();
                while (rectangleNode.IsNotNull)
                {
                    Assert.True(visited.Add(rectangleNode.Raw),
                        "Damage Region rectangle chain must be acyclic.");
                    var bounds = LayersRegionRectangleCodec.ReadBounds(
                        ref layerMemory, rectangleNode);
                    for (var y = regionBounds.MinY + bounds.MinY + 4;
                         y <= regionBounds.MinY + bounds.MaxY + 4; y++)
                        for (var x = regionBounds.MinX + bounds.MinX + 8;
                             x <= regionBounds.MinX + bounds.MaxX + 8; x++)
                            pixels.Add((x, y));
                    rectangleNode = LayersRegionRectangleCodec.ReadNext(
                        ref layerMemory, rectangleNode);
                }
                return pixels;
            }

            var move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.MoveLayer), move));
            Assert.Equal(1u, move.D[0]);

            var expectedDamage = new HashSet<(int X, int Y)>();
            for (var y = 8; y <= 19; y++)
                foreach (var x in new[] { 12, 13 })
                    expectedDamage.Add((x, y));
            for (var x = 14; x <= 23; x++)
                expectedDamage.Add((x, 8));
            var firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(firstDamage.IsNotNull);
            var firstDamagePixels = CaptureDamagePixels(firstDamage.Raw);
            Assert.True(firstDamagePixels.IsSupersetOf(expectedDamage));

            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            callerClipRegion = newRegion.D[0];
            Assert.NotEqual(0u, callerClipRegion);
            rectangle = AllocateGuestMemory(
                bus, (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 4, 4, 4, 4);
            var includeFirstExposure = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeFirstExposure));
            Assert.Equal(1u, includeFirstExposure.D[0]);
            WriteRectangleBounds(bus, rectangle, 7, 6, 7, 6);
            var includeDeletedCover = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeDeletedCover));
            Assert.Equal(1u, includeDeletedCover.D[0]);
            var callerClipBytes = SnapshotGraphicsRegion(
                bus, callerClipRegion);
            var selectedBeforeDelete = new HashSet<(int X, int Y)>
            {
                (12, 8)
            };
            var selectedAfterDelete = new HashSet<(int X, int Y)>
            {
                (12, 8),
                (15, 10)
            };

            var installClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = callerClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installClip));
            Assert.Equal(0u, installClip.D[0]);
            callerClipInstalled = true;
            Assert.True(firstDamagePixels.SetEquals(CaptureDamagePixels(
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw)));

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedBeforeDelete.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var damageBeforeRaster = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            var damageBytes = SnapshotGraphicsRegion(
                bus, damageBeforeRaster.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(selectedBeforeDelete.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageBeforeRaster.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageBeforeRaster.Raw));

            DeleteLayer(bus, libraryBase, top.Layer);
            topExists = false;
            var damageAfterDelete = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(CaptureDamagePixels(damageAfterDelete.Raw)
                .IsSupersetOf(expectedDamage));
            for (var y = 9; y <= 20; y++)
                for (var x = 14; x <= 25; x++)
                    expectedDamage.Add((x, y));
            Assert.True(CaptureDamagePixels(damageAfterDelete.Raw)
                .IsSupersetOf(expectedDamage));
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedAfterDelete.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            damageBytes = SnapshotGraphicsRegion(
                bus, damageAfterDelete.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(selectedAfterDelete.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageAfterDelete.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageAfterDelete.Raw));

            var removeClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                removeClip));
            Assert.Equal(callerClipRegion, removeClip.D[0]);
            callerClipInstalled = false;
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(expectedDamage.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 63, [3] = 31 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 64; x++)
                    Assert.Equal(expectedDamage.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;

            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Refresh | LayerFlags.Updating));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (callerClipInstalled)
            {
                var removeClip = new M68kCpuState
                {
                    A = { [0] = bottom.Layer }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    removeClip);
            }
            if (callerClipRegion != 0)
            {
                var disposeClip = new M68kCpuState
                {
                    A = { [0] = callerClipRegion }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    disposeClip);
            }
            if (rectangle != 0)
                FreeGuestMemory(
                    bus,
                    rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            if (topExists)
                DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void BehindLayerPublishesCoveredLowerLayerDamageForRefresh()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            31,
            19);
        var top = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            15,
            15);

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            var stableHead = ReadLayerClipRect(bus, bottom.Layer);
            var stableFlags = ReadLayerFlags(bus, bottom.Layer);

            // Sending the upper layer behind reveals the lower layer's former
            // covered rectangle. The depth transaction, rather than graphics,
            // owns its DamageList publication.
            var behind = new M68kCpuState { A = { [1] = top.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BehindLayer),
                behind));
            Assert.Equal(1u, behind.D[0]);
            var which = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 10, [1] = 10 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.WhichLayer),
                which));
            Assert.Equal(bottom.Layer, which.D[0]);

            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNotNull);
            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            Assert.NotEqual(stableHead, ReadLayerClipRect(bus, bottom.Layer));

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 10, 10));
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 3, 3));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);

            var end = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, end);
            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));

            Assert.Equal((ushort)(stableFlags | (ushort)LayerFlags.Refresh),
                ReadLayerFlags(bus, bottom.Layer));
        }
        finally
        {
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void PartialRefreshRetainsDamageAcrossBehindLayerDepthChanges()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            31,
            19);
        var leftCover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            7,
            7);
        var rightCover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            8,
            4,
            11,
            7);
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head;
                    clipRect != 0;
                    clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                        y <= Math.Min(19, (int)maxY);
                        y++)
                        for (var x = Math.Max(0, (int)minX);
                            x <= Math.Min(31, (int)maxX);
                            x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            void SendBehind(uint layer)
            {
                var behind = new M68kCpuState { A = { [1] = layer } };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.BehindLayer),
                    behind));
                Assert.Equal(1u, behind.D[0]);
            }

            var firstExposure = new HashSet<(int X, int Y)>();
            for (var y = 4; y <= 7; y++)
                for (var x = 4; x <= 7; x++)
                    firstExposure.Add((x, y));

            // Sending one occluder behind the lower layer creates its first
            // Layers-owned uncover damage.
            SendBehind(leftCover.Layer);
            var firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(firstDamage.IsNotNull);
            var firstDamageBytes = SnapshotGraphicsRegion(bus, firstDamage.Raw);
            var which = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 5, [1] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.WhichLayer),
                which));
            Assert.Equal(bottom.Layer, which.D[0]);

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(firstExposure.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var writePixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 4, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixel),
                writePixel));
            Assert.Equal(0u, writePixel.D[0]);
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 4, 4));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                partialEnd));
            updating = false;
            Assert.Equal(firstDamage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(firstDamageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));

            // A second depth change reveals the adjacent block. Its damage
            // must join the unconsumed first block before ClipRect conversion.
            SendBehind(rightCover.Layer);
            which = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 9, [1] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.WhichLayer),
                which));
            Assert.Equal(bottom.Layer, which.D[0]);
            var combinedDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(combinedDamage.IsNotNull);

            var expectedDamage = new HashSet<(int X, int Y)>(firstExposure);
            for (var y = 4; y <= 7; y++)
                for (var x = 8; x <= 11; x++)
                    expectedDamage.Add((x, y));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            updating = begin.D[0] == 1u;
            Assert.Equal(1u, begin.D[0]);
            Assert.True(expectedDamage.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var damageBytesBeforeRaster = SnapshotGraphicsRegion(
                bus,
                combinedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(
                        expectedDamage.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytesBeforeRaster,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;
            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));

        }
        finally
        {
            DeleteLayer(bus, libraryBase, rightCover.Layer);
            DeleteLayer(bus, libraryBase, leftCover.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void PartialRefreshRetainsDamageAcrossBehindLayerDepthChangesWithClipRegion()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 0, 0, 31, 19);
        var leftCover = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 4, 4, 7, 7);
        var rightCover = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 8, 4, 11, 7);
        uint callerClipRegion = 0;
        uint rectangle = 0;
        var callerClipInstalled = false;
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head; clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                         y <= Math.Min(19, (int)maxY); y++)
                        for (var x = Math.Max(0, (int)minX);
                             x <= Math.Min(31, (int)maxX); x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            HashSet<(int X, int Y)> CaptureDamagePixels(uint region)
            {
                var pixels = new HashSet<(int X, int Y)>();
                var regionAddress = APTR.FromPointer(region);
                var regionBounds = LayersRegionCodec.ReadBounds(
                    ref layerMemory, regionAddress);
                var rectangleNode = LayersRegionCodec.ReadFirst(
                    ref layerMemory, regionAddress);
                var visited = new HashSet<uint>();
                while (rectangleNode.IsNotNull)
                {
                    Assert.True(visited.Add(rectangleNode.Raw),
                        "Damage Region rectangle chain must be acyclic.");
                    var bounds = LayersRegionRectangleCodec.ReadBounds(
                        ref layerMemory, rectangleNode);
                    for (var y = regionBounds.MinY + bounds.MinY;
                         y <= regionBounds.MinY + bounds.MaxY; y++)
                        for (var x = regionBounds.MinX + bounds.MinX;
                             x <= regionBounds.MinX + bounds.MaxX; x++)
                            pixels.Add((x, y));
                    rectangleNode = LayersRegionRectangleCodec.ReadNext(
                        ref layerMemory, rectangleNode);
                }
                return pixels;
            }

            void SendBehind(uint layer)
            {
                var behind = new M68kCpuState { A = { [1] = layer } };
                Assert.True(InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.BehindLayer), behind));
                Assert.Equal(1u, behind.D[0]);
            }

            var firstExposure = new HashSet<(int X, int Y)>();
            for (var y = 4; y <= 7; y++)
                for (var x = 4; x <= 7; x++)
                    firstExposure.Add((x, y));
            SendBehind(leftCover.Layer);

            var firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(firstDamage.IsNotNull);
            var firstDamagePixels = CaptureDamagePixels(firstDamage.Raw);
            Assert.True(firstDamagePixels.IsSupersetOf(firstExposure));

            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            callerClipRegion = newRegion.D[0];
            Assert.NotEqual(0u, callerClipRegion);
            rectangle = AllocateGuestMemory(
                bus, (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 4, 4, 4, 4);
            var includeFirst = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeFirst));
            Assert.Equal(1u, includeFirst.D[0]);
            WriteRectangleBounds(bus, rectangle, 9, 5, 9, 5);
            var includeSecond = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeSecond));
            Assert.Equal(1u, includeSecond.D[0]);
            var callerClipBytes = SnapshotGraphicsRegion(
                bus, callerClipRegion);
            var installClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = callerClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installClip));
            Assert.Equal(0u, installClip.D[0]);
            callerClipInstalled = true;
            Assert.True(firstDamagePixels.SetEquals(CaptureDamagePixels(
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw)));
            firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(firstDamage.IsNotNull);

            var selectedFirst = new HashSet<(int X, int Y)> { (4, 4) };
            var selectedBoth = new HashSet<(int X, int Y)>
            {
                (4, 4),
                (9, 5)
            };
            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, bottom.Layer));
            Assert.True(selectedFirst.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var damageBytes = SnapshotGraphicsRegion(
                bus, firstDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var writePixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 4, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixel),
                writePixel));
            Assert.Equal(0u, writePixel.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(selectedFirst.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(firstDamage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));

            // The second depth mutation must add a disjoint block while the
            // caller Region remains installed and the first block is pending.
            SendBehind(rightCover.Layer);
            var expectedDamage = new HashSet<(int X, int Y)>(firstExposure);
            for (var y = 4; y <= 7; y++)
                for (var x = 8; x <= 11; x++)
                    expectedDamage.Add((x, y));
            var combinedDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(combinedDamage.IsNotNull);
            Assert.True(CaptureDamagePixels(combinedDamage.Raw)
                .IsSupersetOf(expectedDamage));
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedBoth.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            damageBytes = SnapshotGraphicsRegion(
                bus, combinedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(selectedBoth.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));

            var removeClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                removeClip));
            Assert.Equal(callerClipRegion, removeClip.D[0]);
            callerClipInstalled = false;
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(expectedDamage.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var damageBytesBeforeRaster = SnapshotGraphicsRegion(
                bus, combinedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(expectedDamage.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytesBeforeRaster,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;

            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (callerClipInstalled)
            {
                var removeClip = new M68kCpuState
                {
                    A = { [0] = bottom.Layer }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    removeClip);
            }
            if (callerClipRegion != 0)
            {
                var disposeClip = new M68kCpuState
                {
                    A = { [0] = callerClipRegion }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    disposeClip);
            }
            if (rectangle != 0)
                FreeGuestMemory(
                    bus, rectangle, (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, rightCover.Layer);
            DeleteLayer(bus, libraryBase, leftCover.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void PartialRefreshRetainsDamageAcrossDeleteLayer()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 0, 0, 31, 19);
        var leftCover = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 4, 4, 7, 7);
        var rightCover = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 8, 4, 11, 7);
        var leftDeleted = false;
        var rightDeleted = false;
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head;
                    clipRect != 0;
                    clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                        y <= Math.Min(19, (int)maxY);
                        y++)
                        for (var x = Math.Max(0, (int)minX);
                            x <= Math.Min(31, (int)maxX);
                            x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            var firstExposure = new HashSet<(int X, int Y)>();
            for (var y = 4; y <= 7; y++)
                for (var x = 4; x <= 7; x++)
                    firstExposure.Add((x, y));

            // Deleting one occluder publishes the first Layers-owned damage.
            DeleteLayer(bus, libraryBase, leftCover.Layer);
            leftDeleted = true;
            var firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(firstDamage.IsNotNull);
            var firstDamageBytes = SnapshotGraphicsRegion(bus, firstDamage.Raw);

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(firstExposure.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var writePixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 4, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixel),
                writePixel));
            Assert.Equal(0u, writePixel.D[0]);
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 4, 4));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(firstDamage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(firstDamageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));

            // A second deletion adds the adjacent newly exposed block while
            // the first block remains pending for the resumed refresh.
            DeleteLayer(bus, libraryBase, rightCover.Layer);
            rightDeleted = true;
            var which = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 9, [1] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.WhichLayer), which));
            Assert.Equal(bottom.Layer, which.D[0]);

            var expectedDamage = new HashSet<(int X, int Y)>(firstExposure);
            for (var y = 4; y <= 7; y++)
                for (var x = 8; x <= 11; x++)
                    expectedDamage.Add((x, y));

            var combinedDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(combinedDamage.IsNotNull);
            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(expectedDamage.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));

            ClearPlanarBitMap(bus, displayBitMap);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(
                        expectedDamage.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;
            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));

        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.EndUpdate),
                    end);
            }
            if (!rightDeleted)
                DeleteLayer(bus, libraryBase, rightCover.Layer);
            if (!leftDeleted)
                DeleteLayer(bus, libraryBase, leftCover.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void MoveLayerInFrontOfPublishesNewlyVisibleLayerDamageForRefresh()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 0, 0, 31, 19);
        var top = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 4, 4, 15, 15);

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            var move = new M68kCpuState
            {
                // The bottom layer starts behind the top layer. Moving it in
                // front exposes the previously covered intersection, which
                // must become a Layers-owned damage projection.
                A = { [0] = bottom.Layer, [1] = top.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveLayerInFrontOf),
                move));
            Assert.Equal(1u, move.D[0]);
            Assert.Equal(
                bottom.Layer,
                LayersLayerInfoCodec.ReadTopLayer(
                    ref layerMemory, APTR.FromPointer(layerInfo)).Raw);
            Assert.Equal(0u, LayersLayerCodec.ReadFront(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(0u, LayersLayerCodec.ReadBack(
                ref layerMemory, APTR.FromPointer(top.Layer)).Raw);

            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(
                ref layerMemory, damage).IsNotNull);
            var flagsAfterMove = ReadLayerFlags(bus, bottom.Layer);
            Assert.NotEqual(0, flagsAfterMove &
                (ushort)LayerFlags.Refresh);
            var damageBytesBeforeRaster = Enumerable.Range(
                    0, checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray();

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            var flagsBeforeRaster = ReadLayerFlags(bus, bottom.Layer);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 10, 10));
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 3, 3));
            Assert.Equal(flagsBeforeRaster, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(
                damageBytesBeforeRaster,
                Enumerable.Range(0, checked((int)LayersRegionCodec.Size))
                    .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                    .ToArray());

            var end = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, end);
            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));

        }
        finally
        {
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DeleteLayer(bus, libraryBase, top.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void PartialRefreshRetainsDamageAcrossMoveLayerInFrontOf()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 0, 0, 31, 19);
        var leftCover = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 4, 4, 7, 7);
        var rightCover = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 8, 4, 11, 7);
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head;
                    clipRect != 0;
                    clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                        y <= Math.Min(19, (int)maxY);
                        y++)
                        for (var x = Math.Max(0, (int)minX);
                            x <= Math.Min(31, (int)maxX);
                            x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            void MoveInFrontOf(uint target)
            {
                var move = new M68kCpuState
                {
                    A = { [0] = bottom.Layer, [1] = target }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.MoveLayerInFrontOf),
                    move));
                Assert.Equal(1u, move.D[0]);
            }

            var firstExposure = new HashSet<(int X, int Y)>();
            for (var y = 4; y <= 7; y++)
                for (var x = 4; x <= 7; x++)
                    firstExposure.Add((x, y));

            // The bottom layer starts behind both covers. Move it in front of
            // only the left cover, exposing that block while the right block
            // remains covered.
            MoveInFrontOf(leftCover.Layer);
            var firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(firstDamage.IsNotNull);
            var firstDamageBytes = SnapshotGraphicsRegion(bus, firstDamage.Raw);
            var which = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 5, [1] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.WhichLayer), which));
            Assert.Equal(bottom.Layer, which.D[0]);
            which = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 9, [1] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.WhichLayer), which));
            Assert.Equal(rightCover.Layer, which.D[0]);

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(firstExposure.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var writePixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 4, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixel),
                writePixel));
            Assert.Equal(0u, writePixel.D[0]);
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 4, 4));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(firstDamage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(firstDamageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));

            // Moving the same layer in front of the adjacent cover must add
            // the newly exposed right block without retiring the paused area.
            MoveInFrontOf(rightCover.Layer);
            which = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 9, [1] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.WhichLayer), which));
            Assert.Equal(bottom.Layer, which.D[0]);

            var expectedDamage = new HashSet<(int X, int Y)>(firstExposure);
            for (var y = 4; y <= 7; y++)
                for (var x = 8; x <= 11; x++)
                    expectedDamage.Add((x, y));

            var combinedDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(combinedDamage.IsNotNull);
            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(expectedDamage.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(
                        expectedDamage.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;
            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));

        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.EndUpdate),
                    end);
            }
            DeleteLayer(bus, libraryBase, rightCover.Layer);
            DeleteLayer(bus, libraryBase, leftCover.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void PartialRefreshRetainsDamageAcrossMoveLayerInFrontOfWithClipRegion()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 0, 0, 31, 19);
        var leftCover = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 4, 4, 7, 7);
        var rightCover = CreateLayerOnBitMaps(
            bus, libraryBase, layerInfo, displayBitMap, 0,
            LayerCreationFlags.Simple, 8, 4, 11, 7);
        uint callerClipRegion = 0;
        uint rectangle = 0;
        var callerClipInstalled = false;
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            HashSet<(int X, int Y)> CaptureClipPixels(uint head)
            {
                var pixels = new HashSet<(int X, int Y)>();
                for (var clipRect = head; clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(bounds));
                    var minY = unchecked((short)bus.ReadWord(bounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(bounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(bounds + 6));
                    for (var y = Math.Max(0, (int)minY);
                         y <= Math.Min(19, (int)maxY); y++)
                        for (var x = Math.Max(0, (int)minX);
                             x <= Math.Min(31, (int)maxX); x++)
                            pixels.Add((x, y));
                }
                return pixels;
            }

            HashSet<(int X, int Y)> CaptureDamagePixels(uint region)
            {
                var pixels = new HashSet<(int X, int Y)>();
                var regionAddress = APTR.FromPointer(region);
                var regionBounds = LayersRegionCodec.ReadBounds(
                    ref layerMemory, regionAddress);
                var rectangleNode = LayersRegionCodec.ReadFirst(
                    ref layerMemory, regionAddress);
                var visited = new HashSet<uint>();
                while (rectangleNode.IsNotNull)
                {
                    Assert.True(visited.Add(rectangleNode.Raw),
                        "Damage Region rectangle chain must be acyclic.");
                    var bounds = LayersRegionRectangleCodec.ReadBounds(
                        ref layerMemory, rectangleNode);
                    for (var y = regionBounds.MinY + bounds.MinY;
                         y <= regionBounds.MinY + bounds.MaxY; y++)
                        for (var x = regionBounds.MinX + bounds.MinX;
                             x <= regionBounds.MinX + bounds.MaxX; x++)
                            pixels.Add((x, y));
                    rectangleNode = LayersRegionRectangleCodec.ReadNext(
                        ref layerMemory, rectangleNode);
                }
                return pixels;
            }

            void MoveInFrontOf(uint target)
            {
                var move = new M68kCpuState
                {
                    A = { [0] = bottom.Layer, [1] = target }
                };
                Assert.True(InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.MoveLayerInFrontOf), move));
                Assert.Equal(1u, move.D[0]);
            }

            var firstExposure = new HashSet<(int X, int Y)>();
            for (var y = 4; y <= 7; y++)
                for (var x = 4; x <= 7; x++)
                    firstExposure.Add((x, y));
            MoveInFrontOf(leftCover.Layer);

            var firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(firstDamage.IsNotNull);
            var firstDamagePixels = CaptureDamagePixels(firstDamage.Raw);
            Assert.True(firstDamagePixels.IsSupersetOf(firstExposure));
            var which = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 5, [1] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.WhichLayer), which));
            Assert.Equal(bottom.Layer, which.D[0]);
            which = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 9, [1] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.WhichLayer), which));
            Assert.Equal(rightCover.Layer, which.D[0]);

            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            callerClipRegion = newRegion.D[0];
            Assert.NotEqual(0u, callerClipRegion);
            rectangle = AllocateGuestMemory(
                bus, (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 4, 4, 4, 4);
            var includeFirst = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeFirst));
            Assert.Equal(1u, includeFirst.D[0]);
            WriteRectangleBounds(bus, rectangle, 9, 5, 9, 5);
            var includeSecond = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeSecond));
            Assert.Equal(1u, includeSecond.D[0]);
            var callerClipBytes = SnapshotGraphicsRegion(
                bus, callerClipRegion);
            var installClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = callerClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installClip));
            Assert.Equal(0u, installClip.D[0]);
            callerClipInstalled = true;
            Assert.True(firstDamagePixels.SetEquals(CaptureDamagePixels(
                LayersLayerCodec.ReadDamageList(
                    ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw)));
            firstDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));

            var selectedFirst = new HashSet<(int X, int Y)> { (4, 4) };
            var selectedBoth = new HashSet<(int X, int Y)>
            {
                (4, 4),
                (9, 5)
            };
            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedFirst.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var damageBytes = SnapshotGraphicsRegion(bus, firstDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var writePixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 4, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixel),
                writePixel));
            Assert.Equal(0u, writePixel.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(selectedFirst.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, firstDamage.Raw));

            // Advancing the same layer past the right cover adds a disjoint
            // exposure while the first one remains pending.
            MoveInFrontOf(rightCover.Layer);
            which = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 9, [1] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.WhichLayer), which));
            Assert.Equal(bottom.Layer, which.D[0]);
            var expectedDamage = new HashSet<(int X, int Y)>(firstExposure);
            for (var y = 4; y <= 7; y++)
                for (var x = 8; x <= 11; x++)
                    expectedDamage.Add((x, y));
            var combinedDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer));
            Assert.True(combinedDamage.IsNotNull);
            Assert.True(CaptureDamagePixels(combinedDamage.Raw)
                .IsSupersetOf(expectedDamage));
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(selectedBoth.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            damageBytes = SnapshotGraphicsRegion(
                bus, combinedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(selectedBoth.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.EndUpdate), partialEnd));
            updating = false;
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));

            var removeClip = new M68kCpuState
            {
                A = { [0] = bottom.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                removeClip));
            Assert.Equal(callerClipRegion, removeClip.D[0]);
            callerClipInstalled = false;
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus, Lvo(libraryBase, LayersLvo.BeginUpdate), begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.True(expectedDamage.SetEquals(CaptureClipPixels(
                ReadLayerClipRect(bus, bottom.Layer))));
            var damageBytesBeforeRaster = SnapshotGraphicsRegion(
                bus, combinedDamage.Raw);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            Assert.Equal(0u, rectFill.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(expectedDamage.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(damageBytesBeforeRaster,
                SnapshotGraphicsRegion(bus, combinedDamage.Raw));

            var completeEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, completeEnd);
            updating = false;

            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (callerClipInstalled)
            {
                var removeClip = new M68kCpuState
                {
                    A = { [0] = bottom.Layer }
                };
                _ = InvokeHostTrap(
                    bus, Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    removeClip);
            }
            if (callerClipRegion != 0)
            {
                var disposeClip = new M68kCpuState
                {
                    A = { [0] = callerClipRegion }
                };
                _ = InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    disposeClip);
            }
            if (rectangle != 0)
                FreeGuestMemory(
                    bus, rectangle, (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, rightCover.Layer);
            DeleteLayer(bus, libraryBase, leftCover.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void DeleteLayerPublishesRevealedLowerLayerDamageForRefresh()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            31,
            19);
        var top = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            15,
            15);
        var topDeleted = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            var stableHead = ReadLayerClipRect(bus, bottom.Layer);
            var stableFlags = ReadLayerFlags(bus, bottom.Layer);

            // Deleting an occluding simple layer reveals the same lower-layer
            // rectangle as sending it behind.  Layers owns the DamageList;
            // graphics only paints the BeginUpdate projection.
            DeleteLayer(bus, libraryBase, top.Layer);
            topDeleted = true;

            var which = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 10, [1] = 10 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.WhichLayer),
                which));
            Assert.Equal(bottom.Layer, which.D[0]);

            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNotNull);
            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            Assert.NotEqual(stableHead, ReadLayerClipRect(bus, bottom.Layer));

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 10, 10));
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 3, 3));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);

            var end = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, end);
            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));

            Assert.Equal((ushort)(stableFlags | (ushort)LayerFlags.Refresh),
                ReadLayerFlags(bus, bottom.Layer));
        }
        finally
        {
            if (!topDeleted)
                DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void ClipRegionInstalledAfterPausedUpdateIntersectsResumedDamageProjection()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            31,
            19);
        var top = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            15,
            15);
        var sourceInfo = NewLayerInfo(bus, libraryBase);
        var sourceBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var source = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            sourceInfo,
            sourceBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            31,
            19);
        var rectangle = AllocateGuestMemory(bus, (uint)GraphicsLayouts.RectangleSize);
        var areaPattern = AllocateGuestMemory(bus, 2);
        var template = AllocateGuestMemory(bus, 4);
        var pixelArray = AllocateGuestMemory(bus, 16);
        var maskPlane = AllocateGuestMemory(bus, 80);
        var polyPoints = AllocateGuestMemory(bus, 8);
        var areaInfo = AllocateGuestMemory(bus, AreaInfo.Size);
        var areaStorage = AllocateGuestMemory(bus, 64);
        uint region = 0;
        uint sourceRegion = 0;
        uint textFont = 0;
        uint textAddress = 0;
        var installed = false;
        var sourceRegionInstalled = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            var move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveLayer),
                move));
            Assert.Equal(1u, move.D[0]);

            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNotNull);
            var damageBytes = Enumerable.Range(0, checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray();

            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.NewRegion),
                newRegion));
            region = newRegion.D[0];
            Assert.NotEqual(0u, region);

            // Pause this pass before installing the caller Region so the
            // following BeginUpdate projects retained damage onto its two
            // selected rectangles.
            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            var pause = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                pause));
            Assert.Equal(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Updating);
            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);

            // This point is in the lower layer's newly exposed damage strip.
            WriteRectangleBounds(bus, rectangle, 4, 4, 4, 4);
            var include = new M68kCpuState
            {
                A = { [0] = region, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.OrRectRegion),
                include));
            Assert.Equal(1u, include.D[0]);

            // A disjoint second point remains part of the same suspended
            // damage strip. BeginUpdate must preserve both Region rectangles
            // when it intersects the resumed temporary ClipRect projection.
            WriteRectangleBounds(bus, rectangle, 5, 4, 5, 4);
            include = new M68kCpuState
            {
                A = { [0] = region, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.OrRectRegion),
                include));
            Assert.Equal(1u, include.D[0]);

            var install = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = region }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                install));
            Assert.Equal(0u, install.D[0]);
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            installed = true;
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(0, checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);

            var newSourceRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newSourceRegion));
            sourceRegion = newSourceRegion.D[0];
            Assert.NotEqual(0u, sourceRegion);
            WriteRectangleBounds(bus, rectangle, 1, 4, 1, 4);
            var sourceInclude = new M68kCpuState
            {
                A = { [0] = sourceRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                sourceInclude));
            Assert.Equal(1u, sourceInclude.D[0]);
            var installSourceRegion = new M68kCpuState
            {
                A = { [0] = source.Layer, [1] = sourceRegion }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installSourceRegion));
            Assert.Equal(0u, installSourceRegion.D[0]);
            Assert.Equal(sourceRegion, ReadLayerClipRegion(bus, source.Layer));
            sourceRegionInstalled = true;

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 4, 4));
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 5, 4));
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 6, 4));
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 4, 5));

            // The destination caller Region is two isolated pixels, the
            // source caller Region admits one of them, and the Layers-owned
            // damage strip is broader. ClipBlit must copy their three-way
            // intersection, not the full damage strip or either full layer.
            ClearPlanarBitMap(bus, displayBitMap);
            WriteLayerScroll(bus, source.Layer, 2, 0);
            WriteLayerScroll(bus, bottom.Layer, -1, 0);
            var sourcePlane = ReadBitMapPlane(bus, sourceBitMap, 0);
            var sourceBytes = ReadBitMapBytesPerRow(bus, sourceBitMap) *
                ReadBitMapRows(bus, sourceBitMap);
            for (var offset = 0; offset < sourceBytes; offset++)
                bus.WriteByte(sourcePlane + checked((uint)offset), 0xFF, 0);
            var flagsBeforeClipBlit = ReadLayerFlags(bus, bottom.Layer);
            var sourceFlagsBeforeClipBlit = ReadLayerFlags(bus, source.Layer);
            var clipBlit = new M68kCpuState
            {
                A = { [0] = source.RastPort, [1] = bottom.RastPort },
                D =
                {
                    [0] = 0, [1] = 0, [2] = 0, [3] = 0,
                    [4] = 32, [5] = 20, [6] = 0xC0, [7] = 0xCA11_7007
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ClipBlit),
                clipBlit));
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    y == 4 && x == 4,
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(sourceFlagsBeforeClipBlit,
                ReadLayerFlags(bus, source.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // The bitmap-to-RastPort gateway has no source RastPort Region,
            // but must still honor the destination's caller Region and active
            // damage after the same scroll transform.
            ClearPlanarBitMap(bus, displayBitMap);
            var bitmapBlit = new M68kCpuState
            {
                A = { [0] = sourceBitMap, [1] = bottom.RastPort },
                D =
                {
                    [0] = 0, [1] = 0, [2] = 0, [3] = 0,
                    [4] = 32, [5] = 20, [6] = 0xC0, [7] = 0xBB17_7007
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltBitMapRastPort),
                bitmapBlit));
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    y == 4 && (x == 4 || x == 5),
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }

            // BltTemplate supplies five source bits across both visible
            // logical pixels; only their caller-Region/damage intersection
            // may be committed after the layer scroll transform.
            bus.WriteWord(template, 0xF800, 0);
            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            WriteRastPortDrawMode(bus, bottom.RastPort, 0);
            WriteRastPortMask(bus, bottom.RastPort, 0xFF);
            var templateBlit = new M68kCpuState
            {
                A = { [0] = template, [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 3, [3] = 4, [4] = 5, [5] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltTemplate),
                templateBlit));
            Assert.Equal(0u, templateBlit.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    y == 4 && (x == 4 || x == 5),
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // BltMaskBitMapRastPort must additionally apply its one-bit mask:
            // only the first caller-Region pixel receives source data although
            // both pixels are admitted by damage and clipping.
            bus.WriteWord(maskPlane, 0x8000, 0);
            ClearPlanarBitMap(bus, displayBitMap);
            var maskedBlit = new M68kCpuState
            {
                A =
                {
                    [0] = sourceBitMap,
                    [1] = bottom.RastPort,
                    [2] = maskPlane
                },
                D = { [0] = 0, [1] = 0, [2] = 3, [3] = 4, [4] = 5, [5] = 1, [6] = 0xC0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltMaskBitMapRastPort),
                maskedBlit));
            Assert.Equal(0u, maskedBlit.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    y == 4 && x == 4,
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // Chunky-to-planar writes keep their full source rectangle but
            // publish only the caller-Region/damage intersection.
            for (uint index = 0; index < 5; index++)
                bus.WriteByte(pixelArray + index, 1, 0);
            ClearPlanarBitMap(bus, displayBitMap);
            var chunkyPixels = new M68kCpuState
            {
                A = { [0] = bottom.RastPort, [2] = pixelArray },
                D = { [0] = 3, [1] = 4, [2] = 7, [3] = 4, [4] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WriteChunkyPixels),
                chunkyPixels));
            Assert.Equal(0u, chunkyPixels.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    y == 4 && (x == 4 || x == 5),
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // The ellipse's right-hand cardinal sample lands on the second
            // caller-Region pixel after scroll projection; every other point
            // in its raster must remain outside the exact write set.
            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortDrawMode(bus, bottom.RastPort, 0);
            WriteRastPortLinePattern(bus, bottom.RastPort, 0xFFFF);
            var drawEllipse = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 3, [1] = 4, [2] = 1, [3] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.DrawEllipse),
                drawEllipse));
            Assert.Equal(0u, drawEllipse.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    y == 4 && x == 5,
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // Ordinary ScrollRaster moves source pixels only through the
            // intersected caller Region and active damage after scroll
            // projection, leaving the vacated admitted pixel at BPen.
            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            WriteRastPortBackgroundPen(bus, bottom.RastPort, 0);
            var seedScrollPixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 4, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixel),
                seedScrollPixel));
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 5, 4));
            var scrollRaster = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1, [1] = 0, [2] = 3, [3] = 4, [4] = 4, [5] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ScrollRaster),
                scrollRaster));
            Assert.Equal(0u, scrollRaster.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    y == 4 && x == 4,
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // ScrollRasterBF's full-displacement branch erases the complete
            // visible rectangle, but neither caller clipping nor the resumed
            // damage projection may broaden that backfill.
            var scrollPlane = ReadBitMapPlane(bus, displayBitMap, 0);
            for (var offset = 0; offset < 20 * 4; offset++)
                bus.WriteByte(scrollPlane + checked((uint)offset), 0xFF, 0);
            var scrollRasterBf = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 2, [1] = 0, [2] = 3, [3] = 4, [4] = 4, [5] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ScrollRasterBF),
                scrollRasterBf));
            Assert.Equal(0u, scrollRasterBf.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    !(y == 4 && (x == 4 || x == 5)),
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // ClearEOL's row write is intersected with the same caller Region
            // and active damage; all other seeded display pixels stay set.
            for (var offset = 0; offset < 20 * 4; offset++)
                bus.WriteByte(scrollPlane + checked((uint)offset), 0xFF, 0);
            WriteRastPortBackgroundPen(bus, bottom.RastPort, 1);
            WriteRastPortDrawMode(bus, bottom.RastPort, 0);
            WriteRastPortMask(bus, bottom.RastPort, 0xFF);
            WriteRastPortCurrentX(bus, bottom.RastPort, 3);
            WriteRastPortCurrentY(bus, bottom.RastPort, 5);
            WriteRastPortTextMetrics(bus, bottom.RastPort, 1, 1);
            var clearEol = new M68kCpuState
            {
                A = { [1] = bottom.RastPort }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ClearEOL),
                clearEol));
            Assert.Equal(0u, clearEol.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    !(y == 4 && (x == 4 || x == 5)),
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // ClearScreen's text-line prefix and remaining-raster suffix must
            // not escape the two visible pixels from that same text row.
            for (var offset = 0; offset < 20 * 4; offset++)
                bus.WriteByte(scrollPlane + checked((uint)offset), 0xFF, 0);
            var clearScreen = new M68kCpuState
            {
                A = { [1] = bottom.RastPort }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ClearScreen),
                clearScreen));
            Assert.Equal(0u, clearScreen.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    !(y == 4 && (x == 4 || x == 5)),
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // Native rectangle filling is subject to the same caller Region,
            // active damage, and destination scroll projection.
            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            WriteRastPortDrawMode(bus, bottom.RastPort, 0);
            WriteRastPortMask(bus, bottom.RastPort, 0xFF);
            var rectFill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                rectFill));
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    y == 4 && (x == 4 || x == 5),
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // Pattern phase follows the projected bitmap coordinates after
            // the destination scroll transform. The two admitted cells
            // project to x=4 and x=5; this one-row alternating pattern paints
            // only x=4, screen-space (4,4).
            ClearPlanarBitMap(bus, displayBitMap);
            bus.WriteWord(areaPattern, 0xAAAA, 0);
            bus.WriteLong(
                bottom.RastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
                areaPattern);
            bus.WriteByte(
                bottom.RastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
                0,
                0);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            WriteRastPortDrawMode(bus, bottom.RastPort, 0);
            WriteRastPortMask(bus, bottom.RastPort, 0xFF);
            var bltPattern = new M68kCpuState
            {
                A = { [0] = 0, [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19, [4] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.BltPattern),
                bltPattern));
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                var pixel = ReadPlanarBitMapPixel(bus, displayBitMap, x, y);
                Assert.True(
                    pixel == (y == 4 && x == 4),
                    $"Unexpected patterned pixel at ({x},{y}): {pixel}.");
            }
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // EraseRect must use BPen within the same resumed caller-Region
            // and active-damage projection. Seed the whole display to one so
            // only the two admitted destination pixels can be distinguished
            // as erased; the current scroll maps those samples to the screen
            // points (4,4) and (5,4).
            var destinationPlane = ReadBitMapPlane(bus, displayBitMap, 0);
            var destinationBytes = (uint)(ReadBitMapBytesPerRow(bus, displayBitMap) *
                ReadBitMapRows(bus, displayBitMap));
            for (var offset = 0u; offset < destinationBytes; offset++)
                bus.WriteByte(destinationPlane + offset, 0xFF, 0);
            bus.WriteLong(
                bottom.RastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
                0);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            WriteRastPortBackgroundPen(bus, bottom.RastPort, 0);
            WriteRastPortDrawMode(bus, bottom.RastPort, 1);
            WriteRastPortMask(bus, bottom.RastPort, 0xFF);
            WriteRastPortLinePatternCount(bus, bottom.RastPort, 4);
            var eraseRect = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 31, [3] = 19 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.EraseRect),
                eraseRect));
            Assert.Equal(0u, eraseRect.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    !(y == 4 && (x == 4 || x == 5)),
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal((byte)1, ReadRastPortForegroundPen(bus, bottom.RastPort));
            Assert.Equal((byte)0, bus.ReadByte(
                bottom.RastPort + (uint)GraphicsLayouts.RastPortBgPen));
            Assert.Equal((byte)4, ReadRastPortLinePatternCount(bus, bottom.RastPort));
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // Move and Draw stay in RastPort coordinates while the validated
            // projection shifts their raster samples through the layer's
            // scroll. A four-cell patterned line crosses both caller-Region
            // pixels, but only its second sample (screen (4,4)) is enabled.
            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            WriteRastPortDrawMode(bus, bottom.RastPort, 0);
            WriteRastPortMask(bus, bottom.RastPort, 0xFF);
            WriteRastPortLinePattern(bus, bottom.RastPort, 0x4000);
            var moveRaster = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 2, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.Move),
                moveRaster));
            Assert.Equal(0u, moveRaster.D[0]);
            Assert.Equal((byte)15, ReadRastPortLinePatternCount(bus, bottom.RastPort));
            var drawRaster = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 5, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.Draw),
                drawRaster));
            Assert.Equal(0u, drawRaster.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    y == 4 && x == 4,
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal((ushort)5, ReadRastPortCurrentX(bus, bottom.RastPort));
            Assert.Equal((ushort)4, ReadRastPortCurrentY(bus, bottom.RastPort));
            Assert.Equal((byte)12, ReadRastPortLinePatternCount(bus, bottom.RastPort));
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // Draw a real Topaz glyph through the same projection. Its first
            // glyph sample is placed on the first caller-Region pixel; all
            // other glyph samples must remain clipped, including the adjacent
            // second Region pixel when the font's glyph bit is clear there.
            var openFont = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, -72),
                openFont));
            textFont = openFont.D[0];
            Assert.NotEqual(0u, textFont);
            var setFont = new M68kCpuState
            {
                A = { [0] = textFont, [1] = bottom.RastPort }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, -66),
                setFont));
            textAddress = AllocateGuestMemory(bus, 1);
            bus.WriteByte(textAddress, (byte)'A', 0);
            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            WriteRastPortDrawMode(bus, bottom.RastPort, 0);
            WriteRastPortMask(bus, bottom.RastPort, 0xFF);
            WriteRastPortCurrentX(bus, bottom.RastPort, 3);
            WriteRastPortCurrentY(bus, bottom.RastPort, 10);
            var drawText = new M68kCpuState
            {
                A = { [0] = textAddress, [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.Text),
                drawText));
            Assert.Equal(0u, drawText.D[0]);
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 4, 4));
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                if (y == 4 && (x == 4 || x == 5))
                    continue;
                Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal((ushort)11, ReadRastPortCurrentX(bus, bottom.RastPort));
            Assert.Equal((ushort)10, ReadRastPortCurrentY(bus, bottom.RastPort));
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());
            var closeFont = new M68kCpuState { A = { [1] = textFont } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase, -78),
                closeFont));
            textFont = 0;

            // PolyDraw continues a patterned line across two guest vertices.
            // Its three raster samples span screen x=3..5, while the caller
            // Region admits x=4 and x=5; line phase selects only x=4.
            ClearPlanarBitMap(bus, displayBitMap);
            bus.WriteWord(polyPoints, 3, 0);
            bus.WriteWord(polyPoints + 2u, 4, 0);
            bus.WriteWord(polyPoints + 4u, 4, 0);
            bus.WriteWord(polyPoints + 6u, 4, 0);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            WriteRastPortDrawMode(bus, bottom.RastPort, 0);
            WriteRastPortMask(bus, bottom.RastPort, 0xFF);
            WriteRastPortLinePattern(bus, bottom.RastPort, 0x4000);
            var movePoly = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 2, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.Move),
                movePoly));
            Assert.Equal(0u, movePoly.D[0]);
            var polyDraw = new M68kCpuState
            {
                A = { [0] = polyPoints, [1] = bottom.RastPort },
                D = { [0] = 2 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.PolyDraw),
                polyDraw));
            Assert.Equal(0u, polyDraw.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    y == 4 && x == 4,
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal((ushort)4, ReadRastPortCurrentX(bus, bottom.RastPort));
            Assert.Equal((ushort)4, ReadRastPortCurrentY(bus, bottom.RastPort));
            Assert.Equal((byte)13, ReadRastPortLinePatternCount(bus, bottom.RastPort));
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // AreaEnd fills a polygon larger than the caller Region. The
            // active damage remains the Layers-owned outer bound, and only
            // the two installed caller-Region pixels may be published.
            var initArea = new M68kCpuState
            {
                A = { [0] = areaInfo, [1] = areaStorage },
                D = { [0] = 8 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.InitArea),
                initArea));
            WriteRastPortAreaInfo(bus, bottom.RastPort, areaInfo);
            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            WriteRastPortDrawMode(bus, bottom.RastPort, 0);
            WriteRastPortMask(bus, bottom.RastPort, 0xFF);
            bus.WriteLong(
                bottom.RastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
                0);
            bus.WriteByte(
                bottom.RastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
                0,
                0);
            ExecuteAreaVector(GraphicsLvo.AreaMove, 2, 2);
            ExecuteAreaVector(GraphicsLvo.AreaDraw, 7, 2);
            ExecuteAreaVector(GraphicsLvo.AreaDraw, 7, 7);
            ExecuteAreaVector(GraphicsLvo.AreaDraw, 2, 7);
            ExecuteAreaVector(GraphicsLvo.AreaDraw, 2, 2);
            var areaEnd = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0xCAFE_BABEu }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.AreaEnd),
                areaEnd));
            Assert.Equal(0u, areaEnd.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    y == 4 && (x == 4 || x == 5),
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // AreaEllipse records a filled oval through the same active
            // projection; its interior spans both caller-Region pixels, but
            // no other display pixel may be changed by AreaEnd.
            var initEllipseArea = new M68kCpuState
            {
                A = { [0] = areaInfo, [1] = areaStorage },
                D = { [0] = 8 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.InitArea),
                initEllipseArea));
            WriteRastPortAreaInfo(bus, bottom.RastPort, areaInfo);
            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            WriteRastPortDrawMode(bus, bottom.RastPort, 0);
            WriteRastPortMask(bus, bottom.RastPort, 0xFF);
            bus.WriteLong(
                bottom.RastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
                0);
            bus.WriteByte(
                bottom.RastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
                0,
                0);
            var areaEllipse = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 3, [1] = 4, [2] = 2, [3] = 2 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.AreaEllipse),
                areaEllipse));
            Assert.Equal(0u, areaEllipse.D[0]);
            var fillEllipse = new M68kCpuState
            {
                A = { [1] = bottom.RastPort }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.AreaEnd),
                fillEllipse));
            Assert.Equal(0u, fillEllipse.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    y == 4 && (x == 4 || x == 5),
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // Pixel-line transfers retain their full five-sample logical
            // span while publishing and reading only the two admitted cells.
            for (uint index = 0; index < 5; index++)
                bus.WriteByte(pixelArray + index, 1, 0);
            ClearPlanarBitMap(bus, displayBitMap);
            var writePixelLine = new M68kCpuState
            {
                A = { [0] = bottom.RastPort, [2] = pixelArray },
                D = { [0] = 3, [1] = 4, [2] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixelLine8),
                writePixelLine));
            Assert.Equal(5u, writePixelLine.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    y == 4 && (x == 4 || x == 5),
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            for (uint index = 0; index < 5; index++)
                bus.WriteByte(pixelArray + index, 0xCC, 0);
            var readPixelLine = new M68kCpuState
            {
                A = { [0] = bottom.RastPort, [2] = pixelArray },
                D = { [0] = 3, [1] = 4, [2] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ReadPixelLine8),
                readPixelLine));
            Assert.Equal(5u, readPixelLine.D[0]);
            Assert.Equal((byte)1, bus.ReadByte(pixelArray));
            Assert.Equal((byte)1, bus.ReadByte(pixelArray + 1u));
            Assert.Equal((byte)0, bus.ReadByte(pixelArray + 2u));
            Assert.Equal((byte)0, bus.ReadByte(pixelArray + 3u));
            Assert.Equal((byte)0, bus.ReadByte(pixelArray + 4u));

            // The rectangle-shaped pixel-array vectors share the same exact
            // destination/read projection for a one-row five-pixel request.
            for (uint index = 0; index < 5; index++)
                bus.WriteByte(pixelArray + index, 1, 0);
            ClearPlanarBitMap(bus, displayBitMap);
            var writePixelArray = new M68kCpuState
            {
                A = { [0] = bottom.RastPort, [2] = pixelArray },
                D = { [0] = 3, [1] = 4, [2] = 7, [3] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixelArray8),
                writePixelArray));
            Assert.Equal(5u, writePixelArray.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    y == 4 && (x == 4 || x == 5),
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            for (uint index = 0; index < 5; index++)
                bus.WriteByte(pixelArray + index, 0xCC, 0);
            var readPixelArray = new M68kCpuState
            {
                A = { [0] = bottom.RastPort, [2] = pixelArray },
                D = { [0] = 3, [1] = 4, [2] = 7, [3] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ReadPixelArray8),
                readPixelArray));
            Assert.Equal(5u, readPixelArray.D[0]);
            Assert.Equal((byte)1, bus.ReadByte(pixelArray));
            Assert.Equal((byte)1, bus.ReadByte(pixelArray + 1u));
            Assert.Equal((byte)0, bus.ReadByte(pixelArray + 2u));
            Assert.Equal((byte)0, bus.ReadByte(pixelArray + 3u));
            Assert.Equal((byte)0, bus.ReadByte(pixelArray + 4u));
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // Point access uses the same scrolled caller-Region/damage view.
            // RastPort coordinate (3,4) projects to screen (4,4); (4,4)
            // projects to the other admitted point at screen (5,4), while
            // (2,4) is hidden by the caller Region.
            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var writePixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 3, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.WritePixel),
                writePixel));
            Assert.Equal(0u, writePixel.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    y == 4 && x == 4,
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            var readPaintedPixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 3, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ReadPixel),
                readPaintedPixel));
            Assert.Equal(1u, readPaintedPixel.D[0]);
            var readClearPixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 4, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ReadPixel),
                readClearPixel));
            Assert.Equal(0u, readClearPixel.D[0]);
            var readHiddenPixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 2, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ReadPixel),
                readHiddenPixel));
            Assert.Equal(uint.MaxValue, readHiddenPixel.D[0]);

            // Flood traverses the connected source colour, but publication
            // must still be limited by the resumed damage projection and the
            // installed caller Region after the layer's scroll transform.
            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            WriteRastPortDrawMode(bus, bottom.RastPort, 0);
            WriteRastPortMask(bus, bottom.RastPort, 0xFF);
            bus.WriteLong(
                bottom.RastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
                0);
            bus.WriteByte(
                bottom.RastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
                0,
                0);
            var flood = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 3, [1] = 4, [2] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.Flood),
                flood));
            Assert.Equal(1u, flood.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    y == 4 && (x == 4 || x == 5),
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            // An explicit OutlinePen ring isolates one seed pixel. The
            // complement mode makes an accidental write to the admitted
            // outline pixel observable, while clipping/damage still admit
            // only screen x=4 and x=5.
            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortDrawMode(bus, bottom.RastPort, 2);
            bus.WriteByte(
                bottom.RastPort + (uint)GraphicsLayouts.RastPortOutlinePen,
                1,
                0);
            var outlinePlane = ReadBitMapPlane(bus, displayBitMap, 0);
            foreach (var (outlineX, outlineY) in new[]
                     {
                         (3, 4), (5, 4), (4, 3), (4, 5)
                     })
            {
                var outlineAddress = outlinePlane +
                    checked((uint)(outlineY * 4 + (outlineX >> 3)));
                var outlineMask = 0x80 >> (outlineX & 7);
                bus.WriteByte(
                    outlineAddress,
                    (byte)(bus.ReadByte(outlineAddress) | outlineMask),
                    0);
            }
            var borderFlood = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 3, [1] = 4, [2] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.Flood),
                borderFlood));
            Assert.Equal(1u, borderFlood.D[0]);
            for (var y = 0; y < 20; y++)
            for (var x = 0; x < 32; x++)
            {
                Assert.Equal(
                    (y == 4 && x is 3 or 4 or 5) ||
                        (x == 4 && y is 3 or 5),
                    ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }
            Assert.Equal(flagsBeforeClipBlit, ReadLayerFlags(bus, bottom.Layer));
            Assert.Equal(region, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory, APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, Enumerable.Range(
                    0,
                    checked((int)LayersRegionCodec.Size))
                .Select(offset => bus.ReadByte(damage.Raw + (uint)offset))
                .ToArray());

            void ExecuteAreaVector(GraphicsLvo lvo, short x, short y)
            {
                var frame = new M68kCpuState
                {
                    A = { [1] = bottom.RastPort },
                    D = { [0] = unchecked((ushort)x), [1] = unchecked((ushort)y) }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase, (int)lvo),
                    frame));
                Assert.Equal(0u, frame.D[0]);
            }

            var uninstallSourceRegion = new M68kCpuState
            {
                A = { [0] = source.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                uninstallSourceRegion));
            Assert.Equal(sourceRegion, uninstallSourceRegion.D[0]);
            Assert.Equal(0u, ReadLayerClipRegion(bus, source.Layer));
            sourceRegionInstalled = false;
            var disposeSourceRegion = new M68kCpuState
            {
                A = { [0] = sourceRegion }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.DisposeRegion),
                disposeSourceRegion));
            sourceRegion = 0;

            var end = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, end);
            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));


            var uninstall = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                uninstall));
            Assert.Equal(region, uninstall.D[0]);
            Assert.Equal(0u, ReadLayerClipRegion(bus, bottom.Layer));
            installed = false;
        }
        finally
        {
            if ((ReadLayerFlags(bus, bottom.Layer) &
                    (ushort)LayerFlags.Updating) != 0)
            {
                var cleanupEnd = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 1 }
                };
                InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.EndUpdate),
                    cleanupEnd);
            }
            if (sourceRegionInstalled)
            {
                var uninstall = new M68kCpuState
                {
                    A = { [0] = source.Layer }
                };
                InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    uninstall);
            }
            if (installed)
            {
                var uninstall = new M68kCpuState { A = { [0] = bottom.Layer } };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.InstallClipRegion), uninstall);
            }
            if (region != 0)
            {
                var dispose = new M68kCpuState { A = { [0] = region } };
                InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose);
            }
            if (textFont != 0)
            {
                var closeFont = new M68kCpuState { A = { [1] = textFont } };
                InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase, -78),
                    closeFont);
            }
            if (sourceRegion != 0)
            {
                var dispose = new M68kCpuState { A = { [0] = sourceRegion } };
                InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose);
            }
            FreeGuestMemory(bus, rectangle, (uint)GraphicsLayouts.RectangleSize);
            FreeGuestMemory(bus, areaPattern, 2);
            FreeGuestMemory(bus, template, 4);
            FreeGuestMemory(bus, pixelArray, 16);
            FreeGuestMemory(bus, maskPlane, 80);
            FreeGuestMemory(bus, polyPoints, 8);
            FreeGuestMemory(bus, areaInfo, (uint)AreaInfo.Size);
            FreeGuestMemory(bus, areaStorage, 64);
            if (textAddress != 0)
                FreeGuestMemory(bus, textAddress, 1);
            DeleteLayer(bus, libraryBase, source.Layer);
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, sourceInfo);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, sourceBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void EmptyAndDisjointClipRegionsSuppressActiveDamageRaster()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            31,
            19);
        var top = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            15,
            15);
        uint emptyRegion = 0;
        uint disjointRegion = 0;
        uint rectangle = 0;
        var installed = false;
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            var move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveLayer),
                move));
            Assert.Equal(1u, move.D[0]);

            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNotNull);
            var damageBytesBeforeRaster = SnapshotGraphicsRegion(bus, damage.Raw);

            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            emptyRegion = newRegion.D[0];
            Assert.NotEqual(0u, emptyRegion);
            Assert.True(LayersRegionCodec.ReadFirst(
                ref layerMemory,
                APTR.FromPointer(emptyRegion)).IsNull);

            var install = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = emptyRegion }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                install));
            Assert.Equal(0u, install.D[0]);
            Assert.Equal(emptyRegion, ReadLayerClipRegion(bus, bottom.Layer));
            installed = true;
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Updating);
            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);

            // Seed the whole bitmap so a mistaken fallback from an empty,
            // non-null caller Region to the active damage list is observable.
            var plane = ReadBitMapPlane(bus, displayBitMap, 0);
            for (var offset = 0; offset < 4 * 20; offset++)
                bus.WriteByte(plane + checked((uint)offset), 0xFF, 0);
            var bitmapBeforeRaster = SnapshotPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 0);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            Assert.Equal(bitmapBeforeRaster, SnapshotPlanarBitMap(bus, displayBitMap));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytesBeforeRaster,
                SnapshotGraphicsRegion(bus, damage.Raw));
            var activeFlags = ReadLayerFlags(bus, bottom.Layer);
            Assert.Equal((ushort)LayerFlags.Refresh | (ushort)LayerFlags.Updating,
                (ushort)(activeFlags &
                    ((ushort)LayerFlags.Refresh | (ushort)LayerFlags.Updating)));

            var end = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, end);
            Assert.Equal(1u, end.D[0]);
            updating = false;
            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                ((ushort)LayerFlags.Refresh | (ushort)LayerFlags.Updating));

            Assert.Equal(emptyRegion, ReadLayerClipRegion(bus, bottom.Layer));

            // Completion clears Layers-owned damage, but must not uninstall
            // or weaken the caller's empty graphics Region.
            setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            Assert.Equal(bitmapBeforeRaster, SnapshotPlanarBitMap(bus, displayBitMap));

            // A nonempty Region wholly outside the layer has the same empty
            // effective projection. It must not be mistaken for no caller
            // constraint when a new refresh DamageList is published.
            rectangle = AllocateGuestMemory(
                bus,
                (uint)GraphicsLayouts.RectangleSize);
            var newDisjointRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newDisjointRegion));
            disjointRegion = newDisjointRegion.D[0];
            Assert.NotEqual(0u, disjointRegion);
            WriteRectangleBounds(bus, rectangle, 32, 0, 33, 1);
            var include = new M68kCpuState
            {
                A = { [0] = disjointRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                include));
            Assert.Equal(1u, include.D[0]);

            var uninstallEmpty = new M68kCpuState
            {
                A = { [0] = bottom.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                uninstallEmpty));
            Assert.Equal(emptyRegion, uninstallEmpty.D[0]);
            installed = false;
            Assert.Equal(0u, ReadLayerClipRegion(bus, bottom.Layer));

            move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 1, [1] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveLayer),
                move));
            Assert.Equal(1u, move.D[0]);
            damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            var disjointDamageBytes = SnapshotGraphicsRegion(bus, damage.Raw);

            var installDisjoint = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = disjointRegion }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installDisjoint));
            Assert.Equal(0u, installDisjoint.D[0]);
            installed = true;
            Assert.Equal(disjointRegion, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            ClearPlanarBitMap(bus, displayBitMap);
            var bitmapBeforeDisjointRaster = SnapshotPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            Assert.Equal(bitmapBeforeDisjointRaster,
                SnapshotPlanarBitMap(bus, displayBitMap));
            Assert.Equal(disjointDamageBytes,
                SnapshotGraphicsRegion(bus, damage.Raw));

            end = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, end);
            Assert.Equal(1u, end.D[0]);
            updating = false;

            Assert.Equal(disjointRegion, ReadLayerClipRegion(bus, bottom.Layer));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (installed)
            {
                var uninstall = new M68kCpuState
                {
                    A = { [0] = bottom.Layer }
                };
                InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    uninstall);
            }
            foreach (var region in new[] { emptyRegion, disjointRegion })
            {
                if (region == 0) continue;
                var dispose = new M68kCpuState { A = { [0] = region } };
                InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose);
            }
            if (rectangle != 0)
                FreeGuestMemory(bus, rectangle, (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void FullyObscuredDamageBeginUpdateSuppressesLayeredRasterWrites()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 24);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            8,
            4,
            23,
            19);
        var top = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            8,
            4,
            23,
            19);
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            var move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 1, [1] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveLayer),
                move));
            Assert.Equal(1u, move.D[0]);

            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNotNull);

            move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = unchecked((uint)-1), [1] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveLayer),
                move));
            Assert.Equal(1u, move.D[0]);
            damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNotNull);
            var damageBytes = SnapshotGraphicsRegion(bus, damage.Raw);

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.Equal(0u, ReadLayerClipRect(bus, bottom.Layer));
            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Updating);

            ClearPlanarBitMap(bus, displayBitMap);
            var bitmapBeforeRaster = SnapshotPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            Assert.Equal(bitmapBeforeRaster, SnapshotPlanarBitMap(bus, displayBitMap));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, SnapshotGraphicsRegion(bus, damage.Raw));

            var end = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, end);
            Assert.Equal(1u, end.D[0]);
            updating = false;
            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Refresh | LayerFlags.Updating));

        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Theory]
    [InlineData(8, false, false, false)]
    [InlineData(16, false, false, false)]
    [InlineData(16, true, false, false)]
    [InlineData(16, true, true, false)]
    [InlineData(12, true, false, true)]
    public void SmartDamageRasterizesToVisibleAndOwnedBackingFragments(
        int coverMinX,
        bool disjointDamage,
        bool addDamageWhilePaused,
        bool multiCover)
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 24);
        var smart = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Smart,
            8,
            4,
            23,
            19);
        var coverMaxX = multiCover ? 15 : 23;
        var cover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            (short)coverMinX,
            4,
            (short)coverMaxX,
            19);
        uint coverRightLayer = 0;
        if (multiCover)
        {
            coverRightLayer = CreateLayerOnBitMaps(
                bus,
                libraryBase,
                layerInfo,
                displayBitMap,
                0,
                LayerCreationFlags.Simple,
                20,
                4,
                23,
                19).Layer;
        }
        var layerMemory = new LayersTestGuestMemory(bus);
        uint damageRegion = 0;
        uint rectangle = 0;
        var updating = false;

        try
        {
            var settleBegin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                settleBegin));
            Assert.Equal(1u, settleBegin.D[0]);
            updating = true;
            var settleEnd = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                settleEnd));
            Assert.Equal(1u, settleEnd.D[0]);
            updating = false;

            var stableHead = ReadLayerClipRect(bus, smart.Layer);
            var obscured = stableHead;
            while (obscured != 0 &&
                ReadClipRectObscuringLayer(bus, obscured) != cover.Layer)
                obscured = ReadClipRectNext(bus, obscured);
            Assert.NotEqual(0u, obscured);
            var backingBitMap = ReadClipRectBitMap(bus, obscured);
            Assert.NotEqual(0u, backingBitMap);
            Assert.NotEqual(displayBitMap, backingBitMap);
            var savedBackingBounds = LayersClipRectCodec.ReadBounds(
                ref layerMemory,
                APTR.FromPointer(obscured));

            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            damageRegion = newRegion.D[0];
            Assert.NotEqual(0u, damageRegion);
            rectangle = AllocateGuestMemory(
                bus,
                (uint)GraphicsLayouts.RectangleSize);
            if (disjointDamage)
                WriteRectangleBounds(bus, rectangle, 4, 4,
                    (short)(multiCover ? 15 : 11), 7);
            else
                WriteRectangleBounds(bus, rectangle, 0, 0, 15, 15);
            var includeDamage = new M68kCpuState
            {
                A = { [0] = damageRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeDamage));
            Assert.Equal(1u, includeDamage.D[0]);
            if (disjointDamage)
            {
                WriteRectangleBounds(bus, rectangle, 1, 12, 4, 15);
                includeDamage = new M68kCpuState
                {
                    A = { [0] = damageRegion, [1] = rectangle }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.OrRectRegion),
                    includeDamage));
                Assert.Equal(1u, includeDamage.D[0]);

                var firstDamage = LayersRegionCodec.ReadFirst(ref layerMemory,
                    APTR.FromPointer(damageRegion));
                Assert.True(firstDamage.IsNotNull);
                var secondDamage = LayersRegionRectangleCodec.ReadNext(
                    ref layerMemory, firstDamage);
                Assert.True(secondDamage.IsNotNull);
                Assert.True(LayersRegionRectangleCodec.ReadNext(
                    ref layerMemory, secondDamage).IsNull);
            }

            RetireOwnedDamageForCallerFixture(bus, boot, APTR.FromPointer(smart.Layer));
            LayersLayerCodec.WriteDamageList(ref layerMemory,
                APTR.FromPointer(smart.Layer),
                APTR.FromPointer(damageRegion));
            LayersLayerCodec.WriteFlags(ref layerMemory,
                APTR.FromPointer(smart.Layer),
                LayersLayerCodec.ReadFlags(ref layerMemory,
                    APTR.FromPointer(smart.Layer)) | LayerFlags.Refresh);
            var damageBytes = SnapshotGraphicsRegion(bus, damageRegion);

            var begin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            var updateHead = ReadLayerClipRect(bus, smart.Layer);
            Assert.NotEqual(0u, updateHead);

            var activeBackings = new HashSet<uint>();
            var activeBackingOwners = new Dictionary<uint, uint>();
            var visibleFragments = 0;
            for (var clipRect = updateHead; clipRect != 0;
                 clipRect = ReadClipRectNext(bus, clipRect))
            {
                var activeBacking = ReadClipRectBitMap(bus, clipRect);
                var obscuringLayer = ReadClipRectObscuringLayer(bus, clipRect);
                if (obscuringLayer == 0)
                {
                    Assert.Equal(0u, activeBacking);
                    visibleFragments++;
                }
                else
                {
                    Assert.Contains(obscuringLayer, multiCover
                        ? new[] { cover.Layer, coverRightLayer }
                        : new[] { cover.Layer });
                    Assert.NotEqual(0u, activeBacking);
                    Assert.NotEqual(displayBitMap, activeBacking);
                    activeBackings.Add(activeBacking);
                    activeBackingOwners[activeBacking] = obscuringLayer;
                }
            }
            Assert.Equal(coverMinX == 8 ? 0 : disjointDamage ? 2 : 1,
                visibleFragments);
            Assert.Contains(backingBitMap, activeBackings);
            if (multiCover)
                Assert.Equal(2, activeBackings.Count);
            foreach (var backing in activeBackings)
                ClearPlanarBitMap(bus, backing);
            var backingBeforeRaster = activeBackings.ToDictionary(
                bitMap => bitMap,
                bitMap => SnapshotPlanarBitMap(bus, bitMap));

            ClearPlanarBitMap(bus, displayBitMap);
            var displayBeforeRaster = SnapshotPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, smart.RastPort, 1);
            if (multiCover)
            {
                var savedBoundsAddress = LayersClipRectCodec.BoundsAddress(
                    APTR.FromPointer(obscured)).Raw;
                var displayBeforeRejectedRaster =
                    SnapshotPlanarBitMap(bus, displayBitMap);
                var backingBeforeRejectedRaster = activeBackings.ToDictionary(
                    bitMap => bitMap,
                    bitMap => SnapshotPlanarBitMap(bus, bitMap));
                WriteRectangleBounds(bus, savedBoundsAddress,
                    savedBackingBounds.MinX,
                    savedBackingBounds.MinY,
                    savedBackingBounds.MaxX,
                    7);
                try
                {
                    var rejectedSetRast = new M68kCpuState
                    {
                        A = { [1] = smart.RastPort },
                        D = { [0] = 1 }
                    };
                    Assert.True(InvokeHostTrap(
                        bus,
                        Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                            (int)GraphicsLvo.SetRast),
                        rejectedSetRast));
                    Assert.Equal(displayBeforeRejectedRaster,
                        SnapshotPlanarBitMap(bus, displayBitMap));
                    foreach (var (bitMap, before) in backingBeforeRejectedRaster)
                        Assert.Equal(before, SnapshotPlanarBitMap(bus, bitMap));
                    Assert.Equal(updateHead, ReadLayerClipRect(bus, smart.Layer));
                }
                finally
                {
                    WriteRectangleBounds(bus, savedBoundsAddress,
                        savedBackingBounds.MinX,
                        savedBackingBounds.MinY,
                        savedBackingBounds.MaxX,
                        savedBackingBounds.MaxY);
                }
            }
            var setRast = new M68kCpuState
            {
                A = { [1] = smart.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            if (coverMinX == 8)
                Assert.Equal(displayBeforeRaster,
                    SnapshotPlanarBitMap(bus, displayBitMap));
            for (var y = 0; y < 24; y++)
                for (var x = 0; x < 32; x++)
                {
                    var expected = disjointDamage
                        ? (y is >= 8 and <= 11 &&
                                x >= (multiCover ? 16 : 12) &&
                                x < (multiCover ? 20 : 16)) ||
                            (y is >= 16 and <= 19 && x >= 9 &&
                                x <= (multiCover ? 11 : 12))
                        : y is >= 4 and <= 19 && x >= 8 && x < coverMinX;
                    Assert.True(expected ==
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y),
                        $"Display pixel ({x},{y}), multiCover={multiCover}, " +
                            $"disjointDamage={disjointDamage}");
                }
            foreach (var (bitMap, before) in backingBeforeRaster)
            {
                Assert.NotEqual(before, SnapshotPlanarBitMap(bus, bitMap));
                var backingWidth = ReadBitMapBytesPerRow(bus, bitMap) * 8;
                var backingHeight = ReadBitMapRows(bus, bitMap);
                var hiddenWidth = 24 - coverMinX;
                for (var y = 0; y < backingHeight; y++)
                    for (var x = 0; x < backingWidth; x++)
                    {
                        var expected = disjointDamage
                            ? x < 4 && y is >= 4 and <= 7 ||
                                multiCover &&
                                    activeBackingOwners[bitMap] == cover.Layer &&
                                    x == 0 && y is >= 12 and <= 15
                            : x < hiddenWidth && y < 16;
                        Assert.Equal(expected,
                            ReadPlanarBitMapPixel(bus, bitMap, x, y));
                    }
            }
            var displayAfterRaster = SnapshotPlanarBitMap(bus, displayBitMap);
            var backingAfterRaster = activeBackings.ToDictionary(
                bitMap => bitMap,
                bitMap => SnapshotPlanarBitMap(bus, bitMap));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes, SnapshotGraphicsRegion(bus, damageRegion));

            if (disjointDamage)
            {
                var partialEnd = new M68kCpuState
                {
                    A = { [0] = smart.Layer },
                    D = { [0] = 0 }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.EndUpdate),
                    partialEnd));
                updating = false;
                Assert.Equal(stableHead, ReadLayerClipRect(bus, smart.Layer));
                Assert.True(LayersLayerCodec.ReadSaveClipRects(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).IsNull);
                Assert.Equal(0, ReadLayerFlags(bus, smart.Layer) &
                    (ushort)LayerFlags.Updating);
                Assert.NotEqual(0, ReadLayerFlags(bus, smart.Layer) &
                    (ushort)LayerFlags.Refresh);
                Assert.Equal(damageRegion,
                    LayersLayerCodec.ReadDamageList(ref layerMemory,
                        APTR.FromPointer(smart.Layer)).Raw);
                Assert.Equal(damageBytes,
                    SnapshotGraphicsRegion(bus, damageRegion));

                var retryDamageBytes = damageBytes;
                if (addDamageWhilePaused)
                {
                    WriteRectangleBounds(bus, rectangle, 12, 12, 15, 15);
                    var extendDamage = new M68kCpuState
                    {
                        A = { [0] = damageRegion, [1] = rectangle }
                    };
                    Assert.True(InvokeHostTrap(
                        bus,
                        Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                            (int)GraphicsLvo.OrRectRegion),
                        extendDamage));
                    Assert.Equal(1u, extendDamage.D[0]);
                    retryDamageBytes = SnapshotGraphicsRegion(bus, damageRegion);
                    Assert.NotEqual(damageBytes, retryDamageBytes);

                    var firstRetryDamage = LayersRegionCodec.ReadFirst(
                        ref layerMemory, APTR.FromPointer(damageRegion));
                    Assert.True(firstRetryDamage.IsNotNull);
                    var secondRetryDamage = LayersRegionRectangleCodec.ReadNext(
                        ref layerMemory, firstRetryDamage);
                    Assert.True(secondRetryDamage.IsNotNull);
                    var thirdRetryDamage = LayersRegionRectangleCodec.ReadNext(
                        ref layerMemory, secondRetryDamage);
                    Assert.True(thirdRetryDamage.IsNotNull);
                    Assert.True(LayersRegionRectangleCodec.ReadNext(
                        ref layerMemory, thirdRetryDamage).IsNull);
                }

                var retryBegin = new M68kCpuState
                {
                    A = { [0] = smart.Layer }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.BeginUpdate),
                    retryBegin));
                Assert.Equal(1u, retryBegin.D[0]);
                updating = true;

                var retryBackings = new HashSet<uint>();
                for (var clipRect = ReadLayerClipRect(bus, smart.Layer);
                     clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    if (ReadClipRectObscuringLayer(bus, clipRect) != 0)
                        retryBackings.Add(ReadClipRectBitMap(bus, clipRect));
                }
                Assert.Equal(backingAfterRaster.Keys.OrderBy(value => value),
                    retryBackings.OrderBy(value => value));
                foreach (var backing in retryBackings)
                    ClearPlanarBitMap(bus, backing);
                ClearPlanarBitMap(bus, displayBitMap);

                setRast = new M68kCpuState
                {
                    A = { [1] = smart.RastPort },
                    D = { [0] = 1 }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.SetRast),
                    setRast));
                Assert.Equal(displayAfterRaster, SnapshotPlanarBitMap(bus,
                    displayBitMap));
                if (addDamageWhilePaused)
                {
                    foreach (var backing in retryBackings)
                    {
                        var backingWidth = ReadBitMapBytesPerRow(bus, backing) * 8;
                        var backingHeight = ReadBitMapRows(bus, backing);
                        for (var y = 0; y < backingHeight; y++)
                            for (var x = 0; x < backingWidth; x++)
                            {
                                var expected = x < 4 && y is >= 4 and <= 7 ||
                                    x is >= 4 and < 8 && y is >= 12 and <= 15;
                                Assert.Equal(expected,
                                    ReadPlanarBitMapPixel(bus, backing, x, y));
                            }
                    }
                }
                else
                {
                    foreach (var backing in retryBackings)
                        Assert.Equal(backingAfterRaster[backing],
                            SnapshotPlanarBitMap(bus, backing));
                }
                Assert.Equal(damageRegion,
                    LayersLayerCodec.ReadDamageList(ref layerMemory,
                        APTR.FromPointer(smart.Layer)).Raw);
                Assert.Equal(retryDamageBytes,
                    SnapshotGraphicsRegion(bus, damageRegion));
            }

            var end = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                end));
            Assert.Equal(1u, end.D[0]);
            updating = false;
            Assert.Equal(stableHead, ReadLayerClipRect(bus, smart.Layer));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = smart.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            var smartAddress = APTR.FromPointer(smart.Layer);
            LayersLayerCodec.WriteDamageList(ref layerMemory, smartAddress,
                APTR.Null);
            LayersLayerCodec.WriteFlags(ref layerMemory, smartAddress,
                LayersLayerCodec.ReadFlags(ref layerMemory, smartAddress) &
                ~LayerFlags.Refresh);
            if (damageRegion != 0)
            {
                var dispose = new M68kCpuState { A = { [0] = damageRegion } };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (rectangle != 0)
                FreeGuestMemory(bus, rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            if (coverRightLayer != 0)
                DeleteLayer(bus, libraryBase, coverRightLayer);
            DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, smart.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SmartDamageProjectionUsesNegativeLayerOriginAcrossOcclusion()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 24);
        var smart = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Smart,
            -4,
            -2,
            11,
            13);
        var cover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            7,
            8);
        var layerMemory = new LayersTestGuestMemory(bus);
        uint damageRegion = 0;
        uint rectangle = 0;
        var updating = false;

        try
        {
            var settleBegin = new M68kCpuState
            {
                A = { [0] = smart.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                settleBegin));
            Assert.Equal(1u, settleBegin.D[0]);
            updating = true;
            var settleEnd = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                settleEnd));
            Assert.Equal(1u, settleEnd.D[0]);
            updating = false;

            var stableHead = ReadLayerClipRect(bus, smart.Layer);
            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            damageRegion = newRegion.D[0];
            Assert.NotEqual(0u, damageRegion);
            rectangle = AllocateGuestMemory(
                bus,
                (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 6, 6, 12, 10);
            var includeDamage = new M68kCpuState
            {
                A = { [0] = damageRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeDamage));
            Assert.Equal(1u, includeDamage.D[0]);
            RetireOwnedDamageForCallerFixture(bus, boot, APTR.FromPointer(smart.Layer));
            LayersLayerCodec.WriteDamageList(ref layerMemory,
                APTR.FromPointer(smart.Layer), APTR.FromPointer(damageRegion));
            LayersLayerCodec.WriteFlags(ref layerMemory,
                APTR.FromPointer(smart.Layer),
                LayersLayerCodec.ReadFlags(ref layerMemory,
                    APTR.FromPointer(smart.Layer)) | LayerFlags.Refresh);
            var damageBytes = SnapshotGraphicsRegion(bus, damageRegion);

            var begin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;

            var activeBounds = new List<(short MinX, short MinY,
                short MaxX, short MaxY)>();
            uint backingBitMap = 0;
            for (var clipRect = ReadLayerClipRect(bus, smart.Layer);
                 clipRect != 0;
                 clipRect = ReadClipRectNext(bus, clipRect))
            {
                var boundsAddress = LayersClipRectCodec.BoundsAddress(
                    APTR.FromPointer(clipRect)).Raw;
                activeBounds.Add((
                    unchecked((short)bus.ReadWord(boundsAddress)),
                    unchecked((short)bus.ReadWord(boundsAddress + 2)),
                    unchecked((short)bus.ReadWord(boundsAddress + 4)),
                    unchecked((short)bus.ReadWord(boundsAddress + 6))));
                var obscuringLayer = ReadClipRectObscuringLayer(bus, clipRect);
                if (obscuringLayer == 0)
                {
                    Assert.Equal(0u, ReadClipRectBitMap(bus, clipRect));
                    continue;
                }

                Assert.Equal(cover.Layer, obscuringLayer);
                backingBitMap = ReadClipRectBitMap(bus, clipRect);
                Assert.NotEqual(0u, backingBitMap);
            }
            Assert.Equal(new[]
            {
                ((short)2, (short)4, (short)3, (short)8),
                ((short)4, (short)4, (short)7, (short)8),
                ((short)8, (short)4, (short)8, (short)8)
            }, activeBounds);
            Assert.NotEqual(0u, backingBitMap);

            ClearPlanarBitMap(bus, displayBitMap);
            ClearPlanarBitMap(bus, backingBitMap);
            var displayBeforeRaster = SnapshotPlanarBitMap(bus, displayBitMap);
            var backingBeforeRaster = SnapshotPlanarBitMap(bus, backingBitMap);
            WriteRastPortForegroundPen(bus, smart.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = smart.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));

            var actualDisplayPixels = new List<string>();
            for (var y = 0; y < 24; y++)
                for (var x = 0; x < 32; x++)
                    if (ReadPlanarBitMapPixel(bus, displayBitMap, x, y))
                        actualDisplayPixels.Add($"({x},{y})");
            for (var y = 0; y < 24; y++)
                for (var x = 0; x < 32; x++)
                {
                    var expected = y is >= 4 and <= 8 &&
                        (x is >= 2 and <= 3 || x == 8);
                    Assert.True(expected ==
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y),
                        $"Negative-origin display pixel ({x},{y}), " +
                            $"D0={setRast.D[0]}, actual=" +
                            string.Join(' ', actualDisplayPixels));
                }
            Assert.NotEqual(backingBeforeRaster,
                SnapshotPlanarBitMap(bus, backingBitMap));
            var backingWidth = ReadBitMapBytesPerRow(bus, backingBitMap) * 8;
            var backingHeight = ReadBitMapRows(bus, backingBitMap);
            for (var y = 0; y < backingHeight; y++)
                for (var x = 0; x < backingWidth; x++)
                    Assert.Equal(x < 4 && y < 5,
                        ReadPlanarBitMapPixel(bus, backingBitMap, x, y));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var end = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                end));
            Assert.Equal(1u, end.D[0]);
            updating = false;
            Assert.Equal(stableHead, ReadLayerClipRect(bus, smart.Layer));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = smart.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            var smartAddress = APTR.FromPointer(smart.Layer);
            LayersLayerCodec.WriteDamageList(ref layerMemory, smartAddress,
                APTR.Null);
            LayersLayerCodec.WriteFlags(ref layerMemory, smartAddress,
                LayersLayerCodec.ReadFlags(ref layerMemory, smartAddress) &
                ~LayerFlags.Refresh);
            if (damageRegion != 0)
            {
                var dispose = new M68kCpuState { A = { [0] = damageRegion } };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (rectangle != 0)
                FreeGuestMemory(bus, rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, smart.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SmartDamageProjectionClipsNegativeScreenCoordinatesAtDisplayEdge()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 24);
        var smart = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Smart,
            -4,
            -2,
            11,
            13);
        var cover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            1,
            2);
        var layerMemory = new LayersTestGuestMemory(bus);
        uint damageRegion = 0;
        uint rectangle = 0;
        var updating = false;

        try
        {
            var settleBegin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                settleBegin));
            Assert.Equal(1u, settleBegin.D[0]);
            updating = true;
            var settleEnd = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                settleEnd));
            Assert.Equal(1u, settleEnd.D[0]);
            updating = false;

            var stableHead = ReadLayerClipRect(bus, smart.Layer);
            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            damageRegion = newRegion.D[0];
            Assert.NotEqual(0u, damageRegion);
            rectangle = AllocateGuestMemory(
                bus,
                (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 0, 0, 6, 5);
            var includeDamage = new M68kCpuState
            {
                A = { [0] = damageRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeDamage));
            Assert.Equal(1u, includeDamage.D[0]);
            RetireOwnedDamageForCallerFixture(bus, boot, APTR.FromPointer(smart.Layer));
            LayersLayerCodec.WriteDamageList(ref layerMemory,
                APTR.FromPointer(smart.Layer), APTR.FromPointer(damageRegion));
            LayersLayerCodec.WriteFlags(ref layerMemory,
                APTR.FromPointer(smart.Layer),
                LayersLayerCodec.ReadFlags(ref layerMemory,
                    APTR.FromPointer(smart.Layer)) | LayerFlags.Refresh);
            var damageBytes = SnapshotGraphicsRegion(bus, damageRegion);

            var begin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;

            uint backingBitMap = 0;
            for (var clipRect = ReadLayerClipRect(bus, smart.Layer);
                 clipRect != 0;
                 clipRect = ReadClipRectNext(bus, clipRect))
            {
                var obscuringLayer = ReadClipRectObscuringLayer(bus, clipRect);
                if (obscuringLayer == 0)
                    continue;

                Assert.Equal(cover.Layer, obscuringLayer);
                backingBitMap = ReadClipRectBitMap(bus, clipRect);
                Assert.NotEqual(0u, backingBitMap);
            }
            Assert.NotEqual(0u, backingBitMap);

            ClearPlanarBitMap(bus, displayBitMap);
            ClearPlanarBitMap(bus, backingBitMap);
            WriteRastPortForegroundPen(bus, smart.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = smart.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);

            for (var y = 0; y < 24; y++)
                for (var x = 0; x < 32; x++)
                {
                    var expected = y is >= 0 and <= 2
                        ? x == 2
                        : y == 3 && x is >= 0 and <= 2;
                    Assert.Equal(expected,
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
                }
            var backingWidth = ReadBitMapBytesPerRow(bus, backingBitMap) * 8;
            var backingHeight = ReadBitMapRows(bus, backingBitMap);
            for (var y = 0; y < backingHeight; y++)
                for (var x = 0; x < backingWidth; x++)
                    Assert.Equal(x < 2 && y < 3,
                        ReadPlanarBitMapPixel(bus, backingBitMap, x, y));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var end = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                end));
            Assert.Equal(1u, end.D[0]);
            updating = false;
            Assert.Equal(stableHead, ReadLayerClipRect(bus, smart.Layer));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = smart.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            var smartAddress = APTR.FromPointer(smart.Layer);
            LayersLayerCodec.WriteDamageList(ref layerMemory, smartAddress,
                APTR.Null);
            LayersLayerCodec.WriteFlags(ref layerMemory, smartAddress,
                LayersLayerCodec.ReadFlags(ref layerMemory, smartAddress) &
                ~LayerFlags.Refresh);
            if (damageRegion != 0)
            {
                var dispose = new M68kCpuState { A = { [0] = damageRegion } };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (rectangle != 0)
                FreeGuestMemory(bus, rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, smart.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SmartDamageProjectionClipsPositiveScreenCoordinatesAtDisplayEdge()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 24);
        var smart = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Smart,
            28,
            20,
            43,
            35);
        var cover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            29,
            21,
            31,
            23);
        var layerMemory = new LayersTestGuestMemory(bus);
        uint damageRegion = 0;
        uint rectangle = 0;
        var updating = false;

        try
        {
            var settleBegin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                settleBegin));
            Assert.Equal(1u, settleBegin.D[0]);
            updating = true;
            var settleEnd = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                settleEnd));
            Assert.Equal(1u, settleEnd.D[0]);
            updating = false;

            var stableHead = ReadLayerClipRect(bus, smart.Layer);
            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            damageRegion = newRegion.D[0];
            Assert.NotEqual(0u, damageRegion);
            rectangle = AllocateGuestMemory(
                bus,
                (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 0, 0, 10, 10);
            var includeDamage = new M68kCpuState
            {
                A = { [0] = damageRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeDamage));
            Assert.Equal(1u, includeDamage.D[0]);
            RetireOwnedDamageForCallerFixture(bus, boot, APTR.FromPointer(smart.Layer));
            LayersLayerCodec.WriteDamageList(ref layerMemory,
                APTR.FromPointer(smart.Layer), APTR.FromPointer(damageRegion));
            LayersLayerCodec.WriteFlags(ref layerMemory,
                APTR.FromPointer(smart.Layer),
                LayersLayerCodec.ReadFlags(ref layerMemory,
                    APTR.FromPointer(smart.Layer)) | LayerFlags.Refresh);
            var damageBytes = SnapshotGraphicsRegion(bus, damageRegion);

            var begin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;

            uint backingBitMap = 0;
            for (var clipRect = ReadLayerClipRect(bus, smart.Layer);
                 clipRect != 0;
                 clipRect = ReadClipRectNext(bus, clipRect))
            {
                var obscuringLayer = ReadClipRectObscuringLayer(bus, clipRect);
                if (obscuringLayer == 0)
                    continue;

                Assert.Equal(cover.Layer, obscuringLayer);
                backingBitMap = ReadClipRectBitMap(bus, clipRect);
                Assert.NotEqual(0u, backingBitMap);
            }
            Assert.NotEqual(0u, backingBitMap);

            ClearPlanarBitMap(bus, displayBitMap);
            ClearPlanarBitMap(bus, backingBitMap);
            WriteRastPortForegroundPen(bus, smart.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = smart.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);

            for (var y = 0; y < 24; y++)
                for (var x = 0; x < 32; x++)
                {
                    var expected = y == 20 && x is >= 28 and <= 31 ||
                        x == 28 && y is >= 21 and <= 23;
                    Assert.Equal(expected,
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
                }
            var backingWidth = ReadBitMapBytesPerRow(bus, backingBitMap) * 8;
            var backingHeight = ReadBitMapRows(bus, backingBitMap);
            for (var y = 0; y < backingHeight; y++)
                for (var x = 0; x < backingWidth; x++)
                    Assert.Equal(x < 3 && y < 3,
                        ReadPlanarBitMapPixel(bus, backingBitMap, x, y));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var end = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                end));
            Assert.Equal(1u, end.D[0]);
            updating = false;
            Assert.Equal(stableHead, ReadLayerClipRect(bus, smart.Layer));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = smart.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            var smartAddress = APTR.FromPointer(smart.Layer);
            LayersLayerCodec.WriteDamageList(ref layerMemory, smartAddress,
                APTR.Null);
            LayersLayerCodec.WriteFlags(ref layerMemory, smartAddress,
                LayersLayerCodec.ReadFlags(ref layerMemory, smartAddress) &
                ~LayerFlags.Refresh);
            if (damageRegion != 0)
            {
                var dispose = new M68kCpuState { A = { [0] = damageRegion } };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (rectangle != 0)
                FreeGuestMemory(bus, rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, smart.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SmartDamageProjectionUsesScrolledLogicalOriginAcrossOcclusion()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 24);
        var smart = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Smart,
            8,
            6,
            23,
            21);
        var cover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            11,
            8,
            13,
            10);
        var layerMemory = new LayersTestGuestMemory(bus);
        uint damageRegion = 0;
        uint rectangle = 0;
        var updating = false;

        try
        {
            var scroll = new M68kCpuState
            {
                A = { [1] = smart.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                scroll));
            Assert.Equal((short)2, ReadLayerScrollX(bus, smart.Layer));
            Assert.Equal((short)1, ReadLayerScrollY(bus, smart.Layer));

            var settleBegin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                settleBegin));
            Assert.Equal(1u, settleBegin.D[0]);
            updating = true;
            var settleEnd = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                settleEnd));
            Assert.Equal(1u, settleEnd.D[0]);
            updating = false;

            var stableHead = ReadLayerClipRect(bus, smart.Layer);
            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            damageRegion = newRegion.D[0];
            Assert.NotEqual(0u, damageRegion);
            rectangle = AllocateGuestMemory(
                bus,
                (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 2, 1, 9, 6);
            var includeDamage = new M68kCpuState
            {
                A = { [0] = damageRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeDamage));
            Assert.Equal(1u, includeDamage.D[0]);
            RetireOwnedDamageForCallerFixture(bus, boot, APTR.FromPointer(smart.Layer));
            LayersLayerCodec.WriteDamageList(ref layerMemory,
                APTR.FromPointer(smart.Layer), APTR.FromPointer(damageRegion));
            LayersLayerCodec.WriteFlags(ref layerMemory,
                APTR.FromPointer(smart.Layer),
                LayersLayerCodec.ReadFlags(ref layerMemory,
                    APTR.FromPointer(smart.Layer)) | LayerFlags.Refresh);
            var damageBytes = SnapshotGraphicsRegion(bus, damageRegion);

            var begin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;

            var initialBounds = new List<(short MinX, short MinY,
                short MaxX, short MaxY)>();
            var initialProjection = CaptureDamageProjection(initialBounds);
            uint backingBitMap = 0;
            foreach (var fragment in initialProjection)
            {
                if (fragment.ObscuringLayer == 0)
                    continue;

                Assert.Equal(cover.Layer, fragment.ObscuringLayer);
                backingBitMap = fragment.BitMap;
                Assert.NotEqual(0u, backingBitMap);
            }
            Assert.NotEqual(0u, backingBitMap);

            var pause = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                pause));
            Assert.Equal(0u, pause.D[0]);
            updating = false;
            Assert.Equal(stableHead, ReadLayerClipRect(bus, smart.Layer));
            var flagsWhilePaused = ReadLayerFlags(bus, smart.Layer);
            Assert.Equal((ushort)LayerFlags.Refresh,
                (ushort)(flagsWhilePaused &
                    ((ushort)LayerFlags.Refresh | (ushort)LayerFlags.Updating)));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var rescroll = new M68kCpuState
            {
                A = { [1] = smart.Layer },
                D = { [0] = 1, [1] = 2 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                rescroll));
            Assert.Equal((short)3, ReadLayerScrollX(bus, smart.Layer));
            Assert.Equal((short)3, ReadLayerScrollY(bus, smart.Layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var retryBegin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                retryBegin));
            Assert.Equal(1u, retryBegin.D[0]);
            updating = true;
            var activeBounds = new List<(short MinX, short MinY,
                short MaxX, short MaxY)>();
            var retryProjection = CaptureDamageProjection(activeBounds);
            Assert.Equal(initialProjection, retryProjection);
            Assert.Equal(backingBitMap,
                retryProjection.First(fragment =>
                    fragment.ObscuringLayer == cover.Layer).BitMap);

            ClearPlanarBitMap(bus, displayBitMap);
            ClearPlanarBitMap(bus, backingBitMap);
            WriteRastPortForegroundPen(bus, smart.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = smart.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);

            var actualDisplayPixels = new List<string>();
            for (var y = 0; y < 24; y++)
                for (var x = 0; x < 32; x++)
                    if (ReadPlanarBitMapPixel(bus, displayBitMap, x, y))
                        actualDisplayPixels.Add($"({x},{y})");
            for (var y = 0; y < 24; y++)
                for (var x = 0; x < 32; x++)
                {
                    var withinDamage = x is >= 10 and <= 17 &&
                        y is >= 7 and <= 12;
                    var covered = x is >= 11 and <= 13 &&
                        y is >= 8 and <= 10;
                    var expected = withinDamage && !covered;
                    Assert.True(expected == ReadPlanarBitMapPixel(
                            bus,
                            displayBitMap,
                            x,
                            y),
                        $"Scrolled display pixel ({x},{y}), " +
                            $"clips={string.Join(' ', activeBounds)}, " +
                            $"actual={string.Join(' ', actualDisplayPixels)}");
                }
            var backingWidth = ReadBitMapBytesPerRow(bus, backingBitMap) * 8;
            var backingHeight = ReadBitMapRows(bus, backingBitMap);
            for (var y = 0; y < backingHeight; y++)
                for (var x = 0; x < backingWidth; x++)
                    Assert.Equal(x < 3 && y < 3,
                        ReadPlanarBitMapPixel(bus, backingBitMap, x, y));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var end = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                end));
            Assert.Equal(1u, end.D[0]);
            updating = false;
            Assert.Equal(stableHead, ReadLayerClipRect(bus, smart.Layer));

            List<(short MinX, short MinY, short MaxX, short MaxY,
                uint ObscuringLayer, uint BitMap)> CaptureDamageProjection(
                    List<(short MinX, short MinY, short MaxX, short MaxY)> bounds)
            {
                var projection = new List<(short MinX, short MinY,
                    short MaxX, short MaxY, uint ObscuringLayer, uint BitMap)>();
                for (var clipRect = ReadLayerClipRect(bus, smart.Layer);
                     clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var clipBounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var minX = unchecked((short)bus.ReadWord(clipBounds));
                    var minY = unchecked((short)bus.ReadWord(clipBounds + 2));
                    var maxX = unchecked((short)bus.ReadWord(clipBounds + 4));
                    var maxY = unchecked((short)bus.ReadWord(clipBounds + 6));
                    var obscuringLayer = ReadClipRectObscuringLayer(
                        bus,
                        clipRect);
                    var bitMap = ReadClipRectBitMap(bus, clipRect);
                    if (obscuringLayer != 0)
                    {
                        Assert.Equal(cover.Layer, obscuringLayer);
                        Assert.NotEqual(0u, bitMap);
                    }
                    bounds.Add((minX, minY, maxX, maxY));
                    projection.Add((
                        minX,
                        minY,
                        maxX,
                        maxY,
                        obscuringLayer,
                        bitMap));
                }

                return projection;
            }
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = smart.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            var smartAddress = APTR.FromPointer(smart.Layer);
            LayersLayerCodec.WriteDamageList(ref layerMemory, smartAddress,
                APTR.Null);
            LayersLayerCodec.WriteFlags(ref layerMemory, smartAddress,
                LayersLayerCodec.ReadFlags(ref layerMemory, smartAddress) &
                ~LayerFlags.Refresh);
            if (damageRegion != 0)
            {
                var dispose = new M68kCpuState { A = { [0] = damageRegion } };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (rectangle != 0)
                FreeGuestMemory(bus, rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, smart.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SuperBitMapLayerRestoresUncoveredPixelsAcrossDepthChanges()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var superBitMap = AllocatePlanarBitMap(bus, 48, 32);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            0,
            0,
            31,
            19);
        var leftCover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            7,
            7);
        var rightCover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            8,
            4,
            11,
            7);
        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            Assert.Equal(
                superBitMap,
                LayersLayerCodec.ReadSuperBitMap(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);

            uint FindBackingBitmap(uint obscuringLayer)
            {
                for (var clipRect = ReadLayerClipRect(bus, bottom.Layer);
                    clipRect != 0;
                    clipRect = ReadClipRectNext(bus, clipRect))
                {
                    if (ReadClipRectObscuringLayer(bus, clipRect) == obscuringLayer)
                        return ReadClipRectBitMap(bus, clipRect);
                }
                Assert.Fail($"No backing ClipRect for layer {obscuringLayer:X8}.");
                return 0;
            }

            void SendBehind(uint layer)
            {
                var behind = new M68kCpuState { A = { [1] = layer } };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.BehindLayer),
                    behind));
                Assert.Equal(1u, behind.D[0]);
                WaitForBlitterIdle();
            }

            void WaitForBlitterIdle()
            {
                for (var instruction = 0;
                    instruction < 100_000 && bus.Blitter.Busy;
                    instruction++)
                    machine.Cpu.ExecuteInstruction();
                Assert.False(bus.Blitter.Busy);
            }

            uint WhichLayerAt(int x, int y)
            {
                var which = new M68kCpuState
                {
                    A = { [0] = layerInfo },
                    D = { [0] = unchecked((uint)x), [1] = unchecked((uint)y) }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.WhichLayer),
                    which));
                return which.D[0];
            }

            void AssertNoRefreshDamage()
            {
                var damage = LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer));
                Assert.True(damage.IsNull ||
                    LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNull);
                Assert.Equal(0, ReadLayerFlags(bus, bottom.Layer) &
                    (ushort)LayerFlags.Refresh);
            }

            byte[] CaptureOffscreenSuperPixels()
            {
                var pixels = new List<byte>();
                for (var y = 0; y < 32; y++)
                    for (var x = 0; x < 48; x++)
                        if (x >= 32 || y >= 20)
                            pixels.Add(ReadPlanarBitMapPixel(
                                bus, superBitMap, x, y) ? (byte)1 : (byte)0);
                return pixels.ToArray();
            }

            void AssertSuperViewport(
                Func<int, int, bool> expectedPixel)
            {
                for (var y = 0; y < 20; y++)
                    for (var x = 0; x < 32; x++)
                        Assert.True(
                            expectedPixel(x, y) ==
                                ReadPlanarBitMapPixel(bus, superBitMap, x, y),
                            $"SuperBitMap viewport pixel ({x},{y})");
            }

            // Seed the SuperBitMap layer through the normal multi-surface
            // raster path: visible pixels go to the display, hidden pixels to
            // their compact backing maps, and the off-viewport complement to
            // the caller-owned SuperBitMap.
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var fill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 47, [3] = 31 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);
            WaitForBlitterIdle();
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 0, 0));

            var backingBeforeMutation = FindBackingBitmap(rightCover.Layer);
            Assert.NotEqual(0u, backingBeforeMutation);
            Assert.True(ReadPlanarBitMapPixel(
                bus, backingBeforeMutation, 8, 1));
            var backingBeforeHiddenWrite = SnapshotPlanarBitMap(
                bus, backingBeforeMutation);
            Assert.Contains(backingBeforeHiddenWrite, value => value != 0);
            var offscreenSuperBeforeMutation = CaptureOffscreenSuperPixels();

            var readHiddenPixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 9, [1] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ReadPixel),
                readHiddenPixel));
            Assert.Equal(1u, readHiddenPixel.D[0]);

            // Write a distinct value under only the right cover. The display
            // is occluded, so this must target the compact backing bitmap.
            WriteRastPortForegroundPen(bus, bottom.RastPort, 0);
            var fillHidden = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 8, [1] = 4, [2] = 11, [3] = 7 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fillHidden));
            Assert.Equal(0u, fillHidden.D[0]);
            WaitForBlitterIdle();
            var backingAfterHiddenWrite = SnapshotPlanarBitMap(
                bus, backingBeforeMutation);
            Assert.NotEqual(backingBeforeHiddenWrite, backingAfterHiddenWrite);
            Assert.False(ReadPlanarBitMapPixel(
                bus, backingBeforeMutation, 8, 1));
            Assert.Equal(
                offscreenSuperBeforeMutation,
                CaptureOffscreenSuperPixels());
            readHiddenPixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 9, [1] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ReadPixel),
                readHiddenPixel));
            Assert.Equal(0u, readHiddenPixel.D[0]);
            var readLeftHiddenPixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 5, [1] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ReadPixel),
                readLeftHiddenPixel));
            Assert.Equal(1u, readLeftHiddenPixel.D[0]);

            var firstExposure = new HashSet<(int X, int Y)>();
            var secondExposure = new HashSet<(int X, int Y)>();
            for (var y = 4; y <= 7; y++)
            {
                for (var x = 4; x <= 7; x++)
                    firstExposure.Add((x, y));
                for (var x = 8; x <= 11; x++)
                    secondExposure.Add((x, y));
            }
            // A SuperBitMap layer does not publish simple-layer refresh
            // damage: Layers copies its preserved source into the exposed
            // display partition during each depth transaction.
            SendBehind(leftCover.Layer);
            AssertNoRefreshDamage();
            Assert.Equal(bottom.Layer, WhichLayerAt(5, 5));
            Assert.Equal(rightCover.Layer, WhichLayerAt(9, 5));
            Assert.True(
                ReadPlanarBitMapPixel(bus, superBitMap, 4, 4),
                "The newly exposed SuperBitMap source pixel must be retained before partition copy-back.");
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    if (!secondExposure.Contains((x, y)))
                        Assert.True(
                            ReadPlanarBitMapPixel(bus, displayBitMap, x, y),
                            $"Visible display pixel ({x},{y}) should retain pen 1.");
            var readStillHiddenPixel = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 9, [1] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ReadPixel),
                readStillHiddenPixel));
            Assert.Equal(0u, readStillHiddenPixel.D[0]);
            Assert.Equal(
                offscreenSuperBeforeMutation,
                CaptureOffscreenSuperPixels());

            // This partial redraw changes the newly visible left block while
            // the right block remains hidden in its own backing store.
            var fillFirstExposure = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 4, [1] = 4, [2] = 7, [3] = 7 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fillFirstExposure));
            Assert.Equal(0u, fillFirstExposure.D[0]);
            WaitForBlitterIdle();
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    if (!secondExposure.Contains((x, y)))
                        Assert.Equal(
                            !firstExposure.Contains((x, y)),
                            ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.Equal(
                offscreenSuperBeforeMutation,
                CaptureOffscreenSuperPixels());

            // The later depth change must preserve that raster update and
            // reveal the right block from the SuperBitMap-backed content.
            SendBehind(rightCover.Layer);
            AssertNoRefreshDamage();
            Assert.Equal(bottom.Layer, WhichLayerAt(9, 5));
            var combinedExposure = new HashSet<(int X, int Y)>(firstExposure);
            combinedExposure.UnionWith(secondExposure);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(
                        !combinedExposure.Contains((x, y)),
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            AssertSuperViewport((x, y) => !combinedExposure.Contains((x, y)));
            Assert.Equal(
                offscreenSuperBeforeMutation,
                CaptureOffscreenSuperPixels());
            Assert.Equal(
                superBitMap,
                LayersLayerCodec.ReadSuperBitMap(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
        }
        finally
        {
            DeleteLayer(bus, libraryBase, rightCover.Layer);
            DeleteLayer(bus, libraryBase, leftCover.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SuperBitMapUncoverPreservesPixelsAcrossBackingWordBoundary()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 16);
        var superBitMap = AllocatePlanarBitMap(bus, 48, 24);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            0,
            0,
            31,
            15);
        var cover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            13,
            5,
            18,
            8);
        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);

            uint FindBackingBitmap()
            {
                for (var clipRect = ReadLayerClipRect(bus, bottom.Layer);
                    clipRect != 0;
                    clipRect = ReadClipRectNext(bus, clipRect))
                {
                    if (ReadClipRectObscuringLayer(bus, clipRect) == cover.Layer)
                        return ReadClipRectBitMap(bus, clipRect);
                }
                Assert.Fail("The SuperBitMap layer must own a backing for the cover.");
                return 0;
            }

            void WaitForBlitterIdle()
            {
                for (var instruction = 0;
                    instruction < 100_000 && bus.Blitter.Busy;
                    instruction++)
                    machine.Cpu.ExecuteInstruction();
                Assert.False(bus.Blitter.Busy);
            }

            uint ReadLayerPixel(int x, int y)
            {
                var state = new M68kCpuState
                {
                    A = { [1] = bottom.RastPort },
                    D = { [0] = unchecked((uint)x), [1] = unchecked((uint)y) }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.ReadPixel),
                    state));
                return state.D[0];
            }

            byte[] CaptureOffscreenSuperPixels()
            {
                var pixels = new List<byte>();
                for (var y = 0; y < 24; y++)
                    for (var x = 0; x < 48; x++)
                        if (x >= 32 || y >= 16)
                            pixels.Add(ReadPlanarBitMapPixel(
                                bus, superBitMap, x, y) ? (byte)1 : (byte)0);
                return pixels.ToArray();
            }

            void AssertNoSuperRefreshDamage()
            {
                var damage = LayersLayerCodec.ReadDamageList(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer));
                Assert.True(damage.IsNull ||
                    LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNull);
                Assert.Equal(0, ReadLayerFlags(bus, bottom.Layer) &
                    (ushort)LayerFlags.Refresh);
            }

            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var fill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 47, [3] = 23 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);
            WaitForBlitterIdle();

            var backing = FindBackingBitmap();
            Assert.NotEqual(0u, backing);
            // The compact map includes the prefix up to absolute x=13; the
            // hidden block straddles the 16-pixel boundary at x=16.
            Assert.True(ReadPlanarBitMapPixel(bus, backing, 13, 0));
            Assert.True(ReadPlanarBitMapPixel(bus, backing, 16, 1));
            var offscreenBeforeMutation = CaptureOffscreenSuperPixels();

            WriteRastPortForegroundPen(bus, bottom.RastPort, 0);
            var clearHidden = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 13, [1] = 5, [2] = 18, [3] = 8 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                clearHidden));
            Assert.Equal(0u, clearHidden.D[0]);
            WaitForBlitterIdle();
            Assert.False(ReadPlanarBitMapPixel(bus, backing, 13, 0));
            Assert.False(ReadPlanarBitMapPixel(bus, backing, 16, 1));
            Assert.Equal(0u, ReadLayerPixel(16, 6));
            Assert.Equal(offscreenBeforeMutation, CaptureOffscreenSuperPixels());

            var behind = new M68kCpuState { A = { [1] = cover.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BehindLayer),
                behind));
            Assert.Equal(1u, behind.D[0]);
            WaitForBlitterIdle();
            AssertNoSuperRefreshDamage();
            var which = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 16, [1] = 6 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.WhichLayer),
                which));
            Assert.Equal(bottom.Layer, which.D[0]);

            for (var y = 0; y < 16; y++)
                for (var x = 0; x < 32; x++)
                {
                    var expected = x < 13 || x > 18 || y < 5 || y > 8;
                    Assert.Equal(expected,
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
                    Assert.Equal(expected,
                        ReadPlanarBitMapPixel(bus, superBitMap, x, y));
                }
            Assert.Equal(offscreenBeforeMutation, CaptureOffscreenSuperPixels());
            Assert.Equal(
                superBitMap,
                LayersLayerCodec.ReadSuperBitMap(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
        }
        finally
        {
            DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SuperBitMapUncoverMapsScrolledNonzeroOriginToScreenEdge()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var superBitMap = AllocatePlanarBitMap(bus, 48, 32);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            4,
            2,
            31,
            17);
        LayerSurface cover = default;
        try
        {
            var scroll = new M68kCpuState
            {
                A = { [1] = bottom.Layer },
                D = { [0] = 4, [1] = 2 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                scroll));
            Assert.Equal(4u, scroll.D[0]);
            Assert.Equal(2u, scroll.D[1]);
            Assert.Equal((short)4, ReadLayerScrollX(bus, bottom.Layer));
            Assert.Equal((short)2, ReadLayerScrollY(bus, bottom.Layer));

            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var fill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 47, [3] = 31 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);
            for (var instruction = 0;
                instruction < 100_000 && bus.Blitter.Busy;
                instruction++)
                machine.Cpu.ExecuteInstruction();
            Assert.False(bus.Blitter.Busy);

            cover = CreateLayerOnBitMaps(
                bus,
                libraryBase,
                layerInfo,
                displayBitMap,
                0,
                LayerCreationFlags.Simple,
                10,
                6,
                15,
                7);
            var layerMemory = new LayersTestGuestMemory(bus);
            uint FindBackingBitmap()
            {
                for (var clipRect = ReadLayerClipRect(bus, bottom.Layer);
                    clipRect != 0;
                    clipRect = ReadClipRectNext(bus, clipRect))
                    if (ReadClipRectObscuringLayer(bus, clipRect) == cover.Layer)
                        return ReadClipRectBitMap(bus, clipRect);
                Assert.Fail("The scrolled SuperBitMap layer must own cover backing.");
                return 0;
            }

            var backing = FindBackingBitmap();
            Assert.NotEqual(0u, backing);
            Assert.True(ReadPlanarBitMapPixel(bus, backing, 10, 0));
            WriteRastPortForegroundPen(bus, bottom.RastPort, 0);
            var clearHidden = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 10, [1] = 4, [2] = 15, [3] = 7 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                clearHidden));
            Assert.Equal(0u, clearHidden.D[0]);
            for (var instruction = 0;
                instruction < 100_000 && bus.Blitter.Busy;
                instruction++)
                machine.Cpu.ExecuteInstruction();
            Assert.False(bus.Blitter.Busy);
            Assert.False(ReadPlanarBitMapPixel(bus, backing, 10, 0));
            Assert.False(ReadPlanarBitMapPixel(bus, backing, 13, 1));
            var readHidden = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 12, [1] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ReadPixel),
                readHidden));
            Assert.Equal(0u, readHidden.D[0]);

            var behind = new M68kCpuState { A = { [1] = cover.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BehindLayer),
                behind));
            Assert.Equal(1u, behind.D[0]);
            for (var instruction = 0;
                instruction < 100_000 && bus.Blitter.Busy;
                instruction++)
                machine.Cpu.ExecuteInstruction();
            Assert.False(bus.Blitter.Busy);

            var which = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 12, [1] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.WhichLayer),
                which));
            Assert.Equal(bottom.Layer, which.D[0]);
            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNull ||
                LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNull);
            Assert.Equal(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);

            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                {
                    var insideLayer = x is >= 4 and <= 31 && y is >= 2 and <= 17;
                    var insideClearedBlock = x is >= 10 and <= 15 &&
                        y is >= 4 and <= 7;
                    var expected = insideLayer && !insideClearedBlock;
                    var actual = ReadPlanarBitMapPixel(
                        bus,
                        displayBitMap,
                        x,
                        y);
                    Assert.True(
                        expected == actual,
                        $"Scrolled display pixel ({x},{y}) expected {expected} actual {actual}");
                }
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 48; x++)
                {
                    var insideClearedBlock = x is >= 10 and <= 15 &&
                        y is >= 4 and <= 7;
                    Assert.True(
                        !insideClearedBlock ==
                            ReadPlanarBitMapPixel(bus, superBitMap, x, y),
                        $"Scrolled SuperBitMap pixel ({x},{y})");
                }
            Assert.Equal(
                superBitMap,
                LayersLayerCodec.ReadSuperBitMap(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
        }
        finally
        {
            if (cover.Layer != 0)
                DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SuperBitMapUncoverPreservesCallerPixelsBeyondDisplayEdge()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var superBitMap = AllocatePlanarBitMap(bus, 48, 32);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            2,
            2,
            33,
            17);
        var cover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            29,
            6,
            31,
            9);
        var layerMemory = new LayersTestGuestMemory(bus);

        void WaitForBlitterIdle()
        {
            for (var instruction = 0;
                instruction < 100_000 && bus.Blitter.Busy;
                instruction++)
                machine.Cpu.ExecuteInstruction();
            Assert.False(bus.Blitter.Busy);
        }

        void SetSuperPixel(int x, int y, bool value)
        {
            var bytesPerRow = ReadBitMapBytesPerRow(bus, superBitMap);
            var plane = ReadBitMapPlane(bus, superBitMap, 0);
            var address = plane + checked((uint)(y * bytesPerRow + (x >> 3)));
            var mask = (byte)(0x80 >> (x & 7));
            var current = bus.ReadByte(address);
            bus.WriteByte(
                address,
                value ? (byte)(current | mask) : (byte)(current & ~mask),
                0);
        }

        uint FindCoverClipRect()
        {
            for (var clipRect = ReadLayerClipRect(bus, bottom.Layer);
                clipRect != 0;
                clipRect = ReadClipRectNext(bus, clipRect))
                if (ReadClipRectObscuringLayer(bus, clipRect) == cover.Layer)
                    return clipRect;
            Assert.Fail("The SuperBitMap layer must own the visible cover ClipRect.");
            return 0;
        }

        try
        {
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var fill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 47, [3] = 31 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);
            WaitForBlitterIdle();

            var coverClipRect = FindCoverClipRect();
            var backing = ReadClipRectBitMap(bus, coverClipRect);
            Assert.NotEqual(0u, backing);
            var backingBounds = LayersClipRectCodec.ReadBounds(
                ref layerMemory,
                APTR.FromPointer(coverClipRect));
            WriteRastPortForegroundPen(bus, bottom.RastPort, 0);
            var clearHidden = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                // Raster coordinates are layer-local: with a (2,2) layer
                // origin, (27,4)..(29,7) addresses screen (29,6)..(31,9).
                D = { [0] = 27, [1] = 4, [2] = 29, [3] = 7 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                clearHidden));
            Assert.Equal(0u, clearHidden.D[0]);
            WaitForBlitterIdle();
            for (var y = 6; y <= 9; y++)
                for (var x = 29; x <= 31; x++)
                {
                    var backingX = PortableLayers.LayersBitmapCore.BackingX(
                        backingBounds.MinX) + x - backingBounds.MinX;
                    var backingY = y - backingBounds.MinY;
                    var actual = ReadPlanarBitMapPixel(
                        bus, backing, backingX, backingY);
                    Assert.True(!actual,
                        $"Hidden backing pixel ({x},{y}) mapped to ({backingX},{backingY}) in [{backingBounds.MinX},{backingBounds.MinY}..{backingBounds.MaxX},{backingBounds.MaxY}] remained set");
                }
            for (var y = 6; y <= 9; y++)
                for (var x = 29; x <= 31; x++)
                {
                    var superX = x - 2;
                    var superY = y - 2;
                    Assert.False(ReadPlanarBitMapPixel(
                        bus, superBitMap, superX, superY));
                }
            // The layer includes x=32..33, but the physical display ends at
            // x=31. These pixels are outside the cover partition. Seed them
            // after the raster write to verify uncover preserves them.
            for (var y = 4; y <= 7; y++)
                for (var x = 30; x <= 31; x++)
                {
                    SetSuperPixel(x, y, true);
                    Assert.True(ReadPlanarBitMapPixel(
                        bus, superBitMap, x, y));
                }

            var behind = new M68kCpuState { A = { [1] = cover.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BehindLayer),
                behind));
            Assert.Equal(1u, behind.D[0]);
            WaitForBlitterIdle();

            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNull ||
                LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNull);
            Assert.Equal(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);

            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                {
                    var insideLayer = x is >= 2 and <= 31 &&
                        y is >= 2 and <= 17;
                    var insideClearedVisible = x is >= 29 and <= 31 &&
                        y is >= 6 and <= 9;
                    var expected = insideLayer && !insideClearedVisible;
                    var actual = ReadPlanarBitMapPixel(
                        bus, displayBitMap, x, y);
                    Assert.True(
                        expected == actual,
                        $"Offscreen uncover display pixel ({x},{y}) expected {expected} actual {actual}");
                }

            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 48; x++)
                {
                    var insideClearedBacking = x is >= 27 and <= 29 &&
                        y is >= 4 and <= 7;
                    var unseededOffscreen = x is >= 30 and <= 31 &&
                        y is >= 0 and <= 15 && y is not (>= 4 and <= 7);
                    var expected = !insideClearedBacking &&
                        !unseededOffscreen;
                    var actual = ReadPlanarBitMapPixel(
                        bus, superBitMap, x, y);
                    Assert.True(
                        expected == actual,
                        $"Offscreen uncover SuperBitMap pixel ({x},{y}) expected {expected} actual {actual}");
                }
            Assert.Equal(
                superBitMap,
                LayersLayerCodec.ReadSuperBitMap(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
        }
        finally
        {
            DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SuperBitMapUncoverMapsScrollOffsetIndependentOfLayerOrigin()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var superBitMap = AllocatePlanarBitMap(bus, 48, 32);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            4,
            2,
            31,
            17);
        LayerSurface cover = default;
        try
        {
            var scroll = new M68kCpuState
            {
                A = { [1] = bottom.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                scroll));
            Assert.Equal(2u, scroll.D[0]);
            Assert.Equal(1u, scroll.D[1]);
            Assert.Equal((short)2, ReadLayerScrollX(bus, bottom.Layer));
            Assert.Equal((short)1, ReadLayerScrollY(bus, bottom.Layer));

            void WaitForBlitterIdle()
            {
                for (var instruction = 0;
                    instruction < 100_000 && bus.Blitter.Busy;
                    instruction++)
                    machine.Cpu.ExecuteInstruction();
                Assert.False(bus.Blitter.Busy);
            }

            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var fill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 47, [3] = 31 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);
            WaitForBlitterIdle();

            cover = CreateLayerOnBitMaps(
                bus,
                libraryBase,
                layerInfo,
                displayBitMap,
                0,
                LayerCreationFlags.Simple,
                12,
                6,
                17,
                9);
            var layerMemory = new LayersTestGuestMemory(bus);
            uint FindCoverBacking()
            {
                for (var clipRect = ReadLayerClipRect(bus, bottom.Layer);
                    clipRect != 0;
                    clipRect = ReadClipRectNext(bus, clipRect))
                    if (ReadClipRectObscuringLayer(bus, clipRect) == cover.Layer)
                        return ReadClipRectBitMap(bus, clipRect);
                Assert.Fail("The scrolled SuperBitMap layer must own cover backing.");
                return 0;
            }

            var backing = FindCoverBacking();
            Assert.NotEqual(0u, backing);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 0);
            var clearHidden = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                // With bounds origin (4,2) and scroll (2,1), local (10,5)
                // maps to screen (12,6) and SuperBitMap (10,5).
                D = { [0] = 10, [1] = 5, [2] = 15, [3] = 8 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                clearHidden));
            Assert.Equal(0u, clearHidden.D[0]);
            WaitForBlitterIdle();
            Assert.False(ReadPlanarBitMapPixel(bus, backing, 12, 0));
            Assert.False(ReadPlanarBitMapPixel(bus, backing, 15, 1));

            var readHidden = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 10, [1] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ReadPixel),
                readHidden));
            Assert.Equal(0u, readHidden.D[0]);

            var behind = new M68kCpuState { A = { [1] = cover.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BehindLayer),
                behind));
            Assert.Equal(1u, behind.D[0]);
            WaitForBlitterIdle();
            var which = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 12, [1] = 6 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.WhichLayer),
                which));
            Assert.Equal(bottom.Layer, which.D[0]);
            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNull ||
                LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNull);
            Assert.Equal(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);

            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                {
                    var insideLayer = x is >= 4 and <= 31 &&
                        y is >= 2 and <= 17;
                    var insideClearedScreen = x is >= 12 and <= 17 &&
                        y is >= 6 and <= 9;
                    var expected = insideLayer && !insideClearedScreen;
                    var actual = ReadPlanarBitMapPixel(
                        bus, displayBitMap, x, y);
                    Assert.True(
                        expected == actual,
                        $"Independent-scroll display pixel ({x},{y}) expected {expected} actual {actual}");
                }
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 48; x++)
                {
                    var insideClearedSuper = x is >= 10 and <= 15 &&
                        y is >= 5 and <= 8;
                    Assert.True(
                        !insideClearedSuper ==
                            ReadPlanarBitMapPixel(bus, superBitMap, x, y),
                        $"Independent-scroll SuperBitMap pixel ({x},{y})");
                }
            Assert.Equal(
                superBitMap,
                LayersLayerCodec.ReadSuperBitMap(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
        }
        finally
        {
            if (cover.Layer != 0)
                DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SuperBitMapUncoverMapsNegativeOriginAtUpperLeftScreenEdge()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var superBitMap = AllocatePlanarBitMap(bus, 48, 32);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            -2,
            -1,
            29,
            17);
        LayerSurface cover = default;
        try
        {
            var scroll = new M68kCpuState
            {
                A = { [1] = bottom.Layer },
                D = { [0] = 1, [1] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                scroll));
            Assert.Equal(1u, scroll.D[0]);
            Assert.Equal(0u, scroll.D[1]);
            Assert.Equal((short)1, ReadLayerScrollX(bus, bottom.Layer));
            Assert.Equal((short)0, ReadLayerScrollY(bus, bottom.Layer));

            void WaitForBlitterIdle()
            {
                for (var instruction = 0;
                    instruction < 100_000 && bus.Blitter.Busy;
                    instruction++)
                    machine.Cpu.ExecuteInstruction();
                Assert.False(bus.Blitter.Busy);
            }

            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var fill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 47, [3] = 31 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);
            WaitForBlitterIdle();

            cover = CreateLayerOnBitMaps(
                bus,
                libraryBase,
                layerInfo,
                displayBitMap,
                0,
                LayerCreationFlags.Simple,
                0,
                0,
                3,
                3);
            var layerMemory = new LayersTestGuestMemory(bus);
            uint FindCoverBacking()
            {
                for (var clipRect = ReadLayerClipRect(bus, bottom.Layer);
                    clipRect != 0;
                    clipRect = ReadClipRectNext(bus, clipRect))
                    if (ReadClipRectObscuringLayer(bus, clipRect) == cover.Layer)
                        return ReadClipRectBitMap(bus, clipRect);
                Assert.Fail("The negative-origin SuperBitMap layer must own cover backing.");
                return 0;
            }

            var backing = FindCoverBacking();
            Assert.NotEqual(0u, backing);
            Assert.True(ReadPlanarBitMapPixel(bus, backing, 0, 0));
            WriteRastPortForegroundPen(bus, bottom.RastPort, 0);
            var clearHidden = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                // Bounds origin (-2,-1) and scroll (1,0) map local (3,1)
                // to screen (0,0), then to SuperBitMap (3,1).
                D = { [0] = 3, [1] = 1, [2] = 6, [3] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                clearHidden));
            Assert.Equal(0u, clearHidden.D[0]);
            WaitForBlitterIdle();
            Assert.False(ReadPlanarBitMapPixel(bus, backing, 0, 0));
            Assert.False(ReadPlanarBitMapPixel(bus, backing, 3, 3));

            var readHidden = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 3, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ReadPixel),
                readHidden));
            Assert.Equal(0u, readHidden.D[0]);

            var behind = new M68kCpuState { A = { [1] = cover.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BehindLayer),
                behind));
            Assert.Equal(1u, behind.D[0]);
            WaitForBlitterIdle();
            var which = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 0, [1] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.WhichLayer),
                which));
            Assert.Equal(bottom.Layer, which.D[0]);
            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNull ||
                LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNull);
            Assert.Equal(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);

            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                {
                    var insideLayer = x is >= 0 and <= 29 &&
                        y is >= 0 and <= 17;
                    var insideClearedScreen = x is >= 0 and <= 3 &&
                        y is >= 0 and <= 3;
                    var expected = insideLayer && !insideClearedScreen;
                    var actual = ReadPlanarBitMapPixel(
                        bus, displayBitMap, x, y);
                    Assert.True(
                        expected == actual,
                        $"Negative-origin display pixel ({x},{y}) expected {expected} actual {actual}");
                }
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 48; x++)
                {
                    var insideClearedSuper = x is >= 3 and <= 6 &&
                        y is >= 1 and <= 4;
                    var insideViewport = x is >= 1 and <= 32 &&
                        y is >= 0 and <= 18;
                    var clippedOffscreenViewport = insideViewport &&
                        (x <= 2 || y == 0);
                    var expected = !insideClearedSuper &&
                        !clippedOffscreenViewport;
                    Assert.True(
                        expected == ReadPlanarBitMapPixel(
                            bus, superBitMap, x, y),
                        $"Negative-origin SuperBitMap pixel ({x},{y})");
                }
            Assert.Equal(
                superBitMap,
                LayersLayerCodec.ReadSuperBitMap(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
        }
        finally
        {
            if (cover.Layer != 0)
                DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SuperBitMapMoveLayerAcrossOriginSynchronizesClippedPartitions()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var superBitMap = AllocatePlanarBitMap(bus, 48, 32);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            -2,
            -1,
            29,
            17);
        LayerSurface cover = default;
        try
        {
            var scroll = new M68kCpuState
            {
                A = { [1] = bottom.Layer },
                D = { [0] = 1, [1] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                scroll));
            Assert.Equal((short)1, ReadLayerScrollX(bus, bottom.Layer));

            void WaitForBlitterIdle()
            {
                for (var instruction = 0;
                    instruction < 100_000 && bus.Blitter.Busy;
                    instruction++)
                    machine.Cpu.ExecuteInstruction();
                Assert.False(bus.Blitter.Busy);
            }

            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var fill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 47, [3] = 31 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);
            WaitForBlitterIdle();

            cover = CreateLayerOnBitMaps(
                bus,
                libraryBase,
                layerInfo,
                displayBitMap,
                0,
                LayerCreationFlags.Simple,
                -2,
                -1,
                1,
                2);
            var layerMemory = new LayersTestGuestMemory(bus);
            uint FindCoverBacking()
            {
                for (var clipRect = ReadLayerClipRect(bus, bottom.Layer);
                    clipRect != 0;
                    clipRect = ReadClipRectNext(bus, clipRect))
                    if (ReadClipRectObscuringLayer(bus, clipRect) == cover.Layer)
                        return ReadClipRectBitMap(bus, clipRect);
                Assert.Fail("The clipped SuperBitMap partition needs cover backing.");
                return 0;
            }

            var backing = FindCoverBacking();
            Assert.NotEqual(0u, backing);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 0);
            var clearHidden = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                // The negative layer origin and x scroll map layer-local
                // (1,0)..(4,3) onto the old cover at screen (-2,-1)..(1,2).
                D = { [0] = 1, [1] = 0, [2] = 4, [3] = 3 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                clearHidden));
            Assert.Equal(0u, clearHidden.D[0]);
            WaitForBlitterIdle();
            Assert.False(ReadPlanarBitMapPixel(bus, backing, 16, 1));
            Assert.False(ReadPlanarBitMapPixel(bus, backing, 17, 3));

            var move = new M68kCpuState
            {
                A = { [1] = cover.Layer },
                D = { [0] = 4, [1] = 2 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveLayer),
                move));
            Assert.Equal(1u, move.D[0]);
            WaitForBlitterIdle();

            var oldPoint = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 0, [1] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.WhichLayer),
                oldPoint));
            Assert.Equal(bottom.Layer, oldPoint.D[0]);
            var newPoint = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.WhichLayer),
                newPoint));
            Assert.Equal(cover.Layer, newPoint.D[0]);

            var readExposed = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 3, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.ReadPixel),
                readExposed));
            Assert.Equal(0u, readExposed.D[0]);

            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNull ||
                LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNull);
            Assert.Equal(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);

            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                {
                    // A Simple Refresh layer has no backing store. The
                    // application is responsible for drawing its newly
                    // occupied area, so validate preserved pixels outside it.
                    var movedSimpleArea = x is >= 2 and <= 5 &&
                        y is >= 1 and <= 4;
                    if (movedSimpleArea)
                        continue;
                    var insideLayer = x is >= 0 and <= 29 &&
                        y is >= 0 and <= 17;
                    var newlyExposedClear = x is >= 0 and <= 1 &&
                        y is >= 0 and <= 2;
                    var expected = insideLayer && !newlyExposedClear;
                    Assert.True(
                        expected == ReadPlanarBitMapPixel(
                            bus, displayBitMap, x, y),
                        $"Moved-cover display pixel ({x},{y})");
                }
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 48; x++)
                {
                    var clearedSuper = x is >= 1 and <= 4 &&
                        y is >= 0 and <= 3;
                    var insideViewport = x is >= 1 and <= 32 &&
                        y is >= 0 and <= 18;
                    var clippedOffscreenViewport = insideViewport &&
                        (x <= 2 || y == 0);
                    var expected = !clearedSuper &&
                        !clippedOffscreenViewport;
                    Assert.True(
                        expected == ReadPlanarBitMapPixel(
                            bus, superBitMap, x, y),
                        $"Moved-cover SuperBitMap pixel ({x},{y})");
                }
            Assert.Equal(
                superBitMap,
                LayersLayerCodec.ReadSuperBitMap(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
        }
        finally
        {
            if (cover.Layer != 0)
                DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SuperBitMapSizeLayerAcrossOriginSynchronizesNewHiddenStrip()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var superBitMap = AllocatePlanarBitMap(bus, 48, 32);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            -2,
            -1,
            29,
            17);
        var cover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            1,
            1);

        void WaitForBlitterIdle()
        {
            for (var instruction = 0;
                instruction < 100_000 && bus.Blitter.Busy;
                instruction++)
                machine.Cpu.ExecuteInstruction();
            Assert.False(bus.Blitter.Busy);
        }

        try
        {
            var scroll = new M68kCpuState
            {
                A = { [1] = bottom.Layer },
                D = { [0] = 1, [1] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                scroll));
            Assert.Equal((short)1, ReadLayerScrollX(bus, bottom.Layer));

            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var fill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 47, [3] = 31 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);
            WaitForBlitterIdle();

            // Layer-local (5,2)..(7,4) maps to screen (2,1)..(4,3)
            // and the same SuperBitMap coordinates under this origin/scroll.
            WriteRastPortForegroundPen(bus, bottom.RastPort, 0);
            var clearPattern = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 5, [1] = 2, [2] = 7, [3] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                clearPattern));
            Assert.Equal(0u, clearPattern.D[0]);
            WaitForBlitterIdle();
            Assert.False(ReadPlanarBitMapPixel(bus, superBitMap, 7, 4));

            var layerMemory = new LayersTestGuestMemory(bus);
            var resize = new M68kCpuState
            {
                A = { [1] = cover.Layer },
                D = { [0] = 3, [1] = 2 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.SizeLayer),
                resize));
            Assert.Equal(1u, resize.D[0]);
            WaitForBlitterIdle();

            (uint BitMap, int MinX, int MinY) FindNewStripBacking(
                int x,
                int y)
            {
                for (var clipRect = ReadLayerClipRect(bus, bottom.Layer);
                    clipRect != 0;
                    clipRect = ReadClipRectNext(bus, clipRect))
                {
                    if (ReadClipRectObscuringLayer(bus, clipRect) != cover.Layer)
                        continue;
                    var bounds = LayersClipRectCodec.ReadBounds(
                        ref layerMemory,
                        APTR.FromPointer(clipRect));
                    if (x < bounds.MinX || x > bounds.MaxX ||
                        y < bounds.MinY || y > bounds.MaxY)
                        continue;
                    return (
                        ReadClipRectBitMap(bus, clipRect),
                        bounds.MinX,
                        bounds.MinY);
                }
                Assert.Fail("The resized SuperBitMap partition must own the new strip.");
                return default;
            }

            var newStripBacking = FindNewStripBacking(4, 3);
            Assert.NotEqual(0u, newStripBacking.BitMap);
            var backingX = PortableLayers.LayersBitmapCore.BackingX(
                newStripBacking.MinX) + 4 - newStripBacking.MinX;
            var backingY = 3 - newStripBacking.MinY;
            Assert.False(ReadPlanarBitMapPixel(
                bus,
                newStripBacking.BitMap,
                backingX,
                backingY));
            Assert.False(ReadPlanarBitMapPixel(bus, superBitMap, 7, 4));

            var expandedPoint = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 4, [1] = 3 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.WhichLayer),
                expandedPoint));
            Assert.Equal(cover.Layer, expandedPoint.D[0]);

            var superDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(superDamage.IsNull ||
                LayersRegionCodec.ReadFirst(ref layerMemory, superDamage).IsNull);
            Assert.Equal(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);

            var behind = new M68kCpuState { A = { [1] = cover.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BehindLayer),
                behind));
            Assert.Equal(1u, behind.D[0]);
            WaitForBlitterIdle();

            var restoredPoint = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 4, [1] = 3 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.WhichLayer),
                restoredPoint));
            Assert.Equal(bottom.Layer, restoredPoint.D[0]);
            superDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(superDamage.IsNull ||
                LayersRegionCodec.ReadFirst(ref layerMemory, superDamage).IsNull);
            Assert.Equal(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);

            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                {
                    var insideLayer = x is >= 0 and <= 29 &&
                        y is >= 0 and <= 17;
                    var clearedScreen = x is >= 2 and <= 4 &&
                        y is >= 1 and <= 3;
                    var expected = insideLayer && !clearedScreen;
                    Assert.True(
                        expected == ReadPlanarBitMapPixel(
                            bus, displayBitMap, x, y),
                        $"Resized-cover display pixel ({x},{y})");
                }
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 48; x++)
                {
                    var clearedSuper = x is >= 5 and <= 7 &&
                        y is >= 2 and <= 4;
                    var insideViewport = x is >= 1 and <= 32 &&
                        y is >= 0 and <= 18;
                    var clippedOffscreenViewport = insideViewport &&
                        (x <= 2 || y == 0);
                    var expected = !clearedSuper &&
                        !clippedOffscreenViewport;
                    Assert.True(
                        expected == ReadPlanarBitMapPixel(
                            bus, superBitMap, x, y),
                        $"Resized-cover SuperBitMap pixel ({x},{y})");
                }
            Assert.Equal(
                superBitMap,
                LayersLayerCodec.ReadSuperBitMap(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
        }
        finally
        {
            DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SuperBitMapMoveSizeLayerAcrossOriginSynchronizesPartitions()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var superBitMap = AllocatePlanarBitMap(bus, 48, 32);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            -2,
            -1,
            29,
            17);
        LayerSurface cover = default;

        void WaitForBlitterIdle()
        {
            for (var instruction = 0;
                instruction < 100_000 && bus.Blitter.Busy;
                instruction++)
                machine.Cpu.ExecuteInstruction();
            Assert.False(bus.Blitter.Busy);
        }

        try
        {
            var scroll = new M68kCpuState
            {
                A = { [1] = bottom.Layer },
                D = { [0] = 1, [1] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                scroll));
            Assert.Equal((short)1, ReadLayerScrollX(bus, bottom.Layer));

            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var fill = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 0, [1] = 0, [2] = 47, [3] = 31 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);
            WaitForBlitterIdle();

            cover = CreateLayerOnBitMaps(
                bus,
                libraryBase,
                layerInfo,
                displayBitMap,
                0,
                LayerCreationFlags.Simple,
                -2,
                -1,
                1,
                2);
            // Give both the clipped old rectangle and the positive new
            // rectangle distinct lower-layer content before the combined
            // move/resize transaction.
            WriteRastPortForegroundPen(bus, bottom.RastPort, 0);
            var clearOld = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1, [1] = 0, [2] = 4, [3] = 3 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                clearOld));
            Assert.Equal(0u, clearOld.D[0]);
            WaitForBlitterIdle();

            Assert.True(ReadPlanarBitMapPixel(bus, superBitMap, 9, 5));
            Assert.True(ReadPlanarBitMapPixel(bus, superBitMap, 37, 5));
            var clearNewPattern = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                // Local (7,3)..(9,5) maps to screen (4,2)..(6,4) and
                // the display. The existing SuperBitMap copy is not synced.
                D = { [0] = 7, [1] = 3, [2] = 9, [3] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                clearNewPattern));
            Assert.Equal(0u, clearNewPattern.D[0]);
            WaitForBlitterIdle();
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 6, 4));
            // The on-display area is not mirrored into the caller's bitmap
            // until SyncSBitMap; drawing there must leave its stored copy alone.
            Assert.True(ReadPlanarBitMapPixel(bus, superBitMap, 9, 5));

            var clearOffscreenPattern = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                // This lies beyond the right display edge and is owned by the
                // SuperBitMap complement rather than the display bitmap.
                D = { [0] = 35, [1] = 3, [2] = 37, [3] = 5 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                clearOffscreenPattern));
            Assert.Equal(0u, clearOffscreenPattern.D[0]);
            WaitForBlitterIdle();
            Assert.False(ReadPlanarBitMapPixel(bus, superBitMap, 37, 5));
            Assert.True(ReadPlanarBitMapPixel(bus, superBitMap, 38, 5));

            var layerMemory = new LayersTestGuestMemory(bus);
            var moveSize = new M68kCpuState
            {
                A = { [0] = cover.Layer },
                D =
                {
                    [0] = 4,
                    [1] = 2,
                    [2] = 2,
                    [3] = 1
                }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveSizeLayer),
                moveSize));
            Assert.Equal(1u, moveSize.D[0]);
            WaitForBlitterIdle();

            (uint BitMap, int MinX, int MinY) FindCoverBacking(int x, int y)
            {
                for (var clipRect = ReadLayerClipRect(bus, bottom.Layer);
                    clipRect != 0;
                    clipRect = ReadClipRectNext(bus, clipRect))
                {
                    if (ReadClipRectObscuringLayer(bus, clipRect) != cover.Layer)
                        continue;
                    var bounds = LayersClipRectCodec.ReadBounds(
                        ref layerMemory,
                        APTR.FromPointer(clipRect));
                    if (x < bounds.MinX || x > bounds.MaxX ||
                        y < bounds.MinY || y > bounds.MaxY)
                        continue;
                    return (
                        ReadClipRectBitMap(bus, clipRect),
                        bounds.MinX,
                        bounds.MinY);
                }
                Assert.Fail("MoveSizeLayer must publish backing for its new covered strip.");
                return default;
            }

            var newPatternBacking = FindCoverBacking(6, 4);
            Assert.NotEqual(0u, newPatternBacking.BitMap);
            var backingX = PortableLayers.LayersBitmapCore.BackingX(
                newPatternBacking.MinX) + 6 - newPatternBacking.MinX;
            var backingY = 4 - newPatternBacking.MinY;
            Assert.False(ReadPlanarBitMapPixel(
                bus,
                newPatternBacking.BitMap,
                backingX,
                backingY));
            Assert.False(ReadPlanarBitMapPixel(bus, superBitMap, 9, 5));

            var oldPoint = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 0, [1] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.WhichLayer),
                oldPoint));
            Assert.Equal(bottom.Layer, oldPoint.D[0]);
            var coveredPoint = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 6, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.WhichLayer),
                coveredPoint));
            Assert.Equal(cover.Layer, coveredPoint.D[0]);

            var superDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(superDamage.IsNull ||
                LayersRegionCodec.ReadFirst(ref layerMemory, superDamage).IsNull);
            Assert.Equal(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);

            var behind = new M68kCpuState { A = { [1] = cover.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BehindLayer),
                behind));
            Assert.Equal(1u, behind.D[0]);
            WaitForBlitterIdle();

            var restoredPoint = new M68kCpuState
            {
                A = { [0] = layerInfo },
                D = { [0] = 6, [1] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.WhichLayer),
                restoredPoint));
            Assert.Equal(bottom.Layer, restoredPoint.D[0]);
            superDamage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(superDamage.IsNull ||
                LayersRegionCodec.ReadFirst(ref layerMemory, superDamage).IsNull);
            Assert.Equal(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);

            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                {
                    var insideLayer = x is >= 0 and <= 29 &&
                        y is >= 0 and <= 17;
                    var clearedScreen =
                        (x is >= 0 and <= 1 && y is >= 0 and <= 2) ||
                        (x is >= 4 and <= 6 && y is >= 2 and <= 4);
                    var expected = insideLayer && !clearedScreen;
                    Assert.True(
                        expected == ReadPlanarBitMapPixel(
                            bus, displayBitMap, x, y),
                        $"MoveSizeLayer display pixel ({x},{y})");
                }
            for (var y = 0; y < 32; y++)
                for (var x = 0; x < 48; x++)
                {
                    var clearedOldSuper = x is >= 1 and <= 4 &&
                        y is >= 0 and <= 3;
                    var clearedNewPattern = x is >= 7 and <= 9 &&
                        y is >= 3 and <= 5;
                    var clearedOffscreenPattern = x is >= 35 and <= 37 &&
                        y is >= 3 and <= 5;
                    var insideViewport = x is >= 1 and <= 32 &&
                        y is >= 0 and <= 18;
                    var clippedOffscreenViewport = insideViewport &&
                        (x <= 2 || y == 0);
                    var expected = !clearedOldSuper &&
                        !clearedNewPattern &&
                        !clearedOffscreenPattern &&
                        !clippedOffscreenViewport;
                    Assert.True(
                        expected == ReadPlanarBitMapPixel(
                            bus, superBitMap, x, y),
                        $"MoveSizeLayer SuperBitMap pixel ({x},{y})");
                }
            Assert.Equal(
                superBitMap,
                LayersLayerCodec.ReadSuperBitMap(
                    ref layerMemory,
                    APTR.FromPointer(bottom.Layer)).Raw);
        }
        finally
        {
            if (cover.Layer != 0)
                DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SuperBitMapDamageRasterStaysWithinPublicDamageProjection()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var superBitMap = AllocatePlanarBitMap(bus, 48, 32);
        var smart = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            0,
            0,
            31,
            19);
        var cover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            8,
            8);
        var layerMemory = new LayersTestGuestMemory(bus);
        uint damageRegion = 0;
        uint rectangle = 0;
        var updating = false;

        try
        {
            var settleBegin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                settleBegin));
            Assert.Equal(1u, settleBegin.D[0]);
            updating = true;
            var settleEnd = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                settleEnd));
            Assert.Equal(1u, settleEnd.D[0]);
            updating = false;

            var stableHead = ReadLayerClipRect(bus, smart.Layer);
            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            damageRegion = newRegion.D[0];
            Assert.NotEqual(0u, damageRegion);
            rectangle = AllocateGuestMemory(
                bus,
                (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 2, 2, 6, 6);
            var includeDamage = new M68kCpuState
            {
                A = { [0] = damageRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeDamage));
            Assert.Equal(1u, includeDamage.D[0]);
            RetireOwnedDamageForCallerFixture(bus, boot, APTR.FromPointer(smart.Layer));
            LayersLayerCodec.WriteDamageList(ref layerMemory,
                APTR.FromPointer(smart.Layer), APTR.FromPointer(damageRegion));
            LayersLayerCodec.WriteFlags(ref layerMemory,
                APTR.FromPointer(smart.Layer),
                LayersLayerCodec.ReadFlags(ref layerMemory,
                    APTR.FromPointer(smart.Layer)) | LayerFlags.Refresh);
            var damageBytes = SnapshotGraphicsRegion(bus, damageRegion);

            var begin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            var activeHead = ReadLayerClipRect(bus, smart.Layer);
            Assert.NotEqual(0u, activeHead);
            Assert.NotEqual(0u, ReadLayerSuperClipRect(bus, smart.Layer));

            var initialProjection = CapturePublicProjection();
            var backingBitMap = initialProjection.First(fragment =>
                fragment.ObscuringLayer == cover.Layer).BitMap;
            Assert.NotEqual(0u, backingBitMap);

            var pause = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                pause));
            Assert.Equal(0u, pause.D[0]);
            updating = false;
            Assert.Equal(stableHead, ReadLayerClipRect(bus, smart.Layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var scroll = new M68kCpuState
            {
                A = { [1] = smart.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                scroll));
            Assert.Equal((short)2, ReadLayerScrollX(bus, smart.Layer));
            Assert.Equal((short)1, ReadLayerScrollY(bus, smart.Layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var retryBegin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                retryBegin));
            Assert.Equal(1u, retryBegin.D[0]);
            updating = true;
            Assert.NotEqual(0u, ReadLayerSuperClipRect(bus, smart.Layer));
            var retryProjection = CapturePublicProjection();
            Assert.Equal(initialProjection, retryProjection);
            Assert.Equal(backingBitMap,
                retryProjection.First(fragment =>
                    fragment.ObscuringLayer == cover.Layer).BitMap);

            ClearPlanarBitMap(bus, displayBitMap);
            ClearPlanarBitMap(bus, superBitMap);
            ClearPlanarBitMap(bus, backingBitMap);
            var fill = new M68kCpuState
            {
                A = { [1] = smart.RastPort },
                D = { [0] = 1, [1] = 0, [2] = 47, [3] = 31 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);

            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                {
                    var withinDamage = x is >= 2 and <= 6 &&
                        y is >= 2 and <= 6;
                    var covered = x is >= 4 and <= 8 &&
                        y is >= 4 and <= 8;
                    Assert.Equal(withinDamage && !covered,
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
                }
            Assert.All(
                SnapshotPlanarBitMap(bus, superBitMap),
                value => Assert.Equal((byte)0, value));
            var backingWidth = ReadBitMapBytesPerRow(bus, backingBitMap) * 8;
            var backingHeight = ReadBitMapRows(bus, backingBitMap);
            for (var y = 0; y < backingHeight; y++)
                for (var x = 0; x < backingWidth; x++)
                    Assert.Equal(x < 3 && y < 3,
                        ReadPlanarBitMapPixel(bus, backingBitMap, x, y));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var end = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                end));
            Assert.Equal(1u, end.D[0]);
            updating = false;
            Assert.Equal(stableHead, ReadLayerClipRect(bus, smart.Layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            List<(short MinX, short MinY, short MaxX, short MaxY,
                uint ObscuringLayer, uint BitMap)> CapturePublicProjection()
            {
                var projection = new List<(short MinX, short MinY,
                    short MaxX, short MaxY, uint ObscuringLayer, uint BitMap)>();
                for (var clipRect = ReadLayerClipRect(bus, smart.Layer);
                     clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var clipBounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    var obscuringLayer = ReadClipRectObscuringLayer(
                        bus,
                        clipRect);
                    var bitMap = ReadClipRectBitMap(bus, clipRect);
                    projection.Add((
                        unchecked((short)bus.ReadWord(clipBounds)),
                        unchecked((short)bus.ReadWord(clipBounds + 2)),
                        unchecked((short)bus.ReadWord(clipBounds + 4)),
                        unchecked((short)bus.ReadWord(clipBounds + 6)),
                        obscuringLayer,
                        bitMap));
                }

                return projection;
            }
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = smart.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            var smartAddress = APTR.FromPointer(smart.Layer);
            LayersLayerCodec.WriteDamageList(ref layerMemory, smartAddress,
                APTR.Null);
            LayersLayerCodec.WriteFlags(ref layerMemory, smartAddress,
                LayersLayerCodec.ReadFlags(ref layerMemory, smartAddress) &
                ~LayerFlags.Refresh);
            if (damageRegion != 0)
            {
                var dispose = new M68kCpuState { A = { [0] = damageRegion } };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (rectangle != 0)
                FreeGuestMemory(bus, rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, smart.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SuperBitMapDamageProjectionComposesCallerClipAtNegativeDisplayEdgeAfterScroll()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
