                scroll));
            Assert.Equal((short)2, ReadLayerScrollX(bus, smart.Layer));
            Assert.Equal((short)1, ReadLayerScrollY(bus, smart.Layer));

            var stableHead = ReadLayerClipRect(bus, smart.Layer);
            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            damageRegion = newRegion.D[0];
            Assert.NotEqual(0u, damageRegion);
            rectangle = AllocateGuestMemory(
                bus,
                (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 2, 2, 6, 6);
            var includeDamage = new M68kCpuState
            {
                A = { [0] = damageRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeDamage));
            Assert.Equal(1u, includeDamage.D[0]);
            RetireOwnedDamageForCallerFixture(bus, boot, APTR.FromPointer(smart.Layer));
            LayersLayerCodec.WriteDamageList(ref layerMemory,
                APTR.FromPointer(smart.Layer), APTR.FromPointer(damageRegion));
            LayersLayerCodec.WriteFlags(ref layerMemory,
                APTR.FromPointer(smart.Layer),
                LayersLayerCodec.ReadFlags(ref layerMemory,
                    APTR.FromPointer(smart.Layer)) | LayerFlags.Refresh);
            var damageBytes = SnapshotGraphicsRegion(bus, damageRegion);

            var begin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;

            var activeProjection = new List<(short MinX, short MinY,
                short MaxX, short MaxY, uint ObscuringLayer, uint BitMap)>();
            for (var clipRect = ReadLayerClipRect(bus, smart.Layer);
                 clipRect != 0;
                 clipRect = ReadClipRectNext(bus, clipRect))
            {
                var clipBounds = LayersClipRectCodec.BoundsAddress(
                    APTR.FromPointer(clipRect)).Raw;
                activeProjection.Add((
                    unchecked((short)bus.ReadWord(clipBounds)),
                    unchecked((short)bus.ReadWord(clipBounds + 2)),
                    unchecked((short)bus.ReadWord(clipBounds + 4)),
                    unchecked((short)bus.ReadWord(clipBounds + 6)),
                    ReadClipRectObscuringLayer(bus, clipRect),
                    ReadClipRectBitMap(bus, clipRect)));
            }
            Assert.Equal(new[]
            {
                ((short)-2, (short)0, (short)2, (short)0, 0u, 0u),
                ((short)-2, (short)1, (short)-1, (short)3, 0u, 0u),
                ((short)0, (short)1, (short)1, (short)3, cover.Layer,
                    activeProjection.First(fragment =>
                        fragment.ObscuringLayer == cover.Layer).BitMap),
                ((short)2, (short)1, (short)2, (short)3, 0u, 0u),
                ((short)-2, (short)4, (short)2, (short)4, 0u, 0u)
            }, activeProjection);
            var backingBitMap = activeProjection.First(fragment =>
                fragment.ObscuringLayer == cover.Layer).BitMap;
            Assert.NotEqual(0u, backingBitMap);

            ClearPlanarBitMap(bus, displayBitMap);
            ClearPlanarBitMap(bus, superBitMap);
            ClearPlanarBitMap(bus, backingBitMap);
            var fill = new M68kCpuState
            {
                A = { [1] = smart.RastPort },
                D = { [0] = 1, [1] = 0, [2] = 47, [3] = 31 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);

            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                {
                    var withinDamage = x is >= 0 and <= 2 &&
                        y is >= 0 and <= 4;
                    var covered = x is >= 0 and <= 1 &&
                        y is >= 1 and <= 3;
                    Assert.Equal(withinDamage && !covered,
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
                }
            Assert.All(
                SnapshotPlanarBitMap(bus, superBitMap),
                value => Assert.Equal((byte)0, value));
            var backingWidth = ReadBitMapBytesPerRow(bus, backingBitMap) * 8;
            var backingHeight = ReadBitMapRows(bus, backingBitMap);
            for (var y = 0; y < backingHeight; y++)
                for (var x = 0; x < backingWidth; x++)
                    Assert.Equal(x < 2 && y < 3,
                        ReadPlanarBitMapPixel(bus, backingBitMap, x, y));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var end = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                end));
            Assert.Equal(1u, end.D[0]);
            updating = false;
            Assert.Equal(stableHead, ReadLayerClipRect(bus, smart.Layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            // This logical clip maps to [-1,-1..2,3] after the current layer
            // bounds and scroll, intersecting damage at both physical edges.
            var newClipRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newClipRegion));
            callerClipRegion = newClipRegion.D[0];
            Assert.NotEqual(0u, callerClipRegion);
            WriteRectangleBounds(bus, rectangle, 5, 2, 8, 6);
            var includeClip = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeClip));
            Assert.Equal(1u, includeClip.D[0]);
            var installClip = new M68kCpuState
            {
                A = { [0] = smart.Layer, [1] = callerClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installClip));
            Assert.Equal(0u, installClip.D[0]);
            callerClipInstalled = true;
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, smart.Layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var beginWithCallerClip = new M68kCpuState
            {
                A = { [0] = smart.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                beginWithCallerClip));
            Assert.Equal(1u, beginWithCallerClip.D[0]);
            updating = true;

            activeProjection.Clear();
            for (var clipRect = ReadLayerClipRect(bus, smart.Layer);
                 clipRect != 0;
                 clipRect = ReadClipRectNext(bus, clipRect))
            {
                var clipBounds = LayersClipRectCodec.BoundsAddress(
                    APTR.FromPointer(clipRect)).Raw;
                activeProjection.Add((
                    unchecked((short)bus.ReadWord(clipBounds)),
                    unchecked((short)bus.ReadWord(clipBounds + 2)),
                    unchecked((short)bus.ReadWord(clipBounds + 4)),
                    unchecked((short)bus.ReadWord(clipBounds + 6)),
                    ReadClipRectObscuringLayer(bus, clipRect),
                    ReadClipRectBitMap(bus, clipRect)));
            }
            backingBitMap = activeProjection.First(fragment =>
                fragment.ObscuringLayer == cover.Layer).BitMap;
            Assert.NotEqual(0u, backingBitMap);
            Assert.Equal(new[]
            {
                ((short)-1, (short)0, (short)2, (short)0, 0u, 0u),
                ((short)-1, (short)1, (short)-1, (short)3, 0u, 0u),
                ((short)0, (short)1, (short)1, (short)3, cover.Layer,
                    backingBitMap),
                ((short)2, (short)1, (short)2, (short)3, 0u, 0u)
            }, activeProjection);

            ClearPlanarBitMap(bus, displayBitMap);
            ClearPlanarBitMap(bus, superBitMap);
            ClearPlanarBitMap(bus, backingBitMap);
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.True(((y == 0 && x <= 2) ||
                        (x == 2 && y is >= 1 and <= 3)) ==
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y),
                        $"Unexpected display pixel at ({x},{y}).");
            Assert.All(
                SnapshotPlanarBitMap(bus, superBitMap),
                value => Assert.Equal((byte)0, value));
            backingWidth = ReadBitMapBytesPerRow(bus, backingBitMap) * 8;
            backingHeight = ReadBitMapRows(bus, backingBitMap);
            for (var y = 0; y < backingHeight; y++)
                for (var x = 0; x < backingWidth; x++)
                    Assert.Equal(x < 2 && y < 3,
                        ReadPlanarBitMapPixel(bus, backingBitMap, x, y));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var endWithCallerClip = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                endWithCallerClip));
            Assert.Equal(1u, endWithCallerClip.D[0]);
            updating = false;
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, smart.Layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = smart.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            var smartAddress = APTR.FromPointer(smart.Layer);
            LayersLayerCodec.WriteDamageList(ref layerMemory, smartAddress,
                APTR.Null);
            LayersLayerCodec.WriteFlags(ref layerMemory, smartAddress,
                LayersLayerCodec.ReadFlags(ref layerMemory, smartAddress) &
                ~LayerFlags.Refresh);
            if (callerClipInstalled)
            {
                var uninstall = new M68kCpuState
                {
                    A = { [0] = smart.Layer }
                };
                InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    uninstall);
            }
            if (damageRegion != 0)
            {
                var dispose = new M68kCpuState { A = { [0] = damageRegion } };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (callerClipRegion != 0)
            {
                var dispose = new M68kCpuState
                {
                    A = { [0] = callerClipRegion }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (rectangle != 0)
                FreeGuestMemory(bus, rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, smart.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SuperBitMapDamageProjectionComposesCallerClipAtPositiveDisplayEdgeAfterScroll()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var superBitMap = AllocatePlanarBitMap(bus, 48, 32);
        var smart = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            28,
            14,
            59,
            33);
        var cover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            30,
            17,
            31,
            18);
        var layerMemory = new LayersTestGuestMemory(bus);
        uint damageRegion = 0;
        uint callerClipRegion = 0;
        uint replacementClipRegion = 0;
        uint rectangle = 0;
        var updating = false;
        var callerClipInstalled = false;

        try
        {
            var settleBegin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                settleBegin));
            Assert.Equal(1u, settleBegin.D[0]);
            updating = true;
            var settleEnd = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                settleEnd));
            Assert.Equal(1u, settleEnd.D[0]);
            updating = false;

            var scroll = new M68kCpuState
            {
                A = { [1] = smart.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                scroll));
            Assert.Equal((short)2, ReadLayerScrollX(bus, smart.Layer));
            Assert.Equal((short)1, ReadLayerScrollY(bus, smart.Layer));

            var stableHead = ReadLayerClipRect(bus, smart.Layer);
            var newRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newRegion));
            damageRegion = newRegion.D[0];
            Assert.NotEqual(0u, damageRegion);
            rectangle = AllocateGuestMemory(
                bus,
                (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 2, 2, 6, 6);
            var includeDamage = new M68kCpuState
            {
                A = { [0] = damageRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeDamage));
            Assert.Equal(1u, includeDamage.D[0]);
            RetireOwnedDamageForCallerFixture(bus, boot, APTR.FromPointer(smart.Layer));
            LayersLayerCodec.WriteDamageList(ref layerMemory,
                APTR.FromPointer(smart.Layer), APTR.FromPointer(damageRegion));
            LayersLayerCodec.WriteFlags(ref layerMemory,
                APTR.FromPointer(smart.Layer),
                LayersLayerCodec.ReadFlags(ref layerMemory,
                    APTR.FromPointer(smart.Layer)) | LayerFlags.Refresh);
            var damageBytes = SnapshotGraphicsRegion(bus, damageRegion);

            var begin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;

            var activeProjection = new List<(short MinX, short MinY,
                short MaxX, short MaxY, uint ObscuringLayer, uint BitMap)>();
            for (var clipRect = ReadLayerClipRect(bus, smart.Layer);
                 clipRect != 0;
                 clipRect = ReadClipRectNext(bus, clipRect))
            {
                var clipBounds = LayersClipRectCodec.BoundsAddress(
                    APTR.FromPointer(clipRect)).Raw;
                activeProjection.Add((
                    unchecked((short)bus.ReadWord(clipBounds)),
                    unchecked((short)bus.ReadWord(clipBounds + 2)),
                    unchecked((short)bus.ReadWord(clipBounds + 4)),
                    unchecked((short)bus.ReadWord(clipBounds + 6)),
                    ReadClipRectObscuringLayer(bus, clipRect),
                    ReadClipRectBitMap(bus, clipRect)));
            }
            var backingBitMap = activeProjection.First(fragment =>
                fragment.ObscuringLayer == cover.Layer).BitMap;
            Assert.NotEqual(0u, backingBitMap);
            Assert.Equal(new[]
            {
                ((short)30, (short)16, (short)34, (short)16, 0u, 0u),
                ((short)30, (short)17, (short)31, (short)18, cover.Layer,
                    backingBitMap),
                ((short)32, (short)17, (short)34, (short)18, 0u, 0u),
                ((short)30, (short)19, (short)34, (short)20, 0u, 0u)
            }, activeProjection);

            ClearPlanarBitMap(bus, displayBitMap);
            ClearPlanarBitMap(bus, superBitMap);
            ClearPlanarBitMap(bus, backingBitMap);
            var fill = new M68kCpuState
            {
                A = { [1] = smart.RastPort },
                D = { [0] = 1, [1] = 0, [2] = 47, [3] = 31 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);

            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                {
                    var withinDamage = x is >= 30 and <= 31 &&
                        y is >= 16 and <= 19;
                    var covered = y is >= 17 and <= 18;
                    Assert.Equal(withinDamage && !covered,
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
                }
            Assert.All(
                SnapshotPlanarBitMap(bus, superBitMap),
                value => Assert.Equal((byte)0, value));
            var backingWidth = ReadBitMapBytesPerRow(bus, backingBitMap) * 8;
            var backingHeight = ReadBitMapRows(bus, backingBitMap);
            for (var y = 0; y < backingHeight; y++)
                for (var x = 0; x < backingWidth; x++)
                    Assert.Equal(x < 2 && y < 2,
                        ReadPlanarBitMapPixel(bus, backingBitMap, x, y));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var end = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                end));
            Assert.Equal(1u, end.D[0]);
            updating = false;
            Assert.Equal(stableHead, ReadLayerClipRect(bus, smart.Layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            // Install a caller ClipRegion in the scrolled logical coordinate
            // space. Its display-space bounds are [31,18..33,20], intersecting
            // this damage at the occluder and at the physical right/bottom edge.
            var newClipRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newClipRegion));
            callerClipRegion = newClipRegion.D[0];
            Assert.NotEqual(0u, callerClipRegion);
            WriteRectangleBounds(bus, rectangle, 5, 5, 7, 7);
            var includeClip = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeClip));
            Assert.Equal(1u, includeClip.D[0]);
            var callerClipBytes = SnapshotGraphicsRegion(bus,
                callerClipRegion);
            var installClip = new M68kCpuState
            {
                A = { [0] = smart.Layer, [1] = callerClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installClip));
            Assert.Equal(0u, installClip.D[0]);
            callerClipInstalled = true;
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, smart.Layer));
            var stableCallerClipHead = ReadLayerClipRect(bus, smart.Layer);
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var beginWithCallerClip = new M68kCpuState
            {
                A = { [0] = smart.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                beginWithCallerClip));
            Assert.Equal(1u, beginWithCallerClip.D[0]);
            updating = true;

            activeProjection.Clear();
            for (var clipRect = ReadLayerClipRect(bus, smart.Layer);
                 clipRect != 0;
                 clipRect = ReadClipRectNext(bus, clipRect))
            {
                var clipBounds = LayersClipRectCodec.BoundsAddress(
                    APTR.FromPointer(clipRect)).Raw;
                activeProjection.Add((
                    unchecked((short)bus.ReadWord(clipBounds)),
                    unchecked((short)bus.ReadWord(clipBounds + 2)),
                    unchecked((short)bus.ReadWord(clipBounds + 4)),
                    unchecked((short)bus.ReadWord(clipBounds + 6)),
                    ReadClipRectObscuringLayer(bus, clipRect),
                    ReadClipRectBitMap(bus, clipRect)));
            }
            backingBitMap = activeProjection.First(fragment =>
                fragment.ObscuringLayer == cover.Layer).BitMap;
            Assert.NotEqual(0u, backingBitMap);
            Assert.Equal(new[]
            {
                ((short)31, (short)18, (short)31, (short)18, cover.Layer,
                    backingBitMap),
                ((short)32, (short)18, (short)33, (short)18, 0u, 0u),
                ((short)31, (short)19, (short)33, (short)20, 0u, 0u)
            }, activeProjection);
            var initialBackingBitMap = backingBitMap;

            var incompleteEnd = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                incompleteEnd));
            updating = false;
            Assert.Equal(stableCallerClipHead,
                ReadLayerClipRect(bus, smart.Layer));
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, smart.Layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var scrollWhilePaused = new M68kCpuState
            {
                A = { [1] = smart.Layer },
                D = { [0] = 1, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                scrollWhilePaused));
            Assert.Equal((short)3, ReadLayerScrollX(bus, smart.Layer));
            Assert.Equal((short)2, ReadLayerScrollY(bus, smart.Layer));

            var retryBegin = new M68kCpuState
            {
                A = { [0] = smart.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                retryBegin));
            Assert.Equal(1u, retryBegin.D[0]);
            updating = true;
            activeProjection.Clear();
            for (var clipRect = ReadLayerClipRect(bus, smart.Layer);
                 clipRect != 0;
                 clipRect = ReadClipRectNext(bus, clipRect))
            {
                var clipBounds = LayersClipRectCodec.BoundsAddress(
                    APTR.FromPointer(clipRect)).Raw;
                activeProjection.Add((
                    unchecked((short)bus.ReadWord(clipBounds)),
                    unchecked((short)bus.ReadWord(clipBounds + 2)),
                    unchecked((short)bus.ReadWord(clipBounds + 4)),
                    unchecked((short)bus.ReadWord(clipBounds + 6)),
                    ReadClipRectObscuringLayer(bus, clipRect),
                    ReadClipRectBitMap(bus, clipRect)));
            }
            backingBitMap = activeProjection.First(fragment =>
                fragment.ObscuringLayer == cover.Layer).BitMap;
            Assert.Equal(initialBackingBitMap, backingBitMap);
            Assert.Equal(new[]
            {
                ((short)31, (short)18, (short)31, (short)18, cover.Layer,
                    backingBitMap),
                ((short)32, (short)18, (short)33, (short)18, 0u, 0u),
                ((short)31, (short)19, (short)33, (short)20, 0u, 0u)
            }, activeProjection);

            var pauseForClipReplacement = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                pauseForClipReplacement));
            updating = false;
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, smart.Layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var newReplacementRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newReplacementRegion));
            replacementClipRegion = newReplacementRegion.D[0];
            Assert.NotEqual(0u, replacementClipRegion);
            WriteRectangleBounds(bus, rectangle, 4, 4, 6, 6);
            var includeReplacement = new M68kCpuState
            {
                A = { [0] = replacementClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeReplacement));
            Assert.Equal(1u, includeReplacement.D[0]);
            var replacementClipBytes = SnapshotGraphicsRegion(bus,
                replacementClipRegion);

            var installReplacement = new M68kCpuState
            {
                A = { [0] = smart.Layer, [1] = replacementClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installReplacement));
            Assert.Equal(callerClipRegion, installReplacement.D[0]);
            Assert.Equal(replacementClipRegion,
                ReadLayerClipRegion(bus, smart.Layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));
            Assert.Equal(replacementClipBytes,
                SnapshotGraphicsRegion(bus, replacementClipRegion));

            var beginAfterReplacement = new M68kCpuState
            {
                A = { [0] = smart.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                beginAfterReplacement));
            Assert.Equal(1u, beginAfterReplacement.D[0]);
            updating = true;
            activeProjection.Clear();
            for (var clipRect = ReadLayerClipRect(bus, smart.Layer);
                 clipRect != 0;
                 clipRect = ReadClipRectNext(bus, clipRect))
            {
                var clipBounds = LayersClipRectCodec.BoundsAddress(
                    APTR.FromPointer(clipRect)).Raw;
                activeProjection.Add((
                    unchecked((short)bus.ReadWord(clipBounds)),
                    unchecked((short)bus.ReadWord(clipBounds + 2)),
                    unchecked((short)bus.ReadWord(clipBounds + 4)),
                    unchecked((short)bus.ReadWord(clipBounds + 6)),
                    ReadClipRectObscuringLayer(bus, clipRect),
                    ReadClipRectBitMap(bus, clipRect)));
            }
            backingBitMap = activeProjection.First(fragment =>
                fragment.ObscuringLayer == cover.Layer).BitMap;
            Assert.NotEqual(0u, backingBitMap);
            Assert.Equal(new[]
            {
                ((short)30, (short)16, (short)31, (short)16, 0u, 0u),
                ((short)30, (short)17, (short)31, (short)18, cover.Layer,
                    backingBitMap)
            }, activeProjection);

            ClearPlanarBitMap(bus, displayBitMap);
            ClearPlanarBitMap(bus, superBitMap);
            ClearPlanarBitMap(bus, backingBitMap);
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);

            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(x is >= 30 and <= 31 && y == 16,
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.All(
                SnapshotPlanarBitMap(bus, superBitMap),
                value => Assert.Equal((byte)0, value));
            backingWidth = ReadBitMapBytesPerRow(bus, backingBitMap) * 8;
            backingHeight = ReadBitMapRows(bus, backingBitMap);
            for (var y = 0; y < backingHeight; y++)
                for (var x = 0; x < backingWidth; x++)
                    Assert.Equal(x < 2 && y < 2,
                        ReadPlanarBitMapPixel(bus, backingBitMap, x, y));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));

            var endWithCallerClip = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                endWithCallerClip));
            Assert.Equal(1u, endWithCallerClip.D[0]);
            updating = false;
            Assert.Equal(replacementClipRegion,
                ReadLayerClipRegion(bus, smart.Layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));
            Assert.Equal(replacementClipBytes,
                SnapshotGraphicsRegion(bus, replacementClipRegion));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = smart.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            var smartAddress = APTR.FromPointer(smart.Layer);
            LayersLayerCodec.WriteDamageList(ref layerMemory, smartAddress,
                APTR.Null);
            LayersLayerCodec.WriteFlags(ref layerMemory, smartAddress,
                LayersLayerCodec.ReadFlags(ref layerMemory, smartAddress) &
                ~LayerFlags.Refresh);
            if (callerClipInstalled)
            {
                var uninstall = new M68kCpuState
                {
                    A = { [0] = smart.Layer }
                };
                InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    uninstall);
            }
            if (damageRegion != 0)
            {
                var dispose = new M68kCpuState { A = { [0] = damageRegion } };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (callerClipRegion != 0)
            {
                var dispose = new M68kCpuState
                {
                    A = { [0] = callerClipRegion }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (replacementClipRegion != 0)
            {
                var dispose = new M68kCpuState
                {
                    A = { [0] = replacementClipRegion }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (rectangle != 0)
                FreeGuestMemory(bus, rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, smart.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void SuperBitMapPausedDamageResumesAfterCallerClipUninstall()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var superBitMap = AllocatePlanarBitMap(bus, 48, 32);
        var smart = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            28,
            14,
            59,
            33);
        var cover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            30,
            17,
            31,
            18);
        var layerMemory = new LayersTestGuestMemory(bus);
        uint damageRegion = 0;
        uint callerClipRegion = 0;
        uint rectangle = 0;
        uint backingBitMap = 0;
        var updating = false;
        var callerClipInstalled = false;

        try
        {
            var settleBegin = new M68kCpuState
            {
                A = { [0] = smart.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                settleBegin));
            Assert.Equal(1u, settleBegin.D[0]);
            updating = true;
            var settleEnd = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                settleEnd));
            Assert.Equal(1u, settleEnd.D[0]);
            updating = false;

            var scroll = new M68kCpuState
            {
                A = { [1] = smart.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.ScrollLayer),
                scroll));
            Assert.Equal((short)2, ReadLayerScrollX(bus, smart.Layer));
            Assert.Equal((short)1, ReadLayerScrollY(bus, smart.Layer));

            var newDamageRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newDamageRegion));
            damageRegion = newDamageRegion.D[0];
            Assert.NotEqual(0u, damageRegion);
            rectangle = AllocateGuestMemory(
                bus,
                (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 2, 2, 6, 6);
            var includeDamage = new M68kCpuState
            {
                A = { [0] = damageRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeDamage));
            Assert.Equal(1u, includeDamage.D[0]);
            WriteRectangleBounds(bus, rectangle, 10, 10, 11, 11);
            includeDamage = new M68kCpuState
            {
                A = { [0] = damageRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeDamage));
            Assert.Equal(1u, includeDamage.D[0]);
            RetireOwnedDamageForCallerFixture(bus, boot, APTR.FromPointer(smart.Layer));
            LayersLayerCodec.WriteDamageList(ref layerMemory,
                APTR.FromPointer(smart.Layer), APTR.FromPointer(damageRegion));
            LayersLayerCodec.WriteFlags(ref layerMemory,
                APTR.FromPointer(smart.Layer),
                LayersLayerCodec.ReadFlags(ref layerMemory,
                    APTR.FromPointer(smart.Layer)) | LayerFlags.Refresh);
            var damageBytes = SnapshotGraphicsRegion(bus, damageRegion);

            var newClipRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newClipRegion));
            callerClipRegion = newClipRegion.D[0];
            Assert.NotEqual(0u, callerClipRegion);
            WriteRectangleBounds(bus, rectangle, 5, 5, 7, 7);
            var includeClip = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeClip));
            Assert.Equal(1u, includeClip.D[0]);
            var callerClipBytes = SnapshotGraphicsRegion(bus,
                callerClipRegion);
            var install = new M68kCpuState
            {
                A = { [0] = smart.Layer, [1] = callerClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                install));
            Assert.Equal(0u, install.D[0]);
            callerClipInstalled = true;
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, smart.Layer));

            var begin = new M68kCpuState
            {
                A = { [0] = smart.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            var pause = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                pause));
            updating = false;
            Assert.Equal(callerClipRegion,
                ReadLayerClipRegion(bus, smart.Layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var uninstall = new M68kCpuState
            {
                A = { [0] = smart.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                uninstall));
            Assert.Equal(callerClipRegion, uninstall.D[0]);
            callerClipInstalled = false;
            Assert.Equal(0u, ReadLayerClipRegion(bus, smart.Layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;

            var activeProjection = new List<(short MinX, short MinY,
                short MaxX, short MaxY, uint ObscuringLayer, uint BitMap)>();
            for (var clipRect = ReadLayerClipRect(bus, smart.Layer);
                 clipRect != 0;
                 clipRect = ReadClipRectNext(bus, clipRect))
            {
                var clipBounds = LayersClipRectCodec.BoundsAddress(
                    APTR.FromPointer(clipRect)).Raw;
                activeProjection.Add((
                    unchecked((short)bus.ReadWord(clipBounds)),
                    unchecked((short)bus.ReadWord(clipBounds + 2)),
                    unchecked((short)bus.ReadWord(clipBounds + 4)),
                    unchecked((short)bus.ReadWord(clipBounds + 6)),
                    ReadClipRectObscuringLayer(bus, clipRect),
                    ReadClipRectBitMap(bus, clipRect)));
            }
            backingBitMap = activeProjection.First(fragment =>
                fragment.ObscuringLayer == cover.Layer).BitMap;
            Assert.NotEqual(0u, backingBitMap);
            Assert.Equal(new[]
            {
                ((short)30, (short)16, (short)34, (short)16, 0u, 0u),
                ((short)30, (short)17, (short)31, (short)18,
                    cover.Layer, backingBitMap),
                ((short)32, (short)17, (short)34, (short)18, 0u, 0u),
                ((short)30, (short)19, (short)34, (short)20, 0u, 0u),
                ((short)38, (short)24, (short)39, (short)25, 0u, 0u)
            }, activeProjection);

            ClearPlanarBitMap(bus, displayBitMap);
            ClearPlanarBitMap(bus, superBitMap);
            ClearPlanarBitMap(bus, backingBitMap);
            var fill = new M68kCpuState
            {
                A = { [1] = smart.RastPort },
                D = { [0] = 1, [1] = 0, [2] = 47, [3] = 31 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);

            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(x is >= 30 and <= 31 && y is 16 or 19,
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            Assert.All(
                SnapshotPlanarBitMap(bus, superBitMap),
                value => Assert.Equal((byte)0, value));
            var backingWidth = ReadBitMapBytesPerRow(bus, backingBitMap) * 8;
            var backingHeight = ReadBitMapRows(bus, backingBitMap);
            for (var y = 0; y < backingHeight; y++)
                for (var x = 0; x < backingWidth; x++)
                    Assert.Equal(x < 2 && y < 2,
                        ReadPlanarBitMapPixel(bus, backingBitMap, x, y));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var end = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                end));
            Assert.Equal(1u, end.D[0]);
            updating = false;
            Assert.Equal(0u, ReadLayerClipRegion(bus, smart.Layer));
            Assert.Equal(damageRegion,
                LayersLayerCodec.ReadDamageList(ref layerMemory,
                    APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = smart.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (callerClipInstalled)
            {
                var uninstall = new M68kCpuState
                {
                    A = { [0] = smart.Layer }
                };
                InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    uninstall);
            }
            var smartAddress = APTR.FromPointer(smart.Layer);
            LayersLayerCodec.WriteDamageList(ref layerMemory, smartAddress,
                APTR.Null);
            LayersLayerCodec.WriteFlags(ref layerMemory, smartAddress,
                LayersLayerCodec.ReadFlags(ref layerMemory, smartAddress) &
                ~LayerFlags.Refresh);
            if (damageRegion != 0)
            {
                var dispose = new M68kCpuState { A = { [0] = damageRegion } };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (callerClipRegion != 0)
            {
                var dispose = new M68kCpuState
                {
                    A = { [0] = callerClipRegion }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (rectangle != 0)
                FreeGuestMemory(bus, rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, smart.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void LayersOwnedDamageClipUninstallResumesRefreshAndClearsDamage()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var smart = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            31,
            19);
        var cover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            15,
            15);
        var layerMemory = new LayersTestGuestMemory(bus);
        uint callerClipRegion = 0;
        uint rectangle = 0;
        var callerClipInstalled = false;
        var updating = false;

        try
        {
            // A moved cover creates Layers-owned uncover damage on this plain
            // lower layer. SuperBitMap uncover tests supply caller-owned damage
            // because their contents persist without a Layers refresh.
            var move = new M68kCpuState
            {
                A = { [1] = cover.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveLayer),
                move));
            Assert.Equal(1u, move.D[0]);

            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(smart.Layer));
            Assert.True(damage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, damage)
                .IsNotNull);
            Assert.NotEqual(0, ReadLayerFlags(bus, smart.Layer) &
                (ushort)LayerFlags.Refresh);
            var damageBytes = SnapshotGraphicsRegion(bus, damage.Raw);
            var stableHead = ReadLayerClipRect(bus, smart.Layer);

            var begin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            var fullDamageProjection = new List<(
                short MinX, short MinY, short MaxX, short MaxY,
                uint ObscuringLayer, uint BitMap)>();
            for (var clipRect = ReadLayerClipRect(bus, smart.Layer);
                 clipRect != 0;
                 clipRect = ReadClipRectNext(bus, clipRect))
            {
                var bounds = LayersClipRectCodec.BoundsAddress(
                    APTR.FromPointer(clipRect)).Raw;
                fullDamageProjection.Add((
                    unchecked((short)bus.ReadWord(bounds)),
                    unchecked((short)bus.ReadWord(bounds + 2)),
                    unchecked((short)bus.ReadWord(bounds + 4)),
                    unchecked((short)bus.ReadWord(bounds + 6)),
                    ReadClipRectObscuringLayer(bus, clipRect),
                    ReadClipRectBitMap(bus, clipRect)));
            }
            Assert.Contains(fullDamageProjection, fragment =>
                fragment.ObscuringLayer == 0 &&
                fragment.MinX <= 4 && fragment.MaxX >= 4 &&
                fragment.MinY <= 4 && fragment.MaxY >= 4);
            Assert.Contains(fullDamageProjection, fragment =>
                fragment.ObscuringLayer == 0 &&
                fragment.MinX <= 5 && fragment.MaxX >= 5 &&
                fragment.MinY <= 4 && fragment.MaxY >= 4);

            var pause = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                pause));
            updating = false;
            Assert.Equal(stableHead, ReadLayerClipRect(bus, smart.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes, SnapshotGraphicsRegion(bus, damage.Raw));
            Assert.NotEqual(0, ReadLayerFlags(bus, smart.Layer) &
                (ushort)LayerFlags.Refresh);

            var newClipRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newClipRegion));
            callerClipRegion = newClipRegion.D[0];
            Assert.NotEqual(0u, callerClipRegion);
            rectangle = AllocateGuestMemory(
                bus,
                (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 4, 4, 4, 4);
            var includeClip = new M68kCpuState
            {
                A = { [0] = callerClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeClip));
            Assert.Equal(1u, includeClip.D[0]);
            var callerClipBytes = SnapshotGraphicsRegion(bus, callerClipRegion);
            var install = new M68kCpuState
            {
                A = { [0] = smart.Layer, [1] = callerClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                install));
            callerClipInstalled = true;
            Assert.Equal(0u, install.D[0]);

            begin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            var clippedProjection = new List<(short MinX, short MinY,
                short MaxX, short MaxY, uint ObscuringLayer, uint BitMap)>();
            for (var clipRect = ReadLayerClipRect(bus, smart.Layer);
                 clipRect != 0;
                 clipRect = ReadClipRectNext(bus, clipRect))
            {
                var bounds = LayersClipRectCodec.BoundsAddress(
                    APTR.FromPointer(clipRect)).Raw;
                clippedProjection.Add((
                    unchecked((short)bus.ReadWord(bounds)),
                    unchecked((short)bus.ReadWord(bounds + 2)),
                    unchecked((short)bus.ReadWord(bounds + 4)),
                    unchecked((short)bus.ReadWord(bounds + 6)),
                    ReadClipRectObscuringLayer(bus, clipRect),
                    ReadClipRectBitMap(bus, clipRect)));
            }
            Assert.Equal(new[] { ((short)4, (short)4, (short)4, (short)4, 0u, 0u) },
                clippedProjection);

            pause = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                pause));
            updating = false;
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes, SnapshotGraphicsRegion(bus, damage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var uninstall = new M68kCpuState
            {
                A = { [0] = smart.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                uninstall));
            callerClipInstalled = false;
            Assert.Equal(callerClipRegion, uninstall.D[0]);
            Assert.Equal(0u, ReadLayerClipRegion(bus, smart.Layer));
            damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(smart.Layer));
            Assert.True(damage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, damage)
                .IsNotNull);
            damageBytes = SnapshotGraphicsRegion(bus, damage.Raw);
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            begin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            var resumedProjection = new List<(short MinX, short MinY,
                short MaxX, short MaxY, uint ObscuringLayer, uint BitMap)>();
            for (var clipRect = ReadLayerClipRect(bus, smart.Layer);
                 clipRect != 0;
                 clipRect = ReadClipRectNext(bus, clipRect))
            {
                var bounds = LayersClipRectCodec.BoundsAddress(
                    APTR.FromPointer(clipRect)).Raw;
                resumedProjection.Add((
                    unchecked((short)bus.ReadWord(bounds)),
                    unchecked((short)bus.ReadWord(bounds + 2)),
                    unchecked((short)bus.ReadWord(bounds + 4)),
                    unchecked((short)bus.ReadWord(bounds + 6)),
                    ReadClipRectObscuringLayer(bus, clipRect),
                    ReadClipRectBitMap(bus, clipRect)));
            }
            Assert.Equal(fullDamageProjection, resumedProjection);

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, smart.RastPort, 1);
            var fill = new M68kCpuState
            {
                A = { [1] = smart.RastPort },
                D = { [0] = 0, [1] = 4, [2] = 31, [3] = 4 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                {
                    var admitted = fullDamageProjection.Any(fragment =>
                        fragment.ObscuringLayer == 0 &&
                        x >= fragment.MinX && x <= fragment.MaxX &&
                        y >= fragment.MinY && y <= fragment.MaxY);
                    Assert.Equal(y == 4 && admitted,
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
                }
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes, SnapshotGraphicsRegion(bus, damage.Raw));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));

            var complete = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, complete);
            updating = false;
            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, smart.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));

            Assert.NotEqual(0u, ReadLayerClipRect(bus, smart.Layer));
            Assert.Equal(callerClipBytes,
                SnapshotGraphicsRegion(bus, callerClipRegion));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = smart.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (callerClipInstalled)
            {
                var uninstall = new M68kCpuState
                {
                    A = { [0] = smart.Layer }
                };
                InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    uninstall);
            }
            if (callerClipRegion != 0)
            {
                var dispose = new M68kCpuState
                {
                    A = { [0] = callerClipRegion }
                };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (rectangle != 0)
                FreeGuestMemory(bus, rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, smart.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void LayersOwnedDamageSurvivesTwoPartialClipRegionRedrawPasses()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            31,
            19);
        var cover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            15,
            15);
        var layerMemory = new LayersTestGuestMemory(bus);
        uint firstClipRegion = 0;
        uint secondClipRegion = 0;
        uint rectangle = 0;
        var callerClipInstalled = false;
        var updating = false;

        try
        {
            var move = new M68kCpuState
            {
                A = { [1] = cover.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveLayer),
                move));
            Assert.Equal(1u, move.D[0]);

            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, damage)
                .IsNotNull);
            var damageBytes = SnapshotGraphicsRegion(bus, damage.Raw);

            var firstRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                firstRegion));
            firstClipRegion = firstRegion.D[0];
            Assert.NotEqual(0u, firstClipRegion);
            var secondRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                secondRegion));
            secondClipRegion = secondRegion.D[0];
            Assert.NotEqual(0u, secondClipRegion);

            rectangle = AllocateGuestMemory(
                bus,
                (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 4, 4, 4, 4);
            var includeFirstPixel = new M68kCpuState
            {
                A = { [0] = firstClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeFirstPixel));
            Assert.Equal(1u, includeFirstPixel.D[0]);

            WriteRectangleBounds(bus, rectangle, 5, 4, 5, 4);
            var includeSecondPixel = new M68kCpuState
            {
                A = { [0] = secondClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                includeSecondPixel));
            Assert.Equal(1u, includeSecondPixel.D[0]);
            var firstClipBytes = SnapshotGraphicsRegion(bus, firstClipRegion);
            var secondClipBytes = SnapshotGraphicsRegion(bus, secondClipRegion);

            var installFirst = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = firstClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installFirst));
            Assert.Equal(0u, installFirst.D[0]);
            callerClipInstalled = true;

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal(x == 4 && y == 4,
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));

            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                partialEnd));
            updating = false;
            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, SnapshotGraphicsRegion(bus, damage.Raw));
            Assert.Equal(firstClipBytes,
                SnapshotGraphicsRegion(bus, firstClipRegion));
            Assert.Equal(secondClipBytes,
                SnapshotGraphicsRegion(bus, secondClipRegion));

            var installSecond = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = secondClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installSecond));
            Assert.Equal(firstClipRegion, installSecond.D[0]);

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            for (var y = 0; y < 20; y++)
                for (var x = 0; x < 32; x++)
                    Assert.Equal((x == 4 || x == 5) && y == 4,
                        ReadPlanarBitMapPixel(bus, displayBitMap, x, y));

            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, SnapshotGraphicsRegion(bus, damage.Raw));
            Assert.Equal(firstClipBytes,
                SnapshotGraphicsRegion(bus, firstClipRegion));
            Assert.Equal(secondClipBytes,
                SnapshotGraphicsRegion(bus, secondClipRegion));

            var complete = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, complete);
            updating = false;
            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)(LayerFlags.Updating | LayerFlags.Refresh));

            Assert.Equal(secondClipRegion, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(firstClipBytes,
                SnapshotGraphicsRegion(bus, firstClipRegion));
            Assert.Equal(secondClipBytes,
                SnapshotGraphicsRegion(bus, secondClipRegion));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (callerClipInstalled)
            {
                var uninstall = new M68kCpuState
                {
                    A = { [0] = bottom.Layer }
                };
                InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    uninstall);
            }
            foreach (var region in new[] { firstClipRegion, secondClipRegion })
            {
                if (region == 0) continue;
                var dispose = new M68kCpuState { A = { [0] = region } };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (rectangle != 0)
                FreeGuestMemory(bus, rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void DisjointCallerOwnedSuperBitMapDamageSurvivesTwoPartialClipRedrawPasses()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var superBitMap = AllocatePlanarBitMap(bus, 48, 32);
        var smart = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            0,
            0,
            31,
            19);
        var cover = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            8,
            8);
        var layerMemory = new LayersTestGuestMemory(bus);
        uint damageRegion = 0;
        uint firstClipRegion = 0;
        uint secondClipRegion = 0;
        uint rectangle = 0;
        uint backingBitMap = 0;
        var callerClipInstalled = false;
        var updating = false;

        try
        {
            var settleBegin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                settleBegin));
            Assert.Equal(1u, settleBegin.D[0]);
            updating = true;
            var settleEnd = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                settleEnd));
            updating = false;

            var newDamage = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newDamage));
            damageRegion = newDamage.D[0];
            Assert.NotEqual(0u, damageRegion);
            rectangle = AllocateGuestMemory(
                bus,
                (uint)GraphicsLayouts.RectangleSize);
            WriteRectangleBounds(bus, rectangle, 2, 2, 6, 6);
            var addDamage = new M68kCpuState
            {
                A = { [0] = damageRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                addDamage));
            Assert.Equal(1u, addDamage.D[0]);
            WriteRectangleBounds(bus, rectangle, 38, 24, 39, 25);
            addDamage = new M68kCpuState
            {
                A = { [0] = damageRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                addDamage));
            Assert.Equal(1u, addDamage.D[0]);
            RetireOwnedDamageForCallerFixture(bus, boot, APTR.FromPointer(smart.Layer));
            LayersLayerCodec.WriteDamageList(
                ref layerMemory,
                APTR.FromPointer(smart.Layer),
                APTR.FromPointer(damageRegion));
            LayersLayerCodec.WriteFlags(
                ref layerMemory,
                APTR.FromPointer(smart.Layer),
                LayersLayerCodec.ReadFlags(
                    ref layerMemory,
                    APTR.FromPointer(smart.Layer)) | LayerFlags.Refresh);
            var damageBytes = SnapshotGraphicsRegion(bus, damageRegion);

            var newFirstClip = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newFirstClip));
            firstClipRegion = newFirstClip.D[0];
            Assert.NotEqual(0u, firstClipRegion);
            WriteRectangleBounds(bus, rectangle, 2, 2, 3, 3);
            var addFirstClip = new M68kCpuState
            {
                A = { [0] = firstClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                addFirstClip));
            Assert.Equal(1u, addFirstClip.D[0]);

            var newSecondClip = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newSecondClip));
            secondClipRegion = newSecondClip.D[0];
            Assert.NotEqual(0u, secondClipRegion);
            WriteRectangleBounds(bus, rectangle, 5, 5, 6, 6);
            var addSecondClip = new M68kCpuState
            {
                A = { [0] = secondClipRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                addSecondClip));
            Assert.Equal(1u, addSecondClip.D[0]);
            var firstClipBytes = SnapshotGraphicsRegion(bus, firstClipRegion);
            var secondClipBytes = SnapshotGraphicsRegion(bus, secondClipRegion);

            var installFirst = new M68kCpuState
            {
                A = { [0] = smart.Layer, [1] = firstClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installFirst));
            Assert.Equal(0u, installFirst.D[0]);
            callerClipInstalled = true;

            ClearPlanarBitMap(bus, displayBitMap);
            ClearPlanarBitMap(bus, superBitMap);
            var begin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.NotEqual(0, ReadLayerFlags(bus, smart.Layer) &
                (ushort)LayerFlags.Updating);
            var firstProjection = CaptureProjection();
            Assert.Equal(new[]
            {
                ((short)2, (short)2, (short)3, (short)3, 0u, 0u)
            }, firstProjection);

            WriteRastPortForegroundPen(bus, smart.RastPort, 1);
            var fill = new M68kCpuState
            {
                A = { [1] = smart.RastPort },
                D = { [0] = 1, [1] = 0, [2] = 47, [3] = 31 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);
            AssertDisplayPassPixels();
            AssertSuperBitMapIsBlank();

            var partialEnd = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                partialEnd));
            updating = false;
            AssertSuperBitMapIsBlank();
            Assert.Equal(damageRegion, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
            Assert.Equal(firstClipBytes,
                SnapshotGraphicsRegion(bus, firstClipRegion));
            Assert.Equal(secondClipBytes,
                SnapshotGraphicsRegion(bus, secondClipRegion));

            var installSecond = new M68kCpuState
            {
                A = { [0] = smart.Layer, [1] = secondClipRegion }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installSecond));
            Assert.Equal(firstClipRegion, installSecond.D[0]);
            AssertSuperBitMapMatchesFirstPass();

            begin = new M68kCpuState { A = { [0] = smart.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;
            Assert.NotEqual(0, ReadLayerFlags(bus, smart.Layer) &
                (ushort)LayerFlags.Updating);
            AssertSuperBitMapMatchesFirstPass();
            var secondProjection = CaptureProjection();
            backingBitMap = Assert.Single(secondProjection).BitMap;
            Assert.NotEqual(0u, backingBitMap);
            Assert.NotEqual(superBitMap, backingBitMap);
            Assert.Equal(new[]
            {
                ((short)5, (short)5, (short)6, (short)6,
                    cover.Layer, backingBitMap)
            }, secondProjection);

            ClearPlanarBitMap(bus, backingBitMap);
            fill = new M68kCpuState
            {
                A = { [1] = smart.RastPort },
                D = { [0] = 1, [1] = 0, [2] = 47, [3] = 31 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.RectFill),
                fill));
            Assert.Equal(0u, fill.D[0]);
            AssertDisplayPassPixels();
            AssertSuperBitMapMatchesFirstPass();
            var backingWidth = ReadBitMapBytesPerRow(bus, backingBitMap) * 8;
            var backingHeight = ReadBitMapRows(bus, backingBitMap);
            var actualBackingPixels = new List<(int X, int Y)>();
            for (var y = 0; y < backingHeight; y++)
                for (var x = 0; x < backingWidth; x++)
                    if (ReadPlanarBitMapPixel(bus, backingBitMap, x, y))
                        actualBackingPixels.Add((x, y));
            Assert.Equal(new[]
            {
                (0, 0), (1, 0), (0, 1), (1, 1)
            }, actualBackingPixels);
            Assert.Equal(damageRegion, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
            Assert.Equal(firstClipBytes,
                SnapshotGraphicsRegion(bus, firstClipRegion));
            Assert.Equal(secondClipBytes,
                SnapshotGraphicsRegion(bus, secondClipRegion));

            var complete = new M68kCpuState
            {
                A = { [0] = smart.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                complete));
            updating = false;
            Assert.Equal(damageRegion, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(smart.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damageRegion));
            Assert.Equal(secondClipRegion,
                ReadLayerClipRegion(bus, smart.Layer));

            List<(short MinX, short MinY, short MaxX, short MaxY,
                uint ObscuringLayer, uint BitMap)> CaptureProjection()
            {
                var projection = new List<(short MinX, short MinY,
                    short MaxX, short MaxY, uint ObscuringLayer, uint BitMap)>();
                for (var clipRect = ReadLayerClipRect(bus, smart.Layer);
                     clipRect != 0;
                     clipRect = ReadClipRectNext(bus, clipRect))
                {
                    var bounds = LayersClipRectCodec.BoundsAddress(
                        APTR.FromPointer(clipRect)).Raw;
                    projection.Add((
                        unchecked((short)bus.ReadWord(bounds)),
                        unchecked((short)bus.ReadWord(bounds + 2)),
                        unchecked((short)bus.ReadWord(bounds + 4)),
                        unchecked((short)bus.ReadWord(bounds + 6)),
                        ReadClipRectObscuringLayer(bus, clipRect),
                        ReadClipRectBitMap(bus, clipRect)));
                }

                return projection;
            }

            void AssertDisplayPassPixels()
            {
                for (var y = 0; y < 20; y++)
                    for (var x = 0; x < 32; x++)
                        Assert.Equal(x is >= 2 and <= 3 && y is >= 2 and <= 3,
                            ReadPlanarBitMapPixel(bus, displayBitMap, x, y));
            }

            void AssertSuperBitMapIsBlank()
            {
                for (var y = 0; y < 32; y++)
                    for (var x = 0; x < 48; x++)
                        Assert.False(
                            ReadPlanarBitMapPixel(bus, superBitMap, x, y),
                            $"SuperBitMap pixel ({x},{y})");
            }

            void AssertSuperBitMapMatchesFirstPass()
            {
                for (var y = 0; y < 32; y++)
                    for (var x = 0; x < 48; x++)
                        Assert.Equal(x is >= 2 and <= 3 && y is >= 2 and <= 3,
                            ReadPlanarBitMapPixel(bus, superBitMap, x, y));
            }
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = smart.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (callerClipInstalled)
            {
                var uninstall = new M68kCpuState
                {
                    A = { [0] = smart.Layer }
                };
                InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    uninstall);
            }
            if (damageRegion != 0)
            {
                LayersLayerCodec.WriteDamageList(
                    ref layerMemory,
                    APTR.FromPointer(smart.Layer),
                    APTR.Null);
                LayersLayerCodec.WriteFlags(
                    ref layerMemory,
                    APTR.FromPointer(smart.Layer),
                    LayersLayerCodec.ReadFlags(
                        ref layerMemory,
                        APTR.FromPointer(smart.Layer)) & ~LayerFlags.Refresh);
            }
            foreach (var region in new[]
                { damageRegion, firstClipRegion, secondClipRegion })
            {
                if (region == 0) continue;
                var dispose = new M68kCpuState { A = { [0] = region } };
                Assert.True(InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose));
            }
            if (rectangle != 0)
                FreeGuestMemory(bus, rectangle,
                    (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, cover.Layer);
            DeleteLayer(bus, libraryBase, smart.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void EmptyClipRegionPauseCanBeReplacedBeforeRetainedDamageIsResumed()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            31,
            19);
        var top = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            15,
            15);
        var rectangle = AllocateGuestMemory(bus, (uint)GraphicsLayouts.RectangleSize);
        uint emptyRegion = 0;
        uint resumedRegion = 0;
        uint installedRegion = 0;
        var updating = false;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            var move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveLayer),
                move));
            Assert.Equal(1u, move.D[0]);

            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNotNull);
            var damageBytes = SnapshotGraphicsRegion(bus, damage.Raw);

            var newEmptyRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newEmptyRegion));
            emptyRegion = newEmptyRegion.D[0];
            Assert.NotEqual(0u, emptyRegion);
            var installEmpty = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = emptyRegion }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installEmpty));
            Assert.Equal(0u, installEmpty.D[0]);
            installedRegion = emptyRegion;

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;

            ClearPlanarBitMap(bus, displayBitMap);
            var bitmapBeforeEmptyRaster = SnapshotPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            Assert.Equal(bitmapBeforeEmptyRaster,
                SnapshotPlanarBitMap(bus, displayBitMap));
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damage.Raw));

            var pause = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                pause));
            updating = false;
            Assert.Equal((ushort)LayerFlags.Refresh,
                (ushort)(ReadLayerFlags(bus, bottom.Layer) &
                    ((ushort)LayerFlags.Refresh | (ushort)LayerFlags.Updating)));
            Assert.Equal(emptyRegion, ReadLayerClipRegion(bus, bottom.Layer));
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damage.Raw));

            var newResumedRegion = new M68kCpuState();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.NewRegion),
                newResumedRegion));
            resumedRegion = newResumedRegion.D[0];
            Assert.NotEqual(0u, resumedRegion);
            WriteRectangleBounds(bus, rectangle, 4, 4, 4, 4);
            var include = new M68kCpuState
            {
                A = { [0] = resumedRegion, [1] = rectangle }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.OrRectRegion),
                include));
            Assert.Equal(1u, include.D[0]);

            var installResumed = new M68kCpuState
            {
                A = { [0] = bottom.Layer, [1] = resumedRegion }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.InstallClipRegion),
                installResumed));
            Assert.Equal(emptyRegion, installResumed.D[0]);
            installedRegion = resumedRegion;

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updating = true;

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 4, 4));
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 3, 3));
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 5, 4));
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 4, 5));
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damage.Raw));

            var end = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, end);
            Assert.Equal(1u, end.D[0]);
            updating = false;

            Assert.Equal(resumedRegion, ReadLayerClipRegion(bus, bottom.Layer));
        }
        finally
        {
            if (updating)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            if (installedRegion != 0)
            {
                var uninstall = new M68kCpuState
                {
                    A = { [0] = bottom.Layer }
                };
                InvokeHostTrap(
                    bus,
                    Lvo(libraryBase, LayersLvo.InstallClipRegion),
                    uninstall);
            }
            foreach (var region in new[] { emptyRegion, resumedRegion })
            {
                if (region == 0) continue;
                var dispose = new M68kCpuState { A = { [0] = region } };
                InvokeHostTrap(
                    bus,
                    Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                        (int)GraphicsLvo.DisposeRegion),
                    dispose);
            }
            FreeGuestMemory(bus, rectangle, (uint)GraphicsLayouts.RectangleSize);
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void RepeatedBeginUpdateIsIdempotentAndPartialEndRetainsDamageUntilResumedCompletion()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            31,
            19);
        var top = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            15,
            15);
        var updateDepth = 0;

        try
        {
            var layerMemory = new LayersTestGuestMemory(bus);
            var move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveLayer),
                move));
            Assert.Equal(1u, move.D[0]);

            var damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);
            Assert.True(LayersRegionCodec.ReadFirst(ref layerMemory, damage).IsNotNull);
            var damageBytes = SnapshotGraphicsRegion(bus, damage.Raw);
            var stableHead = ReadLayerClipRect(bus, bottom.Layer);

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updateDepth = 1;
            var damageHead = ReadLayerClipRect(bus, bottom.Layer);
            Assert.NotEqual(stableHead, damageHead);
            Assert.Equal(stableHead, LayersLayerCodec.ReadSaveClipRects(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);

            var nestedBegin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                nestedBegin));
            Assert.Equal(1u, nestedBegin.D[0]);
            updateDepth = 1;
            Assert.Equal(damageHead, ReadLayerClipRect(bus, bottom.Layer));

            ClearPlanarBitMap(bus, displayBitMap);
            WriteRastPortForegroundPen(bus, bottom.RastPort, 1);
            var setRast = new M68kCpuState
            {
                A = { [1] = bottom.RastPort },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(AmigaKickstartHost.GraphicsLibraryBase,
                    (int)GraphicsLvo.SetRast),
                setRast));
            Assert.Equal(0u, setRast.D[0]);
            Assert.True(ReadPlanarBitMapPixel(bus, displayBitMap, 4, 4));
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 3, 3));
            Assert.False(ReadPlanarBitMapPixel(bus, displayBitMap, 10, 10));
            Assert.Equal(damageBytes, SnapshotGraphicsRegion(bus, damage.Raw));

            // Repeated BeginUpdate is idempotent: the first partial EndUpdate
            // closes update mode but retains the owned DamageList.
            var partialEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                partialEnd));
            updateDepth = 0;
            Assert.Equal(stableHead, ReadLayerClipRect(bus, bottom.Layer));
            Assert.Equal(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Updating);
            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, SnapshotGraphicsRegion(bus, damage.Raw));

            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);
            Assert.Equal(damage.Raw, LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer)).Raw);
            Assert.Equal(damageBytes, SnapshotGraphicsRegion(bus, damage.Raw));

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updateDepth = 1;
            Assert.NotEqual(0u, ReadLayerClipRect(bus, bottom.Layer));
            var complete = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, complete);
            updateDepth = 0;

            Assert.Equal((ushort)LayerFlags.Refresh, ReadLayerFlags(bus, bottom.Layer) &
                ((ushort)LayerFlags.Refresh | (ushort)LayerFlags.Updating));

            // A repeated BeginUpdate still has one EndUpdate boundary; a
            // complete EndUpdate retires the new damage immediately.
            move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 1, [1] = 0 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveLayer),
                move));
            Assert.Equal(1u, move.D[0]);
            damage = LayersLayerCodec.ReadDamageList(
                ref layerMemory,
                APTR.FromPointer(bottom.Layer));
            Assert.True(damage.IsNotNull);

            begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updateDepth = 1;
            var committedDamageHead = ReadLayerClipRect(bus, bottom.Layer);
            var committedNestedBegin = new M68kCpuState
            {
                A = { [0] = bottom.Layer }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                committedNestedBegin));
            Assert.Equal(1u, committedNestedBegin.D[0]);
            updateDepth = 1;

            var committedInnerEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, committedInnerEnd);
            updateDepth = 0;
            Assert.NotEqual(committedDamageHead, ReadLayerClipRect(bus, bottom.Layer));
            Assert.Equal(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Updating);
            Assert.NotEqual(0, ReadLayerFlags(bus, bottom.Layer) &
                (ushort)LayerFlags.Refresh);

            Assert.Equal((ushort)LayerFlags.Refresh, (ushort)(ReadLayerFlags(bus, bottom.Layer) &
                ((ushort)LayerFlags.Refresh | (ushort)LayerFlags.Updating)));
        }
        finally
        {
            while (updateDepth > 0)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                if (!InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end))
                    break;
                updateDepth--;
            }
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void EndUpdateRejectsMalformedSavedClipRectHeadWithoutLosingDamage()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var displayBitMap = AllocatePlanarBitMap(bus, 32, 20);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            31,
            19);
        var top = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            4,
            15,
            15);
        var memory = new LayersTestGuestMemory(bus);
        var bottomAddress = APTR.FromPointer(bottom.Layer);
        var updateActive = false;
        var savedHeadCorrupted = false;
        var savedHead = APTR.Null;
        var corruptSavedHead = APTR.FromPointer(0xFFFF_FFF0u);

        try
        {
            var move = new M68kCpuState
            {
                A = { [1] = top.Layer },
                D = { [0] = 2, [1] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.MoveLayer),
                move));
            Assert.Equal(1u, move.D[0]);

            var damage = LayersLayerCodec.ReadDamageList(ref memory, bottomAddress);
            Assert.True(damage.IsNotNull);
            var damageBytes = SnapshotGraphicsRegion(bus, damage.Raw);
            var stableHead = ReadLayerClipRect(bus, bottom.Layer);

            var begin = new M68kCpuState { A = { [0] = bottom.Layer } };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.BeginUpdate),
                begin));
            Assert.Equal(1u, begin.D[0]);
            updateActive = true;
            var damageHead = ReadLayerClipRect(bus, bottom.Layer);
            Assert.NotEqual(stableHead, damageHead);
            Assert.Equal(stableHead, LayersLayerCodec.ReadSaveClipRects(
                ref memory,
                bottomAddress).Raw);

            // A damaged saved head must be rejected before EndUpdate publishes
            // its restore, keeping the active ClipRect projection retryable.
            savedHead = LayersLayerCodec.ReadSaveClipRects(ref memory,
                bottomAddress);
            Assert.Equal(stableHead, savedHead.Raw);
            LayersLayerCodec.WriteSaveClipRects(ref memory, bottomAddress,
                corruptSavedHead);
            savedHeadCorrupted = true;
            Assert.Equal(corruptSavedHead.Raw,
                LayersLayerCodec.ReadSaveClipRects(ref memory, bottomAddress).Raw);
            var rejectedEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.EndUpdate),
                rejectedEnd));
            Assert.Equal(damageHead, ReadLayerClipRect(bus, bottom.Layer));
            Assert.Equal(corruptSavedHead.Raw,
                LayersLayerCodec.ReadSaveClipRects(ref memory, bottomAddress).Raw);
            Assert.Equal((ushort)(LayerFlags.Refresh | LayerFlags.Updating),
                (ushort)(ReadLayerFlags(bus, bottom.Layer) &
                    ((ushort)LayerFlags.Refresh | (ushort)LayerFlags.Updating)));
            Assert.Equal(damage.Raw,
                LayersLayerCodec.ReadDamageList(ref memory, bottomAddress).Raw);
            Assert.Equal(damageBytes,
                SnapshotGraphicsRegion(bus, damage.Raw));

            LayersLayerCodec.WriteSaveClipRects(ref memory, bottomAddress,
                savedHead);
            savedHeadCorrupted = false;

            var retryEnd = new M68kCpuState
            {
                A = { [0] = bottom.Layer },
                D = { [0] = 1 }
            };
            AssertEndUpdateClearsOwnedDamage(bus, libraryBase, retryEnd);
            updateActive = false;
            Assert.Equal(stableHead, ReadLayerClipRect(bus, bottom.Layer));

            Assert.Equal((ushort)LayerFlags.Refresh, (ushort)(ReadLayerFlags(bus, bottom.Layer) &
                ((ushort)LayerFlags.Refresh | (ushort)LayerFlags.Updating)));
        }
        finally
        {
            if (savedHeadCorrupted)
                LayersLayerCodec.WriteSaveClipRects(ref memory, bottomAddress,
                    savedHead);
            if (updateActive)
            {
                var end = new M68kCpuState
                {
                    A = { [0] = bottom.Layer },
                    D = { [0] = 0 }
                };
                InvokeHostTrap(bus, Lvo(libraryBase, LayersLvo.EndUpdate), end);
            }
            DeleteLayer(bus, libraryBase, top.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void RtgSwapJournalCommitsBothSidesAndRollsBackBothSides()
    {
        var machine = CreateRtgMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var displayBitMap = AllocateRtgBitMap(boot, bus, 8, 4);
        var superBitMap = AllocateRtgBitMap(boot, bus, 8, 4);
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var bottom = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            superBitMap,
            LayerCreationFlags.Super,
            0,
            0,
            7,
            3);
        var blocker = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            displayBitMap,
            0,
            LayerCreationFlags.Simple,
            4,
            0,
            7,
            3);
        var obscured = FindObscuredClipRect(bus, bottom.Layer);
        var backingBitMap = ReadClipRectBitMap(bus, obscured);
        Assert.NotEqual(0u, backingBitMap);
        Assert.NotEqual(superBitMap, backingBitMap);
        Assert.True(boot.CyberGraphics.TryGetBitMapSurface(backingBitMap, out _));
        LockLayer(bus, libraryBase, bottom.Layer);

        try
        {
            FillRtgBitMap(boot, bus, displayBitMap,
                (x, y) => checked((byte)(0x10 + y * 8 + x)));
            FillRtgBitMap(boot, bus, backingBitMap,
                (x, y) => checked((byte)(0x80 + y * 8 + x)));
            var displayBefore = SnapshotRtgBitMap(boot, bus, displayBitMap);
            var backingBefore = SnapshotRtgBitMap(boot, bus, backingBitMap);
            var superBefore = SnapshotRtgBitMap(boot, bus, superBitMap);
            var swap = new M68kCpuState
            {
                A = { [0] = bottom.RastPort, [1] = obscured }
            };

            boot.FailNextCopperStartLayersPixelTransactionAfterApplyForTest();
            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.SwapBitsRastPortClipRect),
                swap));
            Assert.Equal(displayBefore,
                SnapshotRtgBitMap(boot, bus, displayBitMap));
            Assert.Equal(backingBefore,
                SnapshotRtgBitMap(boot, bus, backingBitMap));
            Assert.Equal(superBefore,
                SnapshotRtgBitMap(boot, bus, superBitMap));

            Assert.True(InvokeHostTrap(
                bus,
                Lvo(libraryBase, LayersLvo.SwapBitsRastPortClipRect),
                swap));
            AssertRtgRectangle(
                boot,
                bus,
                displayBitMap,
                4,
                0,
                4,
                4,
                (x, y) => checked((byte)(0x80 + y * 8 + x + 4)));
            AssertRtgRectangle(
                boot,
                bus,
                backingBitMap,
                4,
                0,
                4,
                4,
                (x, y) => checked((byte)(0x10 + y * 8 + x + 4)));
            Assert.Equal(superBefore,
                SnapshotRtgBitMap(boot, bus, superBitMap));
        }
        finally
        {
            UnlockLayer(bus, libraryBase, bottom.Layer);
            DeleteLayer(bus, libraryBase, blocker.Layer);
            DeleteLayer(bus, libraryBase, bottom.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, superBitMap);
            FreeBitMap(bus, displayBitMap);
        }
    }

    [Fact]
    public void PlanarGuestBackfillMutationReservationRollsBackAndPreservesSuccessOrder()
    {
        var machine = CreateMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayer(bus, libraryBase, layerInfo, 0, 0, 7, 3);
        var plane = ReadBitMapPlane(bus, surface.BitMap, 0);
        var planeBytes = checked(
            ReadBitMapBytesPerRow(bus, surface.BitMap) *
            ReadBitMapRows(bus, surface.BitMap));

        try
        {
            var original = Enumerable.Range(0, planeBytes)
                .Select(index => checked((byte)(0x20 + index)))
                .ToArray();
            for (var index = 0; index < original.Length; index++)
                bus.WriteByte(plane + checked((uint)index), original[index], 0);

            // Cancellation may occur before the provider apply phase: a guest
            // Hook has already written, so the reservation must still undo it.
            var staged = boot.BeginCopperStartLayersPixelTransactionForTest(1);
            Assert.NotEqual(0u, staged);
            Assert.True(boot.StageCopperStartLayersPixelBackfillForTest(
                staged,
                surface.RastPort,
                surface.BitMap,
                LayerBackfillHook.NeverBackfill,
                0,
                0,
                8,
                4));
            for (var index = 0; index < original.Length; index++)
                bus.WriteByte(plane + checked((uint)index), 0xD3, 0);
            boot.CancelCopperStartLayersPixelTransactionForTest(staged);
            var initialStride = ReadBitMapBytesPerRow(bus, surface.BitMap);
            Assert.Equal(
                original.Select((value, index) =>
                    index % initialStride == 0 ? value : (byte)0xD3),
                Enumerable.Range(0, original.Length)
                    .Select(index => bus.ReadByte(plane + checked((uint)index))));

            // Provider writes precede the guest Hook. Completion is release-only,
            // so the Hook's patterned result must remain the final visible state.
            WriteRastPortBackgroundPen(bus, surface.RastPort, 0);
            var successful = boot.BeginCopperStartLayersPixelTransactionForTest(2);
            Assert.True(boot.StageCopperStartLayersPixelBackfillForTest(
                successful,
                surface.RastPort,
                surface.BitMap,
                LayerBackfillHook.Backfill,
                0,
                0,
                8,
                1));
            Assert.True(boot.StageCopperStartLayersPixelBackfillForTest(
                successful,
                surface.RastPort,
                surface.BitMap,
                LayerBackfillHook.NeverBackfill,
                0,
                0,
                8,
                1));
            Assert.True(boot.ApplyCopperStartLayersPixelTransactionForTest(successful));
            Assert.Equal((byte)0, bus.ReadByte(plane));
            bus.WriteByte(plane, 0xA5, 0);
            boot.CompleteCopperStartLayersPixelTransactionForTest(successful);
            Assert.Equal((byte)0xA5, bus.ReadByte(plane));

            var applied = boot.BeginCopperStartLayersPixelTransactionForTest(1);
            Assert.True(boot.StageCopperStartLayersPixelBackfillForTest(
                applied,
                surface.RastPort,
                surface.BitMap,
                LayerBackfillHook.NeverBackfill,
                0,
                0,
                8,
                1));
            Assert.True(boot.ApplyCopperStartLayersPixelTransactionForTest(applied));
            bus.WriteByte(plane, 0x7E, 0);
            boot.CancelCopperStartLayersPixelTransactionForTest(applied);
            Assert.Equal((byte)0xA5, bus.ReadByte(plane));

            // A reservation is rectangle-exact, including edge bits that
            // share a planar byte with pixels outside the Hook bounds.
            var bytesPerRow = ReadBitMapBytesPerRow(bus, surface.BitMap);
            var target = plane + bytesPerRow;
            bus.WriteByte(target, 0xAA, 0);
            bus.WriteByte(target + 1, 0x11, 0);
            var exact = boot.BeginCopperStartLayersPixelTransactionForTest(1);
            Assert.True(boot.StageCopperStartLayersPixelBackfillForTest(
                exact,
                surface.RastPort,
                surface.BitMap,
                LayerBackfillHook.NeverBackfill,
                2,
                1,
                3,
                1));
            Assert.True(boot.ApplyCopperStartLayersPixelTransactionForTest(exact));
            bus.WriteByte(target, 0xFF, 0);
            bus.WriteByte(target + 1, 0x77, 0);
            boot.CancelCopperStartLayersPixelTransactionForTest(exact);
            Assert.Equal((byte)0xEF, bus.ReadByte(target));
            Assert.Equal((byte)0x77, bus.ReadByte(target + 1));
        }
        finally
        {
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, surface.BitMap);
        }
    }

    [Fact]
    public void RtgGuestBackfillMutationReservationRollsBackAndPreservesSuccessOrder()
    {
        var machine = CreateRtgMachine();
        var boot = new AmigaBootController(machine);
        boot.StartBootFromDisk(CreateBootableDisk());
        var bus = machine.Bus;
        var libraryBase = boot.CopperStartLayersLibraryBase;
        var bitMap = AllocateRtgBitMap(boot, bus, 8, 4);
        var layerInfo = NewLayerInfo(bus, libraryBase);
        var surface = CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            bitMap,
            0,
            LayerCreationFlags.Simple,
            0,
            0,
            7,
            3);
        Assert.True(boot.CyberGraphics.TryGetBitMapSurface(bitMap, out var rtg));

        try
        {
            FillRtgBitMap(boot, bus, bitMap,
                (x, y) => checked((byte)(0x30 + y * 8 + x)));
            var original = SnapshotRtgBitMap(boot, bus, bitMap);
            var applied = boot.BeginCopperStartLayersPixelTransactionForTest(1);
            Assert.True(boot.StageCopperStartLayersPixelBackfillForTest(
                applied,
                surface.RastPort,
                bitMap,
                LayerBackfillHook.NeverBackfill,
                0,
                0,
                8,
                4));
            Assert.True(boot.ApplyCopperStartLayersPixelTransactionForTest(applied));
            for (var index = 0; index < original.Length; index++)
                bus.WriteByte(rtg.GuestBaseAddress + checked((uint)index), 0xE7, 0);
            boot.CancelCopperStartLayersPixelTransactionForTest(applied);
            var rolledBack = SnapshotRtgBitMap(boot, bus, bitMap);
            for (var index = 0; index < rolledBack.Length; index++)
            {
                var x = index % rtg.BytesPerRow;
                var expected = x < 8 ? original[index] : (byte)0xE7;
                Assert.Equal(expected, rolledBack[index]);
            }

            var successful = boot.BeginCopperStartLayersPixelTransactionForTest(2);
            Assert.True(boot.StageCopperStartLayersPixelBackfillForTest(
                successful,
                surface.RastPort,
                bitMap,
                LayerBackfillHook.Backfill,
                0,
                0,
                8,
                1));
            Assert.True(boot.StageCopperStartLayersPixelBackfillForTest(
                successful,
                surface.RastPort,
                bitMap,
                LayerBackfillHook.NeverBackfill,
                0,
                0,
                8,
                1));
            Assert.True(boot.ApplyCopperStartLayersPixelTransactionForTest(successful));
            Assert.Equal((byte)0, bus.ReadByte(rtg.GuestBaseAddress));
            bus.WriteByte(rtg.GuestBaseAddress, 0x5A, 0);
            boot.CompleteCopperStartLayersPixelTransactionForTest(successful);
            Assert.Equal((byte)0x5A, bus.ReadByte(rtg.GuestBaseAddress));

            // Rollback restores only the callback rectangle; concurrent guest
            // writes elsewhere on the same provider bitmap remain intact.
            FillRtgBitMap(boot, bus, bitMap,
                (x, y) => checked((byte)(0x40 + y * 8 + x)));
            var exactOriginal = SnapshotRtgBitMap(boot, bus, bitMap);
            var exact = boot.BeginCopperStartLayersPixelTransactionForTest(1);
            Assert.True(boot.StageCopperStartLayersPixelBackfillForTest(
                exact,
                surface.RastPort,
                bitMap,
                LayerBackfillHook.NeverBackfill,
                2,
                1,
                3,
                1));
            Assert.True(boot.ApplyCopperStartLayersPixelTransactionForTest(exact));
            for (var index = 0; index < exactOriginal.Length; index++)
                bus.WriteByte(rtg.GuestBaseAddress + checked((uint)index), 0xE7, 0);
            boot.CancelCopperStartLayersPixelTransactionForTest(exact);
            var exactAfter = SnapshotRtgBitMap(boot, bus, bitMap);
            for (var index = 0; index < exactAfter.Length; index++)
            {
                var x = index % rtg.BytesPerRow;
                var y = index / rtg.BytesPerRow;
                var expected = y == 1 && x is >= 2 and <= 4
                    ? exactOriginal[index]
                    : (byte)0xE7;
                Assert.Equal(expected, exactAfter[index]);
            }
        }
        finally
        {
            DeleteLayer(bus, libraryBase, surface.Layer);
            DisposeLayerInfo(bus, libraryBase, layerInfo);
            FreeBitMap(bus, bitMap);
        }
    }

    private static Machine CreateMachine()
        => new(MachineOptions
            .ForProfile(MachineProfile.A500Pal512KBoot)
            .WithLiveAgnusDma(false));

    private static Machine CreateExpandedMachine()
        => new(MachineOptions
            .ForProfile(MachineProfile.A500Pal512KBoot)
            .WithRealFastRam(8 * 1024 * 1024)
            .WithLiveAgnusDma(false));

    private static Machine CreateRtgMachine()
        => new(MachineOptions
            .ForProfile(MachineProfile.A500Pal512KBoot)
            .WithRtgVram(16L * 1024 * 1024)
            .WithCpu(AmigaM68kCoreFactory.Default, M68kBackendKind.AccurateM68040)
            .WithLiveAgnusDma(false));

    private static uint NewLayerInfo(AmigaBus bus, uint libraryBase)
    {
        var state = new M68kCpuState();
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.NewLayerInfo),
            state));
        Assert.NotEqual(0u, state.D[0]);
        return state.D[0];
    }

    private static void RetireOwnedDamageForCallerFixture(
        AmigaBus bus,
        AmigaBootController boot,
        APTR layer)
    {
        var resources = new BootLayersResourcePlatform(bus, boot);
        var root = APTR.FromPointer(boot.CopperStartLayersRootAddress);
        Assert.True(LayersLayerCodec.ReadDamageList(ref resources, layer).IsNotNull);
        Assert.Equal((LayerFlags)0,
            LayersLayerCodec.ReadFlags(ref resources, layer) & LayerFlags.Updating);
        // Test-only ownership transfer: EndUpdate deliberately keeps the
        // original Region, so release its private owner before substituting
        // externally allocated caller storage. Never free the caller Region.
        Assert.True(PortableLayers.LayersPartitionPixelCore.TryFinishOwnedDamage(
            ref resources, root, layer, complete: true));
        Assert.True(LayersLayerCodec.ReadDamageList(ref resources, layer).IsNull);
        Assert.True(PortableLayers.LayersPartitionPixelCore.ValidateOwnedDamageState(
            ref resources, root, layer));
    }

    private static void AssertEndUpdateClearsOwnedDamage(
        AmigaBus bus,
        uint libraryBase,
        M68kCpuState state)
    {
        Assert.NotEqual(0u, state.D[0]);
        var memory = new LayersTestGuestMemory(bus);
        var layer = APTR.FromPointer(state.A[0]);
        var damage = LayersLayerCodec.ReadDamageList(ref memory, layer);
        Assert.True(damage.IsNotNull);

        Assert.True(InvokeHostTrap(
            bus, Lvo(libraryBase, LayersLvo.EndUpdate), state));

        // Native V40.63 clears the rectangles and bounds in the existing
        // Layers-owned Region; completion does not free its public header.
        Assert.Equal(damage.Raw,
            LayersLayerCodec.ReadDamageList(ref memory, layer).Raw);
        Assert.True(LayersRegionCodec.ReadFirst(ref memory, damage).IsNull);
        var bounds = LayersRegionCodec.ReadBounds(ref memory, damage);
        Assert.Equal((short)0, bounds.MinX);
        Assert.Equal((short)0, bounds.MinY);
        Assert.Equal((short)0, bounds.MaxX);
        Assert.Equal((short)0, bounds.MaxY);
    }

    private static uint AllocateGuestMemory(AmigaBus bus, uint byteCount)
    {
        var state = new M68kCpuState();
        state.D[0] = byteCount;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(AmigaKickstartHost.ExecLibraryBase, -198),
            state));
        Assert.NotEqual(0u, state.D[0]);
        return state.D[0];
    }

    private static void FreeGuestMemory(
        AmigaBus bus,
        uint address,
        uint byteCount)
    {
        var state = new M68kCpuState
        {
            A = { [1] = address },
            D = { [0] = byteCount }
        };
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(AmigaKickstartHost.ExecLibraryBase, -210),
            state));
    }

    private static LayerSurface CreateLayer(
        AmigaBus bus,
        uint libraryBase,
        uint layerInfo,
        short minX,
        short minY,
        short maxX,
        short maxY)
    {
        var width = checked((ushort)(maxX - minX + 1));
        var height = checked((ushort)(maxY - minY + 1));
        var allocateBitMap = new M68kCpuState();
        allocateBitMap.D[0] = width;
        allocateBitMap.D[1] = height;
        allocateBitMap.D[2] = 1;
        allocateBitMap.D[3] = (uint)BitMapFlags.Clear;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(AmigaKickstartHost.GraphicsLibraryBase, -918),
            allocateBitMap));
        var bitMap = allocateBitMap.D[0];
        Assert.NotEqual(0u, bitMap);

        return CreateLayerOnBitMaps(
            bus,
            libraryBase,
            layerInfo,
            bitMap,
            0,
            LayerCreationFlags.Simple,
            minX,
            minY,
            maxX,
            maxY);
    }

    private static LayerSurface CreateLayerOnBitMaps(
        AmigaBus bus,
        uint libraryBase,
        uint layerInfo,
        uint displayBitMap,
        uint superBitMap,
        LayerCreationFlags flags,
        short minX,
        short minY,
        short maxX,
        short maxY)
    {
        var create = new M68kCpuState();
        create.A[0] = layerInfo;
        create.A[1] = displayBitMap;
        create.A[2] = superBitMap;
        create.D[0] = unchecked((uint)minX);
        create.D[1] = unchecked((uint)minY);
        create.D[2] = unchecked((uint)maxX);
        create.D[3] = unchecked((uint)maxY);
        create.D[4] = (uint)flags;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.CreateUpfrontLayer),
            create));
        var layer = create.D[0];
        Assert.NotEqual(0u, layer);
        var rastPort = ReadLayerRastPort(bus, layer);
        var firstClipRect = ReadLayerClipRect(bus, layer);
        Assert.NotEqual(0u, rastPort);
        Assert.NotEqual(0u, firstClipRect);
        return new LayerSurface(displayBitMap, layer, rastPort, firstClipRect);
    }

    private static uint AllocateRtgBitMap(
        AmigaBootController boot,
        AmigaBus bus,
        ushort width,
        ushort height)
    {
        var state = new M68kCpuState();
        state.D[0] = width;
        state.D[1] = height;
        state.D[2] = 8;
        state.D[3] = (uint)BitMapFlags.Clear;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(AmigaKickstartHost.GraphicsLibraryBase, -918),
            state));
        Assert.NotEqual(0u, state.D[0]);
        Assert.True(boot.CyberGraphics.TryGetBitMapSurface(state.D[0], out _));
        return state.D[0];
    }

    private static uint AllocatePlanarBitMap(
        AmigaBus bus,
        ushort width,
        ushort height)
    {
        var state = new M68kCpuState();
        state.D[0] = width;
        state.D[1] = height;
        state.D[2] = 1;
        state.D[3] = (uint)BitMapFlags.Clear;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(AmigaKickstartHost.GraphicsLibraryBase, -918),
            state));
        Assert.NotEqual(0u, state.D[0]);
        return state.D[0];
    }

    private static void ClearPlanarBitMap(AmigaBus bus, uint bitMap)
    {
        var bytesPerRow = ReadBitMapBytesPerRow(bus, bitMap);
        var rows = ReadBitMapRows(bus, bitMap);
        var depth = ReadBitMapDepth(bus, bitMap);
        Assert.InRange(depth, (byte)1, (byte)8);
        for (var plane = 0; plane < depth; plane++)
        {
            var planeAddress = ReadBitMapPlane(bus, bitMap, plane);
            Assert.NotEqual(0u, planeAddress);
            for (var offset = 0; offset < bytesPerRow * rows; offset++)
                bus.WriteByte(planeAddress + checked((uint)offset), 0, 0);
        }
    }

    private static byte[] SnapshotPlanarBitMap(AmigaBus bus, uint bitMap)
    {
        var bytesPerRow = ReadBitMapBytesPerRow(bus, bitMap);
        var rows = ReadBitMapRows(bus, bitMap);
        var depth = ReadBitMapDepth(bus, bitMap);
        var planeSize = checked(bytesPerRow * rows);
        var result = new byte[checked(planeSize * depth)];
        for (var plane = 0; plane < depth; plane++)
        {
            var planeAddress = ReadBitMapPlane(bus, bitMap, plane);
            Assert.NotEqual(0u, planeAddress);
            for (var offset = 0; offset < planeSize; offset++)
            {
                result[plane * planeSize + offset] = bus.ReadByte(
                    planeAddress + checked((uint)offset));
            }
        }
        return result;
    }

    private static byte[] SnapshotGraphicsRegion(AmigaBus bus, uint region)
    {
        var memory = new LayersTestGuestMemory(bus);
        var address = APTR.FromPointer(region);
        var result = new List<byte>();
        for (var offset = 0; offset < checked((int)LayersRegionCodec.Size); offset++)
            result.Add(bus.ReadByte(region + (uint)offset));

        var visited = new HashSet<uint>();
        var rectangle = LayersRegionCodec.ReadFirst(ref memory, address);
        while (rectangle.IsNotNull)
        {
            Assert.True(visited.Add(rectangle.Raw), "Region rectangle chain must be acyclic.");
            for (var offset = 0;
                 offset < checked((int)LayersRegionRectangleCodec.Size);
                 offset++)
                result.Add(bus.ReadByte(rectangle.Raw + (uint)offset));
            rectangle = LayersRegionRectangleCodec.ReadNext(ref memory, rectangle);
        }

        return result.ToArray();
    }

    private readonly struct BootLayersResourcePlatform(
        AmigaBus bus,
        AmigaBootController? boot = null)
        : PortableLayers.ILayersMemoryPlatform,
            PortableLayers.ILayersResourcePlatform
    {
        public bool IsMapped(APTR address, uint byteCount)
            => byteCount <= int.MaxValue &&
                address.Raw <= uint.MaxValue - byteCount &&
                bus.IsMappedMemoryRange(address.Raw, checked((int)byteCount));

        public byte ReadUInt8(APTR address, int offset = 0)
            => bus.ReadByte(Add(address, offset));

        public ushort ReadUInt16(APTR address, int offset = 0)
            => bus.ReadWord(Add(address, offset));

        public uint ReadUInt32(APTR address, int offset = 0)
            => bus.ReadLong(Add(address, offset));

        public void WriteUInt8(APTR address, int offset, byte value)
            => bus.WriteByte(Add(address, offset), value, 0);

        public void WriteUInt16(APTR address, int offset, ushort value)
            => bus.WriteWord(Add(address, offset), value, 0);

        public void WriteUInt32(APTR address, int offset, uint value)
            => bus.WriteLong(Add(address, offset), value);

        public void Clear(APTR address, uint byteCount)
        {
            for (var offset = 0u; offset < byteCount; offset++)
                bus.WriteByte(address.Raw + offset, 0, 0);
        }

        public void Copy(APTR source, APTR destination, uint byteCount)
        {
            if (destination.Raw > source.Raw &&
                (ulong)destination.Raw < (ulong)source.Raw + byteCount)
            {
                for (var offset = byteCount; offset != 0; offset--)
                {
                    var index = offset - 1;
                    bus.WriteByte(destination.Raw + index,
                        bus.ReadByte(source.Raw + index), 0);
                }
                return;
            }

            for (var offset = 0u; offset < byteCount; offset++)
                bus.WriteByte(destination.Raw + offset,
                    bus.ReadByte(source.Raw + offset), 0);
        }

        public APTR Allocate(uint byteCount,
            global::Amiga.Exec.MemoryFlags requirements)
        {
            var state = new M68kCpuState
            {
                D =
                {
                    [0] = byteCount,
                    [1] = (uint)requirements
                }
            };
            if (!InvokeHostTrap(bus,
                Lvo(AmigaKickstartHost.ExecLibraryBase, -198), state))
                return APTR.Null;
            return APTR.FromPointer(state.D[0]);
        }

        public void Free(APTR address, uint byteCount)
            => FreeGuestMemory(bus, address.Raw, byteCount);

        public APTR AllocateOpaque(uint byteCount,
            global::Amiga.Exec.MemoryFlags requirements)
        {
            _ = byteCount;
            _ = requirements;
            return APTR.Null;
        }

        public bool IsOpaqueAllocation(APTR address, uint byteCount)
            => boot?.IsCopperStartLayersOpaqueAllocationForTest(
                address.Raw, byteCount) == true;

        public bool FreeOpaque(APTR address)
        {
            if (boot is null || address.IsNull)
                return false;
            var platform = this;
            var byteCount = PortableLayers.LayersPrivateRecordCore.Size(
                ref platform, address);
            if (byteCount == 0 || !boot.IsCopperStartLayersOpaqueAllocationForTest(
                    address.Raw, byteCount))
                return false;
            boot.FreeCopperStartLayersOpaqueForTest(address.Raw);
            return !boot.IsCopperStartLayersOpaqueAllocationForTest(
                address.Raw, byteCount);
        }

        public APTR GetCurrentTask(APTR execBase)
        {
            var memory = new LayersTestGuestMemory(bus);
            return ExecBaseCodec.ReadThisTask(ref memory, execBase);
        }

        public bool ParkCurrentTask(APTR task, APTR waitObject,
            uint continuationToken)
        {
            _ = task;
            _ = waitObject;
            _ = continuationToken;
            return false;
        }

        public void WakeTask(APTR task, uint continuationToken)
        {
            _ = task;
            _ = continuationToken;
        }

        private static uint Add(APTR address, int offset)
            => unchecked(address.Raw + (uint)offset);
    }

    private static bool ReadPlanarBitMapPixel(
        AmigaBus bus,
        uint bitMap,
        int x,
        int y)
    {
        var bytesPerRow = ReadBitMapBytesPerRow(bus, bitMap);
        var rows = ReadBitMapRows(bus, bitMap);
        Assert.InRange(x, 0, bytesPerRow * 8 - 1);
        Assert.InRange(y, 0, rows - 1);
        var plane = ReadBitMapPlane(bus, bitMap, 0);
        Assert.NotEqual(0u, plane);
        var address = plane + checked((uint)(y * bytesPerRow + (x >> 3)));
        return (bus.ReadByte(address) & (0x80 >> (x & 7))) != 0;
    }

    private static void FillRtgBitMap(
        AmigaBootController boot,
        AmigaBus bus,
        uint bitMap,
        Func<int, int, byte> value)
    {
        Assert.True(boot.CyberGraphics.TryGetBitMapSurface(bitMap, out var surface));
        Assert.Equal(1, surface.BytesPerPixel);
        for (var y = 0; y < surface.Height; y++)
        {
            for (var x = 0; x < surface.Width; x++)
            {
                bus.WriteByte(
                    surface.GuestBaseAddress + checked((uint)(y * surface.BytesPerRow + x)),
                    value(x, y),
                    0);
            }
        }
    }

    private static byte[] SnapshotRtgBitMap(
        AmigaBootController boot,
        AmigaBus bus,
        uint bitMap)
    {
        Assert.True(boot.CyberGraphics.TryGetBitMapSurface(bitMap, out var surface));
        return Enumerable.Range(0, checked(surface.BytesPerRow * surface.Height))
            .Select(offset => bus.ReadByte(
                surface.GuestBaseAddress + checked((uint)offset)))
            .ToArray();
    }

    private static void AssertRtgRectangle(
        AmigaBootController boot,
        AmigaBus bus,
        uint bitMap,
        int minX,
        int minY,
        int width,
        int height,
        Func<int, int, byte> expected)
    {
        Assert.True(boot.CyberGraphics.TryGetBitMapSurface(bitMap, out var surface));
        for (var y = 0; y < height; y++)
        {
            for (var x = 0; x < width; x++)
            {
                Assert.Equal(
                    expected(x, y),
                    bus.ReadByte(
                        surface.GuestBaseAddress + checked((uint)(
                            (minY + y) * surface.BytesPerRow + minX + x))));
            }
        }
    }

    private static uint FindObscuredClipRect(AmigaBus bus, uint layer)
    {
        var current = ReadLayerClipRect(bus, layer);
        while (current != 0)
        {
            if (ReadClipRectObscuringLayer(bus, current) != 0)
            {
                return current;
            }
            current = ReadClipRectNext(bus, current);
        }
        Assert.Fail("The layer has no obscured ClipRect.");
        return 0;
    }

    private static void LockLayer(AmigaBus bus, uint libraryBase, uint layer)
    {
        var state = new M68kCpuState { A = { [1] = layer } };
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.LockLayer),
            state));
    }

    private static void UnlockLayer(AmigaBus bus, uint libraryBase, uint layer)
    {
        var state = new M68kCpuState { A = { [0] = layer } };
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.UnlockLayer),
            state));
    }

    private static void DeleteLayer(AmigaBus bus, uint libraryBase, uint layer)
    {
        var state = new M68kCpuState();
        state.A[1] = layer;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.DeleteLayer),
            state));
        Assert.NotEqual(0u, state.D[0]);
    }

    private static void DisposeLayerInfo(
        AmigaBus bus,
        uint libraryBase,
        uint layerInfo)
    {
        var state = new M68kCpuState();
        state.A[0] = layerInfo;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(libraryBase, LayersLvo.DisposeLayerInfo),
            state));
    }

    private static void FreeBitMap(AmigaBus bus, uint bitMap)
    {
        var state = new M68kCpuState();
        state.A[0] = bitMap;
        Assert.True(InvokeHostTrap(
            bus,
            Lvo(AmigaKickstartHost.GraphicsLibraryBase, -924),
            state));
    }

    private readonly record struct LayerSurface(
        uint BitMap,
        uint Layer,
        uint RastPort,
        uint FirstClipRect);

    private sealed class InstructionWriter
    {
        private readonly AmigaBus _bus;
        private uint _address;

        public InstructionWriter(AmigaBus bus, uint address)
        {
            _bus = bus;
            _address = address;
        }

        public uint Address => _address;

        public void MoveDataImmediate(int register, uint value)
        {
            WriteWord(checked((ushort)(0x203C + (register << 9))));
            WriteLong(value);
        }

        public void MoveAddressImmediate(int register, uint value)
        {
            WriteWord(checked((ushort)(0x207C + (register << 9))));
            WriteLong(value);
        }

        public void OrImmediateConditionCodes(ushort value)
        {
            WriteWord(0x003C);
            WriteWord(value);
        }

        public void JumpSubroutine(uint address)
        {
            WriteWord(0x4EB9);
            WriteLong(address);
        }

        public void BranchToSelf() => WriteWord(0x60FE);

        private void WriteWord(ushort value)
        {
            _bus.WriteWord(_address, value, 0);
            _address += 2;
        }

        private void WriteLong(uint value)
        {
            _bus.WriteLong(_address, value, 0);
            _address += 4;
        }
    }

    private static AmigaDiskImage CreateBootableDisk()
    {
        var data = new byte[AmigaDiskImage.StandardAdfSize];
        data[0] = (byte)'D';
        data[1] = (byte)'O';
        data[2] = (byte)'S';
        BigEndian.WriteUInt32(data, 4, CalculateBootChecksum(data.AsSpan(0, 1024)));
        return AmigaDiskImage.FromAdfBytes(data);
    }

    private static byte[] CreateMinimalKickstartRom()
    {
        var rom = new byte[512 * 1024];
        BigEndian.WriteUInt32(rom, 0, 0x0000_0400);
        BigEndian.WriteUInt32(rom, 4, 0x00F8_0000);
        return rom;
    }

    private static uint CalculateBootChecksum(ReadOnlySpan<byte> bootBlock)
    {
        var sum = 0u;
        for (var offset = 0; offset < 1024; offset += 4)
        {
            var value = BigEndian.ReadUInt32(bootBlock, offset, "boot checksum word");
            var previous = sum;
            sum += value;
            if (sum < previous)
                sum++;
        }
        return ~sum;
    }

    private static uint Lvo(uint libraryBase, int displacement)
        => unchecked((uint)((int)libraryBase + displacement));

    private static bool InvokeHostTrap(
        AmigaBus bus,
        uint address,
        M68kCpuState state)
    {
        if (bus.ReadWord(address) != 0xFF00)
            return false;
        return bus.TryInvokeHostGateway(address, bus.ReadLong(address + 2), state);
    }

    private static void WriteCString(AmigaBus bus, uint address, string value)
    {
        for (var index = 0; index < value.Length; index++)
            bus.WriteByte(
                address + checked((uint)index),
                checked((byte)value[index]),
                0);
        bus.WriteByte(address + checked((uint)value.Length), 0, 0);
    }

    private static void AssertInstalledProfileGateways(
        AmigaBus bus,
        uint libraryBase,
        PortableLayers.LayersAbiProfile profile)
    {
        for (var displacement = -6; displacement >= -24; displacement -= 6)
            Assert.True(bus.HasHostGateway(Lvo(libraryBase, displacement)));

        var minimum = profile == PortableLayers.LayersAbiProfile.Unified
            ? LayersLvo.IsLayerHitable
            : LayersLvo.DoHookClipRects;
        for (var displacement = -30; displacement >= minimum; displacement -= 6)
        {
            var selected = PortableLayers.LayersVectorManifest.TryDescribe(
                checked((short)displacement),
                profile,
                out _);
            Assert.Equal(
                selected,
                bus.HasHostGateway(Lvo(libraryBase, displacement)));
        }
    }

    private static string ReadCString(AmigaBus bus, uint address, int maximumLength)
    {
        var characters = new char[maximumLength];
        var count = 0;
        while (count < characters.Length)
        {
            var value = bus.ReadByte(address + checked((uint)count));
            if (value == 0)
                break;
            characters[count++] = (char)value;
        }
        return new string(characters, 0, count);
    }

}
